    fn scan_bind_expression_end(source: []const u8, start: usize) usize {
        var j = start;
        var paren_depth: usize = 0;
        var bracket_depth: usize = 0;
        while (j < source.len) : (j += 1) {
            const ch = source[j];
            if (std.ascii.isAlphanumeric(ch) or ch == '_' or ch == '.') continue;
            if (ch == '(') {
                paren_depth += 1;
                continue;
            }
            if (ch == '[') {
                bracket_depth += 1;
                continue;
            }
            if (ch == ')') {
                if (paren_depth == 0 and bracket_depth == 0) break;
                paren_depth -|= 1;
                continue;
            }
            if (ch == ']') {
                if (paren_depth == 0 and bracket_depth == 0) break;
                bracket_depth -|= 1;
                continue;
            }
            break;
        }
        return j;
    }

    fn lookup_evaluated_bind_expression(
        self: *Evaluator,
        current_env: *Env,
        bind_expr: []const u8,
    ) ?Value {
        const tokens = lexer_mod.tokenize(bind_expr, self.arena) catch return null;
        const expr = parser_mod.parse_expr(tokens, self.arena) catch return null;
        return self.eval_expr(expr, current_env) catch null;
    }

    fn lookup_bind_value(self: *Evaluator, current_env: *Env, var_name: []const u8) ?Value {
        if (current_env.get(var_name)) |bv| {
            if (bv != .null_val) return bv;
        }
        if (self.lookup_evaluated_bind_expression(current_env, var_name)) |bv| return bv;

        if (self.current_class) |cc| {
            self.ensure_static_init(cc);
            const key = std.fmt.allocPrint(self.arena, "{s}.{s}", .{ cc, var_name }) catch null;
            if (key) |k| {
                if (self.global_env.get(k)) |bv| return bv;
            }
            if (self.find_outer_class_name(cc)) |oc| {
                self.ensure_static_init(oc);
                const okey = std.fmt.allocPrint(
                    self.arena,
                    "{s}.{s}",
                    .{ oc, var_name },
                ) catch null;
                if (okey) |k| {
                    if (self.global_env.get(k)) |bv| return bv;
                }
            }
        }

        if (current_env.get("this")) |tv| {
            if (tv == .object) {
                const this_cn = tv.object.class_name;
                self.ensure_static_init(this_cn);
                const tkey = std.fmt.allocPrint(
                    self.arena,
                    "{s}.{s}",
                    .{ this_cn, var_name },
                ) catch null;
                if (tkey) |k| {
                    if (self.global_env.get(k)) |bv| return bv;
                }
                if (self.find_outer_class_name(this_cn)) |oc| {
                    self.ensure_static_init(oc);
                    const okey = std.fmt.allocPrint(
                        self.arena,
                        "{s}.{s}",
                        .{ oc, var_name },
                    ) catch null;
                    if (okey) |k| {
                        if (self.global_env.get(k)) |bv| return bv;
                    }
                }
            }
        }

        return null;
    }

    /// Extract the first value used in WHERE Name ... conditions.
    /// Supports =, LIKE, IN (:bind), and IN ('a', 'b') through the generic field extractor.
    fn extract_where_name_value(self: *Evaluator, soql: []const u8, current_env: *Env) ?[]const u8 {
        return self.extract_where_field_value(soql, "Name", current_env);
    }

    /// Extract a specific field value from WHERE clause
    fn extract_where_field_value(
        self: *Evaluator,
        soql: []const u8,
        field_name: []const u8,
        current_env: *Env,
    ) ?[]const u8 {
        const where_clause = extract_where_clause(soql) orelse return null;
        var pos: usize = 0;
        while (pos + field_name.len <= where_clause.len) : (pos += 1) {
            if (std.ascii.eqlIgnoreCase(where_clause[pos .. pos + field_name.len], field_name) and
                (pos == 0 or is_soql_whitespace(where_clause[pos - 1]) or where_clause[pos - 1] == '(') and
                (pos + field_name.len == where_clause.len or is_soql_whitespace(where_clause[pos + field_name.len]) or where_clause[pos + field_name.len] == ')'))
            {
                var j = pos + field_name.len;
                while (j < where_clause.len and is_soql_whitespace(where_clause[j])) j += 1;

                var is_in = false;
                if (j + 2 <= where_clause.len and
                    std.ascii.eqlIgnoreCase(where_clause[j .. j + 2], "IN"))
                {
                    is_in = true;
                    j += 2;
                } else if (j + 4 <= where_clause.len and
                    std.ascii.eqlIgnoreCase(where_clause[j .. j + 4], "LIKE"))
                {
                    j += 4;
                } else if (j < where_clause.len and where_clause[j] == '=') {
                    j += 1;
                } else {
                    while (j < where_clause.len and where_clause[j] != '\'' and where_clause[j] != ':' and where_clause[j] != '(' and where_clause[j] != ' ') j += 1;
                }

                while (j < where_clause.len and is_soql_whitespace(where_clause[j])) j += 1;

                if (is_in and j < where_clause.len and where_clause[j] == '(') {
                    j += 1;
                    while (j < where_clause.len and
                        (where_clause[j] == ' ' or where_clause[j] == '\t')) j += 1;
                    if (j < where_clause.len and where_clause[j] == '\'') {
                        j += 1;
                        const start = j;
                        while (j < where_clause.len and where_clause[j] != '\'') j += 1;
                        return where_clause[start..j];
                    }
                    const start = j;
                    while (j < where_clause.len and
                        where_clause[j] != ',' and where_clause[j] != ')' and
                        where_clause[j] != ' ' and where_clause[j] != '\t') j += 1;
                    if (j > start) return std.mem.trim(u8, where_clause[start..j], " \t\n\r'");
                    continue;
                }

                if (j < where_clause.len and where_clause[j] == '\'') {
                    j += 1;
                    const start = j;
                    while (j < where_clause.len and where_clause[j] != '\'') j += 1;
                    return where_clause[start..j];
                }
                // Bare literal (TRUE / FALSE / number / unquoted identifier) — consume
                // up to the next WHERE terminator so predicates like
                // `PermissionsModifyAllData = TRUE` resolve to the string "TRUE"
                // rather than returning null and being skipped during synthesis.
                if (j < where_clause.len and where_clause[j] != '\'' and where_clause[j] != ':' and where_clause[j] != '(') {
                    const start = j;
                    while (j < where_clause.len) : (j += 1) {
                        const ch = where_clause[j];
                        if (ch == ' ' or ch == '\t' or ch == '\n' or ch == '\r') break;
                        if (ch == ')' or ch == ',') break;
                        // Stop at AND/OR boundary (defensive — WHERE terminators
                        // beyond whitespace).
                    }
                    if (j > start) {
                        const raw = std.mem.trim(u8, where_clause[start..j], " \t\n\r");
                        if (raw.len > 0) return raw;
                    }
                }
                if (j < where_clause.len and where_clause[j] == ':') {
                    j += 1;
                    const start = j;
                    j = scan_bind_expression_end(where_clause, j);
                    const var_name = where_clause[start..j];
                    if (self.lookup_bind_value(current_env, var_name)) |v| {
                        switch (v) {
                            .string => return v.string,
                            .list => {
                                for (v.list.items.items) |item| {
                                    switch (item) {
                                        .string => return item.string,
                                        .sobject => {
                                            if (item.sobject.id) |id| return id;
                                        },
                                        else => {
                                            const coerced = utils.coerce_to_string(
                                                item,
                                                self.arena,
                                            ) catch continue;
                                            return coerced;
                                        },
                                    }
                                }
                                return null;
                            },
                            .set => {
                                var it = v.set.entries.iterator();
                                if (it.next()) |entry| {
                                    if (entry.value_ptr.* == .string)
                                        return entry.value_ptr.*.string;
                                }
                                return null;
                            },
                            .map => {
                                var it = v.map.entries.iterator();
                                if (it.next()) |entry| return entry.key_ptr.*;
                                return null;
                            },
                            else => return (utils.coerce_to_string(v, self.arena) catch null),
                        }
                    }
                }
            }
        }
        return null;
    }

    fn has_where_field_null_literal(
        self: *Evaluator,
        soql_or_cond: []const u8,
        field_name: []const u8,
    ) bool {
        _ = self;
        const clause = extract_where_clause(soql_or_cond) orelse soql_or_cond;
        var pos: usize = 0;
        while (pos + field_name.len <= clause.len) : (pos += 1) {
            if (!std.ascii.eqlIgnoreCase(clause[pos .. pos + field_name.len], field_name)) continue;
            if (!(pos == 0 or is_soql_whitespace(clause[pos - 1]) or clause[pos - 1] == '(')) continue;
            var j = pos + field_name.len;
            while (j < clause.len and is_soql_whitespace(clause[j])) j += 1;
            if (j >= clause.len or clause[j] != '=') continue;
            j += 1;
            while (j < clause.len and is_soql_whitespace(clause[j])) j += 1;
            if (j + 4 <= clause.len and std.ascii.eqlIgnoreCase(clause[j .. j + 4], "NULL"))
                return true;
        }
        return false;
    }

    /// Allocate a unique fake Salesforce ID
    fn alloc_id(self: *Evaluator) ![]const u8 {
        const id = try std.fmt.allocPrint(self.arena, "{d:0>18}", .{self.next_id});
        self.next_id += 1;
        return id;
    }

    /// Load a StaticResource body from the file system.
    /// Searches source_paths for staticresources/<name>.json, .csv, .xml, or .resource.
    fn load_static_resource_body(self: *Evaluator, name: []const u8) ?[]const u8 {
        const extensions = [_][]const u8{ ".json", ".csv", ".xml", ".txt", ".resource", "" };
        for (self.source_paths) |sp| {
            // Try walking the directory tree to find staticresources/<name>.<ext>
            if (self.find_static_resource_in_dir(sp, name, &extensions)) |content| return content;
        }
        return null;
    }

    fn find_static_resource_in_dir(
        self: *Evaluator,
        base_path: []const u8,
        name: []const u8,
        extensions: []const []const u8,
    ) ?[]const u8 {
        var dir =
            std.Io.Dir.cwd().openDir(self.io, base_path, .{ .iterate = true }) catch return null;
        defer dir.close(self.io);

        var walker = dir.walk(self.arena) catch return null;
        defer walker.deinit();

        while (walker.next(self.io) catch null) |entry| {
            if (entry.kind != .file) continue;
            // Check if the file is in a "staticresources" directory and matches name
            const path_str = entry.path;
            // Look for "/staticresources/<name>.<ext>" or "staticresources/<name>.<ext>"
            if (std.mem.indexOf(u8, path_str, "staticresources/")) |sr_pos| {
                const after_sr = path_str[sr_pos + "staticresources/".len ..];
                // Check if the filename matches <name>.<ext>
                for (extensions) |ext| {
                    const expected = std.fmt.allocPrint(
                        self.arena,
                        "{s}{s}",
                        .{ name, ext },
                    ) catch continue;
                    if (std.mem.eql(u8, after_sr, expected)) {
                        const full_path = std.fmt.allocPrint(
                            self.arena,
                            "{s}/{s}",
                            .{ base_path, path_str },
                        ) catch continue;
                        if (std.Io.Dir.cwd().readFileAlloc(
                            self.io,
                            full_path,
                            self.arena,
                            .limited(10 * 1024 * 1024),
                        )) |content| {
                            return content;
                        } else |_| {}
                    }
                }
            }
        }
        return null;
    }

    fn has_flow_definition(self: *Evaluator, flow_name: []const u8) bool {
        const suffix = std.fmt.allocPrint(
            self.arena,
            "{s}.flow-meta.xml",
            .{flow_name},
        ) catch return false;
        for (self.source_paths) |base_path| {
            var dir =
                std.Io.Dir.cwd().openDir(self.io, base_path, .{ .iterate = true }) catch continue;
            defer dir.close(self.io);

            var walker = dir.walk(self.arena) catch continue;
            defer walker.deinit();

            while (walker.next(self.io) catch null) |entry| {
                if (entry.kind != .file) continue;
                if (std.mem.endsWith(u8, entry.path, suffix)) return true;
            }
        }
        return false;
    }

    /// Load custom metadata records from .md-meta.xml files in source_paths.
    /// Parses files matching `customMetadata/<TypeName>.<RecordName>.md-meta.xml` and
    /// populates the store with SObject records containing the field values.
    fn load_custom_metadata_from_files(self: *Evaluator, mdt_type: []const u8) !void {
        // Strip __mdt suffix to get the base type name for file matching
        const base_name = if (std.mem.endsWith(u8, mdt_type, "__mdt"))
            mdt_type[0 .. mdt_type.len - 5]
        else
            mdt_type;

        for (self.source_paths) |sp| {
            var dir = std.Io.Dir.cwd().openDir(self.io, sp, .{ .iterate = true }) catch continue;
            defer dir.close(self.io);

            var walker = dir.walk(self.arena) catch continue;
            defer walker.deinit();

            while (walker.next(self.io) catch null) |entry| {
                if (entry.kind != .file) continue;
                if (!std.mem.endsWith(u8, entry.path, ".md-meta.xml")) continue;
                // Check if filename matches: customMetadata/<BaseName>.<RecordName>.md-meta.xml
                if (std.mem.indexOf(u8, entry.path, "customMetadata/")) |cm_pos| {
                    const after_cm = entry.path[cm_pos + "customMetadata/".len ..];
                    // after_cm should be like "Customer_Fields.Contact_Config.md-meta.xml"
                    if (std.ascii.startsWithIgnoreCase(after_cm, base_name) and
                        after_cm.len > base_name.len and after_cm[base_name.len] == '.')
                    {
                        // Extract DeveloperName from filename: <BaseName>.<RecordName>.md-meta.xml
                        const after_dot =
                            after_cm[base_name.len + 1 ..]; // "RecordName.md-meta.xml"
                        const dev_name_raw = if (std.mem.indexOf(u8, after_dot, ".")) |next_dot|
                            after_dot[0..next_dot]
                        else
                            after_dot;
                        // Duplicate on arena since walker memory is temporary
                        const dev_name = self.arena.dupe(u8, dev_name_raw) catch continue;

                        const full_path = std.fmt.allocPrint(
                            self.arena,
                            "{s}/{s}",
                            .{ sp, entry.path },
                        ) catch continue;
                        const content = std.Io.Dir.cwd().readFileAlloc(
                            self.io,
                            full_path,
                            self.arena,
                            .limited(1024 * 1024),
                        ) catch continue;
                        if (try self.parse_custom_metadata_xml(mdt_type, content)) |sob| {
                            // Set DeveloperName from filename
                            try sob.fields.put(
                                self.arena,
                                "DeveloperName",
                                Value{ .string = dev_name },
                            );
                            const gop = try self.store.getOrPut(self.arena, mdt_type);
                            if (!gop.found_existing) gop.value_ptr.* = .empty;
                            try gop.value_ptr.append(self.arena, Value{ .sobject = sob });
                        }
                    }
                }
            }
        }
    }

    /// Parse a single .md-meta.xml file and return an SObject with the field values.
    fn parse_custom_metadata_xml(
        self: *Evaluator,
        mdt_type: []const u8,
        xml: []const u8,
    ) !?*types.SObject {
        const sob = try self.arena.create(types.SObject);
        sob.* = .{ .type_name = mdt_type };
        const id = try self.alloc_id();
        sob.id = id;
        try sob.fields.put(self.arena, "Id", Value{ .string = id });

        // Simple XML parser: find <values><field>...</field><value ...>...</value></values> pairs
        var pos: usize = 0;
        while (pos < xml.len) {
            // Find <field>...</field>
            const field_start_tag = std.mem.indexOfPos(u8, xml, pos, "<field>") orelse break;
            const field_content_start = field_start_tag + "<field>".len;
            const field_end_tag = std.mem.indexOfPos(
                u8,
                xml,
                field_content_start,
                "</field>",
            ) orelse break;
            const field_name = std.mem.trim(u8, xml[field_content_start..field_end_tag], " \t\n\r");

            // Find corresponding <value ...>...</value>
            const value_search_start = field_end_tag + "</field>".len;
            const values_end = std.mem.indexOfPos(
                u8,
                xml,
                value_search_start,
                "</values>",
            ) orelse break;

            // Look for <value ...>content</value> within this <values> block
            // First check for xsi:nil="true" (self-closing tag: <value xsi:nil="true"/>)
            const val_region = xml[value_search_start..values_end];
            if (std.mem.indexOf(u8, val_region, "xsi:nil") != null) {
                // Field is explicitly null — skip it
                pos = values_end + "</values>".len;
                continue;
            }
            if (std.mem.indexOfPos(u8, xml, value_search_start, ">")) |val_tag_end| {
                if (val_tag_end < values_end) {
                    const val_content_start = val_tag_end + 1;
                    if (std.mem.indexOfPos(u8, xml, val_content_start, "</value>")) |val_end| {
                        if (val_end <= values_end) {
                            const field_value = std.mem.trim(
                                u8,
                                xml[val_content_start..val_end],
                                " \t\n\r",
                            );
                            // Determine value type from xsi:type attribute in the <value> tag
                            const val_tag = xml[value_search_start..val_tag_end];
                            const typed_value: Value =
                                if (std.mem.indexOf(u8, val_tag, "xsd:boolean") != null)
                                    Value{ .boolean = std.ascii.eqlIgnoreCase(field_value, "true") }
                                else if (std.mem.indexOf(u8, val_tag, "xsd:double") != null or
                                std.mem.indexOf(u8, val_tag, "xsd:decimal") != null)
                                    if (std.fmt.parseFloat(f64, field_value)) |f| Value{ .double = f } else |_| Value{ .string = field_value }
                                else if (std.mem.indexOf(u8, val_tag, "xsd:int") != null)
                                    if (std.fmt.parseInt(i64, field_value, 10)) |i| Value{ .integer = i } else |_| Value{ .string = field_value }
                                else
                                    Value{ .string = field_value };
                            try sob.fields.put(self.arena, field_name, typed_value);
                            // Also create __r relationship for fields that reference
                            // FieldDefinitions
                            // Convention: Customer_Name__c → value is the API name of a field
                            // Create Customer_Name__r as a FieldDefinition with QualifiedAPIName =
                            // value
                            if (std.mem.endsWith(u8, field_name, "__c") and field_name.len > 3) {
                                const base = field_name[0 .. field_name.len - 3];
                                const rel_name = try std.fmt.allocPrint(
                                    self.arena,
                                    "{s}__r",
                                    .{base},
                                );
                                const fd = try self.arena.create(types.SObject);
                                fd.* = .{ .type_name = "FieldDefinition" };
                                try fd.fields.put(
                                    self.arena,
                                    "QualifiedAPIName",
                                    Value{ .string = field_value },
                                );
                                try sob.fields.put(self.arena, rel_name, Value{ .sobject = fd });
                            }
                        }
                    }
                }
            }

            pos = values_end + "</values>".len;
        }

        // Extract label
        if (std.mem.indexOf(u8, xml, "<label>")) |label_start| {
            const label_content = label_start + "<label>".len;
            if (std.mem.indexOfPos(u8, xml, label_content, "</label>")) |label_end| {
                try sob.fields.put(
                    self.arena,
                    "Label",
                    Value{ .string = std.mem.trim(u8, xml[label_content..label_end], " \t\n\r") },
                );
                try sob.fields.put(
                    self.arena,
                    "MasterLabel",
                    Value{ .string = std.mem.trim(u8, xml[label_content..label_end], " \t\n\r") },
                );
            }
        }

        return sob;
    }

    fn xml_tag_value(self: *Evaluator, xml: []const u8, tag_name: []const u8) ?[]const u8 {
        const start_tag = std.fmt.allocPrint(self.arena, "<{s}>", .{tag_name}) catch return null;
        const end_tag = std.fmt.allocPrint(self.arena, "</{s}>", .{tag_name}) catch return null;
        const start = std.mem.indexOf(u8, xml, start_tag) orelse return null;
        const value_start = start + start_tag.len;
        const value_end = std.mem.indexOfPos(u8, xml, value_start, end_tag) orelse return null;
        return std.mem.trim(u8, xml[value_start..value_end], " \t\n\r");
    }

    fn xml_tag_bool_value(self: *Evaluator, xml: []const u8, tag_name: []const u8) ?bool {
        const raw = self.xml_tag_value(xml, tag_name) orelse return null;
        if (std.ascii.eqlIgnoreCase(raw, "true")) return true;
        if (std.ascii.eqlIgnoreCase(raw, "false")) return false;
        return null;
    }

    fn append_store_record(self: *Evaluator, type_name: []const u8, record: *types.SObject) !void {
        const gop = try self.store.getOrPut(self.arena, type_name);
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        try gop.value_ptr.append(self.arena, Value{ .sobject = record });
    }

    fn find_permission_set_record_by_name(
        self: *Evaluator,
        permission_set_name: []const u8,
    ) ?Value {
        const permission_sets = self.store.get("PermissionSet") orelse return null;
        for (permission_sets.items) |item| {
            if (item != .sobject) continue;
            const name_val = utils.sobject_get(&item.sobject.fields, "Name") orelse continue;
            if (name_val != .string) continue;
            if (std.ascii.eqlIgnoreCase(name_val.string, permission_set_name)) return item;
        }
        return null;
    }

    fn composite_permission_field_components(field_name: []const u8) ?[]const []const u8 {
        if (std.ascii.eqlIgnoreCase(field_name, "BillingAddress")) {
            return &.{ "BillingStreet", "BillingCity", "BillingState", "BillingPostalCode", "BillingCountry" };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "ShippingAddress")) {
            return &.{ "ShippingStreet", "ShippingCity", "ShippingState", "ShippingPostalCode", "ShippingCountry" };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "MailingAddress")) {
            return &.{ "MailingStreet", "MailingCity", "MailingState", "MailingPostalCode", "MailingCountry" };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "OtherAddress")) {
            return &.{ "OtherStreet", "OtherCity", "OtherState", "OtherPostalCode", "OtherCountry" };
        }
        return null;
    }

    fn append_expanded_permission_fields(
        self: *Evaluator,
        expanded: *std.ArrayListUnmanaged([]const u8),
        full_field_name: []const u8,
    ) !void {
        try expanded.append(self.arena, full_field_name);
        const dot = std.mem.lastIndexOfScalar(u8, full_field_name, '.') orelse return;
        const object_name = full_field_name[0..dot];
        const field_name = full_field_name[dot + 1 ..];
        const components = composite_permission_field_components(field_name) orelse return;
        for (components) |component_name| {
            try expanded.append(
                self.arena,
                try std.fmt.allocPrint(self.arena, "{s}.{s}", .{ object_name, component_name }),
            );
        }
    }

    fn load_permission_set_metadata_from_files(self: *Evaluator, requested_name: []const u8) !void {
        if (self.find_permission_set_record_by_name(requested_name) != null) return;

        for (self.source_paths) |sp| {
            var dir = std.Io.Dir.cwd().openDir(self.io, sp, .{ .iterate = true }) catch continue;
            defer dir.close(self.io);

            var walker = dir.walk(self.arena) catch continue;
            defer walker.deinit();

            while (walker.next(self.io) catch null) |entry| {
                if (entry.kind != .file) continue;
                if (std.mem.indexOf(u8, entry.path, "permissionsets/") == null) continue;
                if (!std.mem.endsWith(u8, entry.path, ".permissionset-meta.xml")) continue;

                const file_name = std.fs.path.basename(entry.path);
                const suffix = ".permissionset-meta.xml";
                if (file_name.len <= suffix.len) continue;
                const permission_set_name = file_name[0 .. file_name.len - suffix.len];
                if (!std.ascii.eqlIgnoreCase(permission_set_name, requested_name)) continue;

                const full_path = std.fmt.allocPrint(
                    self.arena,
                    "{s}/{s}",
                    .{ sp, entry.path },
                ) catch continue;
                const xml = std.Io.Dir.cwd().readFileAlloc(
                    self.io,
                    full_path,
                    self.arena,
                    .limited(1024 * 1024),
                ) catch continue;
                if (self.find_permission_set_record_by_name(permission_set_name) != null) return;

                const permission_set = try self.arena.create(types.SObject);
                const permission_set_id = try self.alloc_id();
                permission_set.* = .{ .type_name = "PermissionSet", .id = permission_set_id };
                try permission_set.fields.put(
                    self.arena,
                    "Id",
                    Value{ .string = permission_set_id },
                );
                try permission_set.fields.put(
                    self.arena,
                    "Name",
                    Value{ .string = try self.arena.dupe(u8, permission_set_name) },
                );
                try permission_set.fields.put(
                    self.arena,
                    "Label",
                    Value{ .string = try self.arena.dupe(
                        u8,
                        self.xml_tag_value(xml, "label") orelse permission_set_name,
                    ) },
                );
                try self.append_store_record("PermissionSet", permission_set);

                var object_pos: usize = 0;
                while (object_pos < xml.len) {
                    const block_start = std.mem.indexOfPos(
                        u8,
                        xml,
                        object_pos,
                        "<objectPermissions>",
                    ) orelse break;
                    const block_content_start = block_start + "<objectPermissions>".len;
                    const block_end = std.mem.indexOfPos(
                        u8,
                        xml,
                        block_content_start,
                        "</objectPermissions>",
                    ) orelse break;
                    const block = xml[block_content_start..block_end];

                    const object_name = self.xml_tag_value(block, "object") orelse {
                        object_pos = block_end + "</objectPermissions>".len;
                        continue;
                    };

                    const object_permission = try self.arena.create(types.SObject);
                    object_permission.* = .{ .type_name = "ObjectPermissions", .id = try self.alloc_id() };
                    try object_permission.fields.put(
                        self.arena,
                        "Id",
                        Value{ .string = object_permission.id.? },
                    );
                    try object_permission.fields.put(
                        self.arena,
                        "ParentId",
                        Value{ .string = permission_set_id },
                    );
                    try object_permission.fields.put(
                        self.arena,
                        "SobjectType",
                        Value{ .string = try self.arena.dupe(u8, object_name) },
                    );
                    try object_permission.fields.put(self.arena, "PermissionsRead", Value{ .boolean = self.xml_tag_bool_value(block, "allowRead") orelse false });
                    try object_permission.fields.put(self.arena, "PermissionsCreate", Value{ .boolean = self.xml_tag_bool_value(block, "allowCreate") orelse false });
                    try object_permission.fields.put(self.arena, "PermissionsEdit", Value{ .boolean = self.xml_tag_bool_value(block, "allowEdit") orelse false });
                    try object_permission.fields.put(self.arena, "PermissionsDelete", Value{ .boolean = self.xml_tag_bool_value(block, "allowDelete") orelse false });
                    try self.append_store_record("ObjectPermissions", object_permission);

                    object_pos = block_end + "</objectPermissions>".len;
                }

                var field_pos: usize = 0;
                while (field_pos < xml.len) {
                    const block_start = std.mem.indexOfPos(
                        u8,
                        xml,
                        field_pos,
                        "<fieldPermissions>",
                    ) orelse break;
                    const block_content_start = block_start + "<fieldPermissions>".len;
                    const block_end = std.mem.indexOfPos(
                        u8,
                        xml,
                        block_content_start,
                        "</fieldPermissions>",
                    ) orelse break;
                    const block = xml[block_content_start..block_end];

                    const full_field_name = self.xml_tag_value(block, "field") orelse {
                        field_pos = block_end + "</fieldPermissions>".len;
                        continue;
                    };

                    var expanded_fields: std.ArrayListUnmanaged([]const u8) = .empty;
                    try self.append_expanded_permission_fields(&expanded_fields, full_field_name);
                    for (expanded_fields.items) |expanded_field_name| {
                        const field_permission = try self.arena.create(types.SObject);
                        field_permission.* = .{ .type_name = "FieldPermissions", .id = try self.alloc_id() };
                        try field_permission.fields.put(
                            self.arena,
                            "Id",
                            Value{ .string = field_permission.id.? },
                        );
                        try field_permission.fields.put(
                            self.arena,
                            "ParentId",
                            Value{ .string = permission_set_id },
                        );
                        try field_permission.fields.put(
                            self.arena,
                            "Field",
                            Value{ .string = try self.arena.dupe(u8, expanded_field_name) },
                        );
                        try field_permission.fields.put(self.arena, "PermissionsRead", Value{ .boolean = self.xml_tag_bool_value(block, "readable") orelse false });
                        try field_permission.fields.put(self.arena, "PermissionsCreate", Value{ .boolean = self.xml_tag_bool_value(block, "editable") orelse false });
                        try field_permission.fields.put(self.arena, "PermissionsEdit", Value{ .boolean = self.xml_tag_bool_value(block, "editable") orelse false });
                        try self.append_store_record("FieldPermissions", field_permission);
                    }

                    field_pos = block_end + "</fieldPermissions>".len;
                }

                return;
            }
        }
    }

    /// Execute an aggregate SOQL query (with SUM/AVG/MIN/MAX/COUNT and optional GROUP BY).
    /// Returns List<AggregateResult>.
    fn execute_aggregate_query(
        self: *Evaluator,
        soql: []const u8,
        current_env: *Env,
        include_all_rows: bool,
    ) !Value {
        const from_type_agg = extract_from_type(soql) orelse return self.make_empty_list();
        const select_start = if (std.ascii.indexOfIgnoreCase(soql, "SELECT")) |si| si + 6 else 0;
        const from_start = std.ascii.indexOfIgnoreCase(soql, "FROM") orelse soql.len;
        const select_clause = std.mem.trim(u8, soql[select_start..from_start], " \t\n\r");

        // Parse GROUP BY field(s)
        const group_by_idx = std.ascii.indexOfIgnoreCase(soql, "group by");
        var group_by_fields: [8][]const u8 = undefined;
        var group_by_count: usize = 0;
        if (group_by_idx) |gbi| {
            const gb_clause = std.mem.trim(u8, soql[gbi + 8 ..], " \t\n\r");
            var gb_iter = std.mem.splitScalar(u8, gb_clause, ',');
            while (gb_iter.next()) |raw_f| {
                const f = std.mem.trim(u8, raw_f, " \t\n\r");
                if (f.len == 0) continue;
                if (group_by_count < group_by_fields.len) {
                    group_by_fields[group_by_count] = f;
                    group_by_count += 1;
                }
            }
        }

        // Parse aggregate functions from SELECT clause
        // e.g., "LogPurgeAction__c LogPurgeAction__c, count(id)"
        // Each item is either a plain field (with optional alias) or FUNC(field) alias
        const AggItem = struct {
            fn_name: ?[]const u8, // null = plain field, "COUNT"/"SUM"/etc.
            field: []const u8,
            alias: []const u8,
        };
        var agg_items: [16]AggItem = undefined;
        var agg_count: usize = 0;
        {
            var expr_idx: usize = 0;
            var sel_iter = std.mem.splitScalar(u8, select_clause, ',');
            while (sel_iter.next()) |raw_item| {
                const item = std.mem.trim(u8, raw_item, " \t\n\r");
                if (item.len == 0) continue;
                if (agg_count >= agg_items.len) break;
                if (std.mem.indexOf(u8, item, "(")) |paren_start| {
                    // Aggregate function: FUNC(field) [alias]
                    const fn_name = std.mem.trim(u8, item[0..paren_start], " \t\n\r");
                    if (std.mem.indexOf(u8, item[paren_start..], ")")) |paren_end_rel| {
                        const paren_end = paren_start + paren_end_rel;
                        const field = std.mem.trim(
                            u8,
                            item[paren_start + 1 .. paren_end],
                            " \t\n\r",
                        );
                        const after = std.mem.trim(u8, item[paren_end + 1 ..], " \t\n\r");
                        const alias = if (after.len > 0) after else try std.fmt.allocPrint(
                            self.arena,
                            "expr{d}",
                            .{expr_idx},
                        );
                        agg_items[agg_count] = .{ .fn_name = fn_name, .field = field, .alias = alias };
                        agg_count += 1;
                        expr_idx += 1;
                    }
                } else {
                    // Plain field [alias] — e.g., "LogPurgeAction__c LogPurgeAction__c"
                    var parts = std.mem.splitScalar(u8, item, ' ');
                    const field = parts.next() orelse item;
                    const alias = parts.next() orelse field;
                    agg_items[agg_count] = .{ .fn_name = null, .field = field, .alias = alias };
                    agg_count += 1;
                }
            }
        }

        // Collect matching records
        var matched: std.ArrayListUnmanaged(Value) = .empty;
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, from_type_agg)) {
                for (entry.value_ptr.items) |record| {
                    if (self.matches_where(record, soql, current_env))
                        try matched.append(self.arena, record);
                }
                break;
            }
        }
        // Include trashed records when ALL ROWS was present on the aggregate query
        // (the outer execute_soql strips the keyword before delegating here, so we
        // receive the decision as an explicit parameter instead of re-parsing).
        if (include_all_rows) {
            var trash_iter = self.trash.iterator();
            while (trash_iter.next()) |entry| {
                if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, from_type_agg)) {
                    for (entry.value_ptr.items) |record| {
                        if (self.matches_where(record, soql, current_env))
                            try matched.append(self.arena, record);
                    }
                    break;
                }
            }
        }

        if (group_by_count == 0) {
            // No GROUP BY — single aggregate result over all matched records
            const agg = try self.arena.create(types.SObject);
            agg.* = .{ .type_name = "AggregateResult" };
            for (agg_items[0..agg_count]) |ai| {
                if (ai.fn_name) |fn_name| {
                    try agg.fields.put(
                        self.arena,
                        ai.alias,
                        self.compute_aggregate(fn_name, ai.field, matched.items),
                    );
                }
            }
            const result_list = try self.arena.create(types.ListValue);
            result_list.* = .{};
            try result_list.items.append(self.arena, Value{ .sobject = agg });
            return Value{ .list = result_list };
        }

        // GROUP BY: bucket records by group key(s)
        // Use string key for grouping (concatenation of field values)
        var group_keys: std.ArrayListUnmanaged([]const u8) = .empty;
        var group_records: std.ArrayListUnmanaged(std.ArrayListUnmanaged(Value)) = .empty;

        for (matched.items) |record| {
            // Build group key from GROUP BY fields
            var key_buf: std.ArrayListUnmanaged(u8) = .empty;
            for (group_by_fields[0..group_by_count]) |gb_field| {
                if (key_buf.items.len > 0) try key_buf.append(self.arena, '|');
                const fv = self.resolve_field_path(record, gb_field);
                const fv_str = if (fv != null and fv.? != .null_val)
                    (utils.coerce_to_string(fv.?, self.arena) catch "")
                else
                    "";
                try key_buf.appendSlice(self.arena, fv_str);
            }
            const key = key_buf.items;

            // Find or create group
            var found = false;
            for (group_keys.items, 0..) |gk, idx| {
                if (std.mem.eql(u8, gk, key)) {
                    try group_records.items[idx].append(self.arena, record);
                    found = true;
                    break;
                }
            }
            if (!found) {
                try group_keys.append(self.arena, key);
                var new_group: std.ArrayListUnmanaged(Value) = .empty;
                try new_group.append(self.arena, record);
                try group_records.append(self.arena, new_group);
            }
        }

        // Build AggregateResult per group
        const result_list = try self.arena.create(types.ListValue);
        result_list.* = .{};
        for (group_records.items, 0..) |group, gi| {
            _ = gi;
            const agg = try self.arena.create(types.SObject);
            agg.* = .{ .type_name = "AggregateResult" };
            for (agg_items[0..agg_count]) |ai| {
                if (ai.fn_name) |fn_name| {
                    try agg.fields.put(
                        self.arena,
                        ai.alias,
                        self.compute_aggregate(fn_name, ai.field, group.items),
                    );
                } else {
                    // Plain field: take from first record in group, resolving dotted paths
                    if (group.items.len > 0) {
                        const fv = self.resolve_field_path(
                            group.items[0],
                            ai.field,
                        ) orelse Value.null_val;
                        try agg.fields.put(self.arena, ai.alias, fv);
                    }
                }
            }
            try result_list.items.append(self.arena, Value{ .sobject = agg });
        }
        return Value{ .list = result_list };
    }

    /// Compute a single aggregate value (COUNT/SUM/AVG/MIN/MAX) over a set of records.
    fn compute_aggregate(
        self: *Evaluator,
        fn_name: []const u8,
        field: []const u8,
        records: []const Value,
    ) Value {
        _ = self;
        if (std.ascii.eqlIgnoreCase(fn_name, "COUNT")) {
            var count: i64 = 0;
            for (records) |r| {
                if (r == .sobject) {
                    // COUNT(Id) or COUNT(field) — count non-null values
                    if (utils.sobject_get(&r.sobject.fields, field)) |v| {
                        if (v != .null_val) count += 1;
                    } else if (std.ascii.eqlIgnoreCase(field, "Id") and r.sobject.id != null) {
                        count += 1;
                    }
                }
            }
            return Value{ .integer = count };
        }
        // SUM, AVG, MIN, MAX
        var sum: f64 = 0;
        var count: i64 = 0;
        var min_val: ?f64 = null;
        var max_val: ?f64 = null;
        for (records) |r| {
            if (r == .sobject) {
                if (utils.sobject_get(&r.sobject.fields, field)) |fv| {
                    const num: ?f64 = if (fv == .double) fv.double else if (fv == .integer) @floatFromInt(fv.integer) else null;
                    if (num) |n| {
                        sum += n;
                        count += 1;
                        if (min_val == null or n < min_val.?) min_val = n;
                        if (max_val == null or n > max_val.?) max_val = n;
                    }
                }
            }
        }
        if (std.ascii.eqlIgnoreCase(fn_name, "SUM")) return Value{ .double = sum };
        if (std.ascii.eqlIgnoreCase(fn_name, "AVG")) return if (count > 0) Value{ .double = sum / @as(f64, @floatFromInt(count)) } else Value{ .double = 0 };
        if (std.ascii.eqlIgnoreCase(fn_name, "MIN"))
            return if (min_val) |v| Value{ .double = v } else Value.null_val;
        if (std.ascii.eqlIgnoreCase(fn_name, "MAX"))
            return if (max_val) |v| Value{ .double = v } else Value.null_val;
        return Value{ .integer = count };
    }

    /// Resolve a dotted field path like "Log__r.LogPurgeAction__c" on a record.
    fn resolve_field_path(self: *Evaluator, record: Value, path: []const u8) ?Value {
        if (record != .sobject) return null;
        if (std.mem.indexOfScalar(u8, path, '.') == null) {
            return self.get_s_object_field_value_case_insensitive(record.sobject, path);
        }
        return self.resolve_field_path_value(record.sobject, path);
    }

    /// Execute a SOSL query using fixed search results.
    /// Returns List<List<SObject>> - one list per RETURNING type.
    fn execute_sosl(self: *Evaluator, sosl: []const u8) !Value {
        // Parse RETURNING clause to find type names
        // e.g., FIND 'search' IN ALL FIELDS RETURNING Account(Name), Contact(LastName)
        var type_names: [8][]const u8 = undefined;
        var type_count: usize = 0;
        if (std.ascii.indexOfIgnoreCase(sosl, "RETURNING")) |ret_pos| {
            const returning = sosl[ret_pos + 9 ..];
            var iter = std.mem.splitScalar(u8, returning, ',');
            while (iter.next()) |part| {
                const trimmed = std.mem.trim(u8, part, " \t\n\r");
                if (trimmed.len == 0) continue;
                // Extract type name (before parenthesis)
                var end: usize = 0;
                while (end < trimmed.len and trimmed[end] != '(' and trimmed[end] != ' ') end += 1;
                if (end > 0 and type_count < type_names.len) {
                    type_names[type_count] = trimmed[0..end];
                    type_count += 1;
                }
            }
        }

        // Build result: List<List<SObject>>
        const outer = try self.arena.create(types.ListValue);
        outer.* = .{};

        // Get fixed search result Ids
        var search_ids: std.ArrayListUnmanaged([]const u8) = .empty;
        if (self.fixed_search_results) |fsr| {
            if (fsr == .list) {
                for (fsr.list.items.items) |item| {
                    if (item == .string) {
                        try search_ids.append(self.arena, item.string);
                    }
                }
            }
        }

        // For each RETURNING type, find matching records from store (or metadata stubs)
        for (type_names[0..type_count]) |type_name| {
            const inner = try self.arena.create(types.ListValue);
            inner.* = .{};
            var found_in_store = false;
            var store_iter = self.store.iterator();
            while (store_iter.next()) |entry| {
                if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, type_name)) {
                    found_in_store = true;
                    for (entry.value_ptr.items) |record| {
                        if (record == .sobject and record.sobject.id != null) {
                            // Check if Id is in fixed search results (or no filter)
                            if (search_ids.items.len == 0) {
                                try inner.items.append(self.arena, record);
                            } else {
                                for (search_ids.items) |sid| {
                                    if (std.ascii.eqlIgnoreCase(record.sobject.id.?, sid)) {
                                        try inner.items.append(self.arena, record);
                                        break;
                                    }
                                }
                            }
                        }
                    }
                    break;
                }
            }
            // For metadata types not in store, no results returned
            try outer.items.append(self.arena, Value{ .list = inner });
        }

        return Value{ .list = outer };
    }

    fn matches_where(self: *Evaluator, record: Value, soql: []const u8, current_env: *Env) bool {
        const where_clause = extract_where_clause(soql) orelse return true;
        if (record != .sobject) return true;
        return self.eval_where_condition(record.sobject, where_clause, current_env);
    }

    fn extract_where_in_bind_info(
        self: *Evaluator,
        soql: []const u8,
    ) ?struct { field_name: []const u8, bind_name: []const u8 } {
        _ = self;
        const where_clause = extract_where_clause(soql) orelse return null;
        const in_pos = std.ascii.indexOfIgnoreCase(where_clause, " IN :") orelse return null;

        var field_end = in_pos;
        while (field_end > 0 and
            is_soql_whitespace(where_clause[field_end - 1])) : (field_end -= 1)
        {}
        var field_start = field_end;
        while (field_start > 0) {
            const ch = where_clause[field_start - 1];
            if (std.ascii.isAlphanumeric(ch) or ch == '_' or ch == '.') {
                field_start -= 1;
            } else break;
        }
        if (field_start == field_end) return null;

        var bind_start = in_pos + " IN :".len;
        while (bind_start < where_clause.len and
            is_soql_whitespace(where_clause[bind_start])) : (bind_start += 1)
        {}
        var bind_end = bind_start;
        while (bind_end < where_clause.len and (std.ascii.isAlphanumeric(where_clause[bind_end]) or where_clause[bind_end] == '_')) : (bind_end += 1) {}
        if (bind_end == bind_start) return null;

        return .{
            .field_name = where_clause[field_start..field_end],
            .bind_name = where_clause[bind_start..bind_end],
        };
    }

    fn reorder_records_by_in_bind(
        self: *Evaluator,
        records: *std.ArrayListUnmanaged(Value),
        field_name: []const u8,
        bind_val: Value,
    ) !void {
        if (records.items.len <= 1) return;

        const bind_items: []const Value = switch (bind_val) {
            .list => bind_val.list.items.items,
            .set => bind_val.set.entries.values(),
            else => return,
        };
        if (bind_items.len == 0) return;

        const consumed = try self.arena.alloc(bool, records.items.len);
        @memset(consumed, false);

        var reordered: std.ArrayListUnmanaged(Value) = .empty;

        for (bind_items) |bind_item| {
            const expected =
                if (bind_item == .sobject and std.ascii.eqlIgnoreCase(field_name, "Id")) blk: {
                    if (self.sobject_id_for_result(bind_item.sobject)) |record_id| {
                        break :blk Value{ .string = record_id };
                    }
                    break :blk bind_item;
                } else bind_item;

            for (records.items, 0..) |record, idx| {
                if (consumed[idx] or record != .sobject) continue;
                const actual = if (std.ascii.eqlIgnoreCase(field_name, "Id")) blk: {
                    if (self.sobject_id_for_result(record.sobject)) |record_id| {
                        break :blk Value{ .string = record_id };
                    }
                    break :blk self.get_s_object_field_value_case_insensitive(
                        record.sobject,
                        field_name,
                    ) orelse Value.null_val;
                } else self.get_s_object_field_value_case_insensitive(
                    record.sobject,
                    field_name,
                ) orelse Value.null_val;
                if (utils.value_eql(actual, expected)) {
                    try reordered.append(self.arena, record);
                    consumed[idx] = true;
                    break;
                }
            }
        }

        for (records.items, 0..) |record, idx| {
            if (!consumed[idx]) try reordered.append(self.arena, record);
        }

        records.* = reordered;
    }

    fn bind_collection_contains(self: *Evaluator, field_val: Value, bind_val: Value) bool {
        switch (bind_val) {
            .list => |list| {
                for (list.items.items) |item| {
                    if (utils.value_eql(field_val, item)) return true;
                    if (field_val == .string and item == .sobject) {
                        if (item.sobject.id) |item_id| {
                            if (std.ascii.eqlIgnoreCase(field_val.string, item_id)) return true;
                        }
                    }
                }
                return false;
            },
            .map => |map| {
                if (field_val == .string) {
                    for (map.entries.keys()) |key| {
                        if (std.ascii.eqlIgnoreCase(field_val.string, key)) return true;
                    }
                }
                return false;
            },
            .set => {
                const field_str = utils.coerce_to_string(field_val, self.arena) catch return false;
                return bind_val.set.entries.contains(field_str);
            },
            else => return false,
        }
    }

    fn eval_where_condition(
        self: *Evaluator,
        sob: *types.SObject,
        clause: []const u8,
        current_env: *Env,
    ) bool {
        const trimmed = std.mem.trim(u8, clause, " \t\n\r");
        if (trimmed.len == 0) return true;

        // Handle AND
        if (find_logical_op(trimmed, "AND")) |and_pos| {
            const left_part = trimmed[0..and_pos];
            const right_part = trimmed[and_pos + 3 ..];
            return self.eval_where_condition(sob, left_part, current_env) and
                self.eval_where_condition(sob, right_part, current_env);
        }

        // Handle OR
        if (find_logical_op(trimmed, "OR")) |or_pos| {
            const left_part = trimmed[0..or_pos];
            const right_part = trimmed[or_pos + 2 ..];
            return self.eval_where_condition(sob, left_part, current_env) or
                self.eval_where_condition(sob, right_part, current_env);
        }

        // Strip outer parens
        if (trimmed.len > 2 and trimmed[0] == '(') {
            // Find matching paren
            var depth: u32 = 0;
            var all_enclosed = false;
            for (trimmed, 0..) |ch, i| {
                if (ch == '(') depth += 1;
                if (ch == ')') {
                    depth -= 1;
                    if (depth == 0 and i == trimmed.len - 1) all_enclosed = true;
                }
            }
            if (all_enclosed) {
                return self.eval_where_condition(sob, trimmed[1 .. trimmed.len - 1], current_env);
            }
        }

        // Simple condition: field = 'value' or field = :bindVar or field != 'value'
        return self.eval_simple_condition(sob, trimmed, current_env);
    }

    fn eval_simple_condition(
        self: *Evaluator,
        sob: *types.SObject,
        cond: []const u8,
        current_env: *Env,
    ) bool {
        // Parse: field OP value
        // Find operator
        var op_pos: ?usize = null;
        var op_len: usize = 1;
        var is_neq = false;
        var is_like = false;
        var is_in = false;
        var is_gt = false;
        var is_gte = false;
        var is_lt = false;
        var is_lte = false;

        var i: usize = 0;
        while (i < cond.len) : (i += 1) {
            if (i + 1 < cond.len and cond[i] == '>' and cond[i + 1] == '=') {
                op_pos = i;
                op_len = 2;
                is_gte = true;
                break;
            }
            if (i + 1 < cond.len and cond[i] == '<' and cond[i + 1] == '=') {
                op_pos = i;
                op_len = 2;
                is_lte = true;
                break;
            }
            if (cond[i] == '>' and (i + 1 >= cond.len or cond[i + 1] != '=')) {
                op_pos = i;
                op_len = 1;
                is_gt = true;
                break;
            }
            if (cond[i] == '<' and
                (i + 1 >= cond.len or (cond[i + 1] != '=' and cond[i + 1] != '>')))
            {
                op_pos = i;
                op_len = 1;
                is_lt = true;
                break;
            }
            if (cond[i] == '=' and
                (i == 0 or cond[i - 1] != '!' and cond[i - 1] != '<' and cond[i - 1] != '>'))
            {
                op_pos = i;
                op_len = 1;
                break;
            }
            if (i + 1 < cond.len and cond[i] == '!' and cond[i + 1] == '=') {
                op_pos = i;
                op_len = 2;
                is_neq = true;
                break;
            }
            if (i + 1 < cond.len and cond[i] == '<' and cond[i + 1] == '>') {
                op_pos = i;
                op_len = 2;
                is_neq = true;
                break;
            }
            if (i + 4 <= cond.len and std.ascii.eqlIgnoreCase(cond[i .. i + 4], "LIKE")) {
                if ((i == 0 or cond[i - 1] == ' ') and (i + 4 >= cond.len or cond[i + 4] == ' ')) {
                    op_pos = i;
                    op_len = 4;
                    is_like = true;
                    break;
                }
            }
            if (i + 2 <= cond.len and std.ascii.eqlIgnoreCase(cond[i .. i + 2], "IN")) {
                if ((i == 0 or cond[i - 1] == ' ') and (i + 2 >= cond.len or cond[i + 2] == ' ')) {
                    op_pos = i;
                    op_len = 2;
                    is_in = true;
                    break;
                }
            }
        }

        const op_start = op_pos orelse return true; // can't parse, include record
        const field_name = std.mem.trim(u8, cond[0..op_start], " \t\n\r");
        const value_str = std.mem.trim(u8, cond[op_start + op_len ..], " \t\n\r");

        // Get field value from record (case-insensitive), supporting dotted parent refs
        var field_val: Value = Value.null_val;
        var field_found = false;
        if (std.mem.indexOf(u8, field_name, ".")) |_| {
            if (self.resolve_field_path_value(sob, field_name)) |resolved| {
                field_val = resolved;
                field_found = true;
            }
        } else {
            if (self.get_s_object_field_value_case_insensitive(sob, field_name)) |resolved| {
                field_val = resolved;
                field_found = true;
            }
        }
        if (!field_found) {
            // IsDeleted defaults to FALSE for records in the active store
            if (std.ascii.eqlIgnoreCase(field_name, "IsDeleted")) {
                field_val = Value{ .boolean = false };
                field_found = true;
            }
        }
        if (!field_found) {
            if (self.has_where_field_null_literal(cond, field_name)) {
                return !is_neq;
            }
            // Check if the comparison value is a null bind variable → skip condition
            if (value_str.len > 0 and value_str[0] == ':') {
                const bv_name = value_str[1..];
                if (self.lookup_bind_value(current_env, bv_name)) |bv| {
                    if (bv == .null_val) return true; // null bind → include record
                }
            }
            return if (is_neq) true else false;
        }

        if (is_like) {
            // LIKE support: '%xxx%' → contains, 'xxx%' → startsWith, '%xxx' → endsWith
            if (field_val != .string) return false;
            var pattern = std.mem.trim(u8, value_str, " \t\n\r");
            // バインド変数 :type → 環境から値を解決
            if (pattern.len > 0 and pattern[0] == ':') {
                const var_name = pattern[1..];
                if (self.lookup_bind_value(current_env, var_name)) |bind_val| {
                    if (bind_val == .string) {
                        pattern = bind_val.string;
                    } else return false;
                } else return false;
            }
            if (pattern.len >= 2 and pattern[0] == '\'') pattern = pattern[1..];
            if (pattern.len >= 1 and pattern[pattern.len - 1] == '\'')
                pattern = pattern[0 .. pattern.len - 1];
            pattern = self.collapse_like_wildcards(pattern);
            if (pattern.len == 0) return field_val.string.len == 0;
            var non_wildcard_len: usize = 0;
            for (pattern) |ch| {
                if (ch != '%') non_wildcard_len += 1;
            }
            if (non_wildcard_len == 0) return true;
            const starts_wild = pattern.len > 0 and pattern[0] == '%';
            const ends_wild = pattern.len > 0 and pattern[pattern.len - 1] == '%';
            const inner = pattern[@intFromBool(
                starts_wild,
            ) .. pattern.len - @intFromBool(ends_wild)];
            if (starts_wild and ends_wild) {
                return std.ascii.indexOfIgnoreCase(field_val.string, inner) != null;
            } else if (starts_wild) {
                return std.ascii.endsWithIgnoreCase(field_val.string, inner);
            } else if (ends_wild) {
                return std.ascii.startsWithIgnoreCase(field_val.string, inner);
            }
            return std.ascii.eqlIgnoreCase(field_val.string, pattern);
        }

        if (is_in) {
            // IN ('val1', 'val2') or IN :bindVar
            const in_str = std.mem.trim(u8, value_str, " \t\n\r");
            // Handle :bindVar for IN clause
            if (in_str.len > 0 and in_str[0] == ':') {
                const var_name = in_str[1..];
                if (self.lookup_bind_value(current_env, var_name)) |bind_val| {
                    if (self.bind_collection_contains(field_val, bind_val)) return true;
                    if (bind_val == .list or bind_val == .map or bind_val == .set) return false;
                }
            }
            // IN ('val1', 'val2') — parse literal list
            if (std.mem.indexOf(u8, in_str, "(")) |paren_start| {
                const inner = if (std.mem.lastIndexOf(u8, in_str, ")")) |paren_end|
                    in_str[paren_start + 1 .. paren_end]
                else
                    in_str[paren_start + 1 ..];
                if (std.ascii.indexOfIgnoreCase(inner, "SELECT") != null) {
                    return self.subquery_contains_value(field_val, inner, current_env);
                }
                // Split by comma and check each value
                var iter = std.mem.splitScalar(u8, inner, ',');
                while (iter.next()) |part| {
                    const trimmed = std.mem.trim(u8, part, " \t\n\r'");
                    if (field_val == .string and std.ascii.eqlIgnoreCase(field_val.string, trimmed))
                        return true;
                    if (field_val == .integer) {
                        if (std.fmt.parseInt(i64, trimmed, 10)) |int_val| {
                            if (field_val.integer == int_val) return true;
                        } else |_| {}
                    }
                }
                return false;
            }
            return true; // fallback: include all
        }

        // Resolve the comparison value
        var cmp_val: Value = Value.null_val;
        if (value_str.len > 0 and value_str[0] == '\'') {
            // String literal
            if (value_str.len >= 2) {
                // Find closing quote
                var end = value_str.len;
                if (value_str[end - 1] == '\'') end -= 1;
                cmp_val = Value{ .string = value_str[1..end] };
            }
        } else if (value_str.len > 0 and value_str[0] == ':') {
            // Bind variable
            const var_name = value_str[1..];
            if (self.lookup_bind_value(current_env, var_name)) |bind_val| {
                cmp_val = bind_val;
                if (cmp_val == .null_val and !is_neq) return true;
            } else if (std.mem.indexOf(u8, var_name, ".")) |dot_pos| {
                // Fallback for older dotted bind handling when expression parsing
                // does not resolve the value directly.
                const base_name = var_name[0..dot_pos];
                const prop_name = var_name[dot_pos + 1 ..];
                // Resolve base value, handling array index access (e.g. "list[0]")
                const base_val = blk: {
                    if (std.mem.indexOf(u8, base_name, "[")) |bracket_pos| {
                        const arr_name = base_name[0..bracket_pos];
                        const idx_end = std.mem.indexOfPos(
                            u8,
                            base_name,
                            bracket_pos,
                            "]",
                        ) orelse break :blk current_env.get(base_name);
                        const idx_str = base_name[bracket_pos + 1 .. idx_end];
                        const idx = std.fmt.parseInt(
                            usize,
                            idx_str,
                            10,
                        ) catch break :blk current_env.get(base_name);
                        const arr_val = current_env.get(
                            arr_name,
                        ) orelse break :blk @as(?Value, null);
                        if (arr_val == .list and idx < arr_val.list.items.items.len) {
                            break :blk @as(?Value, arr_val.list.items.items[idx]);
                        }
                        break :blk @as(?Value, null);
                    }
                    break :blk current_env.get(base_name);
                } orelse return true;
                if (base_val == .sobject) {
                    cmp_val = utils.sobject_get(
                        &base_val.sobject.fields,
                        prop_name,
                    ) orelse return true;
                } else if (base_val == .object) {
                    cmp_val = utils.sobject_get(
                        &base_val.object.fields,
                        prop_name,
                    ) orelse return true;
                } else {
                    return false;
                }
            } else {
                return false;
            }
        } else if (std.fmt.parseInt(i64, std.mem.trim(u8, value_str, " \t\n\r"), 10)) |int_val| {
            cmp_val = Value{ .integer = int_val };
        } else |_| {
            // Could be null or enum value
            const trimmed_value = std.mem.trim(u8, value_str, " \t\n\r");
            if (std.ascii.eqlIgnoreCase(trimmed_value, "null")) {
                cmp_val = Value.null_val;
            } else if (std.ascii.eqlIgnoreCase(trimmed_value, "true")) {
                cmp_val = Value{ .boolean = true };
            } else if (std.ascii.eqlIgnoreCase(trimmed_value, "false")) {
                cmp_val = Value{ .boolean = false };
            } else {
                return true; // unknown, include
            }
        }

        if (cmp_val == .list or cmp_val == .map or cmp_val == .set) {
            const contains = self.bind_collection_contains(field_val, cmp_val);
            return if (is_neq) !contains else contains;
        }

        if (is_neq) return !utils.value_eql(field_val, cmp_val);
        if (is_gt or is_gte or is_lt or is_lte) {
            if (builtins.extract_date_string(field_val)) |lhs_date| {
                if (builtins.extract_date_string(cmp_val)) |rhs_date| {
                    const cmp = std.mem.order(u8, lhs_date, rhs_date);
                    if (is_gt) return cmp == .gt;
                    if (is_gte) return cmp == .gt or cmp == .eq;
                    if (is_lt) return cmp == .lt;
                    if (is_lte) return cmp == .lt or cmp == .eq;
                }
            }
            // Numeric comparison
            var lhs: ?f64 = null;
            var rhs: ?f64 = null;
            if (field_val == .integer) lhs = @floatFromInt(field_val.integer);
            if (field_val == .double) lhs = field_val.double;
            if (cmp_val == .integer) rhs = @floatFromInt(cmp_val.integer);
            if (cmp_val == .double) rhs = cmp_val.double;
            // String comparison for dates etc.
            if (field_val == .string and cmp_val == .string) {
                const cmp = std.mem.order(u8, field_val.string, cmp_val.string);
                if (is_gt) return cmp == .gt;
                if (is_gte) return cmp == .gt or cmp == .eq;
                if (is_lt) return cmp == .lt;
                if (is_lte) return cmp == .lt or cmp == .eq;
            }
            if (lhs != null and rhs != null) {
                if (is_gt) return lhs.? > rhs.?;
                if (is_gte) return lhs.? >= rhs.?;
                if (is_lt) return lhs.? < rhs.?;
                if (is_lte) return lhs.? <= rhs.?;
            }
            return false; // incomparable types
        }
        return utils.value_eql(field_val, cmp_val);
    }

    fn subquery_contains_value(
        self: *Evaluator,
        field_val: Value,
        subquery: []const u8,
        current_env: *Env,
    ) bool {
        const select_start = std.ascii.indexOfIgnoreCase(subquery, "SELECT") orelse return false;
        const from_start = std.ascii.indexOfIgnoreCase(subquery, "FROM") orelse return false;
        if (from_start <= select_start + 6) return false;
        const select_clause = std.mem.trim(u8, subquery[select_start + 6 .. from_start], " \t\n\r");
        if (select_clause.len == 0) return false;
        const selected_field =
            std.mem.trim(u8, if (std.mem.indexOfScalar(u8, select_clause, ',')) |comma_pos|
                select_clause[0..comma_pos]
            else
                select_clause, " \t\n\r");

        const subquery_result = self.execute_soql(subquery, current_env) catch return false;
        if (subquery_result != .list) return false;
        for (subquery_result.list.items.items) |item| {
            if (item != .sobject) continue;
            const candidate = if (std.ascii.eqlIgnoreCase(selected_field, "Id"))
                (if (item.sobject.id) |record_id| Value{ .string = record_id } else Value.null_val)
            else
                self.resolve_field_path_value(item.sobject, selected_field) orelse self.get_s_object_field_value_case_insensitive(item.sobject, selected_field) orelse Value.null_val;
            if (utils.value_eql(field_val, candidate)) return true;
        }
        return false;
    }

    fn make_empty_list(self: *Evaluator) !Value {
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        return Value{ .list = list };
    }

    /// Resolve the child SObject type from a relationship name.
    /// e.g., "Contacts" on Account → "Contact"
    fn resolve_child_type(
        self: *Evaluator,
        parent_type: []const u8,
        relationship: []const u8,
    ) ?[]const u8 {
        if (self.resolve_custom_child_relationship(parent_type, relationship)) |custom| {
            return custom.child_type;
        }
        // Common Salesforce relationship mappings
        const mappings = .{
            .{ "Contacts", "Contact" },
            .{ "Opportunities", "Opportunity" },
            .{ "Cases", "Case" },
            .{ "Tasks", "Task" },
            .{ "Events", "Event" },
            .{ "Notes", "Note" },
            .{ "Attachments", "Attachment" },
            .{ "ContentDocumentLinks", "ContentDocumentLink" },
            .{ "Leads", "Lead" },
            .{ "AccountContactRoles", "AccountContactRole" },
            .{ "OpportunityContactRoles", "OpportunityContactRole" },
            .{ "CampaignMemberStatuses", "CampaignMemberStatus" },
            .{ "CampaignMembers", "CampaignMember" },
            // Self-referencing standard relationships (Parent/Owner hierarchy).
            .{ "ChildAccounts", "Account" },
            .{ "ParentAccounts", "Account" },
            .{ "ChildOpportunities", "Opportunity" },
            .{ "ChildCases", "Case" },
            .{ "Assets", "Asset" },
            .{ "AssetContactRoles", "AssetContactRole" },
            .{ "Orders", "Order" },
            .{ "Quotes", "Quote" },
            .{ "Contracts", "Contract" },
        };
        inline for (mappings) |m| {
            if (std.ascii.eqlIgnoreCase(relationship, m[0])) return m[1];
        }
        // Try removing trailing 'es' (statuses → status, boxes → box)
        if (relationship.len > 2 and std.ascii.endsWithIgnoreCase(relationship, "es")) {
            const candidate = relationship[0 .. relationship.len - 2];
            // Only accept if candidate ends in 's' (statuses), 'x', 'sh', 'ch'
            if (std.ascii.endsWithIgnoreCase(candidate, "s") or
                std.ascii.endsWithIgnoreCase(candidate, "x") or
                std.ascii.endsWithIgnoreCase(candidate, "sh") or
                std.ascii.endsWithIgnoreCase(candidate, "ch"))
            {
                return candidate;
            }
        }
        // Try removing trailing 's' for standard plural
        if (relationship.len > 1 and relationship[relationship.len - 1] == 's') {
            return relationship[0 .. relationship.len - 1];
        }
        return null;
    }

    /// Resolve the foreign key field name from child to parent.
    /// e.g., Contact to Account → "AccountId"
    fn resolve_foreign_key(
        self: *Evaluator,
        child_type: []const u8,
        parent_type: []const u8,
        relationship: []const u8,
    ) []const u8 {
        if (self.resolve_custom_child_relationship(parent_type, relationship)) |custom| {
            if (std.ascii.eqlIgnoreCase(custom.child_type, child_type)) return custom.fk_field;
        }
        // Self-referencing hierarchy relationships use ParentId regardless of
        // the logical parent type name.
        const hierarchy_rels = .{
            "ChildAccounts",
            "ChildOpportunities",
            "ChildCases",
            "ParentAccounts",
        };
        inline for (hierarchy_rels) |r| {
            if (std.ascii.eqlIgnoreCase(relationship, r)) return "ParentId";
        }
        // Standard convention: ParentType + "Id"
        const common_fks = .{
            .{ "Account", "AccountId" },
            .{ "Contact", "ContactId" },
            .{ "Opportunity", "OpportunityId" },
            .{ "Case", "CaseId" },
            .{ "Lead", "LeadId" },
            .{ "User", "OwnerId" },
            .{ "Campaign", "CampaignId" },
        };
        inline for (common_fks) |m| {
            if (std.ascii.eqlIgnoreCase(parent_type, m[0])) return m[1];
        }
        // Default: use parent_type + "Id" convention
        return std.fmt.allocPrint(self.arena, "{s}Id", .{parent_type}) catch "ParentId";
    }

    fn resolve_custom_child_relationship(
        self: *Evaluator,
        parent_type: []const u8,
        relationship: []const u8,
    ) ?CustomChildRelationship {
        const key = self.make_child_relationship_key(parent_type, relationship) catch return null;
        return self.child_relationships.get(key);
    }

    fn make_child_relationship_key(
        self: *Evaluator,
        parent_type: []const u8,
        relationship: []const u8,
    ) ![]const u8 {
        const raw = try std.fmt.allocPrint(self.arena, "{s}|{s}", .{ parent_type, relationship });
        const lowered = try self.arena.alloc(u8, raw.len);
        _ = std.ascii.lowerString(lowered, raw);
        return lowered;
    }

    /// Apply parent field lookups like Account.Name, parent__r.Name to query results.
    fn apply_parent_field_lookups(
        self: *Evaluator,
        soql: []const u8,
        from_type: []const u8,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        const select_clause = extract_parent_fields(soql) orelse return;

        // Find fields like Account.Name, Account.ShippingState, parent__r.Name,
        // and also multi-level chains such as Account.Parent.Parent.Name.
        var iter = std.mem.splitScalar(u8, select_clause, ',');
        while (iter.next()) |field_part| {
            const trimmed = std.mem.trim(u8, field_part, " \t\n\r");
            // Skip sub-queries (start with '(')
            if (trimmed.len > 0 and trimmed[0] == '(') continue;
            // Skip non-dotted fields
            if (std.mem.indexOfScalar(u8, trimmed, '.') == null) continue;

            for (records.items) |*rec| {
                if (rec.* != .sobject) continue;
                try self.hydrate_parent_chain(rec.sobject, from_type, trimmed);
            }
        }
    }

    /// Walk a dotted SELECT path like `Account.Parent.Parent.Name` and
    /// materialize each intermediate SObject on `host`, copying the final
    /// leaf value across at the end.  Handles arbitrary-depth parent chains
    /// including self-referencing hierarchies.
    fn hydrate_parent_chain(
        self: *Evaluator,
        host: *types.SObject,
        host_type: []const u8,
        path: []const u8,
    ) !void {
        var remaining = path;
        var current_sob: *types.SObject = host;
        var current_type: []const u8 = host_type;
        while (std.mem.indexOfScalar(u8, remaining, '.')) |dot_pos| {
            const parent_ref = remaining[0..dot_pos];
            const rest = remaining[dot_pos + 1 ..];
            const fk_field = self.parent_ref_to_fk(parent_ref);
            const parent_type = self.parent_ref_to_type_for_s_object(current_type, parent_ref) orelse
                return;
            const fk_val = utils.sobject_get(&current_sob.fields, fk_field) orelse return;
            if (fk_val != .string) return;
            const parent_rec = self.find_record_by_id(parent_type, fk_val.string) orelse return;
            if (parent_rec != .sobject) return;

            const parent_sob = try self.hydrate_upsert_parent_slot(
                current_sob,
                parent_ref,
                parent_type,
            );
            try self.copy_parent_id_into_slot(parent_sob, parent_rec.sobject);

            // Leaf segment: copy the final field value.
            if (std.mem.indexOfScalar(u8, rest, '.') == null) {
                if (self.get_s_object_field_value_case_insensitive(
                    parent_rec.sobject,
                    rest,
                )) |field_val| {
                    try parent_sob.fields.put(self.arena, rest, field_val);
                }
                return;
            }

            try self.mirror_next_segment_fk(parent_sob, parent_rec.sobject, rest);
            current_sob = parent_sob;
            current_type = parent_type;
            remaining = rest;
        }
    }

    /// Get-or-create the parent SObject slot on `current_sob` at `parent_ref`.
    /// Reuses an existing nested SObject when present; otherwise allocates a
    /// fresh one of `parent_type`.
    fn hydrate_upsert_parent_slot(
        self: *Evaluator,
        current_sob: *types.SObject,
        parent_ref: []const u8,
        parent_type: []const u8,
    ) !*types.SObject {
        if (utils.sobject_get(&current_sob.fields, parent_ref)) |existing| {
            if (existing == .sobject) return existing.sobject;
        }
        const parent_sob = try self.arena.create(types.SObject);
        parent_sob.* = .{ .type_name = parent_type };
        try current_sob.fields.put(self.arena, parent_ref, Value{ .sobject = parent_sob });
        return parent_sob;
    }

    /// Always copy the parent's Id so subsequent deep lookups consume it via
    /// the fk_field convention.
    fn copy_parent_id_into_slot(
        self: *Evaluator,
        parent_sob: *types.SObject,
        parent_rec: *types.SObject,
    ) !void {
        const pid = parent_rec.id orelse return;
        parent_sob.id = pid;
        try parent_sob.fields.put(self.arena, "Id", Value{ .string = pid });
    }

    /// Mirror the next segment's FK field from the real parent onto our slot so
    /// the next loop iteration can chase it via `fk_field`.
    fn mirror_next_segment_fk(
        self: *Evaluator,
        parent_sob: *types.SObject,
        parent_rec: *types.SObject,
        rest: []const u8,
    ) !void {
        const next_dot = std.mem.indexOfScalar(u8, rest, '.').?;
        const next_parent_ref = rest[0..next_dot];
        const next_fk = self.parent_ref_to_fk(next_parent_ref);
        if (self.get_s_object_field_value_case_insensitive(parent_rec, next_fk)) |nfk_val| {
            try parent_sob.fields.put(self.arena, next_fk, nfk_val);
        }
    }

    /// SOQL SELECT 内の数式フィールド（<Relationship>_<Field>__c）を FK 経由で親から解決する。
    /// 例: Experience_Name__c → Experience__c FK → 親の Name
    fn resolve_formula_fields(
        self: *Evaluator,
        soql: []const u8,
        records: *std.ArrayListUnmanaged(Value),
    ) !void {
        const select_clause = extract_parent_fields(soql) orelse return;
        var iter = std.mem.splitScalar(u8, select_clause, ',');
        while (iter.next()) |field_part| {
            const trimmed = std.mem.trim(u8, field_part, " \t\n\r");
            // Skip dotted fields (already handled) and sub-queries
            if (std.mem.indexOf(u8, trimmed, ".") != null) continue;
            if (trimmed.len > 0 and trimmed[0] == '(') continue;
            // Pattern: <Prefix>_<Suffix>__c where <Prefix>__c is a FK and <Suffix> is a parent
            // field
            // e.g. Experience_Name__c → FK=Experience__c, parent field=Name
            if (!std.mem.endsWith(u8, trimmed, "__c")) continue;
            const base = trimmed[0 .. trimmed.len - 3]; // strip __c
            // Find underscore separator (last one before __c)
            const sep_pos = std.mem.lastIndexOfScalar(u8, base, '_') orelse continue;
            if (sep_pos == 0) continue;
            const parent_prefix = base[0..sep_pos]; // "Experience"
            const field_suffix = base[sep_pos + 1 ..]; // "Name"
            // Construct FK field: Experience__c
            const fk_field = try std.fmt.allocPrint(self.arena, "{s}__c", .{parent_prefix});

            for (records.items) |*rec| {
                if (rec.* != .sobject) continue;
                // Skip if field already has a non-null value
                if (utils.sobject_get(&rec.sobject.fields, trimmed)) |existing| {
                    if (existing != .null_val) continue;
                }
                // Look up FK
                const fk_val = utils.sobject_get(&rec.sobject.fields, fk_field) orelse continue;
                if (fk_val != .string) continue;
                // Find parent type
                const parent_type = self.find_record_type_by_id(fk_val.string) orelse continue;
                // Find parent record
                const parent_rec = self.find_record_by_id(
                    parent_type,
                    fk_val.string,
                ) orelse continue;
                if (parent_rec != .sobject) continue;
                // Copy the field from parent
                if (utils.sobject_get(&parent_rec.sobject.fields, field_suffix)) |val| {
                    try rec.sobject.fields.put(self.arena, trimmed, val);
                }
            }
        }
    }

    /// Convert a parent reference to FK field name.
    /// Account → AccountId, parent__r → parent__c
    fn parent_ref_to_fk(self: *Evaluator, ref: []const u8) []const u8 {
        // Custom relationship: ends with __r → change to __c
        if (ref.len > 3 and std.ascii.eqlIgnoreCase(ref[ref.len - 3 ..], "__r")) {
            // Replace __r with __c
            const fk = std.fmt.allocPrint(
                self.arena,
                "{s}__c",
                .{ref[0 .. ref.len - 3]},
            ) catch return ref;
            return fk;
        }
        // Standard: Account → AccountId
        const common = .{
            .{ "Account", "AccountId" },
            .{ "Contact", "ContactId" },
            .{ "Opportunity", "OpportunityId" },
            .{ "Case", "CaseId" },
            .{ "Lead", "LeadId" },
            .{ "Owner", "OwnerId" },
            .{ "CreatedBy", "CreatedById" },
            .{ "LastModifiedBy", "LastModifiedById" },
            .{ "Parent", "ParentId" },
            .{ "Profile", "ProfileId" },
            .{ "UserRole", "UserRoleId" },
            .{ "UserLicense", "UserLicenseId" },
        };
        inline for (common) |m| {
            if (std.ascii.eqlIgnoreCase(ref, m[0])) return m[1];
        }
        return ref;
    }

    /// Convert a FK field name back to its relationship name.
    /// AccountId → Account, parent__c → parent__r
    fn fk_to_parent_ref(self: *Evaluator, fk_field: []const u8) []const u8 {
        if (fk_field.len > 3 and std.ascii.eqlIgnoreCase(fk_field[fk_field.len - 3 ..], "__c")) {
            const rel = std.fmt.allocPrint(
                self.arena,
                "{s}__r",
                .{fk_field[0 .. fk_field.len - 3]},
            ) catch return fk_field;
            return rel;
        }
        const common = .{
            .{ "AccountId", "Account" },
            .{ "ContactId", "Contact" },
            .{ "OpportunityId", "Opportunity" },
            .{ "CaseId", "Case" },
            .{ "LeadId", "Lead" },
            .{ "OwnerId", "Owner" },
            .{ "CreatedById", "CreatedBy" },
            .{ "LastModifiedById", "LastModifiedBy" },
            .{ "ParentId", "Parent" },
            .{ "ProfileId", "Profile" },
            .{ "UserRoleId", "UserRole" },
            .{ "UserLicenseId", "UserLicense" },
        };
        inline for (common) |m| {
            if (std.ascii.eqlIgnoreCase(fk_field, m[0])) return m[1];
        }
        return fk_field;
    }

    /// Convert a parent reference to SObject type name.
    /// Account → Account, parent__r → look up FK value's type in store
    fn parent_ref_to_type(self: *Evaluator, ref: []const u8) ?[]const u8 {
        // Custom relationship: parent1__r → parent1__c is the FK field
        // We need to find what type the FK points to
        if (ref.len > 3 and std.ascii.eqlIgnoreCase(ref[ref.len - 3 ..], "__r")) {
            const fk_field = self.parent_ref_to_fk(ref);
            // Search for the FK value in any record and look up the target type
            var store_iter = self.store.iterator();
            while (store_iter.next()) |entry| {
                for (entry.value_ptr.items) |record| {
                    if (record == .sobject) {
                        if (utils.sobject_get(&record.sobject.fields, fk_field)) |fk_val| {
                            if (fk_val == .string) {
                                // Find which type has a record with this Id
                                if (self.find_record_type_by_id(fk_val.string)) |found_type| {
                                    return found_type;
                                }
                            }
                        }
                    }
                }
            }
            return null;
        }
        // Standard relationship → SObject type mapping
        if (std.ascii.eqlIgnoreCase(ref, "Owner") or
            std.ascii.eqlIgnoreCase(ref, "CreatedBy") or
            std.ascii.eqlIgnoreCase(ref, "LastModifiedBy"))
        {
            return "User";
        }
        return ref;
    }

    fn parent_ref_to_type_for_s_object(
        self: *Evaluator,
        object_type: []const u8,
        ref: []const u8,
    ) ?[]const u8 {
        const fk_field = self.parent_ref_to_fk(ref);
        if (self.get_field_metadata(object_type, fk_field)) |meta| {
            if (meta.reference_to) |target_type| return target_type;
        }
        // Self-referencing "Parent" lookup: on Account, Parent → Account; on
        // Case, Parent → Case; etc.  Only Account / Case / Opportunity have a
        // ParentId field at the platform level.
        if (std.ascii.eqlIgnoreCase(ref, "Parent")) {
            if (std.ascii.eqlIgnoreCase(object_type, "Account") or
                std.ascii.eqlIgnoreCase(object_type, "Case") or
                std.ascii.eqlIgnoreCase(object_type, "Opportunity") or
                std.ascii.eqlIgnoreCase(object_type, "Contact"))
            {
                return object_type;
            }
        }
        return self.parent_ref_to_type(ref);
    }

    /// Find a record by Id in the store.
    fn find_record_by_id(self: *Evaluator, type_name: []const u8, id: []const u8) ?Value {
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, type_name)) {
                for (entry.value_ptr.items) |record| {
                    if (record == .sobject) {
                        if (record.sobject.id) |rec_id| {
                            if (std.ascii.eqlIgnoreCase(rec_id, id)) return record;
                        }
                    }
                }
                return null;
            }
        }
        // Fallback: for User type, return synthetic user if id matches UserInfo.getUserId()
        if (std.ascii.eqlIgnoreCase(type_name, "User") and
            std.ascii.eqlIgnoreCase(id, self.current_user_id))
        {
            return self.create_current_user_record() catch null;
        }
        return null;
    }

    pub fn relationship_records_value(_: *Evaluator, value: Value) ?Value {
        return switch (value) {
            .object => |obj| blk: {
                if (obj.fields.get("records")) |records| {
                    if (records == .list) break :blk records;
                }
                break :blk null;
            },
            .sobject => |sob| blk: {
                if (utils.sobject_get(&sob.fields, "records")) |records| {
                    if (records == .list) break :blk records;
                }
                break :blk null;
            },
            .map => |map| blk: {
                for (map.entries.keys(), map.entries.values()) |k, records| {
                    if (std.ascii.eqlIgnoreCase(k, "records") and records == .list)
                        break :blk records;
                }
                break :blk null;
            },
            else => null,
        };
    }

    fn normalize_parsed_json_s_object_field(
        self: *Evaluator,
        sob: *types.SObject,
        field_name: []const u8,
        value: Value,
    ) Value {
        var bctx = builtins.BuiltinContext{
            .arena = self.arena,
            .stdout = &self.stdout,
            .pending_exception = &self.pending_exception,
            .see_all_data = self.see_all_data,
            .eval = self,
        };
        return builtins.normalize_s_object_field_assignment(
            &bctx,
            sob,
            field_name,
            value,
        ) catch value;
    }

    fn find_visible_enum_decl(self: *Evaluator, enum_name: []const u8) ?*ast.EnumDecl {
        const Search = struct {
            fn in_class(cd: *ast.ClassDecl, target: []const u8) ?*ast.EnumDecl {
                for (cd.members) |member| {
                    switch (member) {
                        .enum_decl => |ed| {
                            if (std.ascii.eqlIgnoreCase(ed.name, target)) return ed;
                        },
                        else => {},
                    }
                }
                return null;
            }
        };

        if (self.current_class) |class_name| {
            if (self.find_class(class_name)) |cd| {
                if (Search.in_class(cd, enum_name)) |ed| return ed;
            }
            if (self.find_outer_class_name(class_name)) |outer_name| {
                if (self.find_class(outer_name)) |outer_cd| {
                    if (Search.in_class(outer_cd, enum_name)) |ed| return ed;
                }
            }
        }

        var class_iter = self.classes.iterator();
        while (class_iter.next()) |entry| {
            if (std.mem.indexOfScalar(u8, entry.key_ptr.*, '.') != null) continue;
            if (Search.in_class(entry.value_ptr.*, enum_name)) |ed| return ed;
        }
        return null;
    }

    pub fn get_s_object_field_value_case_insensitive(
        self: *Evaluator,
        sob: *types.SObject,
        field_name: []const u8,
    ) ?Value {
        var matched_value: ?Value = null;
        for (sob.fields.keys(), sob.fields.values()) |k, v| {
            if (std.ascii.eqlIgnoreCase(k, field_name)) {
                matched_value = v;
                break;
            }
        }
        if (matched_value) |value| {
            if (value != .null_val) {
                if (value == .string) {
                    var bctx = builtins.BuiltinContext{ .arena = self.arena, .stdout = &self.stdout, .pending_exception = &self.pending_exception, .see_all_data = self.see_all_data, .eval = self };
                    const display_type = builtins.get_s_object_field_display_type(
                        &bctx,
                        sob,
                        field_name,
                    );
                    if (std.ascii.eqlIgnoreCase(display_type, "DATETIME")) {
                        return builtins.make_datetime_value(self.arena, value.string) catch value;
                    }
                    if (std.ascii.eqlIgnoreCase(display_type, "DATE")) {
                        const date_str =
                            if (value.string.len >= 10) value.string[0..10] else value.string;
                        return builtins.make_date_value(self.arena, date_str) catch value;
                    }
                }
                if (self.relationship_records_value(value)) |records| return records;
                return value;
            }
        }
        if (self.resolve_derived_field_value(sob, field_name)) |derived| return derived;
        if (self.resolve_custom_child_relationship(sob.type_name, field_name) != null or
            (field_name.len > 3 and std.ascii.eqlIgnoreCase(
                field_name[field_name.len - 3 ..],
                "__r",
            ) and
                self.resolve_custom_child_relationship(
                    sob.type_name,
                    field_name[0 .. field_name.len - 3],
                ) != null))
        {
            return self.make_empty_list() catch matched_value;
        }
        return matched_value;
    }

    fn resolve_field_path_value(
        self: *Evaluator,
        sob: *types.SObject,
        field_path: []const u8,
    ) ?Value {
        var current = sob;
        var remaining = field_path;
        while (true) {
            const dot_pos = std.mem.indexOfScalar(u8, remaining, '.') orelse {
                return self.get_s_object_field_value_case_insensitive(current, remaining);
            };
            const segment = remaining[0..dot_pos];
            remaining = remaining[dot_pos + 1 ..];

            if (self.get_s_object_field_value_case_insensitive(current, segment)) |segment_val| {
                if (segment_val == .sobject) {
                    current = segment_val.sobject;
                    continue;
                }
                return null;
            }

            const fk_field = self.parent_ref_to_fk(segment);
            const fk_val = utils.sobject_get(&current.fields, fk_field) orelse return null;
            if (fk_val != .string) return null;

            const parent_type = self.parent_ref_to_type_for_s_object(
                current.type_name,
                segment,
            ) orelse
                self.find_record_type_by_id(fk_val.string) orelse
                blk: {
                    if (fk_val.string.len < 3) break :blk null;
                    const inferred = sobject_type_from_prefix(fk_val.string[0..3]);
                    if (std.ascii.eqlIgnoreCase(inferred, "SObject")) break :blk null;
                    break :blk inferred;
                } orelse return null;

            const parent_record = self.find_record_by_id(
                parent_type,
                fk_val.string,
            ) orelse return null;
            if (parent_record != .sobject) return null;
            current = parent_record.sobject;
        }
    }

    fn resolve_derived_field_value(
        self: *Evaluator,
        sob: *types.SObject,
        field_name: []const u8,
    ) ?Value {
        const metadata = self.get_field_metadata(sob.type_name, field_name) orelse return null;
        if (metadata.summary_operation != null) {
            if (self.compute_summary_field_value(sob, metadata)) |value| return value;
        }
        if (metadata.formula != null) {
            if (self.compute_formula_field_value(sob, metadata)) |value| return value;
        }
        return null;
    }

    fn collect_summary_impact_ids_from_records(
        self: *Evaluator,
        impacted_ids: *std.StringArrayHashMapUnmanaged(void),
        records: []const Value,
        fk_field: []const u8,
    ) !void {
        for (records) |record| {
            if (record != .sobject) continue;
            const fk_val = self.get_s_object_field_value_case_insensitive(
                record.sobject,
                fk_field,
            ) orelse continue;
            if (fk_val != .string or fk_val.string.len == 0) continue;
            try impacted_ids.put(self.arena, fk_val.string, {});
        }
    }

    fn apply_rollup_summary_side_effects(
        self: *Evaluator,
        child_type: []const u8,
        new_records: []const Value,
        old_records: ?std.ArrayListUnmanaged(Value),
    ) !void {
        var parent_iter = self.field_metadata.iterator();
        while (parent_iter.next()) |parent_entry| {
            try self.apply_rollup_for_parent_type(
                parent_entry.key_ptr.*,
                parent_entry.value_ptr.*,
                child_type,
                new_records,
                old_records,
            );
        }
    }

    /// For one parent SObject type: collect the set of parent Ids impacted by
    /// the child delta, recompute every rollup summary field for those parents,
    /// and emit a single bulk update when anything changed.
    fn apply_rollup_for_parent_type(
        self: *Evaluator,
        parent_type: []const u8,
        type_meta: std.StringArrayHashMapUnmanaged(FieldMetadata),
        child_type: []const u8,
        new_records: []const Value,
        old_records: ?std.ArrayListUnmanaged(Value),
    ) !void {
        var impacted_ids: std.StringArrayHashMapUnmanaged(void) = .empty;
        if (!(try self.collect_rollup_impacted_ids(
            type_meta,
            child_type,
            new_records,
            old_records,
            &impacted_ids,
        ))) return;
        if (impacted_ids.count() == 0) return;

        const parent_updates = try self.arena.create(types.ListValue);
        parent_updates.* = .{};
        var parent_old_records: std.ArrayListUnmanaged(Value) = .empty;
        var impacted_iter = impacted_ids.iterator();
        while (impacted_iter.next()) |impacted_entry| {
            try self.recompute_rollup_for_parent(
                parent_type,
                type_meta,
                child_type,
                impacted_entry.key_ptr.*,
                new_records,
                old_records,
                parent_updates,
                &parent_old_records,
            );
        }
        if (parent_updates.items.items.len > 0) {
            try self.execute_dml_with_external_id_internal(
                .update,
                Value{ .list = parent_updates },
                null,
                false,
                parent_old_records,
            );
        }
    }

    /// Walk `type_meta` for rollup-summary fields pointing at `child_type`,
    /// recording impacted parent Ids from both new and old child records.
    /// Returns whether any matching rollup exists for this parent type.
    fn collect_rollup_impacted_ids(
        self: *Evaluator,
        type_meta: std.StringArrayHashMapUnmanaged(FieldMetadata),
        child_type: []const u8,
        new_records: []const Value,
        old_records: ?std.ArrayListUnmanaged(Value),
        impacted_ids: *std.StringArrayHashMapUnmanaged(void),
    ) !bool {
        var has_matching_rollups = false;
        var field_iter = type_meta.iterator();
        while (field_iter.next()) |field_entry| {
            const metadata = field_entry.value_ptr.*;
            const summary_fk = metadata.summary_foreign_key orelse continue;
            const dot_idx = std.mem.indexOfScalar(u8, summary_fk, '.') orelse continue;
            if (!std.ascii.eqlIgnoreCase(summary_fk[0..dot_idx], child_type)) continue;
            has_matching_rollups = true;
            const fk_field = summary_fk[dot_idx + 1 ..];
            try self.collect_summary_impact_ids_from_records(impacted_ids, new_records, fk_field);
            if (old_records) |previous_records| {
                try self.collect_summary_impact_ids_from_records(
                    impacted_ids,
                    previous_records.items,
                    fk_field,
                );
            }
        }
        return has_matching_rollups;
    }

    /// Recompute every rollup-summary field on a single parent. When any value
    /// actually changes, append the updated + pre-delta snapshots to the
    /// caller's update/old lists.
    fn recompute_rollup_for_parent(
        self: *Evaluator,
        parent_type: []const u8,
        type_meta: std.StringArrayHashMapUnmanaged(FieldMetadata),
        child_type: []const u8,
        parent_id: []const u8,
        new_records: []const Value,
        old_records: ?std.ArrayListUnmanaged(Value),
        parent_updates: *types.ListValue,
        parent_old_records: *std.ArrayListUnmanaged(Value),
    ) !void {
        const parent_record = self.find_record_by_id(parent_type, parent_id) orelse return;
        if (parent_record != .sobject) return;
        const updated_parent = try self.clone_s_object(parent_record.sobject);
        const old_parent = try self.clone_s_object(parent_record.sobject);
        var changed = false;
        var summary_iter = type_meta.iterator();
        while (summary_iter.next()) |summary_entry| {
            const field_name = summary_entry.key_ptr.*;
            const metadata = summary_entry.value_ptr.*;
            const summary_fk = metadata.summary_foreign_key orelse continue;
            const dot_idx = std.mem.indexOfScalar(u8, summary_fk, '.') orelse continue;
            if (!std.ascii.eqlIgnoreCase(summary_fk[0..dot_idx], child_type)) continue;
            const new_value = self.compute_summary_field_value(updated_parent, metadata) orelse
                Value.null_val;
            const old_value = self.compute_summary_field_value_before_delta(
                parent_record.sobject,
                metadata,
                new_records,
                old_records,
            ) orelse Value.null_val;
            try old_parent.fields.put(self.arena, field_name, old_value);
            try updated_parent.fields.put(self.arena, field_name, new_value);
            if (!utils.value_eql(old_value, new_value)) changed = true;
        }
        if (!changed) return;
        try parent_updates.items.append(self.arena, Value{ .sobject = updated_parent });
        try parent_old_records.append(self.arena, Value{ .sobject = old_parent });
    }

    fn normalize_summary_field_path(
        _: *Evaluator,
        child_type: []const u8,
        field_path: []const u8,
    ) []const u8 {
        if (std.mem.startsWith(u8, field_path, child_type) and
            field_path.len > child_type.len and
            field_path[child_type.len] == '.')
        {
            return field_path[child_type.len + 1 ..];
        }
        return field_path;
    }

    fn summary_filter_matches(
        self: *Evaluator,
        child: *types.SObject,
        child_type: []const u8,
        filter: SummaryFilter,
    ) bool {
        const field_path = self.normalize_summary_field_path(child_type, filter.field_path);
        const field_val = if (std.mem.indexOfScalar(u8, field_path, '.')) |_|
            self.resolve_field_path_value(child, field_path)
        else
            self.get_s_object_field_value_case_insensitive(child, field_path);
        if (field_val == null) return false;

        if (std.ascii.eqlIgnoreCase(filter.operation, "equals")) {
            return switch (field_val.?) {
                .string => std.ascii.eqlIgnoreCase(field_val.?.string, filter.value),
                .integer => blk: {
                    const expected = std.fmt.parseInt(i64, filter.value, 10) catch break :blk false;
                    break :blk field_val.?.integer == expected;
                },
                .double => blk: {
                    const expected = std.fmt.parseFloat(f64, filter.value) catch break :blk false;
                    break :blk field_val.?.double == expected;
                },
                .boolean => if (std.ascii.eqlIgnoreCase(filter.value, "true")) field_val.?.boolean else if (std.ascii.eqlIgnoreCase(filter.value, "false")) !field_val.?.boolean else false,
                .null_val => std.ascii.eqlIgnoreCase(filter.value, "null"),
                else => {
                    const actual = utils.coerce_to_string(
                        field_val.?,
                        self.arena,
                    ) catch return false;
                    return std.ascii.eqlIgnoreCase(actual, filter.value);
                },
            };
        }

        if (std.ascii.eqlIgnoreCase(filter.operation, "notEqual")) {
            return !self.summary_filter_matches(child, child_type, .{
                .field_path = filter.field_path,
                .operation = "equals",
                .value = filter.value,
            });
        }

        return false;
    }

    fn find_s_object_by_id_in_values(
        _: *Evaluator,
        records: []const Value,
        id: []const u8,
    ) ?*types.SObject {
        for (records) |record| {
            if (record != .sobject or record.sobject.id == null) continue;
            if (std.mem.eql(u8, record.sobject.id.?, id)) return record.sobject;
        }
        return null;
    }

    fn summary_record_matches(
        self: *Evaluator,
        child: *types.SObject,
        child_type: []const u8,
        fk_field: []const u8,
        parent_id: []const u8,
        metadata: FieldMetadata,
    ) bool {
        const fk_val = self.get_s_object_field_value_case_insensitive(
            child,
            fk_field,
        ) orelse return false;
        if (fk_val != .string or !std.ascii.eqlIgnoreCase(fk_val.string, parent_id)) return false;

        for (metadata.summary_filters) |filter| {
            if (!self.summary_filter_matches(child, child_type, filter)) return false;
        }
        return true;
    }

    fn accumulate_summary_value(
        self: *Evaluator,
        child: *types.SObject,
        child_type: []const u8,
        metadata: FieldMetadata,
        count: *i64,
        aggregate: *?Value,
    ) void {
        const summary_operation = metadata.summary_operation orelse return;
        if (std.ascii.eqlIgnoreCase(summary_operation, "count")) {
            count.* += 1;
            return;
        }

        const summarized_field = if (metadata.summarized_field) |field_path|
            self.normalize_summary_field_path(child_type, field_path)
        else
            "";
        if (summarized_field.len == 0) return;

        const child_value = blk: {
            if (std.mem.indexOfScalar(u8, summarized_field, '.')) |_| {
                break :blk self.resolve_field_path_value(
                    child,
                    summarized_field,
                ) orelse Value.null_val;
            }
            break :blk self.get_s_object_field_value_case_insensitive(
                child,
                summarized_field,
            ) orelse Value.null_val;
        };
        if (child_value == .null_val) return;

        if (aggregate.* == null) {
            aggregate.* = child_value;
            return;
        }

        const cmp = self.compare_values(aggregate.*.?, child_value);
        if (std.ascii.eqlIgnoreCase(summary_operation, "min")) {
            if (cmp > 0) aggregate.* = child_value;
        } else if (std.ascii.eqlIgnoreCase(summary_operation, "max")) {
            if (cmp < 0) aggregate.* = child_value;
        }
    }

    fn compute_summary_field_value_before_delta(
        self: *Evaluator,
        sob: *types.SObject,
        metadata: FieldMetadata,
        new_records: []const Value,
        old_records: ?std.ArrayListUnmanaged(Value),
    ) ?Value {
        const summary_operation = metadata.summary_operation orelse return null;
        const summary_fk = metadata.summary_foreign_key orelse return null;
        const dot_idx = std.mem.indexOfScalar(u8, summary_fk, '.') orelse return null;
        const child_type = summary_fk[0..dot_idx];
        const fk_field = summary_fk[dot_idx + 1 ..];

        const parent_id = sob.id orelse blk: {
            if (utils.sobject_get(&sob.fields, "Id")) |id_val| {
                if (id_val == .string) break :blk id_val.string;
            }
            break :blk null;
        };
        if (parent_id == null) {
            if (std.ascii.eqlIgnoreCase(summary_operation, "count")) return Value{ .integer = 0 };
            return Value.null_val;
        }

        const child_records = self.store.get(child_type) orelse {
            if (std.ascii.eqlIgnoreCase(summary_operation, "count")) return Value{ .integer = 0 };
            return Value.null_val;
        };

        var count: i64 = 0;
        var aggregate: ?Value = null;

        for (child_records.items) |record| {
            if (record != .sobject or record.sobject.id == null) continue;
            const record_id = record.sobject.id.?;

            if (old_records) |previous_records| {
                if (self.find_s_object_by_id_in_values(
                    previous_records.items,
                    record_id,
                )) |old_child| {
                    if (self.summary_record_matches(
                        old_child,
                        child_type,
                        fk_field,
                        parent_id.?,
                        metadata,
                    )) {
                        self.accumulate_summary_value(
                            old_child,
                            child_type,
                            metadata,
                            &count,
                            &aggregate,
                        );
                    }
                    continue;
                }
            }

            const inserted_now = self.find_s_object_by_id_in_values(new_records, record_id) != null;
            if (inserted_now) continue;

            if (self.summary_record_matches(
                record.sobject,
                child_type,
                fk_field,
                parent_id.?,
                metadata,
            )) {
                self.accumulate_summary_value(
                    record.sobject,
                    child_type,
                    metadata,
                    &count,
                    &aggregate,
                );
            }
        }

        if (old_records) |previous_records| {
            for (previous_records.items) |record| {
                if (record != .sobject or record.sobject.id == null) continue;
                if (self.find_record_in_store(child_type, record.sobject.id.?)) |_| continue;
                if (self.summary_record_matches(
                    record.sobject,
                    child_type,
                    fk_field,
                    parent_id.?,
                    metadata,
                )) {
                    self.accumulate_summary_value(
                        record.sobject,
                        child_type,
                        metadata,
                        &count,
                        &aggregate,
                    );
                }
            }
        }

        if (std.ascii.eqlIgnoreCase(summary_operation, "count")) return Value{ .integer = count };
        return aggregate orelse Value.null_val;
    }

    fn compute_summary_field_value(
        self: *Evaluator,
        sob: *types.SObject,
        metadata: FieldMetadata,
    ) ?Value {
        const summary_operation = metadata.summary_operation orelse return null;
        const summary_fk = metadata.summary_foreign_key orelse return null;
        const dot_idx = std.mem.indexOfScalar(u8, summary_fk, '.') orelse return null;
        const child_type = summary_fk[0..dot_idx];
        const fk_field = summary_fk[dot_idx + 1 ..];

        const parent_id = sob.id orelse blk: {
            if (utils.sobject_get(&sob.fields, "Id")) |id_val| {
                if (id_val == .string) break :blk id_val.string;
            }
            break :blk null;
        };

        if (parent_id == null) {
            if (std.ascii.eqlIgnoreCase(summary_operation, "count")) return Value{ .integer = 0 };
            return Value.null_val;
        }

        const child_records = self.store.get(child_type) orelse {
            if (std.ascii.eqlIgnoreCase(summary_operation, "count")) return Value{ .integer = 0 };
            return Value.null_val;
        };

        var count: i64 = 0;
        var aggregate: ?Value = null;

        for (child_records.items) |record| {
            if (record != .sobject) continue;
            if (!self.summary_record_matches(
                record.sobject,
                child_type,
                fk_field,
                parent_id.?,
                metadata,
            )) continue;
            self.accumulate_summary_value(record.sobject, child_type, metadata, &count, &aggregate);
        }

        if (std.ascii.eqlIgnoreCase(summary_operation, "count")) return Value{ .integer = count };
        return aggregate orelse Value.null_val;
    }

    fn compute_formula_field_value(
        self: *Evaluator,
        sob: *types.SObject,
        metadata: FieldMetadata,
    ) ?Value {
        const formula = metadata.formula orelse return null;
        const trimmed = std.mem.trim(u8, formula, " \t\n\r");
        if (trimmed.len == 0) return null;

        if (std.mem.indexOfScalar(u8, trimmed, '+')) |_| {
            var total: i64 = 0;
            var term_iter = std.mem.splitScalar(u8, trimmed, '+');
            while (term_iter.next()) |raw_term| {
                const term = std.mem.trim(u8, raw_term, " \t\n\r()");
                if (term.len == 0) continue;
                const term_value = self.get_s_object_field_value_case_insensitive(
                    sob,
                    term,
                ) orelse Value.null_val;
                switch (term_value) {
                    .integer => |i| total += i,
                    .double => |d| total += @intFromFloat(d),
                    .null_val => {
                        if (!metadata.formula_blank_as_zero) return Value.null_val;
                    },
                    else => return Value.null_val,
                }
            }
            return Value{ .integer = total };
        }

        if (std.mem.indexOfScalar(u8, trimmed, '.')) |_| {
            return self.resolve_field_path_value(sob, trimmed);
        }

        if (std.ascii.indexOfIgnoreCase(trimmed, "!= null")) |idx| {
            const lhs = std.mem.trim(u8, trimmed[0..idx], " \t\n\r");
            const lhs_value = self.get_s_object_field_value_case_insensitive(
                sob,
                lhs,
            ) orelse Value.null_val;
            return Value{ .boolean = lhs_value != .null_val };
        }

        if (std.ascii.indexOfIgnoreCase(trimmed, "== null")) |idx| {
            const lhs = std.mem.trim(u8, trimmed[0..idx], " \t\n\r");
            const lhs_value = self.get_s_object_field_value_case_insensitive(
                sob,
                lhs,
            ) orelse Value.null_val;
            return Value{ .boolean = lhs_value == .null_val };
        }

        return self.get_s_object_field_value_case_insensitive(sob, trimmed);
    }

    /// Create a shallow clone of an SObject (copies the fields map).
    fn clone_s_object(self: *Evaluator, src: *types.SObject) !*types.SObject {
        const copy = try self.arena.create(types.SObject);
        copy.* = .{ .type_name = src.type_name, .id = src.id };
        for (src.fields.keys(), src.fields.values()) |k, v| {
            try copy.fields.put(self.arena, k, v);
        }
        return copy;
    }

    fn default_custom_setting_record(
        self: *Evaluator,
        class_name: []const u8,
        setup_owner_id: ?[]const u8,
    ) !Value {
        const sob = try self.arena.create(types.SObject);
        sob.* = .{ .type_name = class_name };
        if (self.field_defaults.get(class_name)) |defaults| {
            for (defaults.keys(), defaults.values()) |fk, fv| {
                try sob.fields.put(self.arena, fk, fv);
            }
        }
        if (setup_owner_id) |owner_id| {
            try sob.fields.put(self.arena, "SetupOwnerId", Value{ .string = owner_id });
        }
        return Value{ .sobject = sob };
    }

    fn clone_custom_setting_record(
        self: *Evaluator,
        record: *types.SObject,
        setup_owner_id: ?[]const u8,
        clear_id: bool,
    ) !Value {
        const copy = try self.clone_s_object(record);
        if (clear_id) {
            copy.id = null;
            try copy.fields.put(self.arena, "Id", Value.null_val);
        }
        if (setup_owner_id) |owner_id| {
            try copy.fields.put(self.arena, "SetupOwnerId", Value{ .string = owner_id });
        }
        return Value{ .sobject = copy };
    }

    fn find_custom_setting_record(
        self: *Evaluator,
        class_name: []const u8,
        owner_id: []const u8,
    ) ?*types.SObject {
        var cs_iter = self.store.iterator();
        while (cs_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) continue;
            for (entry.value_ptr.items) |item| {
                if (item != .sobject) continue;
                if (utils.sobject_get(&item.sobject.fields, "SetupOwnerId")) |stored_owner| {
                    if (stored_owner == .string and
                        std.ascii.eqlIgnoreCase(stored_owner.string, owner_id))
                    {
                        return item.sobject;
                    }
                }
            }
        }
        return null;
    }

    fn first_custom_setting_record(self: *Evaluator, class_name: []const u8) ?*types.SObject {
        var cs_iter = self.store.iterator();
        while (cs_iter.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) continue;
            for (entry.value_ptr.items) |item| {
                if (item == .sobject) return item.sobject;
            }
        }
        return null;
    }

    fn custom_setting_kind(self: *Evaluator, class_name: []const u8) ?[]const u8 {
        if (self.custom_setting_kinds.get(class_name)) |kind| return kind;
        if (self.custom_setting_types.get(class_name) != null) return "Hierarchy";
        return null;
    }

    fn resolve_bare_static_value(self: *Evaluator, current_env: *Env, name: []const u8) ?Value {
        if (current_env.get("this")) |this_val| {
            if (this_val == .object) {
                const this_cn = this_val.object.class_name;
                if (self.resolve_static_field_value_on_class(this_cn, name)) |val| return val;
                if (self.find_class(this_cn)) |cd| {
                    if (cd.super_class) |sc| {
                        if (self.resolve_static_field_value_on_class(
                            sc.name,
                            name,
                        )) |val| return val;
                    }
                }
                if (self.resolve_outer_static_field(this_cn, name)) |val| return val;
            }
        }

        if (self.current_class) |cc| {
            if (self.resolve_static_field_value_on_class(cc, name)) |val| return val;
            if (self.find_class(cc)) |cd| {
                if (cd.super_class) |sc| {
                    if (self.resolve_static_field_value_on_class(sc.name, name)) |val| return val;
                }
            }
            if (self.resolve_outer_static_field(cc, name)) |val| return val;
        }

        return null;
    }

    fn handle_custom_setting_static_method(
        self: *Evaluator,
        class_name: []const u8,
        method_name: []const u8,
        args: []const Value,
    ) !?Value {
        if (!std.mem.endsWith(u8, class_name, "__c")) return null;

        const kind = self.custom_setting_kind(class_name);
        const is_hierarchy = kind != null and std.ascii.eqlIgnoreCase(kind.?, "Hierarchy");

        if (std.ascii.eqlIgnoreCase(method_name, "getOrgDefaults")) {
            if (is_hierarchy) {
                if (self.find_custom_setting_record(class_name, "00D000000000001")) |org_defaults| {
                    return try self.clone_custom_setting_record(org_defaults, null, false);
                }
                return try self.default_custom_setting_record(class_name, "00D000000000001");
            }
            if (self.first_custom_setting_record(class_name)) |record| {
                return try self.clone_custom_setting_record(record, null, false);
            }
            return try self.default_custom_setting_record(class_name, null);
        }

        if (std.ascii.eqlIgnoreCase(method_name, "getInstance")) {
            if (is_hierarchy) {
                const owner_id = if (args.len > 0 and args[0] == .string and args[0].string.len > 0)
                    args[0].string
                else
                    self.current_user_id;
                const profile_id = self.current_profile_id;
                const org_id = "00D000000000001";

                if (self.find_custom_setting_record(class_name, owner_id)) |user_record| {
                    return try self.clone_custom_setting_record(user_record, owner_id, false);
                }
                if (self.find_custom_setting_record(class_name, profile_id)) |profile_record| {
                    return try self.clone_custom_setting_record(profile_record, owner_id, true);
                }
                if (self.find_custom_setting_record(class_name, org_id)) |org_defaults| {
                    return try self.clone_custom_setting_record(org_defaults, owner_id, true);
                }
                return try self.default_custom_setting_record(class_name, owner_id);
            }

            if (self.first_custom_setting_record(class_name)) |record| {
                return try self.clone_custom_setting_record(record, null, false);
            }
            return try self.default_custom_setting_record(class_name, null);
        }

        if (std.ascii.eqlIgnoreCase(method_name, "getValues") and
            args.len > 0 and
            args[0] == .string)
        {
            if (self.find_custom_setting_record(class_name, args[0].string)) |record| {
                return try self.clone_custom_setting_record(record, null, false);
            }
            return Value.null_val;
        }

        return null;
    }

    /// Find the type name of a record by its Id, searching all types in store.
    fn find_record_type_by_id(self: *Evaluator, id: []const u8) ?[]const u8 {
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            for (entry.value_ptr.items) |record| {
                if (record == .sobject) {
                    if (record.sobject.id) |rec_id| {
                        if (std.ascii.eqlIgnoreCase(rec_id, id)) return entry.key_ptr.*;
                    }
                }
            }
        }
        return null;
    }

    // -----------------------------------------------------------------------
    // 式の評価
    // -----------------------------------------------------------------------

    fn resolve_schema_dotted_identifier(self: *Evaluator, name: []const u8) !?Value {
        if (std.mem.startsWith(u8, name, "SObjectType.") and
            std.mem.indexOfScalar(u8, name["SObjectType.".len..], '.') == null)
        {
            const object_name = name["SObjectType.".len..];
            const sot = try self.arena.create(types.ObjectInstance);
            sot.* = .{ .class_name = "Schema.SObjectType" };
            try sot.fields.put(self.arena, "name", Value{ .string = object_name });
            return Value{ .object = sot };
        }
        if (!std.mem.startsWith(u8, name, "Schema.")) return null;
        const suffix = name["Schema.".len..];
        const dot_idx = std.mem.lastIndexOfScalar(u8, suffix, '.') orelse return null;
        const owner_name = suffix[0..dot_idx];
        const member_name = suffix[dot_idx + 1 ..];
        if (std.ascii.eqlIgnoreCase(owner_name, "SObjectType")) {
            const sot = try self.arena.create(types.ObjectInstance);
            sot.* = .{ .class_name = "Schema.SObjectType" };
            try sot.fields.put(self.arena, "name", Value{ .string = member_name });
            return Value{ .object = sot };
        }
        if (std.ascii.eqlIgnoreCase(member_name, "SObjectType")) {
            const sot = try self.arena.create(types.ObjectInstance);
            sot.* = .{ .class_name = "Schema.SObjectType" };
            try sot.fields.put(self.arena, "name", Value{ .string = owner_name });
            return Value{ .object = sot };
        }
        if (!std.ascii.eqlIgnoreCase(member_name, "class")) {
            return try self.make_s_object_field_token(owner_name, member_name);
        }
        return null;
    }

    fn resolve_instance_field_live(self: *Evaluator, name: []const u8, current_env: *Env) ?Value {
        const this_live = current_env.get("this") orelse return null;
        if (this_live != .object) return null;
        const live = utils.sobject_get(&this_live.object.fields, name) orelse return null;
        if (live == .null_val) return null;
        const live_cd = self.find_class(this_live.object.class_name) orelse return null;
        if (!(self.is_instance_field(live_cd, name) or self.is_parent_instance_field(live_cd, name))) {
            return null;
        }
        if (current_env.get_declared_type(name) != null) return null;
        return live;
    }

    fn invoke_instance_getter(self: *Evaluator, name: []const u8, current_env: *Env) !?Value {
        const this_expr_node = try self.arena.create(ast.Expr);
        this_expr_node.* = .this_expr;
        const fa_node = try self.arena.create(ast.FieldAccess);
        fa_node.* = .{ .object = this_expr_node, .field = name, .null_safe = false };
        const fa_expr = try self.arena.create(ast.Expr);
        fa_expr.* = .{ .field_access = fa_node };
        return try self.eval_expr(fa_expr, current_env);
    }

    fn read_backing_field_in_getter(self: *Evaluator, this_check: Value, name: []const u8) Value {
        if (self.find_field_decl_with_owner(this_check.object.class_name, name)) |lookup| {
            if (lookup.field_decl.modifiers.is_static) {
                return self.read_static_backing_value(lookup.owner_name, name);
            }
        }
        if (this_check.object.fields.get(name)) |fv| return fv;
        for (this_check.object.fields.keys(), this_check.object.fields.values()) |fk, fv| {
            if (std.ascii.eqlIgnoreCase(fk, name)) return fv;
        }
        return .null_val;
    }

    fn resolve_this_getter_or_backing(self: *Evaluator, name: []const u8, current_env: *Env) !?Value {
        const this_check = current_env.get("this") orelse return null;
        if (this_check != .object) return null;
        const already_in_instance_getter = if (self.evaluating_getter) |eg|
            std.ascii.eqlIgnoreCase(eg, name)
        else
            false;
        const shadowed_by_typed_local = current_env.get_declared_type(name) != null;
        if (!already_in_instance_getter and !shadowed_by_typed_local) {
            const this_cd = self.find_class(this_check.object.class_name) orelse return null;
            var scan_cd: ?*ast.ClassDecl = this_cd;
            while (scan_cd) |scd| {
                for (scd.members) |m| {
                    if (m != .field_decl) continue;
                    const pfd = m.field_decl;
                    if (std.ascii.eqlIgnoreCase(pfd.name, name) and pfd.getter_body != null) {
                        return try self.invoke_instance_getter(name, current_env);
                    }
                }
                scan_cd = if (scd.super_class) |sc| self.find_class(sc.name) else null;
            }
            return null;
        }
        if (already_in_instance_getter) {
            return self.read_backing_field_in_getter(this_check, name);
        }
        return null;
    }

    fn resolve_class_static_field_from_this(self: *Evaluator, name: []const u8, current_env: *Env) ?Value {
        const this_val = current_env.get("this") orelse return null;
        if (this_val != .object) return null;
        const this_cn = this_val.object.class_name;
        const key = std.fmt.allocPrint(self.arena, "{s}.{s}", .{ this_cn, name }) catch
            return .null_val;
        if (self.global_env.get(key)) |val| return val;
        if (self.find_class(this_cn)) |cd| {
            if (cd.super_class) |sc| {
                self.ensure_static_init(sc.name);
                const pkey = std.fmt.allocPrint(self.arena, "{s}.{s}", .{ sc.name, name }) catch
                    return .null_val;
                if (self.global_env.get(pkey)) |val| return val;
            }
        }
        if (self.resolve_outer_static_field(this_cn, name)) |val| return val;
        return null;
    }

    fn resolve_current_class_static_field(self: *Evaluator, name: []const u8) ?Value {
        const cc = self.current_class orelse return null;
        if (self.resolve_static_field_value_on_class(cc, name)) |val| return val;
        if (self.find_class(cc)) |cd| {
            if (cd.super_class) |sc| {
                if (self.resolve_static_field_value_on_class(sc.name, name)) |val| return val;
            }
        }
        if (self.resolve_outer_static_field(cc, name)) |val| return val;
        return null;
    }

    fn resolve_inner_type_identifier(self: *Evaluator, name: []const u8, current_env: *Env) ?Value {
        const check_classes = [_]?[]const u8{
            if (current_env.get("this")) |tv| (if (tv == .object) tv.object.class_name else null) else null,
            self.current_class,
        };
        for (check_classes) |cc_opt| {
            var cur_class: ?[]const u8 = cc_opt;
            while (cur_class) |ccn| {
                const ccd = self.find_class(ccn) orelse break;
                for (ccd.members) |member| {
                    switch (member) {
                        .enum_decl => |ed| {
                            if (std.ascii.eqlIgnoreCase(ed.name, name)) return Value{ .string = name };
                        },
                        .class_decl => |inner_cd| {
                            if (std.ascii.eqlIgnoreCase(inner_cd.name, name)) return Value{ .string = name };
                        },
                        else => {},
                    }
                }
                cur_class = if (ccd.super_class) |sc| sc.name else null;
            }
        }
        return null;
    }

    fn try_schema_prefix_field_access(
        self: *Evaluator,
        schema_name: []const u8,
        field: []const u8,
    ) !?Value {
        if (is_known_schema_enum_type(schema_name)) return Value{ .string = field };
        if (std.ascii.eqlIgnoreCase(schema_name, "SObjectType")) {
            const sot = try self.arena.create(types.ObjectInstance);
            sot.* = .{ .class_name = "Schema.SObjectType" };
            try sot.fields.put(self.arena, "name", Value{ .string = field });
            return Value{ .object = sot };
        }
        if (std.ascii.eqlIgnoreCase(field, "SObjectType")) {
            const sot = try self.arena.create(types.ObjectInstance);
            sot.* = .{ .class_name = "Schema.SObjectType" };
            try sot.fields.put(self.arena, "name", Value{ .string = schema_name });
            return Value{ .object = sot };
        }
        if (self.is_s_object_type_name(schema_name) and !std.ascii.eqlIgnoreCase(field, "class")) {
            return try self.make_s_object_field_token(schema_name, field);
        }
        return null;
    }

    fn try_three_level_enum_constant(
        self: *Evaluator,
        outer_name: []const u8,
        inner_name: []const u8,
        field: []const u8,
    ) !?Value {
        self.ensure_static_init(outer_name);
        const inner_fq = try std.fmt.allocPrint(self.arena, "{s}.{s}", .{ outer_name, inner_name });
        self.ensure_static_init(inner_fq);
        const fq_key = try std.fmt.allocPrint(
            self.arena,
            "{s}.{s}.{s}",
            .{ outer_name, inner_name, field },
        );
        if (self.global_env.get(fq_key)) |v| return v;
        if (self.find_class(outer_name)) |cd| {
            for (cd.members) |member| {
                if (member == .enum_decl and
                    std.ascii.eqlIgnoreCase(member.enum_decl.name, inner_name))
                {
                    return Value{ .string = field };
                }
            }
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "System") and
            (std.ascii.eqlIgnoreCase(inner_name, "AccessType") or
                std.ascii.eqlIgnoreCase(inner_name, "AccessLevel") or
                std.ascii.eqlIgnoreCase(inner_name, "LoggingLevel") or
                std.ascii.eqlIgnoreCase(inner_name, "TriggerOperation")))
        {
            return Value{ .string = field };
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "Schema") and is_known_schema_enum_type(inner_name)) {
            return Value{ .string = field };
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "Schema") and
            !std.ascii.eqlIgnoreCase(inner_name, "sObjectType") and
            !std.ascii.eqlIgnoreCase(inner_name, "SObjectType") and
            self.is_s_object_type_name(inner_name))
        {
            if (std.ascii.eqlIgnoreCase(field, "SObjectType")) {
                const sot = try self.arena.create(types.ObjectInstance);
                sot.* = .{ .class_name = "Schema.SObjectType" };
                try sot.fields.put(self.arena, "name", Value{ .string = inner_name });
                return Value{ .object = sot };
            }
            if (!std.ascii.eqlIgnoreCase(field, "class")) {
                return try self.make_s_object_field_token(inner_name, field);
            }
        }
        return null;
    }

    fn eval_field_access_expr(self: *Evaluator, fa: *ast.FieldAccess, current_env: *Env) anyerror!Value {
        if (fa.object.* == .identifier and
            std.mem.startsWith(u8, fa.object.identifier.name, "Schema."))
        {
            const schema_name = fa.object.identifier.name["Schema.".len..];
            if (try self.try_schema_prefix_field_access(schema_name, fa.field)) |v| return v;
        }
        if (fa.object.* == .field_access) {
            const inner_fa = fa.object.field_access;
            if (inner_fa.object.* == .identifier) {
                const outer_name = inner_fa.object.identifier.name;
                const inner_name = inner_fa.field;
                if (try self.try_three_level_enum_constant(outer_name, inner_name, fa.field)) |v| {
                    return v;
                }
            }
        }
        if (fa.null_safe) {
            const obj = self.eval_expr(fa.object, current_env) catch |err| {
                if (err == error.ApexException and self.pending_exception != null) {
                    if (self.pending_exception.? == .object) {
                        const cn = self.pending_exception.?.object.class_name;
                        if (std.ascii.indexOfIgnoreCase(cn, "NullPointer") != null) {
                            self.pending_exception = null;
                            return Value.null_val;
                        }
                    }
                }
                return err;
            };
            if (obj == .null_val) return Value.null_val;
            return self.eval_field_access(fa, obj, current_env);
        }
        const obj = try self.eval_expr(fa.object, current_env);
        return self.eval_field_access(fa, obj, current_env);
    }

    fn instanceof_sobject(val: Value, type_name: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(type_name, "SObject") or
            std.ascii.eqlIgnoreCase(type_name, "Sobject") or
            std.ascii.eqlIgnoreCase(type_name, "sObject"))
        {
            return true;
        }
        return std.ascii.eqlIgnoreCase(val.sobject.type_name, type_name);
    }

    fn instanceof_object(self: *Evaluator, val: Value, type_name: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(val.object.class_name, type_name)) return true;
        if (std.mem.lastIndexOfScalar(u8, type_name, '.')) |dot_pos| {
            if (std.ascii.eqlIgnoreCase(val.object.class_name, type_name[dot_pos + 1 ..])) return true;
        }
        if (std.mem.lastIndexOfScalar(u8, val.object.class_name, '.')) |dot_pos| {
            if (std.ascii.eqlIgnoreCase(val.object.class_name[dot_pos + 1 ..], type_name)) return true;
        }
        if (self.find_class(val.object.class_name)) |cd| {
            var cur: ?*ast.ClassDecl = cd;
            while (cur) |ccd| {
                for (ccd.interfaces) |iface| {
                    if (std.ascii.eqlIgnoreCase(iface.name, type_name)) return true;
                    if (std.mem.lastIndexOfScalar(u8, iface.name, '.')) |dot_pos| {
                        if (std.ascii.eqlIgnoreCase(iface.name[dot_pos + 1 ..], type_name)) return true;
                    }
                }
                if (ccd.super_class) |sc| {
                    if (std.ascii.eqlIgnoreCase(sc.name, type_name)) return true;
                    cur = self.find_class(sc.name);
                } else break;
            }
        }
        if (std.mem.endsWith(u8, type_name, "Exception") and
            std.mem.endsWith(u8, val.object.class_name, "Exception"))
        {
            return true;
        }
        return false;
    }

    fn instanceof_list(self: *Evaluator, val: Value, tn: anytype) bool {
        const tn_base = blk: {
            if (std.mem.lastIndexOfScalar(u8, tn.name, '.')) |di| break :blk tn.name[di + 1 ..];
            break :blk tn.name;
        };
        const is_list_match = std.ascii.eqlIgnoreCase(tn.name, "List");
        const is_iter_match = std.ascii.eqlIgnoreCase(tn_base, "Iterable");
        if (!is_list_match and !is_iter_match) return false;
        if (tn.params.len == 0) return true;
        const elem_type = tn.params[0].name;
        if (std.ascii.eqlIgnoreCase(elem_type, "Object")) return true;
        if (elem_type.len == 0 or elem_type.len > 128) return true;
        for (val.list.items.items) |item| {
            if (item == .null_val) continue;
            if (instanceof_matches_primitive(item, elem_type)) return true;
            if (item == .object and self.is_subclass_of(item.object.class_name, elem_type)) return true;
            return false;
        }
        return true;
    }

    fn instanceof_set_or_map(val: Value, tn_name: []const u8) bool {
        if (val == .map) return std.ascii.eqlIgnoreCase(tn_name, "Map");
        const tn_base = if (std.mem.lastIndexOfScalar(u8, tn_name, '.')) |di|
            tn_name[di + 1 ..]
        else
            tn_name;
        return std.ascii.eqlIgnoreCase(tn_name, "Set") or std.ascii.eqlIgnoreCase(tn_base, "Iterable");
    }

    fn instanceof_string(val: Value, type_name: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(type_name, "String")) return true;
        if (std.ascii.eqlIgnoreCase(type_name, "Id")) return is_salesforce_id_string(val.string);
        return false;
    }

    fn eval_instanceof_expr(self: *Evaluator, ie: *ast.InstanceofExpr, current_env: *Env) anyerror!Value {
        const val = try self.eval_expr(ie.operand, current_env);
        const type_name = ie.type_name.name;
        if (instanceof_matches_primitive(val, type_name)) return Value{ .boolean = true };
        return switch (val) {
            .sobject => Value{ .boolean = instanceof_sobject(val, type_name) },
            .object => Value{ .boolean = self.instanceof_object(val, type_name) },
            .list => Value{ .boolean = self.instanceof_list(val, ie.type_name) },
            .map, .set => Value{ .boolean = instanceof_set_or_map(val, type_name) },
            .string => Value{ .boolean = instanceof_string(val, type_name) },
            .integer, .long, .double => Value{ .boolean = instanceof_matches_primitive(val, type_name) },
            .boolean => Value{ .boolean = std.ascii.eqlIgnoreCase(type_name, "Boolean") },
            else => Value{ .boolean = false },
        };
    }

    fn raise_type_exception(
        self: *Evaluator,
        src_name: []const u8,
        target: []const u8,
    ) !void {
        const msg = try std.fmt.allocPrint(
            self.arena,
            "Invalid conversion from runtime type {s} to {s}",
            .{ src_name, target },
        );
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "System.TypeException" };
        try exc.fields.put(self.arena, "message", Value{ .string = msg });
        self.pending_exception = Value{ .object = exc };
    }

    fn iface_matches_target(iface_name: []const u8, target: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(iface_name, target)) return true;
        if (std.mem.lastIndexOfScalar(u8, target, '.')) |di| {
            if (std.ascii.eqlIgnoreCase(iface_name, target[di + 1 ..])) return true;
        }
        if (std.mem.lastIndexOfScalar(u8, iface_name, '.')) |di| {
            if (std.ascii.eqlIgnoreCase(iface_name[di + 1 ..], target)) return true;
        }
        return false;
    }

    fn cast_compatible_upward(self: *Evaluator, src_name: []const u8, target: []const u8) bool {
        const src_cd = self.find_class(src_name) orelse return false;
        var cur: ?*ast.ClassDecl = src_cd;
        while (cur) |cd| {
            if (std.ascii.eqlIgnoreCase(cd.name, target)) return true;
            for (cd.interfaces) |iface| {
                if (iface_matches_target(iface.name, target)) return true;
            }
            if (cd.super_class) |sc| {
                if (std.ascii.eqlIgnoreCase(sc.name, target)) return true;
                cur = self.find_class(sc.name);
            } else break;
        }
        return false;
    }

    fn cast_compatible_downward(self: *Evaluator, src_name: []const u8, target: []const u8) bool {
        const tgt_cd = self.find_class(target) orelse return false;
        var cur2: ?*ast.ClassDecl = tgt_cd;
        while (cur2) |cd| {
            if (std.ascii.eqlIgnoreCase(cd.name, src_name)) return true;
            if (cd.super_class) |sc| {
                if (std.ascii.eqlIgnoreCase(sc.name, src_name)) return true;
                cur2 = self.find_class(sc.name);
            } else break;
        }
        return false;
    }

    fn handle_date_like_cast(
        self: *Evaluator,
        val: Value,
        src_name: []const u8,
        target: []const u8,
    ) !?Value {
        if (!(std.ascii.eqlIgnoreCase(target, "DateTime") or
            std.ascii.eqlIgnoreCase(target, "Date") or
            std.ascii.eqlIgnoreCase(target, "Time")))
        {
            return null;
        }
        if (std.ascii.eqlIgnoreCase(src_name, "Date") and
            std.ascii.eqlIgnoreCase(target, "DateTime"))
        {
            if (val.object.fields.get("value")) |v| {
                if (v == .string) {
                    const dt_str = try std.fmt.allocPrint(
                        self.arena,
                        "{s}T00:00:00Z",
                        .{v.string},
                    );
                    return try builtins.make_datetime_value(self.arena, dt_str);
                }
            }
            return val;
        }
        if (std.ascii.eqlIgnoreCase(src_name, target)) return null;
        const normalized_target =
            if (std.ascii.eqlIgnoreCase(target, "DateTime")) "Datetime" else if (std.ascii.eqlIgnoreCase(target, "Date")) "Date" else if (std.ascii.eqlIgnoreCase(target, "Time")) "Time" else target;
        try self.raise_type_exception(src_name, normalized_target);
        return error.ApexException;
    }

    fn check_class_cast(
        self: *Evaluator,
        src_name: []const u8,
        target: []const u8,
    ) !void {
        if (std.ascii.eqlIgnoreCase(src_name, target)) return;
        if (self.cast_compatible_upward(src_name, target)) return;
        if (self.cast_compatible_downward(src_name, target)) return;
        if (self.is_known_interface_name(target)) {
            try self.raise_type_exception(src_name, target);
            return error.ApexException;
        }
        if (self.find_class(target)) |tgt_cd| {
            if (tgt_cd.modifiers.is_abstract and self.find_class(src_name) != null) {
                try self.raise_type_exception(src_name, target);
                return error.ApexException;
            }
        }
    }

    fn eval_cast_expr(self: *Evaluator, ce: *ast.CastExpr, current_env: *Env) anyerror!Value {
        const val = try self.eval_expr(ce.operand, current_env);
        const target = ce.target_type.name;
        if (val == .object) {
            const src_name = val.object.class_name;
            if (try self.handle_date_like_cast(val, src_name, target)) |v| return v;
            try self.check_class_cast(src_name, target);
        }
        return val;
    }

    fn eval_call_super(self: *Evaluator, current_env: *Env, args: []const Value) !void {
        const this_val = current_env.get("this") orelse return;
        if (this_val != .object) return;
        const ctor_class = if (self.current_constructor_class) |cc|
            self.find_class(cc)
        else
            self.find_class(this_val.object.class_name);
        const cd = ctor_class orelse return;
        const sc = cd.super_class orelse return;
        const parent_decl = self.find_class(sc.name) orelse return;
        try self.run_constructor(parent_decl, this_val.object, args);
    }

    fn eval_call_this_delegate(self: *Evaluator, current_env: *Env, args: []const Value) !void {
        const this_val = current_env.get("this") orelse return;
        if (this_val != .object) return;
        const ctor_class_name = if (self.current_constructor_class) |cc|
            cc
        else
            this_val.object.class_name;
        const cd = self.find_class(ctor_class_name) orelse return;
        try self.run_constructor(cd, this_val.object, args);
    }

    fn sync_fields_back_to_env(
        pre_fields: []const Value,
        this_obj: *types.ObjectInstance,
        current_env: *Env,
    ) void {
        for (this_obj.fields.keys(), this_obj.fields.values(), 0..) |fk, fv, fi| {
            if (fi < pre_fields.len) {
                const pre = pre_fields[fi];
                const changed = switch (fv) {
                    .null_val => pre != .null_val,
                    .string => |s| if (pre == .string)
                        s.ptr != pre.string.ptr or s.len != pre.string.len
                    else
                        true,
                    .integer => |i| if (pre == .integer) i != pre.integer else true,
                    .boolean => |b| if (pre == .boolean) b != pre.boolean else true,
                    else => true,
                };
                if (changed) current_env.set(fk, fv) catch {};
            } else {
                current_env.set(fk, fv) catch {};
            }
        }
    }

    fn try_call_as_instance_method(
        self: *Evaluator,
        callee: []const u8,
        args: []const Value,
        current_env: *Env,
    ) !?Value {
        const this_val = current_env.get("this") orelse return null;
        if (this_val != .object) return null;
        const actual_decl = self.find_class(this_val.object.class_name);
        const dispatch_decl = blk: {
            if (self.current_class) |current_class_name| {
                if (self.find_class(current_class_name)) |owner_decl| break :blk owner_decl;
            }
            break :blk actual_decl orelse return Value.null_val;
        };
        const md = self.find_method_in_hierarchy(actual_decl, dispatch_decl, callee, args.len);
        if (md == null) return null;

        var pre_fields: [16]Value = undefined;
        const field_keys = this_val.object.fields.keys();
        const n_snap = @min(field_keys.len, pre_fields.len);
        for (this_val.object.fields.values()[0..n_snap], 0..) |v, fi| {
            pre_fields[fi] = v;
        }
        const result = try self.call_instance_method(
            dispatch_decl,
            this_val.object,
            callee,
            args,
        );
        sync_fields_back_to_env(pre_fields[0..n_snap], this_val.object, current_env);
        return result;
    }

    fn try_call_static_in_current_class(
        self: *Evaluator,
        callee: []const u8,
        args: []const Value,
    ) !?Value {
        const cc = self.current_class orelse return null;
        if (self.find_class(cc)) |cd| {
            if (self.find_best_method_in_class_filtered(cd, callee, args, true) != null) {
                return try self.call_method(cc, callee, args);
            }
        }
        if (self.resolve_outer_static_method_owner(cc, callee, args)) |outer_owner| {
            return try self.call_method(outer_owner, callee, args);
        }
        return null;
    }

    fn try_call_any_loaded_class(
        self: *Evaluator,
        callee: []const u8,
        args: []const Value,
    ) !?Value {
        var class_iter = self.classes.iterator();
        while (class_iter.next()) |entry| {
            for (entry.value_ptr.*.members) |member| {
                if (member != .method_decl) continue;
                const md = member.method_decl;
                if (std.ascii.eqlIgnoreCase(md.name, callee)) {
                    return try self.call_method(entry.key_ptr.*, callee, args);
                }
            }
        }
        return null;
    }

    fn eval_call_expr(self: *Evaluator, call: *ast.CallExpr, current_env: *Env) anyerror!Value {
        if (call.loc.line > 0) {
            self.current_call_line = call.loc.line;
            if (self.call_stack.items.len > 0) {
                self.call_stack.items[self.call_stack.items.len - 1].line = call.loc.line;
            }
        }
        var args: std.ArrayListUnmanaged(Value) = .empty;
        var call_type_hints: std.ArrayListUnmanaged(?[]const u8) = .empty;
        for (call.args) |*arg| {
            var arg_value = try self.eval_expr(arg, current_env);
            arg_value = try self.maybe_coerce_schema_expr_value(arg, arg_value);
            try args.append(self.arena, arg_value);
            const hint = self.extract_expr_type_hint(arg, current_env);
            try call_type_hints.append(self.arena, hint);
        }
        const prev_hints = self.cast_type_hints;
        self.cast_type_hints = call_type_hints.items;
        defer self.cast_type_hints = prev_hints;

        if (std.mem.eql(u8, call.callee, "super")) {
            try self.eval_call_super(current_env, args.items);
            return Value.void_val;
        }
        if (std.mem.eql(u8, call.callee, "this")) {
            try self.eval_call_this_delegate(current_env, args.items);
            return Value.void_val;
        }
        if (try self.try_call_as_instance_method(call.callee, args.items, current_env)) |v| return v;
        if (try self.try_call_static_in_current_class(call.callee, args.items)) |v| return v;
        if (try self.try_call_any_loaded_class(call.callee, args.items)) |v| return v;
        if (current_env.get("this")) |this_val| {
            if (this_val == .object or this_val == .sobject or this_val == .string or
                this_val == .list or this_val == .map or this_val == .set)
            {
                return self.eval_instance_method(this_val, call.callee, args.items, current_env);
            }
        }
        return Value.null_val;
    }

    fn eval_identifier_expr(self: *Evaluator, name: []const u8, current_env: *Env) anyerror!Value {
        if (current_env.get(name)) |val| {
            if (val != .null_val) return val;
        }
        if (self.resolve_instance_field_live(name, current_env)) |val| return val;
        if (try self.resolve_schema_dotted_identifier(name)) |val| return val;
        if (try self.resolve_this_getter_or_backing(name, current_env)) |val| return val;
        if (self.resolve_class_static_field_from_this(name, current_env)) |val| return val;
        if (self.resolve_current_class_static_field(name)) |val| return val;
        if (self.resolve_inner_type_identifier(name, current_env)) |val| return val;
        return .null_val;
    }

    fn eval_binary_expr(self: *Evaluator, bin: *ast.BinaryExpr, current_env: *Env) anyerror!Value {
        const left = try self.eval_expr(bin.left, current_env);
        switch (bin.op) {
            .and_op => {
                if (!(utils.coerce_to_bool(left) catch false)) return Value{ .boolean = false };
            },
            .or_op => {
                if (utils.coerce_to_bool(left) catch false) return Value{ .boolean = true };
            },
            else => {},
        }
        const right = try self.eval_expr(bin.right, current_env);
        return eval_binary(self, left, bin.op, right, self.arena);
    }

    fn eval_assignment_expr(self: *Evaluator, asgn: *ast.Assignment, current_env: *Env) anyerror!Value {
        const val = try self.eval_expr(asgn.value, current_env);
        if (asgn.is_postfix) {
            const original = self.eval_expr(asgn.target, current_env) catch Value.null_val;
            _ = try self.eval_assignment(asgn, val, current_env);
            return original;
        }
        return self.eval_assignment(asgn, val, current_env);
    }

    fn eval_index_access_expr(self: *Evaluator, ia: *ast.IndexAccess, current_env: *Env) anyerror!Value {
        const obj = try self.eval_expr(ia.object, current_env);
        const idx = try self.eval_expr(ia.index, current_env);
        if (obj == .list and idx == .integer) {
            if (idx.integer >= 0) {
                const i: usize = @intCast(idx.integer);
                if (i < obj.list.items.items.len) return obj.list.items.items[i];
            }
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "ListException" };
            try exc.fields.put(self.arena, "message", Value{ .string = try std.fmt.allocPrint(
                self.arena,
                "List index out of bounds: {d}",
                .{idx.integer},
            ) });
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        if (obj == .map and idx == .string) {
            return obj.map.entries.get(idx.string) orelse Value.null_val;
        }
        return Value.null_val;
    }

    fn eval_new_expr_wrapper(self: *Evaluator, ne: *ast.NewExpr, current_env: *Env) anyerror!Value {
        if (ne.loc.line > 0) {
            self.current_call_line = ne.loc.line;
            if (self.call_stack.items.len > 0) {
                self.call_stack.items[self.call_stack.items.len - 1].line = ne.loc.line;
            }
        }
        const val = try self.eval_new_expr(ne, current_env);
        if (val == .object and std.mem.endsWith(u8, val.object.class_name, "Exception")) {
            if (val.object.fields.get("stackTraceString") == null) {
                const line = if (ne.loc.line > 0) ne.loc.line else 1;
                const trace = try self.build_stack_trace_string();
                try val.object.fields.put(self.arena, "stackTraceString", Value{ .string = trace });
                try val.object.fields.put(self.arena, "lineNumber", Value{ .integer = @intCast(line) });
            }
        }
        return val;
    }

    fn eval_ternary_expr(self: *Evaluator, te: *ast.TernaryExpr, current_env: *Env) anyerror!Value {
        const cond = try self.eval_expr(te.condition, current_env);
        if (utils.coerce_to_bool(cond) catch false) {
            return self.eval_expr(te.then_expr, current_env);
        }
        return self.eval_expr(te.else_expr, current_env);
    }

    pub fn eval_expr(self: *Evaluator, expr: *const ast.Expr, current_env: *Env) anyerror!Value {
        self.call_depth +|= 1;
        defer self.call_depth -|= 1;

        if (self.call_depth > self.max_call_depth) {
            // error を返すと error return trace の記録でスタックを消費し
            // OS スタックオーバーフローを引き起こす場合があるため null を返す
            return .null_val;
        }
        return switch (expr.*) {
            .integer_literal => |v| Value{ .integer = v },
            .long_literal => |v| Value{ .long = v },
            .double_literal => |v| Value{ .double = v },
            .string_literal => |v| Value{ .string = v },
            .boolean_literal => |v| Value{ .boolean = v },
            .null_literal => .null_val,
            .this_expr, .super_expr => current_env.get("this") orelse .null_val,
            .identifier => |id| try self.eval_identifier_expr(id.name, current_env),
            .binary => |bin| try self.eval_binary_expr(bin, current_env),
            .unary => |un| eval_unary(un.op, try self.eval_expr(un.operand, current_env)),
            .assignment => |asgn| try self.eval_assignment_expr(asgn, current_env),
            .call => |call| try self.eval_call_expr(call, current_env),
            .method_call => |mc| try self.eval_method_call(mc, current_env),
            .field_access => |fa| try self.eval_field_access_expr(fa, current_env),
            .index_access => |ia| try self.eval_index_access_expr(ia, current_env),
            .new_expr => |ne| try self.eval_new_expr_wrapper(ne, current_env),
            .cast_expr => |ce| try self.eval_cast_expr(ce, current_env),
            .ternary => |te| try self.eval_ternary_expr(te, current_env),
            .instanceof => |ie| try self.eval_instanceof_expr(ie, current_env),
            .soql => |sq| try self.execute_soql(sq.raw, current_env),
            .grouped => |inner| try self.eval_expr(inner, current_env),
        };
    }

    fn is_collection_type_name(type_name: []const u8) bool {
        const base = type_base_name(strip_type_namespace(type_name));
        return std.ascii.eqlIgnoreCase(base, "List") or
            std.ascii.eqlIgnoreCase(base, "Set") or
            std.ascii.eqlIgnoreCase(base, "Iterable") or
            std.ascii.eqlIgnoreCase(base, "Map");
    }

    fn strip_type_namespace(type_name: []const u8) []const u8 {
        if (std.ascii.startsWithIgnoreCase(type_name, "System.")) return type_name["System.".len..];
        if (std.ascii.startsWithIgnoreCase(type_name, "Schema.")) return type_name["Schema.".len..];
        return type_name;
    }

    fn extract_collection_element_type_name(type_name: []const u8) ?[]const u8 {
        const stripped = strip_type_namespace(type_name);
        if (std.ascii.startsWithIgnoreCase(stripped, "List<") or
            std.ascii.startsWithIgnoreCase(stripped, "Set<") or
            std.ascii.startsWithIgnoreCase(stripped, "Iterable<"))
        {
            const lt = std.mem.indexOfScalar(u8, stripped, '<') orelse return null;
            const gt = std.mem.lastIndexOfScalar(u8, stripped, '>') orelse return null;
            if (gt <= lt + 1) return null;
            return std.mem.trim(u8, stripped[lt + 1 .. gt], " \t");
        }
        if (std.mem.endsWith(u8, stripped, "[]")) return stripped[0 .. stripped.len - 2];
        return null;
    }

    fn extract_map_type_args(type_name: []const u8) ?struct { key: []const u8, value: []const u8 } {
        const stripped = strip_type_namespace(type_name);
        if (!std.ascii.startsWithIgnoreCase(stripped, "Map<")) return null;
        const lt = std.mem.indexOfScalar(u8, stripped, '<') orelse return null;
        const gt = std.mem.lastIndexOfScalar(u8, stripped, '>') orelse return null;
        if (gt <= lt + 1) return null;

        const inner = stripped[lt + 1 .. gt];
        var depth: usize = 0;
        for (inner, 0..) |ch, idx| {
            switch (ch) {
                '<' => depth += 1,
                '>' => {
                    if (depth > 0) depth -= 1;
                },
                ',' => if (depth == 0) {
                    return .{
                        .key = std.mem.trim(u8, inner[0..idx], " \t"),
                        .value = std.mem.trim(u8, inner[idx + 1 ..], " \t"),
                    };
                },
                else => {},
            }
        }
        return null;
    }

    fn annotate_declared_collection_type(
        self: *Evaluator,
        value: Value,
        declared_type: ?[]const u8,
    ) Value {
        if (declared_type) |type_name| {
            if (value == .list) {
                if (value.list.element_type == null) {
                    if (extract_collection_element_type_name(type_name)) |elem_type| {
                        value.list.element_type = strip_type_namespace(elem_type);
                    }
                }
            }
        }
        _ = self;
        return value;
    }

    fn names_match_by_simple_name(left: []const u8, right: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(left, right)) return true;
        const left_simple =
            if (std.mem.lastIndexOfScalar(u8, left, '.')) |idx| left[idx + 1 ..] else left;
        const right_simple =
            if (std.mem.lastIndexOfScalar(u8, right, '.')) |idx| right[idx + 1 ..] else right;
        return std.ascii.eqlIgnoreCase(left_simple, right_simple);
    }

    fn infer_list_element_type(
        self: *Evaluator,
        list: *types.ListValue,
        arg_hint: ?[]const u8,
    ) ?[]const u8 {
        _ = self;
        if (list.element_type) |element_type| return strip_type_namespace(element_type);
        if (arg_hint) |hint| {
            if (extract_collection_element_type_name(hint)) |element_type| return strip_type_namespace(element_type);
        }
        if (list.items.items.len == 0) return null;

        return switch (list.items.items[0]) {
            .sobject => |sob| strip_type_namespace(sob.type_name),
            .object => |obj| strip_type_namespace(obj.class_name),
            .string => |s| if (Evaluator.is_salesforce_id_string(s)) "Id" else null,
            else => null,
        };
    }

    fn score_list_argument_for_param(
        self: *Evaluator,
        list: *types.ListValue,
        arg_hint: ?[]const u8,
        param_type: types.TypeRef,
    ) i32 {
        const param_base = type_base_name(param_type.name);
        if (!std.ascii.eqlIgnoreCase(param_base, "List") and
            !std.ascii.eqlIgnoreCase(param_base, "Iterable"))
        {
            return overload_score_for_arg(Value{ .list = list }, param_type.name);
        }
        if (param_type.params.len == 0) return 2;

        const param_elem_type = strip_type_namespace(self.render_type_ref(param_type.params[0]));
        const param_elem_base = type_base_name(param_elem_type);
        const actual_elem_type = self.infer_list_element_type(list, arg_hint);
        const actual_items_are_sobjects = blk: {
            if (list.items.items.len == 0) break :blk false;
            break :blk list.items.items[0] == .sobject;
        };
        if (actual_elem_type == null) return 2;

        const actual_elem_base = type_base_name(actual_elem_type.?);
        if (std.ascii.eqlIgnoreCase(param_elem_base, "SObject")) {
            if (actual_items_are_sobjects or
                std.ascii.eqlIgnoreCase(actual_elem_base, "SObject") or
                self.is_s_object_type_name(actual_elem_base))
            {
                return 3;
            }
            return 0;
        }
        if (names_match_by_simple_name(actual_elem_base, param_elem_base)) return 3;
        if (self.is_s_object_type_name(actual_elem_base) and
            self.is_s_object_type_name(param_elem_base) and
            self.is_subclass_of(actual_elem_base, param_elem_base))
        {
            return 2;
        }
        return 0;
    }

    fn type_base_name(type_name: []const u8) []const u8 {
        const stripped = strip_type_namespace(type_name);
        if (std.mem.indexOfScalar(u8, stripped, '<')) |lt| return stripped[0..lt];
        return stripped;
    }

    fn find_declared_field_type(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) ?[]const u8 {
        if (self.find_class(class_name)) |cd| {
            var cur: ?*ast.ClassDecl = cd;
            while (cur) |ccd| {
                for (ccd.members) |member| {
                    switch (member) {
                        .field_decl => |fd| {
                            if (std.ascii.eqlIgnoreCase(fd.name, field_name))
                                return self.render_type_ref(fd.type_ref);
                        },
                        else => {},
                    }
                }
                cur = if (ccd.super_class) |sc| self.find_class(sc.name) else null;
            }
        }
        return null;
    }

    fn resolve_assignment_target_type(
        self: *Evaluator,
        target: *const ast.Expr,
        current_env: *Env,
    ) ?[]const u8 {
        switch (target.*) {
            .identifier => |id| {
                if (current_env.get_declared_type(id.name)) |type_name| return type_name;
                if (current_env.get("this")) |this_val| {
                    if (this_val == .object) {
                        if (self.find_declared_field_type(
                            this_val.object.class_name,
                            id.name,
                        )) |type_name| return type_name;
                    }
                }
                if (self.current_class) |cc| {
                    if (self.find_declared_field_type(cc, id.name)) |type_name| return type_name;
                    if (self.find_outer_class_name(cc)) |outer| {
                        if (self.find_declared_field_type(
                            outer,
                            id.name,
                        )) |type_name| return type_name;
                    }
                }
                return null;
            },
            .field_access => |fa| {
                if (fa.object.* == .this_expr) {
                    if (current_env.get("this")) |this_val| {
                        if (this_val == .object) {
                            return self.find_declared_field_type(
                                this_val.object.class_name,
                                fa.field,
                            );
                        }
                    }
                    return null;
                }
                if (fa.object.* == .identifier) {
                    const owner_name = fa.object.identifier.name;
                    if (current_env.get_declared_type(owner_name)) |owner_type| {
                        if (self.find_declared_field_type(
                            type_base_name(owner_type),
                            fa.field,
                        )) |type_name| return type_name;
                    }
                    const is_class = self.find_class(owner_name) != null;
                    const is_var = current_env.get(owner_name) != null;
                    if (is_class and !is_var) {
                        if (self.find_declared_field_type(
                            owner_name,
                            fa.field,
                        )) |type_name| return type_name;
                    }
                }
                if (self.resolve_assignment_target_type(fa.object, current_env)) |owner_type| {
                    if (self.find_declared_field_type(
                        type_base_name(owner_type),
                        fa.field,
                    )) |type_name| return type_name;
                }
                return null;
            },
            else => return null,
        }
    }

    fn extract_expr_type_hint(
        self: *Evaluator,
        expr: *const ast.Expr,
        current_env: *Env,
    ) ?[]const u8 {
        switch (expr.*) {
            .cast_expr => |ce| return self.render_type_ref(ce.target_type),
            .new_expr => |ne| return self.extract_new_expr_container_hint(ne),
            .ternary => |te| return self.extract_ternary_type_hint(te, current_env),
            .identifier, .field_access => {
                if (self.resolve_assignment_target_type(expr, current_env)) |type_name| {
                    return strip_type_namespace(type_name);
                }
                // Fall back to enum detection for bare `MyEnum.VALUE` forms.
                return self.enum_access_type_name(expr);
            },
            .method_call => |mc| return self.extract_method_call_type_hint(mc, current_env),
            else => return null,
        }
    }

    /// Only surface container-shape hints (Set<X>, List<X>, Map<K,V>) so that
    /// generic-element overloads can disambiguate. For user types the ranker's
    /// subclass-scoring pass already handles disambiguation.
    fn extract_new_expr_container_hint(self: *Evaluator, ne: *ast.NewExpr) ?[]const u8 {
        const rendered = self.render_type_ref(ne.type_name);
        if (std.mem.indexOfScalar(u8, rendered, '<') != null) return rendered;
        return null;
    }

    /// `cond ? then : else` — when both branches have a compatible hint
    /// (typically enum expressions like `flag ? MyEnum.A : MyEnum.B`), surface
    /// it so overload resolution can prefer the enum-typed parameter. Falls
    /// back to whichever branch has a hint, else null.
    fn extract_ternary_type_hint(
        self: *Evaluator,
        te: *ast.TernaryExpr,
        current_env: *Env,
    ) ?[]const u8 {
        const then_hint = self.extract_expr_type_hint(te.then_expr, current_env) orelse
            self.enum_access_type_name(te.then_expr) orelse null;
        const else_hint = self.extract_expr_type_hint(te.else_expr, current_env) orelse
            self.enum_access_type_name(te.else_expr) orelse null;
        if (then_hint != null and else_hint != null and
            std.ascii.eqlIgnoreCase(then_hint.?, else_hint.?))
        {
            return then_hint;
        }
        if (then_hint != null) return then_hint;
        if (else_hint != null) return else_hint;
        return null;
    }

    fn extract_method_call_type_hint(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        current_env: *Env,
    ) ?[]const u8 {
        const arg_count = mc.args.len;
        if (mc.object.* == .identifier) {
            const target_name = mc.object.identifier.name;
            if (self.find_class(target_name)) |class_decl| {
                if (self.find_method_in_hierarchy(
                    null,
                    class_decl,
                    mc.method,
                    arg_count,
                )) |method_decl| {
                    return strip_type_namespace(self.render_type_ref(method_decl.return_type));
                }
            }
            if (self.resolve_assignment_target_type(mc.object, current_env)) |instance_type| {
                const base_type = type_base_name(instance_type);
                if (self.find_class(base_type)) |class_decl| {
                    if (self.find_method_in_hierarchy(
                        null,
                        class_decl,
                        mc.method,
                        arg_count,
                    )) |method_decl| {
                        return strip_type_namespace(
                            self.render_type_ref(method_decl.return_type),
                        );
                    }
                }
            }
        }
        if (mc.object.* == .field_access) {
            const fa = mc.object.field_access;
            if (fa.object.* == .identifier) {
                const qualified_name = std.fmt.allocPrint(
                    self.arena,
                    "{s}.{s}",
                    .{ fa.object.identifier.name, fa.field },
                ) catch return null;
                if (self.find_class(qualified_name)) |class_decl| {
                    if (self.find_method_in_hierarchy(
                        null,
                        class_decl,
                        mc.method,
                        arg_count,
                    )) |method_decl| {
                        return strip_type_namespace(
                            self.render_type_ref(method_decl.return_type),
                        );
                    }
                }
            }
        }
        return null;
    }

    fn maybe_coerce_schema_expr_value(
        self: *Evaluator,
        expr: *const ast.Expr,
        value: Value,
    ) !Value {
        if (value != .string) return value;
        return switch (expr.*) {
            .identifier => |id| try self.coerce_schema_identifier(id.name, value),
            .field_access => |fa| try self.coerce_schema_field_access(fa, value),
            else => value,
        };
    }

    /// Identifier of the form `Schema.Owner.Member` where the real lookup
    /// should produce a Schema-enum value, an SObjectType token, or an
    /// SObjectField token.
    fn coerce_schema_identifier(
        self: *Evaluator,
        name: []const u8,
        value: Value,
    ) !Value {
        if (!std.mem.startsWith(u8, name, "Schema.")) return value;
        const suffix = name["Schema.".len..];
        const dot_idx = std.mem.lastIndexOfScalar(u8, suffix, '.') orelse return value;
        const owner_name = suffix[0..dot_idx];
        const member_name = suffix[dot_idx + 1 ..];
        if (is_known_schema_enum_type(owner_name)) return Value{ .string = member_name };
        if (std.ascii.eqlIgnoreCase(owner_name, "SObjectType")) {
            return try self.make_sobject_type_token(member_name);
        }
        if (std.ascii.eqlIgnoreCase(member_name, "SObjectType")) {
            return try self.make_sobject_type_token(owner_name);
        }
        if (std.ascii.eqlIgnoreCase(member_name, "class")) return value;
        return try self.make_s_object_field_token(owner_name, member_name);
    }

    /// FieldAccess chains rooted at `Schema.*` → produce the matching proxy
    /// value (enum string / SObjectType token / SObjectField token). Returns
    /// the original `value` when no Schema-based rewrite applies.
    fn coerce_schema_field_access(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        value: Value,
    ) !Value {
        if (fa.object.* == .field_access) {
            if (try self.coerce_schema_two_level(fa)) |v| return v;
        }
        if (fa.object.* == .identifier and
            std.mem.startsWith(u8, fa.object.identifier.name, "Schema."))
        {
            if (try self.coerce_schema_one_level(
                fa.object.identifier.name["Schema.".len..],
                fa.field,
            )) |v| return v;
        }
        return value;
    }

    fn coerce_schema_two_level(
        self: *Evaluator,
        fa: *ast.FieldAccess,
    ) !?Value {
        const inner_fa = fa.object.field_access;
        if (inner_fa.object.* != .identifier) return null;
        if (!std.ascii.eqlIgnoreCase(inner_fa.object.identifier.name, "Schema")) return null;
        if (is_known_schema_enum_type(inner_fa.field)) return Value{ .string = fa.field };
        if (std.ascii.eqlIgnoreCase(inner_fa.field, "sObjectType") or
            std.ascii.eqlIgnoreCase(inner_fa.field, "SObjectType"))
        {
            return try self.make_sobject_type_token(fa.field);
        }
        if (std.ascii.eqlIgnoreCase(fa.field, "SObjectType")) {
            return try self.make_sobject_type_token(inner_fa.field);
        }
        if (!std.ascii.eqlIgnoreCase(fa.field, "class")) {
            return try self.make_s_object_field_token(inner_fa.field, fa.field);
        }
        return null;
    }

    fn coerce_schema_one_level(
        self: *Evaluator,
        schema_name: []const u8,
        field_name: []const u8,
    ) !?Value {
        if (is_known_schema_enum_type(schema_name)) return Value{ .string = field_name };
        if (std.ascii.eqlIgnoreCase(schema_name, "SObjectType")) {
            return try self.make_sobject_type_token(field_name);
        }
        if (std.ascii.eqlIgnoreCase(field_name, "SObjectType")) {
            return try self.make_sobject_type_token(schema_name);
        }
        if (!std.ascii.eqlIgnoreCase(field_name, "class")) {
            return try self.make_s_object_field_token(schema_name, field_name);
        }
        return null;
    }

    fn render_type_ref(self: *Evaluator, type_ref: types.TypeRef) []const u8 {
        if (type_ref.params.len == 0) return strip_type_namespace(type_ref.name);

        var buf: std.ArrayListUnmanaged(u8) = .empty;
        buf.appendSlice(
            self.arena,
            strip_type_namespace(type_ref.name),
        ) catch return strip_type_namespace(type_ref.name);
        buf.append(self.arena, '<') catch return strip_type_namespace(type_ref.name);
        for (type_ref.params, 0..) |param, i| {
            if (i > 0) buf.appendSlice(self.arena, ",") catch {};
            buf.appendSlice(self.arena, self.render_type_ref(param)) catch {};
        }
        buf.append(self.arena, '>') catch {};
        return buf.toOwnedSlice(self.arena) catch strip_type_namespace(type_ref.name);
    }

    fn coerce_soql_assignment_to_declared_type(
        self: *Evaluator,
        val: Value,
        source_expr: ?*const ast.Expr,
        target_type: []const u8,
    ) !Value {
        if (source_expr == null or
            source_expr.?.* != .soql or
            val != .list or
            is_collection_type_name(target_type))
        {
            return val;
        }
        if (val.list.items.items.len > 0) return val.list.items.items[0];

        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "QueryException" };
        try exc.fields.put(
            self.arena,
            "message",
            Value{ .string = "List has no rows for assignment to SObject" },
        );
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn eval_assignment(
        self: *Evaluator,
        asgn: *ast.Assignment,
        val: Value,
        current_env: *Env,
    ) !Value {
        var coerced_val = val;
        if (self.resolve_assignment_target_type(asgn.target, current_env)) |target_type| {
            coerced_val = try self.coerce_soql_assignment_to_declared_type(
                coerced_val,
                asgn.value,
                target_type,
            );
            coerced_val = self.annotate_declared_collection_type(coerced_val, target_type);
        }
        switch (asgn.target.*) {
            .identifier => |id| {
                // ??= : only assign if current value is null
                if (asgn.op == .null_coalesce_assign) {
                    const cur = self.eval_expr(asgn.target, current_env) catch Value.null_val;
                    if (cur != .null_val) return cur;
                    // Current is null, fall through to assign the new value
                    const nca = try self.arena.create(ast.Assignment);
                    nca.* = .{ .target = asgn.target, .op = .assign, .value = asgn.value, .loc = asgn.loc };
                    return self.eval_assignment(nca, coerced_val, current_env);
                }
                const final_val = if (asgn.op != .assign) blk: {
                    const cur = if (current_env.has(id.name))
                        (current_env.get(id.name) orelse Value.null_val)
                    else
                        (self.resolve_bare_static_value(
                            current_env,
                            id.name,
                        ) orelse Value.null_val);
                    var result = eval_compound_assign(cur, asgn.op, coerced_val, self.arena);
                    // Handle string concatenation for +=
                    if (asgn.op == .plus_assign and (cur == .string or coerced_val == .string)) {
                        const ls = try utils.coerce_to_string(cur, self.arena);
                        const rs = try utils.coerce_to_string(coerced_val, self.arena);
                        result = Value{ .string = try std.fmt.allocPrint(
                            self.arena,
                            "{s}{s}",
                            .{ ls, rs },
                        ) };
                    }
                    break :blk result;
                } else coerced_val;
                current_env.set(id.name, final_val) catch {
                    // Before defining locally, check if this is a static field
                    // (ClassName.fieldName)
                    // to avoid shadowing static variables with local bindings.
                    var found_static = false;
                    if (self.current_class) |cc| {
                        const sk = std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ cc, id.name },
                        ) catch "";
                        if (self.global_env.get(sk) != null) {
                            self.global_env.set(sk, final_val) catch {};
                            found_static = true;
                        } else if (self.find_outer_class_name(cc)) |oc| {
                            const osk = std.fmt.allocPrint(
                                self.arena,
                                "{s}.{s}",
                                .{ oc, id.name },
                            ) catch "";
                            if (self.global_env.get(osk) != null) {
                                self.global_env.set(osk, final_val) catch {};
                                found_static = true;
                            }
                        }
                    }
                    if (current_env.get("this")) |tv| {
                        if (tv == .object) {
                            const sk = std.fmt.allocPrint(
                                self.arena,
                                "{s}.{s}",
                                .{ tv.object.class_name, id.name },
                            ) catch "";
                            if (self.global_env.get(sk) != null) {
                                self.global_env.set(sk, final_val) catch {};
                                found_static = true;
                            } else if (self.find_outer_class_name(tv.object.class_name)) |oc| {
                                const osk = std.fmt.allocPrint(
                                    self.arena,
                                    "{s}.{s}",
                                    .{ oc, id.name },
                                ) catch "";
                                if (self.global_env.get(osk) != null) {
                                    self.global_env.set(osk, final_val) catch {};
                                    found_static = true;
                                }
                            }
                        }
                    }
                    if (!found_static) {
                        try current_env.define(id.name, final_val);
                    }
                };
                // Also update instance field on `this` if field exists or is declared
                if (current_env.get("this")) |this_val| {
                    if (this_val == .object) {
                        // Check if this field already exists on the instance or is declared in
                        // class
                        var should_update = false;
                        for (this_val.object.fields.keys()) |k| {
                            if (std.ascii.eqlIgnoreCase(k, id.name)) {
                                should_update = true;
                                break;
                            }
                        }
                        if (!should_update) {
                            if (self.find_class(this_val.object.class_name)) |cd| {
                                should_update = self.is_instance_field(
                                    cd,
                                    id.name,
                                ) or self.is_parent_instance_field(cd, id.name);
                            }
                        }
                        if (should_update) {
                            try this_val.object.fields.put(self.arena, id.name, final_val);
                        }
                        // Also update static field if applicable
                        const static_key = std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ this_val.object.class_name, id.name },
                        ) catch "";
                        if (self.global_env.get(static_key) != null) {
                            self.global_env.set(static_key, final_val) catch {};
                        }
                    }
                }
                // Also update current_class static field if applicable
                if (self.current_class) |cc| {
                    if (current_env.get("this") == null) { // Only in static context
                        const static_key = std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ cc, id.name },
                        ) catch "";
                        if (self.global_env.get(static_key) != null) {
                            self.global_env.set(static_key, final_val) catch {};
                        } else if (self.find_outer_class_name(cc)) |oc| {
                            const osk = std.fmt.allocPrint(
                                self.arena,
                                "{s}.{s}",
                                .{ oc, id.name },
                            ) catch "";
                            if (self.global_env.get(osk) != null) {
                                self.global_env.set(osk, final_val) catch {};
                            }
                        }
                    }
                }
                return final_val;
            },
            .field_access => |fa| {
                // Handle static field assignment: ClassName.fieldName = val
                if (fa.object.* == .identifier) {
                    const cls = fa.object.identifier.name;
                    // Check if it's a class name (not a local variable or a static field
                    // in the enclosing class/inheritance chain).
                    const is_class = self.find_class(cls) != null or
                        std.ascii.eqlIgnoreCase(cls, "RestContext") or
                        std.ascii.eqlIgnoreCase(cls, "System") or
                        std.ascii.eqlIgnoreCase(cls, "Trigger");
                    const is_var = current_env.get(cls) != null or self.resolve_bare_static_value(
                        current_env,
                        cls,
                    ) != null;
                    if (is_class and !is_var) {
                        // Lazy static init: ensure the class is initialized before writing
                        self.ensure_static_init(cls);
                        const key = try std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ cls, fa.field },
                        );
                        var final_val = coerced_val;
                        if (asgn.op != .assign) {
                            const cur = self.global_env.get(key) orelse Value.null_val;
                            final_val = eval_compound_assign(cur, asgn.op, coerced_val, self.arena);
                            if (asgn.op == .plus_assign and
                                (cur == .string or coerced_val == .string))
                            {
                                const ls = try utils.coerce_to_string(cur, self.arena);
                                const rs = try utils.coerce_to_string(coerced_val, self.arena);
                                final_val = Value{ .string = try std.fmt.allocPrint(
                                    self.arena,
                                    "{s}{s}",
                                    .{ ls, rs },
                                ) };
                            }
                        }
                        self.global_env.set(key, final_val) catch {
                            try self.global_env.define(key, final_val);
                        };
                        return final_val;
                    }
                }
                const obj = try self.eval_expr(fa.object, current_env);
                var final_val = coerced_val;
                if (asgn.op != .assign) {
                    // Compound assignment: get current value and compute
                    const cur = if (obj == .sobject)
                        utils.sobject_get(&obj.sobject.fields, fa.field) orelse Value.null_val
                    else if (obj == .object)
                        utils.sobject_get(&obj.object.fields, fa.field) orelse Value.null_val
                    else
                        Value.null_val;
                    final_val = eval_compound_assign(cur, asgn.op, coerced_val, self.arena);
                    // Handle string concatenation for +=
                    if (asgn.op == .plus_assign and (cur == .string or coerced_val == .string)) {
                        const ls = try utils.coerce_to_string(cur, self.arena);
                        const rs = try utils.coerce_to_string(coerced_val, self.arena);
                        final_val = Value{ .string = try std.fmt.allocPrint(
                            self.arena,
                            "{s}{s}",
                            .{ ls, rs },
                        ) };
                    }
                }
                if (obj == .sobject) {
                    try utils.sobject_put(&obj.sobject.fields, self.arena, fa.field, final_val);
                    // Sync SObject.id when Id field is set
                    if (std.ascii.eqlIgnoreCase(fa.field, "Id")) {
                        obj.sobject.id = if (final_val == .string) final_val.string else null;
                    }
                } else if (obj == .object) {
                    if (self.find_class(obj.object.class_name)) |class_decl| {
                        for (class_decl.members) |member| {
                            switch (member) {
                                .field_decl => |fd| {
                                    if (!std.ascii.eqlIgnoreCase(fd.name, fa.field) or
                                        fd.setter_body == null)
                                    {
                                        continue;
                                    }

                                    const setter_env = try self.global_env.child();
                                    try setter_env.define("this", Value{ .object = obj.object });

                                    for (
                                        obj.object.fields.keys(),
                                        obj.object.fields.values(),
                                    ) |k, v| {
                                        setter_env.set(k, v) catch {
                                            try setter_env.define(k, v);
                                        };
                                    }
                                    try setter_env.define("value", final_val);
                                    _ = try self.exec_block(fd.setter_body.?, setter_env);

                                    if (setter_env.get("this")) |this_val| {
                                        if (this_val == .object and this_val.object == obj.object) {
                                            var field_keys: std.ArrayListUnmanaged(
                                                []const u8,
                                            ) = .empty;
                                            for (obj.object.fields.keys()) |k| field_keys.append(
                                                self.arena,
                                                k,
                                            ) catch {};
                                            for (field_keys.items) |k| {
                                                if (setter_env.get(k)) |updated| {
                                                    try obj.object.fields.put(
                                                        self.arena,
                                                        k,
                                                        updated,
                                                    );
                                                }
                                            }
                                        } else if (this_val == .object) {
                                            for (
                                                this_val.object.fields.keys(),
                                                this_val.object.fields.values(),
                                            ) |k, v| {
                                                try obj.object.fields.put(self.arena, k, v);
                                            }
                                        }
                                    }

                                    if (fa.object.* == .this_expr) {
                                        current_env.set(
                                            fa.field,
                                            obj.object.fields.get(fa.field) orelse final_val,
                                        ) catch {};
                                    }
                                    return final_val;
                                },
                                else => {},
                            }
                        }
                    }
                    // Case-insensitive put: use existing key if it matches
                    var existing_key: ?[]const u8 = null;
                    for (obj.object.fields.keys()) |k| {
                        if (std.ascii.eqlIgnoreCase(k, fa.field)) {
                            existing_key = k;
                            break;
                        }
                    }
                    try obj.object.fields.put(self.arena, existing_key orelse fa.field, final_val);
                    // Sync local env when assigning to this.field
                    // so that bare field references (without this.) see the updated value
                    if (fa.object.* == .this_expr) {
                        current_env.set(fa.field, final_val) catch {};
                    }
                }
                return final_val;
            },
            .index_access => |ia| {
                const obj = try self.eval_expr(ia.object, current_env);
                const idx = try self.eval_expr(ia.index, current_env);
                if (obj == .list and idx == .integer and idx.integer >= 0) {
                    const i: usize = @intCast(idx.integer);
                    if (i < obj.list.items.items.len) {
                        obj.list.items.items[i] = val;
                    }
                }
                return val;
            },
            else => return val,
        }
    }

    /// Apex platform magic: `record.FieldName.addError(msg)` is sugar for
    /// `record.addError(FieldName, msg)` — attach an error to the field on the
    /// record rather than dereferencing its value. Detecting the pattern
    /// before evaluating the receiver avoids a spurious NPE on null fields.
    fn try_mc_add_error_sugar(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        current_env: *Env,
    ) anyerror!?Value {
        if (!std.ascii.eqlIgnoreCase(mc.method, "addError")) return null;
        if (mc.args.len != 1) return null;
        if (mc.object.* != .field_access) return null;

        const fa = mc.object.field_access;
        const receiver_val = self.eval_expr(fa.object, current_env) catch Value.null_val;
        if (receiver_val != .sobject) return null;

        const msg_val = try self.eval_expr(&mc.args[0], current_env);
        const msg_str: []const u8 = switch (msg_val) {
            .string => |s| s,
            else => try utils.coerce_to_string(msg_val, self.arena),
        };
        const err_obj = try self.arena.create(types.ObjectInstance);
        err_obj.* = .{ .class_name = "Database.Error" };
        try err_obj.fields.put(self.arena, "message", Value{ .string = msg_str });
        try err_obj.fields.put(
            self.arena,
            "statusCode",
            Value{ .string = "FIELD_CUSTOM_VALIDATION_EXCEPTION" },
        );
        try err_obj.fields.put(self.arena, "field", Value{ .string = fa.field });
        const fields_list = try self.arena.create(types.ListValue);
        fields_list.* = .{};
        try fields_list.items.append(self.arena, Value{ .string = fa.field });
        try err_obj.fields.put(self.arena, "fields", Value{ .list = fields_list });

        var errors_list =
            if (utils.sobject_get(&receiver_val.sobject.fields, "errors")) |existing|
                if (existing == .list) existing.list else blk: {
                    const lst = try self.arena.create(types.ListValue);
                    lst.* = .{};
                    break :blk lst;
                }
            else blk: {
                const lst = try self.arena.create(types.ListValue);
                lst.* = .{};
                break :blk lst;
            };
        try errors_list.items.append(self.arena, Value{ .object = err_obj });
        try utils.sobject_put(
            &receiver_val.sobject.fields,
            self.arena,
            "errors",
            Value{ .list = errors_list },
        );
        return Value.void_val;
    }

    /// Null-safe operator (?.): when the receiver evaluates to null (or throws
    /// a NullPointerException), short-circuit the call to null. Returns null
    /// when the call is not null-safe or the receiver is non-null.
    fn mc_null_safe_short_circuit(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        current_env: *Env,
    ) anyerror!?Value {
        if (!mc.null_safe) return null;
        const obj_val = self.eval_expr(mc.object, current_env) catch |err| {
            if (err == error.ApexException and self.pending_exception != null) {
                if (self.pending_exception.? == .object) {
                    const class_name = self.pending_exception.?.object.class_name;
                    if (std.ascii.indexOfIgnoreCase(class_name, "NullPointer") != null) {
                        self.pending_exception = null;
                        return Value.null_val;
                    }
                }
            }
            return err;
        };
        if (obj_val == .null_val) return Value.null_val;
        return null;
    }

    /// `System.Search.query(soql)` short-circuit: execute SOSL directly.
    /// Returns null when the method call is not this specific chain.
    fn mc_try_system_search_query(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        args: []const Value,
    ) anyerror!?Value {
        if (mc.object.* != .field_access) return null;
        const search_fa = mc.object.field_access;
        if (search_fa.object.* != .identifier) return null;
        if (!(std.ascii.eqlIgnoreCase(search_fa.object.identifier.name, "System") and
            std.ascii.eqlIgnoreCase(search_fa.field, "Search") and
            std.ascii.eqlIgnoreCase(mc.method, "query")))
        {
            return null;
        }
        if (args.len > 0 and args[0] == .string) {
            return try self.execute_sosl(args[0].string);
        }
        const outer = try self.arena.create(types.ListValue);
        outer.* = .{};
        return Value{ .list = outer };
    }

    /// `super.method(...)` dispatch: resolve the super class of the current
    /// class and invoke the method against `this`.
    fn mc_dispatch_super_call(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        args: []const Value,
        current_env: *Env,
    ) anyerror!Value {
        const this_val = current_env.get("this") orelse return Value.null_val;
        if (this_val != .object) return Value.null_val;
        const current_class_name = self.current_class orelse return Value.null_val;
        const current_decl = self.find_class(current_class_name) orelse return Value.null_val;
        const sc = current_decl.super_class orelse return Value.null_val;
        const super_decl = self.find_class(sc.name) orelse return Value.null_val;
        return try self.call_super_instance_method(
            super_decl,
            this_val.object,
            mc.method,
            args,
        );
    }

    /// Dispatch `SomeIdentifier.method(args)` where the receiver is a bare
    /// identifier. Tries in order: named builtins (Assert/Test/JSON/__mdt/
    /// Integer.valueOf), local variable bound to `class_name`, shadowing user
    /// class, Database, builtin static dispatch, Custom Metadata getInstance/
    /// getAll, Custom Setting statics, user class call, Test factory stubs,
    /// getSObjectType fallback, and finally implicit `this` instance method.
    fn mc_dispatch_identifier(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        args: []const Value,
        current_env: *Env,
    ) anyerror!Value {
        const class_name = mc.object.identifier.name;
        if (try self.mc_try_named_builtin_dispatch(class_name, mc.method, args, current_env)) |v| {
            return v;
        }
        if (try self.mc_try_resolved_variable_dispatch(mc, args, current_env)) |v| return v;
        if (try self.mc_try_user_class_shadow_dispatch(mc, class_name, args, current_env)) |v| {
            return v;
        }
        if (std.ascii.eqlIgnoreCase(class_name, "Database")) {
            return self.handle_database_method(mc.method, args, current_env);
        }
        var bctx = builtins.BuiltinContext{
            .arena = self.arena,
            .stdout = &self.stdout,
            .pending_exception = &self.pending_exception,
            .see_all_data = self.see_all_data,
            .eval = self,
        };
        if (try builtins.dispatch_static(&bctx, class_name, mc.method, args)) |result| {
            return result;
        }
        if (try self.mc_try_custom_metadata_dispatch(class_name, mc.method, args)) |v| return v;
        if (try self.handle_custom_setting_static_method(class_name, mc.method, args)) |r| {
            return r;
        }
        if (!std.ascii.eqlIgnoreCase(class_name, "Database") and
            self.find_class(class_name) != null)
        {
            return self.call_method(class_name, mc.method, args);
        }
        if (try self.handle_test_factory(class_name, mc.method, args)) |result| return result;
        if (std.ascii.eqlIgnoreCase(mc.method, "getSObjectType")) {
            return try self.make_sobject_type_token(class_name);
        }
        // Unknown static target — the identifier may resolve to an instance
        // value via implicit `this`. Route through eval_expr so instance
        // property getters fire.
        if (self.find_class(class_name) == null) {
            if (self.eval_expr(mc.object, current_env)) |obj_val| {
                if (obj_val != .null_val) {
                    return self.eval_instance_method(obj_val, mc.method, args, current_env);
                }
            } else |_| {}
        }
        return self.call_method(class_name, mc.method, args);
    }

    /// Dispatch when the identifier resolves to a local variable or a static
    /// field with a primitive/reference value. Returns null when no binding
    /// matches (the caller falls through to the static class dispatch).
    fn mc_try_resolved_variable_dispatch(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        const class_name = mc.object.identifier.name;
        const resolved_var = try self.mc_resolve_identifier_variable(class_name, current_env);
        switch (resolved_var) {
            .list, .map, .set, .sobject, .object, .string, .double, .integer, .boolean => {
                return try self.eval_instance_method(
                    resolved_var,
                    mc.method,
                    args,
                    current_env,
                );
            },
            else => {},
        }
        if (resolved_var == .null_val and current_env.has(class_name)) {
            const rebound = try self.eval_expr(mc.object, current_env);
            return try self.eval_instance_method(rebound, mc.method, args, current_env);
        }
        return null;
    }

    /// When a platform static namespace (e.g. `Messaging`, `Http`) is shadowed
    /// by a user-defined class visible in scope, dispatch to the user class
    /// instead. Returns null when no shadowing applies.
    fn mc_try_user_class_shadow_dispatch(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        class_name: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (!is_builtin_static_namespace(class_name)) return null;
        const visible_class = self.resolve_visible_user_class_in_scope(current_env, class_name) orelse
            return null;
        return try self.call_method(visible_class, mc.method, args);
    }

    /// Dispatch for named builtin classes: Assert, Test, JSON, __mdt,
    /// Integer.valueOf, System.enqueue_job/schedule/assert*. Returns null
    /// when the identifier does not match any known builtin.
    fn mc_try_named_builtin_dispatch(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(class_name, "Assert")) {
            return try self.handle_assert(method, args);
        }
        if (std.ascii.eqlIgnoreCase(class_name, "System") and
            (std.ascii.startsWithIgnoreCase(method, "assert") or
                std.ascii.eqlIgnoreCase(method, "assert")))
        {
            return try self.handle_assert(method, args);
        }
        if (std.ascii.eqlIgnoreCase(class_name, "Test")) {
            return try self.handle_test(method, args);
        }
        if (std.ascii.eqlIgnoreCase(class_name, "System") and
            std.ascii.eqlIgnoreCase(method, "enqueue_job"))
        {
            if (args.len > 0 and args[0] == .object) return try self.enqueue_job(args[0].object);
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(class_name, "System") and
            std.ascii.eqlIgnoreCase(method, "schedule"))
        {
            return try self.handle_system_method("schedule", method, args, current_env);
        }
        if (std.ascii.eqlIgnoreCase(class_name, "JSON")) {
            if (try self.mc_try_json_builtin(method, args)) |v| return v;
        }
        if (try self.mc_try_custom_metadata_dispatch(class_name, method, args)) |v| return v;
        if (try self.mc_try_integer_valueof(class_name, method, args)) |v| return v;
        return null;
    }

    fn mc_try_integer_valueof(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!std.ascii.eqlIgnoreCase(class_name, "Integer")) return null;
        if (!std.ascii.eqlIgnoreCase(method, "valueOf")) return null;
        if (args.len == 0 or args[0] != .string) return null;
        if (std.fmt.parseInt(i64, args[0].string, 10)) |v| {
            return Value{ .integer = v };
        } else |_| {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "System.TypeException" };
            try exc.fields.put(self.arena, "message", Value{ .string = try std.fmt.allocPrint(
                self.arena,
                "Invalid integer: {s}",
                .{args[0].string},
            ) });
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
    }

    /// JSON.serialize / deserialize / deserializeStrict / createParser.
    fn mc_try_json_builtin(
        self: *Evaluator,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(method, "serialize") or
            std.ascii.eqlIgnoreCase(method, "serializePretty"))
        {
            return try self.mc_json_serialize(args);
        }
        if (std.ascii.eqlIgnoreCase(method, "deserialize") or
            std.ascii.eqlIgnoreCase(method, "deserializeStrict"))
        {
            return try self.mc_json_deserialize(args);
        }
        if (std.ascii.eqlIgnoreCase(method, "createParser")) {
            if (args.len >= 1 and args[0] == .string) {
                const parser_obj = try self.arena.create(types.ObjectInstance);
                parser_obj.* = .{ .class_name = "JSONParser" };
                try parser_obj.fields.put(self.arena, "__json_body__", args[0]);
                return Value{ .object = parser_obj };
            }
            return Value.null_val;
        }
        return null;
    }

    fn mc_json_serialize(
        self: *Evaluator,
        args: []const Value,
    ) anyerror!Value {
        if (args.len == 0) return Value{ .string = "{}" };
        if (args[0] == .object and (std.ascii.eqlIgnoreCase(
            args[0].object.class_name,
            "Schema.SObjectField",
        ) or std.ascii.eqlIgnoreCase(args[0].object.class_name, "SObjectField"))) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "System.JSONException" };
            try exc.fields.put(self.arena, "message", Value{
                .string = "Apex Type unsupported in JSON: Schema.SObjectField",
            });
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        self.last_json_value = args[0];
        return Value{ .string = try utils.to_json(args[0], self.arena) };
    }

    fn mc_json_deserialize(
        self: *Evaluator,
        args: []const Value,
    ) anyerror!Value {
        if (args.len >= 1 and args[0] == .string) {
            return try self.mc_json_deserialize_string(args);
        }
        if (args.len >= 1 and args[0] == .null_val) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "JSONException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "Argument cannot be null." },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        return Value.null_val;
    }

    fn mc_json_deserialize_string(
        self: *Evaluator,
        args: []const Value,
    ) anyerror!Value {
        const json_str = args[0].string;
        const trimmed_json = std.mem.trim(u8, json_str, " \t\r\n");
        if (trimmed_json.len == 0 or
            (trimmed_json[0] != '{' and trimmed_json[0] != '[' and trimmed_json[0] != '"' and
                !std.ascii.isDigit(trimmed_json[0]) and
                !std.mem.startsWith(u8, trimmed_json, "null") and
                !std.mem.startsWith(u8, trimmed_json, "true") and
                !std.mem.startsWith(u8, trimmed_json, "false")))
        {
            return try self.raise_json_exception("JSONException", json_str);
        }
        const type_name: []const u8 = if (args.len >= 2 and args[1] == .object) blk: {
            const tobj = args[1].object;
            if (std.ascii.eqlIgnoreCase(tobj.class_name, "Type")) {
                if (tobj.fields.get("name")) |n| {
                    if (n == .string) break :blk n.string;
                }
            }
            break :blk tobj.class_name;
        } else "Object";
        const is_list_type = std.ascii.startsWithIgnoreCase(type_name, "List") or
            std.mem.endsWith(u8, type_name, "[]");
        if (!utils.is_json_balanced(trimmed_json)) {
            return try self.raise_json_exception("System.JSONException", json_str);
        }
        if (self.parse_json_value(json_str, type_name)) |pv| return pv;
        if (trimmed_json.len > 2) {
            return try self.raise_json_exception("JSONException", json_str);
        }
        if (is_list_type) {
            const list = try self.arena.create(types.ListValue);
            list.* = .{};
            return Value{ .list = list };
        }
        const obj = try self.arena.create(types.SObject);
        obj.* = .{ .type_name = "Object" };
        return Value{ .sobject = obj };
    }

    fn raise_json_exception(
        self: *Evaluator,
        class_name: []const u8,
        json_str: []const u8,
    ) anyerror!Value {
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = class_name };
        try exc.fields.put(self.arena, "message", Value{ .string = try std.fmt.allocPrint(
            self.arena,
            "Malformed JSON: {s}",
            .{json_str},
        ) });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    /// Custom Metadata Type: `MyType__mdt.getInstance(name)` / `getAll()`.
    /// Lazily loads the store from `.md-meta.xml` on first access, then
    /// resolves developer names case-insensitively. Returns null when the
    /// identifier is not a `__mdt` type or the method is not supported.
    fn mc_try_custom_metadata_dispatch(
        self: *Evaluator,
        class_name: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!std.mem.endsWith(u8, class_name, "__mdt")) return null;
        if (!(std.ascii.eqlIgnoreCase(method, "getInstance") or
            std.ascii.eqlIgnoreCase(method, "getAll")))
        {
            return null;
        }
        self.ensure_custom_metadata_loaded(class_name);
        if (std.ascii.eqlIgnoreCase(method, "getInstance")) {
            const dev_name = if (args.len > 0 and args[0] == .string) args[0].string else "";
            if (dev_name.len == 0) return Value.null_val;
            return self.mc_find_custom_metadata_record(class_name, dev_name);
        }
        // getAll()
        const map = try self.arena.create(types.MapValue);
        map.* = .{};
        var mi = self.store.iterator();
        while (mi.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) continue;
            for (entry.value_ptr.items) |item| {
                if (item != .sobject) continue;
                if (utils.sobject_get(&item.sobject.fields, "DeveloperName")) |dn| {
                    if (dn == .string) try map.entries.put(self.arena, dn.string, item);
                }
            }
        }
        return Value{ .map = map };
    }

    fn ensure_custom_metadata_loaded(self: *Evaluator, class_name: []const u8) void {
        var found = false;
        var si = self.store.iterator();
        while (si.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) {
                found = true;
                break;
            }
        }
        if (!found) self.load_custom_metadata_from_files(class_name) catch {};
    }

    fn mc_find_custom_metadata_record(
        self: *Evaluator,
        class_name: []const u8,
        dev_name: []const u8,
    ) Value {
        var mi = self.store.iterator();
        while (mi.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.key_ptr.*, class_name)) continue;
            for (entry.value_ptr.items) |item| {
                if (item != .sobject) continue;
                if (utils.sobject_get(&item.sobject.fields, "DeveloperName")) |dn| {
                    if (dn == .string and std.ascii.eqlIgnoreCase(dn.string, dev_name)) {
                        return item;
                    }
                }
            }
        }
        return Value.null_val;
    }

    /// Resolve a bare identifier to a local, static property getter output,
    /// or static field value inherited from the class chain / outer classes.
    /// Returns null_val when nothing matches.
    fn mc_resolve_identifier_variable(
        self: *Evaluator,
        class_name: []const u8,
        current_env: *Env,
    ) anyerror!Value {
        if (current_env.get(class_name)) |v| return v;
        if (self.current_class) |cc| {
            if (try self.mc_resolve_static_getter_on_class(cc, class_name)) |v| return v;
            const key = std.fmt.allocPrint(
                self.arena,
                "{s}.{s}",
                .{ cc, class_name },
            ) catch return Value.null_val;
            if (self.global_env.get(key)) |v| return v;
            if (self.resolve_outer_static_field(cc, class_name)) |v| return v;
        }
        if (current_env.get("this")) |this_val| {
            if (this_val == .object) {
                if (try self.mc_resolve_static_from_this(this_val.object.class_name, class_name)) |v| {
                    return v;
                }
            }
        }
        return Value.null_val;
    }

    fn mc_resolve_static_getter_on_class(
        self: *Evaluator,
        cc: []const u8,
        class_name: []const u8,
    ) anyerror!?Value {
        const already_in_getter = if (self.evaluating_getter) |eg|
            std.ascii.eqlIgnoreCase(eg, class_name)
        else
            false;
        if (already_in_getter) return null;
        const cd = self.find_class(cc) orelse return null;
        for (cd.members) |member| {
            switch (member) {
                .field_decl => |fd| {
                    if (!(fd.modifiers.is_static and
                        std.ascii.eqlIgnoreCase(fd.name, class_name) and
                        fd.getter_body != null)) continue;
                    const getter_env = self.global_env.child() catch return Value.null_val;
                    const saved_class = self.current_class;
                    const saved_getter = self.evaluating_getter;
                    self.current_class = cc;
                    self.evaluating_getter = class_name;
                    defer {
                        self.current_class = saved_class;
                        self.evaluating_getter = saved_getter;
                    }

                    const result = self.exec_block(fd.getter_body.?, getter_env) catch
                        return Value.null_val;
                    return switch (result) {
                        .return_val => |v| v,
                        else => self.return_value,
                    };
                },
                else => {},
            }
        }
        return null;
    }

    fn mc_resolve_static_from_this(
        self: *Evaluator,
        this_cn: []const u8,
        class_name: []const u8,
    ) anyerror!?Value {
        const key = std.fmt.allocPrint(
            self.arena,
            "{s}.{s}",
            .{ this_cn, class_name },
        ) catch return Value.null_val;
        if (self.global_env.get(key)) |v| return v;
        // Walk parent class chain for inherited static fields.
        if (self.find_class(this_cn)) |this_cd| {
            var cur_parent = this_cd.super_class;
            while (cur_parent) |sc| {
                self.ensure_static_init(sc.name);
                const pkey = std.fmt.allocPrint(
                    self.arena,
                    "{s}.{s}",
                    .{ sc.name, class_name },
                ) catch break;
                if (self.global_env.get(pkey)) |v| return v;
                cur_parent = if (self.find_class(sc.name)) |pcd| pcd.super_class else null;
            }
        }
        if (self.resolve_outer_static_field(this_cn, class_name)) |v| return v;
        return null;
    }

    fn eval_method_call(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        current_env: *Env,
    ) anyerror!Value {
        // Set call-site line for stack trace generation, and update parent frame's line
        if (mc.loc.line > 0) {
            self.current_call_line = mc.loc.line;
            if (self.call_stack.items.len > 0)
                self.call_stack.items[self.call_stack.items.len - 1].line = mc.loc.line;
        }

        if (try self.try_mc_add_error_sugar(mc, current_env)) |v| return v;
        if (try self.mc_null_safe_short_circuit(mc, current_env)) |v| return v;

        var args: std.ArrayListUnmanaged(Value) = .empty;
        var arg_type_hints: std.ArrayListUnmanaged(?[]const u8) = .empty;
        for (mc.args) |*arg| {
            var arg_value = try self.eval_expr(arg, current_env);
            arg_value = try self.maybe_coerce_schema_expr_value(arg, arg_value);
            try args.append(self.arena, arg_value);
            const hint = self.extract_expr_type_hint(arg, current_env);
            try arg_type_hints.append(self.arena, hint);
        }
        const prev_hints = self.cast_type_hints;
        self.cast_type_hints = arg_type_hints.items;
        defer self.cast_type_hints = prev_hints;

        if (try self.mc_try_system_search_query(mc, args.items)) |v| return v;
        if (mc.object.* == .super_expr) {
            return try self.mc_dispatch_super_call(mc, args.items, current_env);
        }
        if (mc.object.* == .identifier) {
            return try self.mc_dispatch_identifier(mc, args.items, current_env);
        }
        if (mc.object.* == .field_access) {
            if (try self.mc_dispatch_nested_field_access(mc, args.items, current_env)) |v| {
                return v;
            }
        }

        // Instance method on evaluated object
        const obj = try self.eval_expr(mc.object, current_env);
        return self.eval_instance_method(obj, mc.method, args.items, current_env);
    }

    /// Dispatch for chains of the form `Outer.Inner.method(...)` (three-level
    /// field_access on the receiver). Covers Schema.<X>.SObjectType.<m>,
    /// System.Assert.*, System.<ns>.<m>, <X>.<Y>.getDescribe, DataWeave.Script,
    /// Invocable.Action, Flow.Interview, ConnectApi.*, and Cache.Session/Org.
    /// Returns null when no branch applies.
    fn mc_dispatch_nested_field_access(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        const fa = mc.object.field_access;
        if (fa.object.* == .field_access) {
            if (try self.mc_try_three_level_schema(mc, fa, args, current_env)) |v| return v;
        }
        if (fa.object.* != .identifier) return null;
        const outer_class = fa.object.identifier.name;
        const inner = fa.field;

        if (std.ascii.eqlIgnoreCase(outer_class, "System") and
            std.ascii.eqlIgnoreCase(inner, "Assert"))
        {
            return try self.handle_assert(mc.method, args);
        }
        if (std.ascii.eqlIgnoreCase(outer_class, "System")) {
            return try self.handle_system_method(inner, mc.method, args, current_env);
        }
        if (std.ascii.eqlIgnoreCase(mc.method, "getDescribe")) {
            return try self.mc_get_describe_for_token(mc, outer_class, inner, args, current_env);
        }
        if (try self.mc_try_dataweave_script(outer_class, inner, mc.method, args)) |v| return v;
        if (try self.mc_try_invocable_action(outer_class, inner, mc.method, args)) |v| return v;
        if (try self.mc_try_flow_interview(outer_class, inner, mc.method, args)) |v| return v;
        if (std.ascii.eqlIgnoreCase(outer_class, "ConnectApi")) {
            return (try self.handle_connect_api_namespace(inner, mc.method, args)) orelse
                Value.null_val;
        }
        if (try self.mc_try_cache_partition(outer_class, inner, mc.method, args)) |v| return v;
        return null;
    }

    /// Three-level `Schema.TypeName.SObjectType.X` / `Schema.TypeName.Field.
    /// getDescribe()` chains. Returns null when the outer isn't `Schema`.
    fn mc_try_three_level_schema(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        fa: *ast.FieldAccess,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        const inner_fa = fa.object.field_access;
        if (inner_fa.object.* != .identifier) return null;
        const outer_name = inner_fa.object.identifier.name;
        const type_name = inner_fa.field;
        if (!std.ascii.eqlIgnoreCase(outer_name, "Schema")) return null;

        if (std.ascii.eqlIgnoreCase(type_name, "SObjectType")) {
            const sot = try self.make_sobject_type_token(fa.field);
            return try self.eval_instance_method(sot, mc.method, args, current_env);
        }
        if (std.ascii.eqlIgnoreCase(fa.field, "SObjectType")) {
            const sot = try self.make_sobject_type_token(type_name);
            return try self.eval_instance_method(sot, mc.method, args, current_env);
        }
        if (std.ascii.eqlIgnoreCase(mc.method, "getDescribe")) {
            var bctx = builtins.BuiltinContext{
                .arena = self.arena,
                .stdout = &self.stdout,
                .pending_exception = &self.pending_exception,
                .see_all_data = self.see_all_data,
                .eval = self,
            };
            return try builtins.create_field_describe_result(&bctx, type_name, fa.field);
        }
        return null;
    }

    fn mc_get_describe_for_token(
        self: *Evaluator,
        mc: *ast.MethodCallExpr,
        outer_class: []const u8,
        inner: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!Value {
        if (std.ascii.eqlIgnoreCase(inner, "SObjectType")) {
            const sot = try self.make_sobject_type_token(outer_class);
            return try self.eval_instance_method(sot, mc.method, args, current_env);
        }
        var bctx = builtins.BuiltinContext{
            .arena = self.arena,
            .stdout = &self.stdout,
            .pending_exception = &self.pending_exception,
            .see_all_data = self.see_all_data,
            .eval = self,
        };
        return try builtins.create_field_describe_result(&bctx, outer_class, inner);
    }

    fn mc_try_dataweave_script(
        self: *Evaluator,
        outer_class: []const u8,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(outer_class, "DataWeave") and
            std.ascii.eqlIgnoreCase(inner, "Script"))) return null;
        if (!(std.ascii.eqlIgnoreCase(method, "createScript") and
            args.len > 0 and args[0] == .string)) return null;
        const dw = try self.arena.create(types.ObjectInstance);
        dw.* = .{ .class_name = "DataWeave.Script" };
        try dw.fields.put(self.arena, "scriptName", args[0]);
        return Value{ .object = dw };
    }

    fn mc_try_invocable_action(
        self: *Evaluator,
        outer_class: []const u8,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(outer_class, "Invocable") and
            std.ascii.eqlIgnoreCase(inner, "Action"))) return null;
        var bctx = builtins.BuiltinContext{
            .arena = self.arena,
            .stdout = &self.stdout,
            .pending_exception = &self.pending_exception,
            .see_all_data = self.see_all_data,
            .eval = self,
        };
        return try builtins.dispatch_static(&bctx, "Invocable.Action", method, args);
    }

    fn mc_try_flow_interview(
        self: *Evaluator,
        outer_class: []const u8,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!(std.ascii.eqlIgnoreCase(outer_class, "Flow") and
            std.ascii.eqlIgnoreCase(inner, "Interview"))) return null;
        if (!std.ascii.eqlIgnoreCase(method, "createInterview")) return null;
        if (args.len == 0 or args[0] != .string) return null;
        if (!self.has_flow_definition(args[0].string)) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "TypeException" };
            try exc.fields.put(self.arena, "message", Value{ .string = "Unknown Flow" });
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        const interview = try self.arena.create(types.ObjectInstance);
        interview.* = .{ .class_name = "Flow.Interview" };
        try interview.fields.put(self.arena, "flowName", args[0]);
        if (args.len > 1 and args[1] == .map) {
            for (args[1].map.entries.keys(), args[1].map.entries.values()) |k, v| {
                try interview.fields.put(self.arena, k, v);
            }
        }
        return Value{ .object = interview };
    }

    fn mc_try_cache_partition(
        self: *Evaluator,
        outer_class: []const u8,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (!std.ascii.eqlIgnoreCase(outer_class, "Cache")) return null;
        if (!(std.ascii.eqlIgnoreCase(inner, "Session") or
            std.ascii.eqlIgnoreCase(inner, "Org"))) return null;
        if (!std.ascii.eqlIgnoreCase(method, "getPartition")) return null;

        const partition_name = if (args.len > 0 and args[0] == .string)
            args[0].string
        else
            "default";
        const cache_key = try std.fmt.allocPrint(
            self.arena,
            "Cache.{s}.partition:{s}",
            .{ inner, partition_name },
        );
        if (self.global_env.get(cache_key)) |existing| {
            if (existing == .object) return existing;
        }
        const partition = try self.arena.create(types.ObjectInstance);
        partition.* = .{ .class_name = "Cache.Partition" };
        const cache_map = try self.arena.create(types.MapValue);
        cache_map.* = .{};
        const is_available = std.ascii.indexOfIgnoreCase(partition_name, "NeverExist") == null;
        try partition.fields.put(self.arena, "_cache", Value{ .map = cache_map });
        try partition.fields.put(self.arena, "_is_available", Value{ .boolean = is_available });
        self.global_env.set(cache_key, Value{ .object = partition }) catch {
            try self.global_env.define(cache_key, Value{ .object = partition });
        };
        return Value{ .object = partition };
    }

    fn connect_api_create_object(self: *Evaluator, class_name: []const u8) !*types.ObjectInstance {
        const obj = try self.arena.create(types.ObjectInstance);
        obj.* = .{ .class_name = class_name };
        return obj;
    }

    fn prepare_method_arg_value(self: *Evaluator, value: Value) !Value {
        return switch (value) {
            .string => |s| Value{ .string = try self.arena.dupe(u8, s) },
            else => value,
        };
    }

    fn connect_api_create_record_ref(self: *Evaluator, record_id: []const u8) !Value {
        const record = try self.connect_api_create_object("ConnectApi.Record");
        try record.fields.put(self.arena, "id", Value{ .string = record_id });
        return Value{ .object = record };
    }

    fn connect_api_markup_tag(markup_value: Value) ?[]const u8 {
        return switch (markup_value) {
            .string => |name| blk: {
                if (std.ascii.eqlIgnoreCase(name, "Bold")) break :blk "b";
                if (std.ascii.eqlIgnoreCase(name, "Code")) break :blk "code";
                if (std.ascii.eqlIgnoreCase(name, "Italic")) break :blk "i";
                if (std.ascii.eqlIgnoreCase(name, "ListItem")) break :blk "li";
                if (std.ascii.eqlIgnoreCase(name, "OrderedList")) break :blk "ol";
                if (std.ascii.eqlIgnoreCase(name, "Paragraph")) break :blk "p";
                if (std.ascii.eqlIgnoreCase(name, "Strikethrough")) break :blk "s";
                if (std.ascii.eqlIgnoreCase(name, "Underline")) break :blk "u";
                if (std.ascii.eqlIgnoreCase(name, "UnorderedList")) break :blk "ul";
                break :blk null;
            },
            else => null,
        };
    }

    fn is_connect_api_hashtag_char(ch: u8) bool {
        return std.ascii.isAlphanumeric(ch) or ch == '_';
    }

    fn is_connect_api_whitespace(ch: u8) bool {
        return ch == ' ' or ch == '\t' or ch == '\n' or ch == '\r';
    }

    fn is_connect_api_mention_id(self: *Evaluator, record_id: []const u8) bool {
        _ = self;
        if (record_id.len != 15 and record_id.len != 18) return false;
        for (record_id) |ch| {
            if (!std.ascii.isAlphanumeric(ch)) return false;
        }
        if (std.mem.startsWith(u8, record_id, "005")) return true;
        if (std.mem.startsWith(u8, record_id, "00G")) return true;
        if (std.mem.startsWith(u8, record_id, "0F9")) return true;
        return false;
    }

    fn connect_api_class_name_equals(class_name: []const u8, simple_name: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(class_name, simple_name)) return true;
        if (std.mem.lastIndexOfScalar(u8, class_name, '.')) |dot| {
            return std.ascii.eqlIgnoreCase(class_name[dot + 1 ..], simple_name);
        }
        return false;
    }

    fn connect_api_append_output_segment(
        self: *Evaluator,
        segments: *types.ListValue,
        segment: *types.ObjectInstance,
    ) !void {
        try segments.items.append(self.arena, Value{ .object = segment });
    }

    fn connect_api_append_text_segment(
        self: *Evaluator,
        segments: *types.ListValue,
        text: []const u8,
    ) !void {
        if (text.len == 0) return;
        const segment = try self.connect_api_create_object("ConnectApi.TextSegment");
        try segment.fields.put(self.arena, "text", Value{ .string = text });
        try self.connect_api_append_output_segment(segments, segment);
    }

    fn connect_api_append_parsed_text(
        self: *Evaluator,
        segments: *types.ListValue,
        text: []const u8,
    ) !void {
        var text_start: usize = 0;
        var i: usize = 0;
        while (i < text.len) {
            const is_http = std.mem.startsWith(
                u8,
                text[i..],
                "http://",
            ) or std.mem.startsWith(u8, text[i..], "https://");
            if (is_http) {
                try self.connect_api_append_text_segment(segments, text[text_start..i]);
                var end = i;
                while (end < text.len and !is_connect_api_whitespace(text[end])) : (end += 1) {}
                const link = try self.connect_api_create_object("ConnectApi.LinkSegment");
                try link.fields.put(self.arena, "url", Value{ .string = text[i..end] });
                try self.connect_api_append_output_segment(segments, link);
                i = end;
                text_start = end;
                continue;
            }

            if (text[i] == '#' and i + 1 < text.len and is_connect_api_hashtag_char(text[i + 1])) {
                try self.connect_api_append_text_segment(segments, text[text_start..i]);
                var end = i + 1;
                while (end < text.len and is_connect_api_hashtag_char(text[end])) : (end += 1) {}
                const hashtag = try self.connect_api_create_object("ConnectApi.HashtagSegment");
                try hashtag.fields.put(self.arena, "tag", Value{ .string = text[i + 1 .. end] });
                try self.connect_api_append_output_segment(segments, hashtag);
                i = end;
                text_start = end;
                continue;
            }

            i += 1;
        }

        try self.connect_api_append_text_segment(segments, text[text_start..]);
    }

    fn connect_api_build_output_segments(
        self: *Evaluator,
        message_segments: Value,
    ) !*types.ListValue {
        const output = try self.arena.create(types.ListValue);
        output.* = .{};
        if (message_segments != .list) return output;

        for (message_segments.list.items.items) |segment_input| {
            if (segment_input != .object) continue;
            const class_name = segment_input.object.class_name;

            if (connect_api_class_name_equals(class_name, "TextSegmentInput")) {
                const text = utils.sobject_get(
                    &segment_input.object.fields,
                    "text",
                ) orelse Value.null_val;
                if (text == .string) try self.connect_api_append_parsed_text(output, text.string);
                continue;
            }

            if (connect_api_class_name_equals(class_name, "MentionSegmentInput")) {
                const mention_id = utils.sobject_get(
                    &segment_input.object.fields,
                    "id",
                ) orelse Value.null_val;
                if (mention_id == .string) {
                    if (!self.is_connect_api_mention_id(mention_id.string)) {
                        const exc = try self.arena.create(types.ObjectInstance);
                        exc.* = .{ .class_name = "ConnectApi.ConnectApiException" };
                        try exc.fields.put(self.arena, "message", Value{ .string = "Only user and group IDs may be used in inline mentions." });
                        self.pending_exception = Value{ .object = exc };
                        return error.ApexException;
                    }
                    const mention = try self.connect_api_create_object("ConnectApi.MentionSegment");
                    try mention.fields.put(
                        self.arena,
                        "record",
                        try self.connect_api_create_record_ref(mention_id.string),
                    );
                    try self.connect_api_append_output_segment(output, mention);
                }
                continue;
            }

            if (connect_api_class_name_equals(class_name, "LinkSegmentInput")) {
                const url = utils.sobject_get(
                    &segment_input.object.fields,
                    "url",
                ) orelse Value.null_val;
                if (url == .string) {
                    const link = try self.connect_api_create_object("ConnectApi.LinkSegment");
                    try link.fields.put(self.arena, "url", url);
                    try self.connect_api_append_output_segment(output, link);
                }
                continue;
            }

            if (connect_api_class_name_equals(class_name, "HashtagSegmentInput")) {
                const tag = utils.sobject_get(
                    &segment_input.object.fields,
                    "tag",
                ) orelse Value.null_val;
                if (tag == .string) {
                    const hashtag = try self.connect_api_create_object("ConnectApi.HashtagSegment");
                    try hashtag.fields.put(self.arena, "tag", tag);
                    try self.connect_api_append_output_segment(output, hashtag);
                }
                continue;
            }

            if (connect_api_class_name_equals(class_name, "MarkupBeginSegmentInput")) {
                const markup = try self.connect_api_create_object("ConnectApi.MarkupBeginSegment");
                if (utils.sobject_get(&segment_input.object.fields, "markupType")) |markup_type| {
                    try markup.fields.put(self.arena, "markupType", markup_type);
                }
                try self.connect_api_append_output_segment(output, markup);
                continue;
            }

            if (connect_api_class_name_equals(class_name, "MarkupEndSegmentInput")) {
                const markup = try self.connect_api_create_object("ConnectApi.MarkupEndSegment");
                if (utils.sobject_get(&segment_input.object.fields, "markupType")) |markup_type| {
                    try markup.fields.put(self.arena, "markupType", markup_type);
                }
                try self.connect_api_append_output_segment(output, markup);
                continue;
            }

            if (connect_api_class_name_equals(class_name, "EntityLinkSegmentInput")) {
                const entity = try self.connect_api_create_object("ConnectApi.EntityLinkSegment");
                if (utils.sobject_get(&segment_input.object.fields, "entityId")) |entity_id| {
                    try entity.fields.put(self.arena, "record", entity_id);
                }
                try self.connect_api_append_output_segment(output, entity);
                continue;
            }

            if (connect_api_class_name_equals(class_name, "InlineImageSegmentInput")) {
                const image = try self.connect_api_create_object("ConnectApi.InlineImageSegment");
                const thumbnails = try self.connect_api_create_object(
                    "ConnectApi.InlineImageThumbnails",
                );
                if (utils.sobject_get(&segment_input.object.fields, "fileId")) |file_id| {
                    try thumbnails.fields.put(self.arena, "fileId", file_id);
                }
                try image.fields.put(self.arena, "thumbnails", Value{ .object = thumbnails });
                if (utils.sobject_get(&segment_input.object.fields, "altText")) |alt_text| {
                    try image.fields.put(self.arena, "altText", alt_text);
                }
                try self.connect_api_append_output_segment(output, image);
                continue;
            }
        }

        return output;
    }

    fn connect_api_render_body_text(
        self: *Evaluator,
        output_segments: *types.ListValue,
    ) ![]const u8 {
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        for (output_segments.items.items) |segment| {
            if (segment != .object) continue;
            const class_name = segment.object.class_name;
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.TextSegment")) {
                if (utils.sobject_get(&segment.object.fields, "text")) |text| {
                    if (text == .string) try buf.appendSlice(self.arena, text.string);
                }
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.LinkSegment")) {
                if (utils.sobject_get(&segment.object.fields, "url")) |url| {
                    if (url == .string) try buf.appendSlice(self.arena, url.string);
                }
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.HashtagSegment")) {
                if (utils.sobject_get(&segment.object.fields, "tag")) |tag| {
                    if (tag == .string) {
                        try buf.append(self.arena, '#');
                        try buf.appendSlice(self.arena, tag.string);
                    }
                }
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.MentionSegment")) {
                if (utils.sobject_get(&segment.object.fields, "record")) |record| {
                    if (record == .object) {
                        if (utils.sobject_get(&record.object.fields, "id")) |record_id| {
                            if (record_id == .string) {
                                try buf.append(self.arena, '{');
                                try buf.appendSlice(self.arena, record_id.string);
                                try buf.append(self.arena, '}');
                            }
                        }
                    }
                }
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.MarkupBeginSegment") or
                std.ascii.eqlIgnoreCase(class_name, "ConnectApi.MarkupEndSegment"))
            {
                const markup_type = utils.sobject_get(
                    &segment.object.fields,
                    "markupType",
                ) orelse Value.null_val;
                const tag_name = connect_api_markup_tag(markup_type) orelse continue;
                if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.MarkupBeginSegment")) {
                    try buf.appendSlice(self.arena, "<");
                    try buf.appendSlice(self.arena, tag_name);
                    try buf.appendSlice(self.arena, ">");
                } else {
                    try buf.appendSlice(self.arena, "</");
                    try buf.appendSlice(self.arena, tag_name);
                    try buf.appendSlice(self.arena, ">");
                }
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.InlineImageSegment")) {
                if (utils.sobject_get(&segment.object.fields, "thumbnails")) |thumbs| {
                    if (thumbs == .object) {
                        if (utils.sobject_get(&thumbs.object.fields, "fileId")) |file_id| {
                            if (file_id == .string) {
                                try buf.appendSlice(self.arena, "image: ");
                                try buf.appendSlice(self.arena, file_id.string);
                            }
                        }
                    }
                }
                continue;
            }
            if (std.ascii.eqlIgnoreCase(class_name, "ConnectApi.EntityLinkSegment")) {
                if (utils.sobject_get(&segment.object.fields, "text")) |text| {
                    if (text == .string) try buf.appendSlice(self.arena, text.string);
                }
            }
        }
        return buf.items;
    }

    fn connect_api_extract_message_segments(self: *Evaluator, value: Value, depth: u8) ?Value {
        if (depth == 0) return null;
        switch (value) {
            .list => return value,
            .object => |obj| {
                if (utils.sobject_get(&obj.fields, "messageSegments")) |segments| {
                    if (segments == .list) return segments;
                }
                for (obj.fields.values()) |field_value| {
                    if (self.connect_api_extract_message_segments(
                        field_value,
                        depth - 1,
                    )) |segments| return segments;
                }
                return null;
            },
            else => return null,
        }
    }

    fn connect_api_create_feed_body(self: *Evaluator, message_segments: Value) !Value {
        const output_segments = try self.connect_api_build_output_segments(message_segments);
        const body_text = try self.connect_api_render_body_text(output_segments);
        const body = try self.connect_api_create_object("ConnectApi.FeedBody");
        try body.fields.put(self.arena, "messageSegments", Value{ .list = output_segments });
        try body.fields.put(self.arena, "text", Value{ .string = body_text });
        return Value{ .object = body };
    }

    fn connect_api_persist_feed_item(
        self: *Evaluator,
        parent_id: Value,
        body_value: Value,
    ) ![]const u8 {
        const feed_item = try self.arena.create(types.SObject);
        feed_item.* = .{ .type_name = "FeedItem" };
        if (parent_id == .string) {
            try feed_item.fields.put(self.arena, "ParentId", parent_id);
        } else if (parent_id != .null_val) {
            try feed_item.fields.put(
                self.arena,
                "ParentId",
                Value{ .string = try utils.coerce_to_string(parent_id, self.arena) },
            );
        }
        if (body_value == .object) {
            if (utils.sobject_get(&body_value.object.fields, "text")) |body_text| {
                if (body_text == .string) try feed_item.fields.put(self.arena, "Body", body_text);
            }
        }
        try self.insert_record(feed_item);
        return feed_item.id orelse "";
    }

    fn handle_connect_api_namespace(
        self: *Evaluator,
        namespace: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (!self.see_all_data) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "UnsupportedOperationException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "ConnectApi is not supported in data-siloed tests" },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }

        if (!std.ascii.eqlIgnoreCase(namespace, "ChatterFeeds")) return Value.null_val;
        if (std.ascii.eqlIgnoreCase(method, "postFeedElement")) {
            return try self.connect_api_post_feed_element(args);
        }
        if (std.ascii.eqlIgnoreCase(method, "postCommentToFeedElement")) {
            return try self.connect_api_post_comment(args);
        }
        return Value.null_val;
    }

    fn connect_api_post_feed_element(
        self: *Evaluator,
        args: []const Value,
    ) !Value {
        var subject_id: Value = Value.null_val;
        var message_segments: Value = Value.null_val;
        if (args.len >= 2 and args[1] == .object) {
            subject_id = utils.sobject_get(
                &args[1].object.fields,
                "subjectId",
            ) orelse Value.null_val;
            message_segments = self.connect_api_extract_message_segments(args[1], 4) orelse
                Value.null_val;
        } else if (args.len >= 4) {
            subject_id = args[1];
            message_segments = try self.connect_api_build_text_segments(args[3]);
        }
        const body_value = try self.connect_api_create_feed_body(message_segments);
        const feed_id = try self.connect_api_persist_feed_item(subject_id, body_value);
        const feed_element = try self.connect_api_create_object("ConnectApi.FeedElement");
        try feed_element.fields.put(self.arena, "id", Value{ .string = feed_id });
        try feed_element.fields.put(self.arena, "body", body_value);
        return Value{ .object = feed_element };
    }

    fn connect_api_post_comment(
        self: *Evaluator,
        args: []const Value,
    ) !Value {
        var message_segments: Value = Value.null_val;
        if (args.len >= 3 and args[2] == .object) {
            message_segments = self.connect_api_extract_message_segments(args[2], 4) orelse
                Value.null_val;
        }
        const body_value = try self.connect_api_create_feed_body(message_segments);
        const comment = try self.connect_api_create_object("ConnectApi.Comment");
        try comment.fields.put(self.arena, "id", Value{ .string = try self.alloc_id() });
        try comment.fields.put(self.arena, "body", body_value);
        return Value{ .object = comment };
    }

    /// Fall-back message_segments builder for the 4-arg postFeedElement form
    /// (subjectId, feedItemType, text). Wraps the text in a
    /// ConnectApi.TextSegmentInput list.
    fn connect_api_build_text_segments(
        self: *Evaluator,
        text_arg: Value,
    ) !Value {
        const text_segments = try self.arena.create(types.ListValue);
        text_segments.* = .{};
        const text_segment = try self.connect_api_create_object("ConnectApi.TextSegmentInput");
        const text_value = switch (text_arg) {
            .string => text_arg.string,
            else => try utils.coerce_to_string(text_arg, self.arena),
        };
        try text_segment.fields.put(self.arena, "text", Value{ .string = text_value });
        try text_segments.items.append(self.arena, Value{ .object = text_segment });
        return Value{ .list = text_segments };
    }

    fn throw_null_pointer_exception(self: *Evaluator) !void {
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "System.NullPointerException" };
        try exc.fields.put(
            self.arena,
            "message",
            Value{ .string = "Attempt to de-reference a null object" },
        );
        self.pending_exception = Value{ .object = exc };
    }

    fn eval_primitive_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
    ) !?Value {
        if (obj == .boolean) {
            if (std.ascii.eqlIgnoreCase(method, "toString")) {
                return Value{ .string = if (obj.boolean) "true" else "false" };
            }
            if (std.ascii.eqlIgnoreCase(method, "hashCode")) {
                return Value{ .integer = if (obj.boolean) 1231 else 1237 };
            }
        }
        if (obj == .integer) {
            if (std.ascii.eqlIgnoreCase(method, "toString")) {
                return Value{ .string = try utils.coerce_to_string(obj, self.arena) };
            }
            if (std.ascii.eqlIgnoreCase(method, "hashCode")) return obj;
        }
        if (obj == .long) {
            if (std.ascii.eqlIgnoreCase(method, "toString")) {
                return Value{ .string = try utils.coerce_to_string(obj, self.arena) };
            }
            if (std.ascii.eqlIgnoreCase(method, "hashCode")) {
                return Value{ .integer = @intCast(obj.long) };
            }
        }
        if (obj == .double) {
            if (std.ascii.eqlIgnoreCase(method, "toString")) {
                return Value{ .string = try utils.coerce_to_string(obj, self.arena) };
            }
            if (std.ascii.eqlIgnoreCase(method, "hashCode")) {
                return Value{ .integer = @intFromFloat(obj.double) };
            }
        }
        return null;
    }

    fn eval_search_query_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (obj != .object) return null;
        if (!(std.ascii.eqlIgnoreCase(obj.object.class_name, "Search") or
            std.ascii.eqlIgnoreCase(obj.object.class_name, "System.Search")))
        {
            return null;
        }
        if (!std.ascii.eqlIgnoreCase(method, "query")) return null;
        if (args.len > 0 and args[0] == .string) {
            return try self.execute_sosl(args[0].string);
        }
        const outer = try self.arena.create(types.ListValue);
        outer.* = .{};
        return Value{ .list = outer };
    }

    /// Http / HttpRequest .send() → apply the configured mock if any. Returns
    /// null when the call does not match (let later dispatch handle it).
    fn eval_http_send_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (obj != .object) return null;
        if (!std.ascii.eqlIgnoreCase(method, "send")) return null;
        if (!(std.ascii.eqlIgnoreCase(obj.object.class_name, "Http") or
            std.ascii.eqlIgnoreCase(obj.object.class_name, "HttpRequest")))
        {
            return null;
        }
        self.limits_callouts += 1;
        const mock = self.callout_mock orelse return null;
        if (mock != .object) return null;
        const mock_class = self.find_class(mock.object.class_name) orelse return null;
        const req_arg = if (args.len > 0) args[0] else Value.null_val;
        return try self.call_instance_method(
            mock_class,
            mock.object,
            "respond",
            &.{req_arg},
        );
    }

    /// Type.getName()/toString()/getSimpleName() → the stored `name` field, or null.
    fn eval_type_reflection_method(obj: Value, method: []const u8) ?Value {
        if (obj != .object) return null;
        if (!std.ascii.eqlIgnoreCase(obj.object.class_name, "Type")) return null;
        if (!(std.ascii.eqlIgnoreCase(method, "getName") or
            std.ascii.eqlIgnoreCase(method, "toString") or
            std.ascii.eqlIgnoreCase(method, "getSimpleName")))
        {
            return null;
        }
        if (obj.object.fields.get("name")) |n| {
            if (n == .string) return n;
        }
        return Value.null_val;
    }

    /// Type.newInstance() for built-in collection (List/Map/Set) or SObject type
    /// names. Returns null for user-defined types (handled elsewhere).
    fn eval_type_new_instance_builtin(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
    ) anyerror!?Value {
        if (obj != .object) return null;
        if (!std.ascii.eqlIgnoreCase(obj.object.class_name, "Type")) return null;
        if (!std.ascii.eqlIgnoreCase(method, "newInstance")) return null;
        const type_name = if (obj.object.fields.get("name")) |n|
            (if (n == .string) n.string else "Object")
        else
            "Object";
        if (std.ascii.startsWithIgnoreCase(type_name, "Map")) {
            const map = try self.arena.create(types.MapValue);
            map.* = .{};
            return Value{ .map = map };
        }
        if (std.ascii.startsWithIgnoreCase(type_name, "List")) {
            const list = try self.arena.create(types.ListValue);
            list.* = .{};
            return Value{ .list = list };
        }
        if (std.ascii.startsWithIgnoreCase(type_name, "Set")) {
            const set = try self.arena.create(types.SetValue);
            set.* = .{};
            return Value{ .set = set };
        }
        if (self.is_s_object_type_name(type_name)) {
            const sob = try self.arena.create(types.SObject);
            sob.* = .{ .type_name = type_name };
            return Value{ .sobject = sob };
        }
        return try self.instantiate_class(type_name);
    }

    /// Type.newInstance() for user-defined classes. Instantiates the class,
    /// initialises fields, and runs the no-arg constructor if available.
    fn eval_type_new_instance_user_class(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
    ) anyerror!?Value {
        if (obj != .object) return null;
        if (!std.ascii.eqlIgnoreCase(obj.object.class_name, "Type")) return null;
        if (!std.ascii.eqlIgnoreCase(method, "newInstance")) return null;
        const type_name = if (obj.object.fields.get("name")) |n|
            (if (n == .string) n.string else "Object")
        else
            "Object";
        const cd = self.find_class(type_name) orelse return null;
        const inst = try self.arena.create(types.ObjectInstance);
        // Preserve the requested type name so qualified inner classes continue
        // to dispatch against the intended outer class.
        inst.* = .{ .class_name = type_name };
        self.init_instance_fields(cd, inst) catch {};
        if (cd.super_class) |sc| {
            if (self.find_class(sc.name)) |parent| {
                self.init_instance_fields(parent, inst) catch {};
            }
        }
        if (self.find_method_in_hierarchy(null, cd, type_name, 0)) |ctor| {
            const ctor_env = try self.global_env.child();
            try ctor_env.define("this", Value{ .object = inst });
            for (inst.fields.keys(), inst.fields.values()) |k, v| {
                ctor_env.set(k, v) catch {
                    try ctor_env.define(k, v);
                };
            }
            _ = self.exec_block(ctor.body, ctor_env) catch {};
            if (ctor_env.get("this")) |tv| {
                if (tv == .object and tv.object == inst) {} else if (tv == .object) {
                    for (tv.object.fields.keys(), tv.object.fields.values()) |k, v| {
                        inst.fields.put(self.arena, k, v) catch {};
                    }
                }
            }
        }
        return Value{ .object = inst };
    }

    /// Stub provider delegation: if `obj` has a `__stubProvider__` field, forward
    /// the method call through `handleMethodCall(...)`. Default Object methods
    /// (toString/hashCode/equals) are NOT stubbed unless the class overrides them.
    fn eval_stub_provider_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (obj != .object) return null;
        const provider_val = obj.object.fields.get("__stubProvider__") orelse return null;
        if (provider_val != .object) return null;
        const prov_class = self.find_class(provider_val.object.class_name) orelse return null;

        const stub_md = if (self.find_class(obj.object.class_name)) |stub_class|
            self.find_method_in_hierarchy_typed(null, stub_class, method, args) orelse
                self.find_method_in_hierarchy(null, stub_class, method, args.len)
        else
            null;
        const is_default_object_method =
            (args.len == 0 and
                (std.ascii.eqlIgnoreCase(method, "toString") or
                    std.ascii.eqlIgnoreCase(method, "hashCode"))) or
            (args.len == 1 and std.ascii.eqlIgnoreCase(method, "equals"));
        if (is_default_object_method and stub_md == null) return null;

        // Build args for
        //   handleMethodCall(
        //       stubbedObject, stubbedMethodName, returnType,
        //       listOfParamTypes, listOfParamNames, listOfArgs)
        const args_list = try self.arena.create(types.ListValue);
        args_list.* = .{};
        for (args) |a| try args_list.items.append(self.arena, a);

        const type_list = try self.arena.create(types.ListValue);
        type_list.* = .{};
        for (args, 0..) |a, i| {
            const type_name: []const u8 = if (stub_md) |md|
                if (i < md.params.len)
                    self.render_type_ref(md.params[i].type_ref)
                else
                    stub_provider_param_type_fallback(a)
            else
                stub_provider_param_type_fallback(a);
            const type_obj = try self.arena.create(types.ObjectInstance);
            type_obj.* = .{ .class_name = "Type" };
            try type_obj.fields.put(self.arena, "name", Value{ .string = type_name });
            try type_list.items.append(self.arena, Value{ .object = type_obj });
        }

        const name_list = try self.arena.create(types.ListValue);
        name_list.* = .{};
        if (stub_md) |md| {
            for (md.params) |p| {
                try name_list.items.append(self.arena, Value{ .string = p.name });
            }
        }

        const hmc_args = [_]Value{
            obj,
            Value{ .string = method },
            Value.null_val,
            Value{ .list = type_list },
            Value{ .list = name_list },
            Value{ .list = args_list },
        };
        return try self.call_instance_method(
            prov_class,
            provider_val.object,
            "handleMethodCall",
            &hmc_args,
        );
    }

    /// Dispatch JSONParser instance methods (nextToken / getCurrentToken /
    /// getCurrentName / getText / readValueAs). Returns null for non-JSONParser
    /// objects or unhandled methods.
    fn eval_json_parser_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (obj != .object) return null;
        if (!std.ascii.eqlIgnoreCase(obj.object.class_name, "JSONParser")) return null;
        const json_body = if (obj.object.fields.get("__json_body__")) |jb|
            (if (jb == .string) jb.string else null)
        else
            null;
        if (std.ascii.eqlIgnoreCase(method, "nextToken")) {
            const body = json_body orelse return Value.null_val;
            return try self.json_parser_next_token(obj.object, body);
        }
        if (std.ascii.eqlIgnoreCase(method, "getCurrentToken")) {
            return obj.object.fields.get("__token__") orelse Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "getCurrentName")) {
            const token_value = obj.object.fields.get("__token__") orelse Value.null_val;
            if (token_value == .string and
                std.ascii.eqlIgnoreCase(token_value.string, "FIELD_NAME"))
            {
                return obj.object.fields.get("__text__") orelse Value.null_val;
            }
            return Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "getText")) {
            return obj.object.fields.get("__text__") orelse Value{ .string = "" };
        }
        if (std.ascii.eqlIgnoreCase(method, "readValueAs")) {
            const pos: usize = if (obj.object.fields.get("__pos__")) |p|
                (if (p == .integer and p.integer > 0)
                    @intCast(@as(u64, @bitCast(p.integer)))
                else
                    0)
            else
                0;
            const body = json_body orelse return Value.null_val;
            // Back up one position to include the current token ([ or {)
            const start = if (pos > 0) pos - 1 else 0;
            const remaining = body[start..];
            const type_name: []const u8 = if (args.len >= 1 and args[0] == .object) blk: {
                if (std.ascii.eqlIgnoreCase(args[0].object.class_name, "Type")) {
                    if (args[0].object.fields.get("name")) |n| {
                        if (n == .string) break :blk n.string;
                    }
                }
                break :blk args[0].object.class_name;
            } else "Object";
            if (self.parse_json_value(remaining, type_name)) |pv| return pv;
            return Value.null_val;
        }
        return null;
    }

    /// Advance a JSONParser's __pos__/__token__/__text__ fields to the next token.
    fn json_parser_next_token(
        self: *Evaluator,
        inst: *types.ObjectInstance,
        body: []const u8,
    ) anyerror!Value {
        var pos: usize = if (inst.fields.get("__pos__")) |p|
            (if (p == .integer) @intCast(@as(u64, @bitCast(p.integer))) else 0)
        else
            0;
        while (pos < body.len and (body[pos] == ' ' or body[pos] == '\t' or
            body[pos] == '\n' or body[pos] == '\r' or body[pos] == ','))
        {
            pos += 1;
        }
        if (pos >= body.len) {
            try inst.fields.put(self.arena, "__token__", Value.null_val);
            return Value.null_val;
        }
        const ch = body[pos];
        switch (ch) {
            '{' => try self.json_parser_put_token(inst, "START_OBJECT", "{"),
            '}' => try self.json_parser_put_token(inst, "END_OBJECT", "}"),
            '[' => try self.json_parser_put_token(inst, "START_ARRAY", "["),
            ']' => try self.json_parser_put_token(inst, "END_ARRAY", "]"),
            '"' => return try self.json_parser_consume_string(inst, body, pos),
            else => {},
        }
        switch (ch) {
            '{', '}', '[', ']' => pos += 1,
            't', 'f' => pos = try self.json_parser_consume_true_false(inst, body, pos),
            'n' => {
                try self.json_parser_put_token(inst, "VALUE_NULL", "null");
                pos += 4;
            },
            else => pos = try self.json_parser_consume_number_or_skip(inst, body, pos, ch),
        }
        try inst.fields.put(self.arena, "__pos__", Value{ .integer = @intCast(pos) });
        return inst.fields.get("__token__") orelse Value.null_val;
    }

    /// Consume a `"..."` token, distinguishing FIELD_NAME (followed by `:`)
    /// from VALUE_STRING. Returns the resulting token value.
    fn json_parser_consume_string(
        self: *Evaluator,
        inst: *types.ObjectInstance,
        body: []const u8,
        start_quote: usize,
    ) anyerror!Value {
        const start = start_quote + 1;
        var pos = start_quote + 1;
        while (pos < body.len and body[pos] != '"') : (pos += 1) {
            if (body[pos] == '\\') pos += 1;
        }
        const text = body[start..pos];
        if (pos < body.len) pos += 1; // skip closing quote
        var peek = pos;
        while (peek < body.len and (body[peek] == ' ' or body[peek] == '\t')) {
            peek += 1;
        }
        if (peek < body.len and body[peek] == ':') {
            try inst.fields.put(self.arena, "__token__", Value{ .string = "FIELD_NAME" });
            pos = peek + 1;
        } else {
            try inst.fields.put(self.arena, "__token__", Value{ .string = "VALUE_STRING" });
        }
        try inst.fields.put(self.arena, "__text__", Value{ .string = text });
        try inst.fields.put(self.arena, "__pos__", Value{ .integer = @intCast(pos) });
        return inst.fields.get("__token__") orelse Value.null_val;
    }

    fn json_parser_consume_true_false(
        self: *Evaluator,
        inst: *types.ObjectInstance,
        body: []const u8,
        pos: usize,
    ) anyerror!usize {
        if (std.mem.startsWith(u8, body[pos..], "true")) {
            try self.json_parser_put_token(inst, "VALUE_TRUE", "true");
            return pos + 4;
        }
        try self.json_parser_put_token(inst, "VALUE_FALSE", "false");
        return pos + 5;
    }

    fn json_parser_consume_number_or_skip(
        self: *Evaluator,
        inst: *types.ObjectInstance,
        body: []const u8,
        start_pos: usize,
        ch: u8,
    ) anyerror!usize {
        if (!(std.ascii.isDigit(ch) or ch == '-')) return start_pos + 1;
        const start = start_pos;
        var pos = start_pos;
        while (pos < body.len and (std.ascii.isDigit(body[pos]) or
            body[pos] == '.' or body[pos] == '-' or
            body[pos] == 'e' or body[pos] == 'E' or body[pos] == '+'))
        {
            pos += 1;
        }
        const number_text = body[start..pos];
        const token_name = if (std.mem.indexOfAny(u8, number_text, ".eE") != null)
            "VALUE_NUMBER_FLOAT"
        else
            "VALUE_NUMBER_INT";
        try inst.fields.put(self.arena, "__token__", Value{ .string = token_name });
        try inst.fields.put(self.arena, "__text__", Value{ .string = number_text });
        return pos;
    }

    fn json_parser_put_token(
        self: *Evaluator,
        inst: *types.ObjectInstance,
        token: []const u8,
        text: []const u8,
    ) anyerror!void {
        try inst.fields.put(self.arena, "__token__", Value{ .string = token });
        try inst.fields.put(self.arena, "__text__", Value{ .string = text });
    }

    /// Time.hour/minute/second/millisecond → the stored field values.
    fn eval_time_accessor_method(obj: Value, method: []const u8) ?Value {
        if (obj != .object) return null;
        if (!std.ascii.eqlIgnoreCase(obj.object.class_name, "Time")) return null;
        const keys = [_][]const u8{ "hour", "minute", "second", "millisecond" };
        for (keys) |key| {
            if (std.ascii.eqlIgnoreCase(method, key)) {
                return obj.object.fields.get(key) orelse Value{ .integer = 0 };
            }
        }
        return null;
    }

    /// Date / Datetime instance methods: extract the inner date string and
    /// dispatch through eval_string_method, re-wrapping results back into
    /// Date/Datetime where the original method preserves the type.
    fn eval_date_like_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (obj != .object) return null;
        if (!(std.ascii.eqlIgnoreCase(obj.object.class_name, "Date") or
            std.ascii.eqlIgnoreCase(obj.object.class_name, "Datetime")))
        {
            return null;
        }
        const date_str = builtins.extract_date_string(obj) orelse return null;

        // No-arg format(): Salesforce default is M/d/yyyy for Date, M/d/yyyy, h:mm a for Datetime.
        if (args.len == 0 and std.ascii.eqlIgnoreCase(method, "format")) {
            if (try self.default_date_like_format(obj, date_str)) |v| return v;
        }

        const result = try self.eval_string_method(date_str, method, args);
        if (result != .string) return result;
        if (std.ascii.eqlIgnoreCase(method, "date") or
            std.ascii.eqlIgnoreCase(method, "dateGmt"))
        {
            return try builtins.make_date_value(self.arena, result.string);
        }
        if (std.ascii.eqlIgnoreCase(method, "addDays") or
            std.ascii.eqlIgnoreCase(method, "addMonths") or
            std.ascii.eqlIgnoreCase(method, "addYears") or
            std.ascii.eqlIgnoreCase(method, "addHours") or
            std.ascii.eqlIgnoreCase(method, "addMinutes") or
            std.ascii.eqlIgnoreCase(method, "addSeconds"))
        {
            if (std.ascii.eqlIgnoreCase(obj.object.class_name, "Date")) {
                return try builtins.make_date_value(self.arena, result.string);
            }
            return try builtins.make_datetime_value(self.arena, result.string);
        }
        return result;
    }

    /// Default format for Date → `M/d/yyyy`, Datetime → `M/d/yyyy, h:mm AM/PM`.
    /// Returns null when parse_iso_date cannot interpret the stored value.
    fn default_date_like_format(
        self: *Evaluator,
        obj: Value,
        date_str: []const u8,
    ) anyerror!?Value {
        const dt = parse_iso_date(date_str) orelse return null;
        if (std.ascii.eqlIgnoreCase(obj.object.class_name, "Date")) {
            return Value{ .string = try std.fmt.allocPrint(
                self.arena,
                "{d}/{d}/{d:0>4}",
                .{ dt.m, dt.d, @as(u32, @intCast(dt.y)) },
            ) };
        }
        const hour12: u8 = blk: {
            const h_mod = dt.h % 12;
            break :blk if (h_mod == 0) 12 else h_mod;
        };
        const am_pm: []const u8 = if (dt.h < 12) "AM" else "PM";
        return Value{ .string = try std.fmt.allocPrint(
            self.arena,
            "{d}/{d}/{d:0>4}, {d}:{d:0>2} {s}",
            .{ dt.m, dt.d, @as(u32, @intCast(dt.y)), hour12, dt.mi, am_pm },
        ) };
    }

    /// Dispatch user-defined class methods for ObjectInstance values. When the
    /// current `this` points at `obj` and `current_class` is known, prefer the
    /// declared class over the instance's `class_name`. Also walks outer
    /// classes to resolve methods shadowed by same-named top-level classes
    /// (e.g. `LoggerDataStore.Database` vs top-level `Database`).
    fn eval_user_class_dispatch(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (obj != .object) return null;
        const dispatch_decl = blk: {
            if (current_env.get("this")) |this_val| {
                if (this_val == .object and this_val.object == obj.object) {
                    if (self.current_class) |current_class_name| {
                        if (self.find_class(current_class_name)) |owner_decl| break :blk owner_decl;
                    }
                }
            }
            break :blk self.find_class(obj.object.class_name) orelse null;
        };
        const class_decl = dispatch_decl orelse return null;
        const md = self.find_method_in_hierarchy_typed(null, class_decl, method, args) orelse
            self.find_method_in_hierarchy(null, class_decl, method, args.len);
        if (md != null) {
            return try self.call_instance_method(class_decl, obj.object, method, args);
        }
        // Method not found in this class — it may be shadowed by a same-named
        // top-level class. Search outer classes whose inner class matches the
        // instance class_name and has the method.
        var cls_iter = self.classes.iterator();
        while (cls_iter.next()) |entry| {
            const cd = entry.value_ptr.*;
            for (cd.members) |member| {
                switch (member) {
                    .class_decl => |inner_cd| {
                        if (!std.ascii.eqlIgnoreCase(
                            inner_cd.name,
                            obj.object.class_name,
                        ) or inner_cd == class_decl) continue;
                        const inner_md = self.find_method_in_hierarchy_typed(
                            null,
                            inner_cd,
                            method,
                            args,
                        ) orelse
                            self.find_method_in_hierarchy(null, inner_cd, method, args.len);
                        if (inner_md != null) {
                            return try self.call_instance_method(
                                inner_cd,
                                obj.object,
                                method,
                                args,
                            );
                        }
                    },
                    else => {},
                }
            }
        }
        return null;
    }

    fn stub_provider_param_type_fallback(a: Value) []const u8 {
        return switch (a) {
            .string => "String",
            .integer => "Integer",
            .double => "Double",
            .boolean => "Boolean",
            .list => "List",
            .map => "Map",
            .set => "Set",
            .sobject => "SObject",
            .object => |o| o.class_name,
            .null_val => "Object",
            else => "Object",
        };
    }

    fn eval_instance_method(
        self: *Evaluator,
        obj: Value,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) anyerror!Value {
        if (obj == .null_val) {
            try self.throw_null_pointer_exception();
            return error.ApexException;
        }
        if (try self.eval_search_query_method(obj, method, args)) |v| return v;
        if (try self.eval_primitive_instance_method(obj, method)) |v| return v;
        if (try self.eval_http_send_method(obj, method, args)) |v| return v;
        if (eval_type_reflection_method(obj, method)) |v| return v;
        if (try self.eval_type_new_instance_builtin(obj, method)) |v| return v;
        if (try self.eval_stub_provider_method(obj, method, args)) |v| return v;
        if (try self.eval_type_new_instance_user_class(obj, method)) |v| return v;
        if (try self.eval_json_parser_method(obj, method, args)) |v| return v;
        if (eval_time_accessor_method(obj, method)) |v| return v;
        if (try self.eval_date_like_instance_method(obj, method, args)) |v| return v;
        if (try self.eval_user_class_dispatch(obj, method, args, current_env)) |v| return v;

        var bctx = builtins.BuiltinContext{
            .arena = self.arena,
            .stdout = &self.stdout,
            .pending_exception = &self.pending_exception,
            .see_all_data = self.see_all_data,
            .eval = self,
        };
        if (try builtins.dispatch_instance(&bctx, obj, method, args)) |result| {
            return result;
        }

        if (obj == .sobject) {
            if (try self.eval_sobject_instance_method(obj.sobject, method, args)) |v| return v;
        }
        if (obj == .list) return self.eval_list_method(obj.list, method, args);
        if (obj == .map) return self.eval_map_method(obj.map, method, args);
        if (obj == .set) return self.eval_set_method(obj.set, method, args);
        if (obj == .string) return self.eval_string_method(obj.string, method, args);

        // ObjectInstance methods (user-defined class) — last resort fallback:
        // when class_name resolves to a loaded class, dispatch with `this` bound.
        // (Inner class pattern "OuterClass.InnerClass" is handled above.)
        if (obj == .object) {
            if (self.find_class(obj.object.class_name)) |class_decl| {
                return self.call_instance_method(class_decl, obj.object, method, args);
            }
        }

        return Value.null_val;
    }

    /// Dispatcher for SObject instance methods (getSObjects, get, getSObject,
    /// put, clone/deepClone, isClone, getSObjectType, Database result accessors,
    /// getPopulatedFieldsAsMap, addError). Returns null when the method name
    /// does not match any SObject builtin.
    fn eval_sobject_instance_method(
        self: *Evaluator,
        sobj: *types.SObject,
        method: []const u8,
        args: []const Value,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(method, "getSObjects") and
            args.len > 0 and args[0] == .string)
        {
            if (utils.sobject_get(&sobj.fields, args[0].string)) |raw| {
                if (self.relationship_records_value(raw)) |records| return records;
                return raw;
            }
            return try self.make_empty_list();
        }
        if (std.ascii.eqlIgnoreCase(method, "get") and args.len > 0) {
            return try self.eval_sobject_get_method(sobj, args);
        }
        if (std.ascii.eqlIgnoreCase(method, "getSObject") and args.len > 0) {
            return try self.eval_sobject_get_sobject_method(sobj, args);
        }
        if (std.ascii.eqlIgnoreCase(method, "put") and args.len >= 2) {
            return try self.eval_sobject_put_method(sobj, args);
        }
        if (std.ascii.eqlIgnoreCase(method, "clone") or
            std.ascii.eqlIgnoreCase(method, "deepClone"))
        {
            return try self.eval_sobject_clone_method(sobj, args);
        }
        if (std.ascii.eqlIgnoreCase(method, "isClone")) {
            return Value{ .boolean = sobj.is_clone };
        }
        if (std.ascii.eqlIgnoreCase(method, "getSObjectType")) {
            const sot = try self.arena.create(types.ObjectInstance);
            sot.* = .{ .class_name = "Schema.SObjectType" };
            try sot.fields.put(self.arena, "name", Value{ .string = sobj.type_name });
            return Value{ .object = sot };
        }
        if (try self.eval_sobject_database_result_method(sobj, method)) |v| return v;
        if (std.ascii.eqlIgnoreCase(method, "getPopulatedFieldsAsMap")) {
            return try self.eval_sobject_populated_fields_as_map(sobj);
        }
        if (std.ascii.eqlIgnoreCase(method, "addError") and args.len > 0) {
            try self.eval_sobject_add_error(sobj, args);
            return Value.void_val;
        }
        return null;
    }

    /// Database result accessors exposed on SObject values (SaveResult,
    /// UpsertResult, etc.). Returns null when the method is unrelated.
    fn eval_sobject_database_result_method(
        self: *Evaluator,
        sobj: *types.SObject,
        method: []const u8,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(method, "isSuccess")) {
            return utils.sobject_get(&sobj.fields, "success") orelse
                utils.sobject_get(&sobj.fields, "isSuccess") orelse
                Value{ .boolean = true };
        }
        if (std.ascii.eqlIgnoreCase(method, "isCreated")) {
            return utils.sobject_get(&sobj.fields, "created") orelse
                utils.sobject_get(&sobj.fields, "isCreated") orelse
                Value{ .boolean = false };
        }
        if (std.ascii.eqlIgnoreCase(method, "getErrors")) {
            return utils.sobject_get(&sobj.fields, "errors") orelse
                try self.make_empty_list();
        }
        if (std.ascii.eqlIgnoreCase(method, "hasErrors")) {
            if (utils.sobject_get(&sobj.fields, "errors")) |errs_val| {
                if (errs_val == .list) {
                    return Value{ .boolean = errs_val.list.items.items.len > 0 };
                }
            }
            return Value{ .boolean = false };
        }
        if (std.ascii.eqlIgnoreCase(method, "getId")) {
            return utils.sobject_get(&sobj.fields, "Id") orelse
                utils.sobject_get(&sobj.fields, "id") orelse Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "getMessage")) {
            return self.get_s_object_field_value_case_insensitive(sobj, "message") orelse
                Value{ .string = "" };
        }
        if (std.ascii.eqlIgnoreCase(method, "getStatusCode")) {
            return self.get_s_object_field_value_case_insensitive(sobj, "statusCode") orelse
                Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "get_fields")) {
            return self.get_s_object_field_value_case_insensitive(sobj, "fields") orelse
                try self.make_empty_list();
        }
        return null;
    }

    /// Resolve an SObjectField-like argument down to its underlying field name,
    /// falling back to coerce_to_string.
    fn sobject_field_name_from_arg(self: *Evaluator, arg: Value) anyerror![]const u8 {
        return switch (arg) {
            .string => |s| s,
            .object => |ob| blk: {
                if (ob.fields.get("fieldName")) |n| {
                    if (n == .string) break :blk n.string;
                }
                if (ob.fields.get("name")) |n| {
                    if (n == .string) break :blk n.string;
                }
                break :blk try utils.coerce_to_string(arg, self.arena);
            },
            else => try utils.coerce_to_string(arg, self.arena),
        };
    }

    fn eval_sobject_get_method(
        self: *Evaluator,
        sobj: *types.SObject,
        args: []const Value,
    ) anyerror!Value {
        const field_name = try self.sobject_field_name_from_arg(args[0]);
        if (self.get_s_object_field_value_case_insensitive(sobj, field_name)) |value| {
            return value;
        }
        var get_bctx = builtins.BuiltinContext{
            .arena = self.arena,
            .stdout = &self.stdout,
            .pending_exception = &self.pending_exception,
            .see_all_data = self.see_all_data,
            .eval = self,
        };
        if (builtins.sobject_field_exists(&get_bctx, sobj, field_name)) return Value.null_val;
        const exc = try self.arena.create(types.ObjectInstance);
        exc.* = .{ .class_name = "System.SObjectException" };
        try exc.fields.put(self.arena, "message", Value{ .string = try std.fmt.allocPrint(
            self.arena,
            "Invalid field {s} for {s}",
            .{ field_name, sobj.type_name },
        ) });
        self.pending_exception = Value{ .object = exc };
        return error.ApexException;
    }

    fn eval_sobject_get_sobject_method(
        self: *Evaluator,
        sobj: *types.SObject,
        args: []const Value,
    ) anyerror!Value {
        const raw_name = try self.sobject_field_name_from_arg(args[0]);
        if (self.get_s_object_field_value_case_insensitive(sobj, raw_name)) |loaded| {
            if (loaded == .sobject) return loaded;
        }

        const relationship_name = if (std.mem.endsWith(u8, raw_name, "__c") or
            std.mem.endsWith(u8, raw_name, "Id"))
            self.fk_to_parent_ref(raw_name)
        else
            raw_name;
        if (!std.ascii.eqlIgnoreCase(relationship_name, raw_name)) {
            if (self.get_s_object_field_value_case_insensitive(sobj, relationship_name)) |loaded| {
                if (loaded == .sobject) return loaded;
            }
        }

        const fk_field = if (std.mem.endsWith(u8, raw_name, "__c") or
            std.mem.endsWith(u8, raw_name, "Id"))
            raw_name
        else
            self.parent_ref_to_fk(raw_name);
        const fk_value = self.get_s_object_field_value_case_insensitive(sobj, fk_field) orelse
            return Value.null_val;
        if (fk_value != .string) return Value.null_val;

        const target_type = blk: {
            if (self.get_field_metadata(sobj.type_name, fk_field)) |meta| {
                if (meta.reference_to) |reference_to| break :blk reference_to;
            }
            if (self.find_record_type_by_id(fk_value.string)) |record_type| break :blk record_type;
            if (fk_value.string.len >= 3) {
                const inferred = sobject_type_from_prefix(fk_value.string[0..3]);
                if (!std.ascii.eqlIgnoreCase(inferred, "SObject")) break :blk inferred;
            }
            break :blk null;
        } orelse return Value.null_val;

        if (self.find_record_by_id(target_type, fk_value.string)) |record| {
            if (record == .sobject) return record;
        }

        const related = try self.arena.create(types.SObject);
        related.* = .{ .type_name = target_type };
        related.id = fk_value.string;
        try related.fields.put(self.arena, "Id", fk_value);
        return Value{ .sobject = related };
    }

    fn eval_sobject_put_method(
        self: *Evaluator,
        sobj: *types.SObject,
        args: []const Value,
    ) anyerror!Value {
        // put(String fieldName, value) or put(SObjectField, value). The token
        // form exposes "name" first (unlike `get`/`getSObject` which prefer
        // "fieldName"), matching Apex semantics for Schema.SObjectField tokens.
        const field_name: []const u8 = if (args[0] == .string)
            args[0].string
        else if (args[0] == .object) blk: {
            if (args[0].object.fields.get("name")) |n| {
                if (n == .string) break :blk n.string;
            }
            if (args[0].object.fields.get("fieldName")) |n| {
                if (n == .string) break :blk n.string;
            }
            break :blk try utils.coerce_to_string(args[0], self.arena);
        } else try utils.coerce_to_string(args[0], self.arena);

        var put_bctx = builtins.BuiltinContext{
            .arena = self.arena,
            .stdout = &self.stdout,
            .pending_exception = &self.pending_exception,
            .see_all_data = self.see_all_data,
            .eval = self,
        };
        const normalized = try builtins.normalize_s_object_field_assignment(
            &put_bctx,
            sobj,
            field_name,
            args[1],
        );
        try utils.sobject_put(&sobj.fields, self.arena, field_name, normalized);
        if (std.ascii.eqlIgnoreCase(field_name, "Id") and normalized == .string) {
            sobj.id = normalized.string;
        }
        return normalized;
    }

    fn eval_sobject_clone_method(
        self: *Evaluator,
        sobj: *types.SObject,
        args: []const Value,
    ) anyerror!Value {
        const clone = try self.arena.create(types.SObject);
        clone.* = .{ .type_name = sobj.type_name, .is_clone = true };
        const preserve_id =
            if (args.len >= 1 and args[0] == .boolean) args[0].boolean else true;
        if (preserve_id and sobj.id != null) clone.id = sobj.id;
        for (sobj.fields.keys(), sobj.fields.values()) |k, v| {
            if (!preserve_id and std.ascii.eqlIgnoreCase(k, "Id")) continue;
            try clone.fields.put(self.arena, k, v);
        }
        return Value{ .sobject = clone };
    }

    fn eval_sobject_populated_fields_as_map(
        self: *Evaluator,
        sobj: *types.SObject,
    ) anyerror!Value {
        const map = try self.arena.create(types.MapValue);
        map.* = .{};
        for (sobj.fields.keys(), sobj.fields.values()) |k, v| {
            if (v == .null_val) continue;
            // Synthetic bookkeeping keys stored by addError/attachments/etc. are
            // not real fields and should not appear in getPopulatedFieldsAsMap.
            if (std.ascii.eqlIgnoreCase(k, "errors")) continue;
            try map.entries.put(self.arena, k, v);
        }
        return Value{ .map = map };
    }

    /// sobject.addError(msg) or addError(field, msg) — per Apex semantics this
    /// attaches an Error to the record's getErrors() list rather than throwing;
    /// only the enclosing DML (insert/update) converts the attached errors into
    /// a DmlException at commit time.
    fn eval_sobject_add_error(
        self: *Evaluator,
        sobj: *types.SObject,
        args: []const Value,
    ) anyerror!void {
        const msg_val = if (args.len >= 2) args[1] else args[0];
        const field_val: ?Value = if (args.len >= 2) args[0] else null;
        const err_obj = try self.arena.create(types.ObjectInstance);
        err_obj.* = .{ .class_name = "Database.Error" };
        try err_obj.fields.put(self.arena, "message", msg_val);
        try err_obj.fields.put(
            self.arena,
            "statusCode",
            Value{ .string = "FIELD_CUSTOM_VALIDATION_EXCEPTION" },
        );
        const fields_list = try self.arena.create(types.ListValue);
        fields_list.* = .{};
        if (field_val) |fv| {
            const field_name: []const u8 = switch (fv) {
                .string => |s| s,
                .object => |ob| blk: {
                    if (ob.fields.get("fieldName")) |fn_val| {
                        if (fn_val == .string) break :blk fn_val.string;
                    }
                    if (ob.fields.get("name")) |n_val| {
                        if (n_val == .string) break :blk n_val.string;
                    }
                    break :blk "";
                },
                else => "",
            };
            try fields_list.items.append(self.arena, Value{ .string = field_name });
            try err_obj.fields.put(self.arena, "field", Value{ .string = field_name });
        }
        try err_obj.fields.put(self.arena, "fields", Value{ .list = fields_list });

        var errors_list = if (utils.sobject_get(&sobj.fields, "errors")) |existing|
            if (existing == .list) existing.list else blk: {
                const lst = try self.arena.create(types.ListValue);
                lst.* = .{};
                break :blk lst;
            }
        else blk: {
            const lst = try self.arena.create(types.ListValue);
            lst.* = .{};
            break :blk lst;
        };
        try errors_list.items.append(self.arena, Value{ .object = err_obj });
        try utils.sobject_put(
            &sobj.fields,
            self.arena,
            "errors",
            Value{ .list = errors_list },
        );
    }

    fn eval_list_method(
        self: *Evaluator,
        list: *types.ListValue,
        method: []const u8,
        args: []const Value,
    ) !Value {
        if (try self.eval_list_introspection(list, method, args)) |v| return v;
        if (try self.eval_list_mutation(list, method, args)) |v| return v;
        if (try self.eval_list_copy(list, method, args)) |v| return v;
        if (std.ascii.eqlIgnoreCase(method, "sort")) {
            try self.eval_list_sort(list, args);
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "getSObjectType")) {
            return try self.eval_list_get_sobject_type(list);
        }
        return Value.null_val;
    }

    /// Pure-query methods: iterator, toString, hashCode, equals, size, isEmpty,
    /// get, contains, indexOf.
    fn eval_list_introspection(
        self: *Evaluator,
        list: *types.ListValue,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "iterator")) {
            const iter = try self.arena.create(types.ObjectInstance);
            iter.* = .{ .class_name = "System.Iterator" };
            const values_list = try self.arena.create(types.ListValue);
            values_list.* = .{};
            for (list.items.items) |item| {
                try values_list.items.append(self.arena, item);
            }
            try iter.fields.put(self.arena, "__items__", Value{ .list = values_list });
            try iter.fields.put(self.arena, "__pos__", Value{ .integer = 0 });
            return Value{ .object = iter };
        }
        if (std.ascii.eqlIgnoreCase(method, "toString")) {
            var buffer = std.ArrayListUnmanaged(u8).empty;
            try buffer.append(self.arena, '(');
            for (list.items.items, 0..) |item, idx| {
                if (idx > 0) try buffer.appendSlice(self.arena, ", ");
                const item_string = try self.value_to_string(item);
                try buffer.appendSlice(self.arena, item_string);
            }
            try buffer.append(self.arena, ')');
            return Value{ .string = buffer.items };
        }
        if (std.ascii.eqlIgnoreCase(method, "hashCode")) {
            return Value{ .integer = try self.value_hash_code(Value{ .list = list }) };
        }
        if (std.ascii.eqlIgnoreCase(method, "equals") and args.len > 0) {
            return Value{ .boolean = self.values_equal(Value{ .list = list }, args[0]) };
        }
        if (std.ascii.eqlIgnoreCase(method, "size")) {
            return Value{ .integer = @intCast(list.items.items.len) };
        }
        if (std.ascii.eqlIgnoreCase(method, "isEmpty")) {
            return Value{ .boolean = list.items.items.len == 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "get") and args.len > 0 and args[0] == .integer) {
            if (args[0].integer < 0) return Value.null_val;
            const i: usize = @intCast(args[0].integer);
            if (i < list.items.items.len) return list.items.items[i];
            return Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "contains") and args.len > 0) {
            for (list.items.items) |item| {
                if (self.values_equal(item, args[0])) return Value{ .boolean = true };
            }
            return Value{ .boolean = false };
        }
        if (std.ascii.eqlIgnoreCase(method, "indexOf") and args.len > 0) {
            for (list.items.items, 0..) |item, idx| {
                if (self.values_equal(item, args[0])) return Value{ .integer = @intCast(idx) };
            }
            return Value{ .integer = -1 };
        }
        return null;
    }

    /// In-place mutating methods: add, set, clear, remove, addAll.
    fn eval_list_mutation(
        self: *Evaluator,
        list: *types.ListValue,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "add")) {
            if (args.len >= 2 and args[0] == .integer) {
                if (args[0].integer < 0) return .void_val;
                const i: usize = @intCast(args[0].integer);
                if (i <= list.items.items.len) {
                    try list.items.insert(self.arena, i, args[1]);
                }
                return .void_val;
            }
            if (args.len > 0) try list.items.append(self.arena, args[0]);
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "set") and args.len >= 2 and args[0] == .integer) {
            if (args[0].integer < 0) return .void_val;
            const i: usize = @intCast(args[0].integer);
            if (i < list.items.items.len) list.items.items[i] = args[1];
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "clear")) {
            list.items.items.len = 0;
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "remove") and args.len > 0 and args[0] == .integer) {
            if (args[0].integer < 0) return .void_val;
            const i: usize = @intCast(args[0].integer);
            if (i < list.items.items.len) return list.items.orderedRemove(i);
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "addAll") and args.len > 0) {
            if (args[0] == .list) {
                for (args[0].list.items.items) |item| try list.items.append(self.arena, item);
            } else if (args[0] == .set) {
                for (args[0].set.entries.values()) |item| try list.items.append(self.arena, item);
            }
            return .void_val;
        }
        return null;
    }

    /// clone / deepClone: allocate a fresh ListValue preserving declared
    /// element_type and explicitly_generic flags, deep-cloning SObject items
    /// when requested.
    fn eval_list_copy(
        self: *Evaluator,
        list: *types.ListValue,
        method: []const u8,
        _: []const Value,
    ) !?Value {
        if (!(std.ascii.eqlIgnoreCase(method, "clone") or
            std.ascii.eqlIgnoreCase(method, "deepClone"))) return null;
        const is_deep = std.ascii.eqlIgnoreCase(method, "deepClone");
        const new_list = try self.arena.create(types.ListValue);
        new_list.* = .{};
        new_list.element_type = list.element_type;
        new_list.explicitly_generic = list.explicitly_generic;
        for (list.items.items) |item| {
            const cloned = if (is_deep and item == .sobject) blk: {
                const clone = try self.clone_s_object(item.sobject);
                break :blk Value{ .sobject = clone };
            } else item;
            try new_list.items.append(self.arena, cloned);
        }
        return Value{ .list = new_list };
    }

    /// List.sort() — use the supplied Comparator.compare(a, b) when present,
    /// otherwise fall back to natural ordering (Comparable.compareTo for user
    /// classes, compare_values otherwise).
    fn eval_list_sort(
        self: *Evaluator,
        list: *types.ListValue,
        args: []const Value,
    ) !void {
        if (args.len > 0 and args[0] == .object) {
            const comparator_obj = args[0].object;
            const comparator_class = self.find_class(comparator_obj.class_name) orelse return;
            const items = list.items.items;
            var i_idx: usize = 1;
            while (i_idx < items.len) : (i_idx += 1) {
                const key = items[i_idx];
                var j_idx: usize = i_idx;
                while (j_idx > 0) {
                    const cmp = try self.call_instance_method(
                        comparator_class,
                        comparator_obj,
                        "compare",
                        &.{ items[j_idx - 1], key },
                    );
                    if (cmp == .integer and cmp.integer > 0) {
                        items[j_idx] = items[j_idx - 1];
                        j_idx -= 1;
                    } else break;
                }
                items[j_idx] = key;
            }
            return;
        }
        // Default sort: Comparable.compareTo for user classes, natural order
        // for everything else (strings / numbers).
        const items = list.items.items;
        const use_comparable = items.len > 0 and items[0] == .object and
            self.has_comparable_interface(items[0].object.class_name);
        var i_idx: usize = 1;
        while (i_idx < items.len) : (i_idx += 1) {
            const key = items[i_idx];
            var j_idx: usize = i_idx;
            while (j_idx > 0) {
                const cmp =
                    if (use_comparable and items[j_idx - 1] == .object and key == .object)
                        try self.call_compare_to(items[j_idx - 1].object, key)
                    else
                        self.compare_values(items[j_idx - 1], key);
                if (cmp > 0) {
                    items[j_idx] = items[j_idx - 1];
                    j_idx -= 1;
                } else break;
            }
            items[j_idx] = key;
        }
    }

    /// List.getSObjectType() — consults the declared element_type first, with
    /// inference rules for the generic List<SObject> case. See inline notes
    /// for the subtle distinctions between implicit-generic SObject lists
    /// (inferred from content) and explicitly-generic ones (always null).
    fn eval_list_get_sobject_type(
        self: *Evaluator,
        list: *types.ListValue,
    ) !Value {
        if (list.element_type) |element_type| {
            const base_type = type_base_name(element_type);
            if (std.ascii.eqlIgnoreCase(base_type, "Object") or
                is_collection_type_name(base_type)) return Value.null_val;
            if (std.ascii.eqlIgnoreCase(base_type, "SObject")) {
                return try self.infer_sobject_list_type(list);
            }
            return try self.make_sobject_type_token(base_type);
        }
        if (list.items.items.len > 0 and list.items.items[0] == .sobject) {
            return try self.make_sobject_type_token(list.items.items[0].sobject.type_name);
        }
        return Value.null_val;
    }

    /// List<SObject> element-type inference: if every item is the same
    /// concrete SObjectType (common when typed lists get coerced through a
    /// SObject parameter — e.g. Map<Id, SObject>.values() piped into super(...)),
    /// report that type. Lists explicitly constructed with `new List<SObject>()`
    /// always return null to match real Apex (NebulaLogger's
    /// `setRecord(Iterable<Id>)` relies on this to classify Id-collection
    /// inputs as `Unknown`).
    fn infer_sobject_list_type(
        self: *Evaluator,
        list: *types.ListValue,
    ) !Value {
        if (list.explicitly_generic) return Value.null_val;
        if (list.items.items.len == 0) return Value.null_val;
        var inferred: ?[]const u8 = null;
        for (list.items.items) |item| {
            if (item != .sobject) return Value.null_val;
            if (inferred) |prev| {
                if (!std.ascii.eqlIgnoreCase(prev, item.sobject.type_name)) return Value.null_val;
            } else {
                inferred = item.sobject.type_name;
            }
        }
        const type_name = inferred orelse return Value.null_val;
        return try self.make_sobject_type_token(type_name);
    }

    fn uses_unique_collection_key(_: *Evaluator, value: Value) bool {
        return switch (value) {
            .object => |obj| !(std.ascii.eqlIgnoreCase(obj.class_name, "Type") or
                std.ascii.eqlIgnoreCase(obj.class_name, "Schema.SObjectType") or
                std.ascii.eqlIgnoreCase(obj.class_name, "Schema.SObjectField") or
                std.ascii.eqlIgnoreCase(obj.class_name, "SObjectField") or
                std.ascii.eqlIgnoreCase(obj.class_name, "DescribeFieldResult") or
                std.ascii.eqlIgnoreCase(obj.class_name, "Date") or
                std.ascii.eqlIgnoreCase(obj.class_name, "Datetime") or
                std.ascii.eqlIgnoreCase(obj.class_name, "Blob")),
            .list, .map, .set => true,
            else => false,
        };
    }

    fn alloc_unique_collection_key(self: *Evaluator) ![]const u8 {
        const key = try std.fmt.allocPrint(self.arena, "__key__:{d}", .{self.next_id});
        self.next_id += 1;
        return key;
    }

    fn find_map_entry_key(self: *Evaluator, map: *types.MapValue, key_value: Value) ?[]const u8 {
        if (key_value == .null_val) {
            if (map.entries.contains("")) return "";
        } else if (!self.uses_unique_collection_key(key_value)) {
            const rendered = utils.coerce_to_string(key_value, self.arena) catch null;
            if (rendered) |key| {
                if (map.entries.contains(key)) return key;
                for (map.entries.keys()) |existing_key| {
                    if (std.ascii.eqlIgnoreCase(existing_key, key)) return existing_key;
                }
            }
        }

        for (map.key_values.keys(), map.key_values.values()) |stored_key, original_key| {
            if (self.values_equal(original_key, key_value)) return stored_key;
        }

        return null;
    }

    fn map_storage_key(self: *Evaluator, map: *types.MapValue, key_value: Value) ![]const u8 {
        if (self.find_map_entry_key(map, key_value)) |existing| return existing;
        if (key_value == .null_val) return "";
        if (self.uses_unique_collection_key(key_value)) return self.alloc_unique_collection_key();
        return utils.coerce_to_string(key_value, self.arena);
    }

    /// Map primitives: put/get/containsKey/size/isEmpty, plus the rarely-used
    /// equals/hashCode overrides that user code may delegate through.
    fn eval_map_basic_method(
        self: *Evaluator,
        map: *types.MapValue,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "put") and args.len >= 2) {
            const key = try self.map_storage_key(map, args[0]);
            try map.entries.put(self.arena, key, args[1]);
            try map.key_values.put(self.arena, key, args[0]);
            return .void_val;
        }
        // Apex's Map.equals(Object) compares entries pairwise. Missing this
        // returned null and silently broke equality checks for user classes
        // that override equals() and delegate to an internal Map.
        if (std.ascii.eqlIgnoreCase(method, "equals") and args.len > 0) {
            return Value{ .boolean = self.values_equal(Value{ .map = map }, args[0]) };
        }
        if (std.ascii.eqlIgnoreCase(method, "hashCode")) {
            return Value{ .integer = try self.value_hash_code(Value{ .map = map }) };
        }
        if (std.ascii.eqlIgnoreCase(method, "get") and args.len > 0) {
            if (self.find_map_entry_key(map, args[0])) |key| {
                if (map.entries.get(key)) |v| return v;
            }
            return Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "containsKey") and args.len > 0) {
            return Value{ .boolean = self.find_map_entry_key(map, args[0]) != null };
        }
        if (std.ascii.eqlIgnoreCase(method, "size")) {
            return Value{ .integer = @intCast(map.entries.count()) };
        }
        if (std.ascii.eqlIgnoreCase(method, "isEmpty")) {
            return Value{ .boolean = map.entries.count() == 0 };
        }
        return null;
    }

    /// Projection methods: keySet, values.
    fn eval_map_projection_method(
        self: *Evaluator,
        map: *types.MapValue,
        method: []const u8,
        _: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "keySet")) {
            const set = try self.arena.create(types.SetValue);
            set.* = .{};
            for (map.entries.keys()) |key| {
                const original_key = map.key_values.get(key) orelse Value{ .string = key };
                try set.entries.put(self.arena, key, original_key);
            }
            return Value{ .set = set };
        }
        if (std.ascii.eqlIgnoreCase(method, "values")) {
            const list = try self.arena.create(types.ListValue);
            list.* = .{};
            for (map.entries.values()) |val| try list.items.append(self.arena, val);
            return Value{ .list = list };
        }
        return null;
    }

    /// Bulk / mutation methods: remove / putAll / clear / clone / deepClone.
    fn eval_map_bulk_method(
        self: *Evaluator,
        map: *types.MapValue,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "remove") and args.len > 0) {
            if (self.find_map_entry_key(map, args[0])) |key| {
                const val = map.entries.get(key) orelse return Value.null_val;
                _ = map.entries.orderedRemove(key);
                _ = map.key_values.orderedRemove(key);
                return val;
            }
            return Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "putAll") and args.len > 0) {
            try self.eval_map_put_all(map, args[0]);
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "clear")) {
            map.entries = .empty;
            map.key_values = .empty;
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "clone") or
            std.ascii.eqlIgnoreCase(method, "deepClone"))
        {
            return try self.eval_map_clone(map, method);
        }
        return null;
    }

    fn eval_map_put_all(
        self: *Evaluator,
        map: *types.MapValue,
        source: Value,
    ) !void {
        if (source == .map) {
            for (source.map.entries.keys(), source.map.entries.values()) |k, v| {
                try map.entries.put(self.arena, k, v);
                const original_key = source.map.key_values.get(k) orelse Value{ .string = k };
                try map.key_values.put(self.arena, k, original_key);
            }
            return;
        }
        if (source != .list) return;
        // putAll from list of SObjects: key=Id, value=record.
        for (source.list.items.items) |item| {
            if (item == .sobject and item.sobject.id != null) {
                try map.entries.put(self.arena, item.sobject.id.?, item);
                try map.key_values.put(
                    self.arena,
                    item.sobject.id.?,
                    Value{ .string = item.sobject.id.? },
                );
            }
        }
    }

    fn eval_map_clone(
        self: *Evaluator,
        map: *types.MapValue,
        method: []const u8,
    ) !Value {
        const new_map = try self.arena.create(types.MapValue);
        new_map.* = .{};
        const deep = std.ascii.eqlIgnoreCase(method, "deepClone");
        for (map.entries.keys(), map.entries.values()) |k, v| {
            const cloned_val = if (deep and v == .sobject) blk: {
                const clone = try self.clone_s_object(v.sobject);
                break :blk Value{ .sobject = clone };
            } else v;
            try new_map.entries.put(self.arena, k, cloned_val);
            const original_key = map.key_values.get(k) orelse Value{ .string = k };
            try new_map.key_values.put(self.arena, k, original_key);
        }
        return Value{ .map = new_map };
    }

    fn eval_map_method(
        self: *Evaluator,
        map: *types.MapValue,
        method: []const u8,
        args: []const Value,
    ) !Value {
        if (try self.eval_map_basic_method(map, method, args)) |v| return v;
        if (try self.eval_map_projection_method(map, method, args)) |v| return v;
        if (try self.eval_map_bulk_method(map, method, args)) |v| return v;
        // Implicit `getFieldName()` accessor for map entries (dot-get).
        if (args.len == 0 and std.mem.startsWith(u8, method, "get") and method.len > 3) {
            const field_name = method[3..];
            for (map.entries.keys(), map.entries.values()) |k, v| {
                if (std.ascii.eqlIgnoreCase(k, field_name)) return v;
            }
            return Value.null_val;
        }
        return Value.null_val;
    }

    fn set_entry_key(self: *Evaluator, value: Value) ![]const u8 {
        return switch (value) {
            .sobject => |sob| blk: {
                if (sob.id) |id| break :blk id;
                if (utils.sobject_get(&sob.fields, "Id")) |id_val| {
                    if (id_val == .string) break :blk id_val.string;
                }
                if (utils.sobject_get(&sob.fields, "UniqueId__c")) |unique_id| {
                    if (unique_id == .string) {
                        break :blk try std.fmt.allocPrint(
                            self.arena,
                            "{s}#uid:{s}",
                            .{ sob.type_name, unique_id.string },
                        );
                    }
                }
                if (utils.sobject_get(&sob.fields, "Name")) |name_val| {
                    if (name_val == .string) {
                        break :blk try std.fmt.allocPrint(
                            self.arena,
                            "{s}#name:{s}",
                            .{ sob.type_name, name_val.string },
                        );
                    }
                }
                const json = try utils.to_json(value, self.arena);
                break :blk try std.fmt.allocPrint(
                    self.arena,
                    "{s}#json:{s}",
                    .{ sob.type_name, json },
                );
            },
            .object, .list, .map, .set => try self.alloc_unique_collection_key(),
            else => try utils.coerce_to_string(value, self.arena),
        };
    }

    fn find_set_entry_key(self: *Evaluator, set: *types.SetValue, value: Value) ?[]const u8 {
        if (!self.uses_unique_collection_key(value)) {
            const rendered = self.set_entry_key(value) catch null;
            if (rendered) |key| {
                if (set.entries.contains(key)) return key;
            }
        }

        for (set.entries.keys(), set.entries.values()) |stored_key, existing_value| {
            if (self.values_equal(existing_value, value)) return stored_key;
        }

        return null;
    }

    fn eval_set_method(
        self: *Evaluator,
        set: *types.SetValue,
        method: []const u8,
        args: []const Value,
    ) !Value {
        if (try self.eval_set_membership_method(set, method, args)) |v| return v;
        if (try self.eval_set_mutation_method(set, method, args)) |v| return v;
        if (try self.eval_set_copy_method(set, method, args)) |v| return v;
        return Value.null_val;
    }

    /// Predicate / introspection methods: add (also mutates), contains, equals,
    /// hashCode, size, isEmpty, toString, containsAll.
    fn eval_set_membership_method(
        self: *Evaluator,
        set: *types.SetValue,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "add") and args.len > 0) {
            if (self.find_set_entry_key(set, args[0]) != null) return Value{ .boolean = false };
            const key = try self.set_entry_key(args[0]);
            try set.entries.put(self.arena, key, args[0]);
            return Value{ .boolean = true };
        }
        if (std.ascii.eqlIgnoreCase(method, "equals") and args.len > 0) {
            return Value{ .boolean = self.values_equal(Value{ .set = set }, args[0]) };
        }
        if (std.ascii.eqlIgnoreCase(method, "hashCode")) {
            return Value{ .integer = try self.value_hash_code(Value{ .set = set }) };
        }
        if (std.ascii.eqlIgnoreCase(method, "contains") and args.len > 0) {
            return Value{ .boolean = self.find_set_entry_key(set, args[0]) != null };
        }
        if (std.ascii.eqlIgnoreCase(method, "size")) {
            return Value{ .integer = @intCast(set.entries.count()) };
        }
        if (std.ascii.eqlIgnoreCase(method, "isEmpty")) {
            return Value{ .boolean = set.entries.count() == 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "toString")) {
            return Value{ .string = try utils.coerce_to_string(Value{ .set = set }, self.arena) };
        }
        if (std.ascii.eqlIgnoreCase(method, "containsAll") and
            args.len > 0 and args[0] == .set)
        {
            for (args[0].set.entries.values()) |item| {
                if (self.find_set_entry_key(set, item) == null) return Value{ .boolean = false };
            }
            return Value{ .boolean = true };
        }
        return null;
    }

    /// Mutating methods: addAll, remove, clear.
    fn eval_set_mutation_method(
        self: *Evaluator,
        set: *types.SetValue,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "addAll") and args.len > 0) {
            if (args[0] == .list) {
                for (args[0].list.items.items) |item| {
                    const key = try self.set_entry_key(item);
                    try set.entries.put(self.arena, key, item);
                }
            } else if (args[0] == .set) {
                for (args[0].set.entries.keys(), args[0].set.entries.values()) |key, item| {
                    try set.entries.put(self.arena, key, item);
                }
            }
            return Value{ .boolean = true };
        }
        if (std.ascii.eqlIgnoreCase(method, "remove") and args.len > 0) {
            if (self.find_set_entry_key(set, args[0])) |key| {
                _ = set.entries.orderedRemove(key);
                return Value{ .boolean = true };
            }
            return Value{ .boolean = false };
        }
        if (std.ascii.eqlIgnoreCase(method, "clear")) {
            set.entries = .empty;
            return .void_val;
        }
        return null;
    }

    /// Set-wide copy/iterator methods: clone/deepClone/iterator.
    fn eval_set_copy_method(
        self: *Evaluator,
        set: *types.SetValue,
        method: []const u8,
        _: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "clone") or
            std.ascii.eqlIgnoreCase(method, "deepClone"))
        {
            const new_set = try self.arena.create(types.SetValue);
            new_set.* = .{};
            for (set.entries.keys(), set.entries.values()) |key, item| {
                try new_set.entries.put(self.arena, key, item);
            }
            return Value{ .set = new_set };
        }
        if (std.ascii.eqlIgnoreCase(method, "iterator")) {
            // Return an Iterator-like object that wraps the set values.
            const iter = try self.arena.create(types.ObjectInstance);
            iter.* = .{ .class_name = "System.Iterator" };
            const values_list = try self.arena.create(types.ListValue);
            values_list.* = .{};
            for (set.entries.values()) |item| {
                try values_list.items.append(self.arena, item);
            }
            try iter.fields.put(self.arena, "__items__", Value{ .list = values_list });
            try iter.fields.put(self.arena, "__pos__", Value{ .integer = 0 });
            return Value{ .object = iter };
        }
        return null;
    }

    /// Simple pure queries and case conversions.
    fn eval_string_method_basic(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "toString")) return Value{ .string = s };
        if (std.ascii.eqlIgnoreCase(method, "hashCode")) {
            return Value{ .integer = self.string_hash_code(s) };
        }
        if (std.ascii.eqlIgnoreCase(method, "length")) return Value{ .integer = @intCast(s.len) };
        if (std.ascii.eqlIgnoreCase(method, "toUpperCase")) {
            const upper = try self.arena.alloc(u8, s.len);
            for (s, 0..) |ch, i| upper[i] = std.ascii.toUpper(ch);
            return Value{ .string = upper };
        }
        if (std.ascii.eqlIgnoreCase(method, "toLowerCase")) {
            const lower = try self.arena.alloc(u8, s.len);
            for (s, 0..) |ch, i| lower[i] = std.ascii.toLower(ch);
            return Value{ .string = lower };
        }
        if (std.ascii.eqlIgnoreCase(method, "trim")) {
            return Value{ .string = std.mem.trim(u8, s, " \t\r\n") };
        }
        if (std.ascii.eqlIgnoreCase(method, "repeat") and args.len > 0) {
            const count: usize = switch (args[0]) {
                .integer => |i| if (i > 0) @intCast(i) else 0,
                .double => |d| if (d > 0) @intFromFloat(d) else 0,
                else => 0,
            };
            if (count == 0 or s.len == 0) return Value{ .string = "" };
            const buf = try self.arena.alloc(u8, s.len * count);
            for (0..count) |ci| @memcpy(buf[ci * s.len ..][0..s.len], s);
            return Value{ .string = buf };
        }
        return null;
    }

    /// Substring search / boundary checks.
    fn eval_string_method_search(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        _ = self;
        if (std.ascii.eqlIgnoreCase(method, "contains") and args.len > 0 and args[0] == .string) {
            return Value{ .boolean = std.mem.indexOf(u8, s, args[0].string) != null };
        }
        if (std.ascii.eqlIgnoreCase(method, "containsIgnoreCase") and
            args.len > 0 and args[0] == .string)
        {
            return Value{ .boolean = std.ascii.indexOfIgnoreCase(s, args[0].string) != null };
        }
        if (std.ascii.eqlIgnoreCase(method, "startsWith") and
            args.len > 0 and args[0] == .string)
        {
            return Value{ .boolean = std.mem.startsWith(u8, s, args[0].string) };
        }
        if (std.ascii.eqlIgnoreCase(method, "endsWith") and
            args.len > 0 and args[0] == .string)
        {
            return Value{ .boolean = std.mem.endsWith(u8, s, args[0].string) };
        }
        if (std.ascii.eqlIgnoreCase(method, "indexOf") and
            args.len > 0 and args[0] == .string)
        {
            const needle = args[0].string;
            var from: usize = 0;
            if (args.len >= 2 and args[1] == .integer) {
                const raw = args[1].integer;
                if (raw > 0) {
                    const raw_u: usize = @intCast(raw);
                    from = if (raw_u > s.len) s.len else raw_u;
                }
            }
            if (from >= s.len and needle.len > 0) return Value{ .integer = -1 };
            const idx = std.mem.indexOfPos(u8, s, from, needle);
            return Value{ .integer = if (idx) |i| @intCast(i) else -1 };
        }
        if (std.ascii.eqlIgnoreCase(method, "lastIndexOf") and
            args.len > 0 and args[0] == .string)
        {
            const idx = std.mem.lastIndexOf(u8, s, args[0].string);
            return Value{ .integer = if (idx) |i| @intCast(i) else -1 };
        }
        return null;
    }

    fn eval_string_method_substring(s: []const u8, args: []const Value) !?Value {
        if (args.len >= 2 and args[0] == .integer and args[1] == .integer) {
            const s_len_i64: i64 = @intCast(s.len);
            const start_i64 = @max(args[0].integer, 0);
            const end_i64 = @max(@min(args[1].integer, s_len_i64), 0);
            const start: usize = @intCast(start_i64);
            const end: usize = @intCast(end_i64);
            if (start <= end and end <= s.len) return Value{ .string = s[start..end] };
        } else if (args.len >= 1 and args[0] == .integer) {
            const start: usize = @intCast(@max(args[0].integer, 0));
            if (start <= s.len) return Value{ .string = s[start..] };
        }
        return Value{ .string = s };
    }

    fn append_split_literal(
        arena: std.mem.Allocator,
        list: *types.ListValue,
        s: []const u8,
        pattern: []const u8,
        split_limit: ?usize,
    ) !void {
        if (split_limit) |limit| {
            if (limit <= 1) {
                try list.items.append(arena, Value{ .string = s });
                return;
            }
            var start: usize = 0;
            var splits_done: usize = 0;
            while (splits_done + 1 < limit) {
                const next = std.mem.indexOfPos(u8, s, start, pattern) orelse break;
                try list.items.append(arena, Value{ .string = s[start..next] });
                start = next + pattern.len;
                splits_done += 1;
            }
            try list.items.append(arena, Value{ .string = s[start..] });
            return;
        }
        var iter = std.mem.splitSequence(u8, s, pattern);
        while (iter.next()) |part| {
            try list.items.append(arena, Value{ .string = part });
        }
    }

    fn eval_string_method_split(self: *Evaluator, s: []const u8, args: []const Value) !Value {
        const list = try self.arena.create(types.ListValue);
        list.* = .{};
        const pattern = args[0].string;
        const split_limit: ?usize =
            if (args.len >= 2 and args[1] == .integer and args[1].integer > 0)
                @intCast(args[1].integer)
            else
                null;
        if (pattern.len == 0) {
            for (0..s.len) |ci| {
                try list.items.append(self.arena, Value{ .string = s[ci .. ci + 1] });
            }
            return Value{ .list = list };
        }
        // Apex's String.split(regex) treats the argument as a regex.
        const regex_chars = "\\[].|?*+()^${}";
        const has_regex_meta = std.mem.indexOfAny(u8, pattern, regex_chars) != null;
        if (has_regex_meta) {
            if (split_by_regex(self.arena, pattern, s, split_limit)) |parts| {
                for (parts) |part| {
                    try list.items.append(self.arena, Value{ .string = part });
                }
                return Value{ .list = list };
            } else |_| {
                // Regex engine rejected — fall through to literal split.
            }
        }
        try append_split_literal(self.arena, list, s, pattern, split_limit);
        return Value{ .list = list };
    }

    fn eval_string_method_replace_all_tail(trimmed_result: []const u8, trimmed_input: []const u8) ?Value {
        if (std.mem.eql(u8, trimmed_result, trimmed_input)) return null;
        if (std.mem.indexOf(u8, trimmed_input, "Class.") == null) return null;
        const anonymous_tail = "AnonymousBlock: line 1, column 1";
        if (std.mem.eql(u8, trimmed_result, anonymous_tail)) return Value{ .string = "" };
        if (!std.mem.startsWith(u8, trimmed_result, "Class.")) return null;
        const orphaned_tail = std.mem.trim(u8, trimmed_result["Class.".len..], " \t\r\n");
        if (std.mem.eql(u8, orphaned_tail, anonymous_tail)) return Value{ .string = "" };
        return null;
    }

    fn eval_string_method_replace_all(self: *Evaluator, s: []const u8, args: []const Value) !Value {
        const result = try regex.replace_all(self.arena, args[0].string, s, args[1].string);
        const trimmed_result = std.mem.trim(u8, result, " \t\r\n");
        const trimmed_input = std.mem.trim(u8, s, " \t\r\n");
        if (eval_string_method_replace_all_tail(trimmed_result, trimmed_input)) |v| return v;
        return Value{ .string = result };
    }

    fn parse_numeric_arg(arg: Value, arena: std.mem.Allocator) ?usize {
        return switch (arg) {
            .integer => |i| @intCast(@max(i, 0)),
            .double => |d| if (d > 0) @intFromFloat(d) else 0,
            .string => |arg_s| blk: {
                if (std.fmt.parseInt(i64, arg_s, 10)) |parsed| {
                    break :blk @intCast(@max(parsed, 0));
                } else |_| {}
                if (std.fmt.parseFloat(f64, arg_s)) |parsed| {
                    break :blk if (parsed > 0) @intFromFloat(parsed) else 0;
                } else |_| {}
                break :blk null;
            },
            else => blk: {
                const arg_s = utils.coerce_to_string(arg, arena) catch break :blk null;
                if (std.fmt.parseInt(i64, arg_s, 10)) |parsed| {
                    break :blk @intCast(@max(parsed, 0));
                } else |_| {}
                if (std.fmt.parseFloat(f64, arg_s)) |parsed| {
                    break :blk if (parsed > 0) @intFromFloat(parsed) else 0;
                } else |_| {}
                break :blk null;
            },
        };
    }

    fn eval_string_method_pad_abbrev(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "left") and args.len > 0) {
            const n: usize = parse_numeric_arg(args[0], self.arena) orelse return Value{ .string = s };
            const end = @min(n, s.len);
            return Value{ .string = s[0..end] };
        }
        if (std.ascii.eqlIgnoreCase(method, "right") and args.len > 0 and args[0] == .integer) {
            const n: usize = @intCast(@max(args[0].integer, 0));
            const start = if (n >= s.len) 0 else s.len - n;
            return Value{ .string = s[start..] };
        }
        if (std.ascii.eqlIgnoreCase(method, "abbreviate") and
            args.len > 0 and args[0] == .integer)
        {
            const max_width: usize = @intCast(@max(args[0].integer, 0));
            if (s.len <= max_width) return Value{ .string = s };
            if (max_width <= 3) return Value{ .string = s[0..max_width] };
            const prefix = s[0 .. max_width - 3];
            return Value{ .string = try std.fmt.allocPrint(self.arena, "{s}...", .{prefix}) };
        }
        if (std.ascii.eqlIgnoreCase(method, "leftPad") and args.len > 0 and args[0] == .integer) {
            const target_len: usize = @intCast(@max(args[0].integer, 0));
            if (s.len >= target_len) return Value{ .string = s };
            const pad_char: u8 = if (args.len > 1 and args[1] == .string and
                args[1].string.len > 0) args[1].string[0] else ' ';
            const result = try self.arena.alloc(u8, target_len);
            const pad_count = target_len - s.len;
            @memset(result[0..pad_count], pad_char);
            @memcpy(result[pad_count..], s);
            return Value{ .string = result };
        }
        if (std.ascii.eqlIgnoreCase(method, "rightPad") and args.len > 0 and args[0] == .integer) {
            const target_len: usize = @intCast(@max(args[0].integer, 0));
            if (s.len >= target_len) return Value{ .string = s };
            const pad_char: u8 = if (args.len > 1 and args[1] == .string and
                args[1].string.len > 0) args[1].string[0] else ' ';
            const result = try self.arena.alloc(u8, target_len);
            @memcpy(result[0..s.len], s);
            @memset(result[s.len..], pad_char);
            return Value{ .string = result };
        }
        return null;
    }

    fn eval_string_method_predicates(s: []const u8, method: []const u8) ?Value {
        if (std.ascii.eqlIgnoreCase(method, "isBlank")) {
            return Value{ .boolean = std.mem.trim(u8, s, " \t\r\n").len == 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "isNotBlank")) {
            return Value{ .boolean = std.mem.trim(u8, s, " \t\r\n").len > 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "isEmpty")) {
            return Value{ .boolean = s.len == 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "isNotEmpty")) {
            return Value{ .boolean = s.len > 0 };
        }
        return null;
    }

    fn all_chars_match(s: []const u8, pred: fn (u8) bool) bool {
        if (s.len == 0) return false;
        for (s) |ch| {
            if (!pred(ch)) return false;
        }
        return true;
    }

    fn eval_string_method_char_class(self: *Evaluator, s: []const u8, method: []const u8) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "isNumeric")) {
            return Value{ .boolean = all_chars_match(s, std.ascii.isDigit) };
        }
        if (std.ascii.eqlIgnoreCase(method, "isAlpha")) {
            return Value{ .boolean = all_chars_match(s, std.ascii.isAlphabetic) };
        }
        if (std.ascii.eqlIgnoreCase(method, "isAlphanumeric")) {
            return Value{ .boolean = all_chars_match(s, std.ascii.isAlphanumeric) };
        }
        if (std.ascii.eqlIgnoreCase(method, "capitalize")) {
            if (s.len == 0) return Value{ .string = s };
            const result = try self.arena.alloc(u8, s.len);
            result[0] = std.ascii.toUpper(s[0]);
            @memcpy(result[1..], s[1..]);
            return Value{ .string = result };
        }
        if (std.ascii.eqlIgnoreCase(method, "deleteWhitespace")) {
            var buf = try self.arena.alloc(u8, s.len);
            var j_idx: usize = 0;
            for (s) |ch| {
                if (!std.ascii.isWhitespace(ch)) {
                    buf[j_idx] = ch;
                    j_idx += 1;
                }
            }
            return Value{ .string = buf[0..j_idx] };
        }
        if (std.ascii.eqlIgnoreCase(method, "normalizeSpace")) {
            return Value{ .string = std.mem.trim(u8, s, " \t\r\n") };
        }
        return null;
    }

    fn eval_string_method_remove(s: []const u8, method: []const u8, args: []const Value) ?Value {
        if (args.len == 0 or args[0] != .string) return null;
        if (std.ascii.eqlIgnoreCase(method, "removeEnd")) {
            if (std.mem.endsWith(u8, s, args[0].string)) {
                return Value{ .string = s[0 .. s.len - args[0].string.len] };
            }
            return Value{ .string = s };
        }
        if (std.ascii.eqlIgnoreCase(method, "removeStart")) {
            if (std.mem.startsWith(u8, s, args[0].string)) {
                return Value{ .string = s[args[0].string.len..] };
            }
            return Value{ .string = s };
        }
        return null;
    }

    fn eval_string_method_format(self: *Evaluator, s: []const u8, args: []const Value) !Value {
        if (args.len > 0 and args[0] == .list) {
            var result = std.ArrayListUnmanaged(u8).empty;
            const items = args[0].list.items.items;
            var i: usize = 0;
            while (i < s.len) {
                if (s[i] == '{' and i + 1 < s.len) {
                    if (std.mem.indexOfScalarPos(u8, s, i + 1, '}')) |close| {
                        const idx_str = s[i + 1 .. close];
                        if (std.fmt.parseInt(usize, idx_str, 10)) |idx| {
                            if (idx < items.len) {
                                const val_str: []const u8 = try utils.coerce_to_string(
                                    items[idx],
                                    self.arena,
                                );
                                try result.appendSlice(self.arena, val_str);
                                i = close + 1;
                                continue;
                            }
                        } else |_| {}
                    }
                }
                try result.append(self.arena, s[i]);
                i += 1;
            }
            return Value{ .string = result.items };
        }
        if (args.len > 0 and args[0] == .string) {
            return self.format_date_time_pattern(s, args[0].string);
        }
        return Value{ .string = s };
    }

    fn eval_string_method_date_accessor(self: *Evaluator, s: []const u8, method: []const u8) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "date")) {
            const dt = parse_iso_date(s) orelse return Value{ .string = s };
            return Value{ .string = try std.fmt.allocPrint(
                self.arena,
                "{d:0>4}-{d:0>2}-{d:0>2}",
                .{ @as(u32, @intCast(dt.y)), dt.m, dt.d },
            ) };
        }
        if (std.ascii.eqlIgnoreCase(method, "time")) {
            const dt = parse_iso_date(s) orelse return Value{ .string = "00:00:00" };
            const time_str = try std.fmt.allocPrint(
                self.arena,
                "{d:0>2}:{d:0>2}:{d:0>2}.000",
                .{ dt.h, dt.mi, dt.sec },
            );
            const time_obj = try self.arena.create(types.ObjectInstance);
            time_obj.* = .{ .class_name = "Time" };
            try time_obj.fields.put(self.arena, "value", Value{ .string = time_str });
            try time_obj.fields.put(self.arena, "hour", Value{ .integer = @as(i64, dt.h) });
            try time_obj.fields.put(self.arena, "minute", Value{ .integer = @as(i64, dt.mi) });
            try time_obj.fields.put(self.arena, "second", Value{ .integer = @as(i64, dt.sec) });
            try time_obj.fields.put(self.arena, "millisecond", Value{ .integer = 0 });
            return Value{ .object = time_obj };
        }
        if (std.ascii.eqlIgnoreCase(method, "getTime")) {
            const dt = parse_iso_date(s) orelse return Value{ .integer = 0 };
            const y = @as(i64, dt.y);
            const doy = @as(i64, day_of_year(dt.m, dt.d));
            const is_leap: i64 = if (@mod(y, 4) == 0 and
                (@mod(y, 100) != 0 or @mod(y, 400) == 0)) @as(i64, 1) else 0;
            const leap_adj: i64 = if (dt.m > 2) is_leap else 0;
            const days_from_epoch = (y - 1970) * 365 +
                @divFloor(y - 1969, 4) -
                @divFloor(y - 1901, 100) +
                @divFloor(y - 1601, 400) +
                doy - 1 + leap_adj;
            const secs = days_from_epoch * 86400 +
                @as(i64, dt.h) * 3600 +
                @as(i64, dt.mi) * 60 +
                @as(i64, dt.sec);
            return Value{ .integer = secs * 1000 };
        }
        return null;
    }

    fn coerce_i32_arg(args: []const Value) i32 {
        if (args.len == 0) return 0;
        return switch (args[0]) {
            .integer => |iv| @intCast(iv),
            .double => |dv| @intFromFloat(dv),
            else => 0,
        };
    }

    fn format_iso_datetime(
        arena: std.mem.Allocator,
        y: u32,
        m: u8,
        d: u8,
        h: u8,
        mi: u8,
        sec: u8,
    ) ![]const u8 {
        return std.fmt.allocPrint(
            arena,
            "{d:0>4}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}Z",
            .{ y, m, d, h, mi, sec },
        );
    }

    fn eval_string_method_add_hours(self: *Evaluator, s: []const u8, args: []const Value) anyerror!Value {
        const dt = parse_iso_date(s) orelse return Value{ .string = s };
        const delta = coerce_i32_arg(args);
        var h: i32 = @as(i32, dt.h) + delta;
        var day_offset: i32 = 0;
        while (h >= 24) {
            h -= 24;
            day_offset += 1;
        }
        while (h < 0) {
            h += 24;
            day_offset -= 1;
        }
        const y = @as(u32, @intCast(dt.y));
        if (day_offset != 0) {
            const base = try format_iso_datetime(self.arena, y, dt.m, dt.d, @as(u8, @intCast(h)), dt.mi, dt.sec);
            return try self.date_time_add(base, "addDays", &.{Value{ .integer = day_offset }});
        }
        return Value{ .string = try format_iso_datetime(self.arena, y, dt.m, dt.d, @as(u8, @intCast(h)), dt.mi, dt.sec) };
    }

    fn eval_string_method_add_minutes(self: *Evaluator, s: []const u8, args: []const Value) anyerror!Value {
        const dt = parse_iso_date(s) orelse return Value{ .string = s };
        const delta = coerce_i32_arg(args);
        var mi: i32 = @as(i32, dt.mi) + delta;
        var hour_offset: i32 = 0;
        while (mi >= 60) {
            mi -= 60;
            hour_offset += 1;
        }
        while (mi < 0) {
            mi += 60;
            hour_offset -= 1;
        }
        const base = try format_iso_datetime(
            self.arena,
            @as(u32, @intCast(dt.y)),
            dt.m,
            dt.d,
            dt.h,
            @as(u8, @intCast(mi)),
            dt.sec,
        );
        if (hour_offset != 0) {
            return try self.eval_string_method(base, "addHours", &.{Value{ .integer = hour_offset }});
        }
        return Value{ .string = base };
    }

    fn eval_string_method_add_seconds(self: *Evaluator, s: []const u8, args: []const Value) anyerror!Value {
        const dt = parse_iso_date(s) orelse return Value{ .string = s };
        const delta = coerce_i32_arg(args);
        var sec: i32 = @as(i32, dt.sec) + delta;
        var min_offset: i32 = 0;
        while (sec >= 60) {
            sec -= 60;
            min_offset += 1;
        }
        while (sec < 0) {
            sec += 60;
            min_offset -= 1;
        }
        const base = try format_iso_datetime(
            self.arena,
            @as(u32, @intCast(dt.y)),
            dt.m,
            dt.d,
            dt.h,
            dt.mi,
            @as(u8, @intCast(sec)),
        );
        if (min_offset != 0) {
            return try self.eval_string_method(base, "addMinutes", &.{Value{ .integer = min_offset }});
        }
        return Value{ .string = base };
    }

    fn eval_string_method_add_hms(self: *Evaluator, s: []const u8, method: []const u8, args: []const Value) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(method, "addHours")) return try self.eval_string_method_add_hours(s, args);
        if (std.ascii.eqlIgnoreCase(method, "addMinutes")) return try self.eval_string_method_add_minutes(s, args);
        if (std.ascii.eqlIgnoreCase(method, "addSeconds")) return try self.eval_string_method_add_seconds(s, args);
        return null;
    }

    fn eval_string_method_date_component(s: []const u8, method: []const u8) ?Value {
        if (std.ascii.eqlIgnoreCase(method, "year") or
            std.ascii.eqlIgnoreCase(method, "yearGmt"))
        {
            const dt = parse_iso_date(s) orelse return Value.null_val;
            return Value{ .integer = dt.y };
        }
        if (std.ascii.eqlIgnoreCase(method, "month") or
            std.ascii.eqlIgnoreCase(method, "monthGmt"))
        {
            const dt = parse_iso_date(s) orelse return Value.null_val;
            return Value{ .integer = dt.m };
        }
        if (std.ascii.eqlIgnoreCase(method, "day") or
            std.ascii.eqlIgnoreCase(method, "dayGmt"))
        {
            const dt = parse_iso_date(s) orelse return Value.null_val;
            return Value{ .integer = dt.d };
        }
        if (std.ascii.eqlIgnoreCase(method, "hour") or
            std.ascii.eqlIgnoreCase(method, "hourGmt"))
        {
            const dt = parse_iso_date(s) orelse return Value{ .integer = 0 };
            return Value{ .integer = dt.h };
        }
        if (std.ascii.eqlIgnoreCase(method, "minute") or
            std.ascii.eqlIgnoreCase(method, "minuteGmt"))
        {
            const dt = parse_iso_date(s) orelse return Value{ .integer = 0 };
            return Value{ .integer = dt.mi };
        }
        if (std.ascii.eqlIgnoreCase(method, "second") or
            std.ascii.eqlIgnoreCase(method, "secondGmt"))
        {
            const dt = parse_iso_date(s) orelse return Value{ .integer = 0 };
            return Value{ .integer = dt.sec };
        }
        if (std.ascii.eqlIgnoreCase(method, "millisecond") or
            std.ascii.eqlIgnoreCase(method, "millisecondGmt"))
        {
            _ = parse_iso_date(s) orelse return Value{ .integer = 0 };
            return Value{ .integer = 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "day_of_year")) {
            const dt = parse_iso_date(s) orelse return Value.null_val;
            const is_leap =
                (@mod(dt.y, 4) == 0 and (@mod(dt.y, 100) != 0 or @mod(dt.y, 400) == 0));
            var doy: i32 = @as(i32, day_of_year(dt.m, dt.d));
            if (is_leap and dt.m > 2) doy += 1;
            return Value{ .integer = doy };
        }
        return null;
    }

    fn arg_to_date_string(s: []const u8, arg: Value) []const u8 {
        return switch (arg) {
            .string => |os| os,
            .object => |obj| blk: {
                if (obj.fields.get("value")) |v| if (v == .string) break :blk v.string;
                break :blk s;
            },
            else => s,
        };
    }

    fn eval_string_method_date_diff(s: []const u8, method: []const u8, args: []const Value) ?Value {
        if (args.len == 0) return null;
        if (std.ascii.eqlIgnoreCase(method, "daysBetween")) {
            const other_str = arg_to_date_string(s, args[0]);
            const a = parse_iso_date(s) orelse return Value.null_val;
            const b = parse_iso_date(other_str) orelse return Value.null_val;
            const a_days = iso_date_to_epoch_days(a.y, a.m, a.d);
            const b_days = iso_date_to_epoch_days(b.y, b.m, b.d);
            return Value{ .integer = b_days - a_days };
        }
        if (std.ascii.eqlIgnoreCase(method, "monthsBetween")) {
            const other_str = arg_to_date_string(s, args[0]);
            const a = parse_iso_date(s) orelse return Value.null_val;
            const b = parse_iso_date(other_str) orelse return Value.null_val;
            const diff = (@as(i64, b.y) - @as(i64, a.y)) * 12 +
                (@as(i64, b.m) - @as(i64, a.m));
            return Value{ .integer = diff };
        }
        return null;
    }

    fn eval_string_method_format_gmt(self: *Evaluator, s: []const u8, args: []const Value) !Value {
        if (args.len > 0 and args[0] == .string) {
            return self.format_date_time_pattern(s, args[0].string);
        }
        if (!(s.len >= 19 and s[4] == '-' and s[7] == '-' and s[10] == 'T')) {
            return Value{ .string = s };
        }
        const year = s[0..4];
        const month_num = std.fmt.parseInt(u8, s[5..7], 10) catch 1;
        const day = s[8..10];
        const hour24 = std.fmt.parseInt(u8, s[11..13], 10) catch 0;
        const minute = s[14..16];
        const second = s[17..19];
        const month_names = [_][]const u8{
            "January",   "February", "March",    "April",
            "May",       "June",     "July",     "August",
            "September", "October",  "November", "December",
        };
        const month_name = if (month_num >= 1 and month_num <= 12)
            month_names[month_num - 1]
        else
            "January";
        const hour12: u8 = if (hour24 == 0) 12 else if (hour24 > 12) hour24 - 12 else hour24;
        const am_pm: []const u8 = if (hour24 < 12) "AM" else "PM";
        return Value{ .string = try std.fmt.allocPrint(
            self.arena,
            "{d:0>2}:{s}:{s} {s}, {s} {s}, {s}",
            .{ hour12, minute, second, am_pm, month_name, day, year },
        ) };
    }

    fn eval_string_method_enum_value_of(self: *Evaluator, s: []const u8, args: []const Value) !Value {
        if (self.find_visible_enum_decl(s)) |enum_decl| {
            if (args[0] == .null_val) return Value.null_val;
            const raw_value = if (args[0] == .string)
                args[0].string
            else
                try utils.coerce_to_string(args[0], self.arena);
            for (enum_decl.values) |enum_value| {
                if (std.ascii.eqlIgnoreCase(enum_value, raw_value))
                    return Value{ .string = enum_value };
            }
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "System.NoSuchElementException" };
            try exc.fields.put(self.arena, "message", Value{ .string = try std.fmt.allocPrint(
                self.arena,
                "No enum constant {s}.{s}",
                .{ s, raw_value },
            ) });
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        return args[0];
    }

    fn resolve_sobject_type_from_id(self: *Evaluator, s: []const u8) []const u8 {
        var type_name: []const u8 = "SObject";
        var store_iter = self.store.iterator();
        while (store_iter.next()) |entry| {
            for (entry.value_ptr.items) |rec| {
                if (rec == .sobject and rec.sobject.id != null and
                    std.ascii.eqlIgnoreCase(rec.sobject.id.?, s))
                {
                    type_name = rec.sobject.type_name;
                    break;
                }
            }
        }
        if (std.mem.eql(u8, type_name, "SObject")) {
            if (self.id_type_map.get(s)) |tn| type_name = tn;
        }
        if (std.mem.eql(u8, type_name, "SObject") and s.len >= 3) {
            type_name = sobject_type_from_prefix(s[0..3]);
        }
        if (std.mem.eql(u8, type_name, "SObject") and s.len >= 3) {
            const id_prefix = s[0..3];
            var store_iter2 = self.store.iterator();
            while (store_iter2.next()) |entry| {
                const entry_prefix = sobject_key_prefix(entry.key_ptr.*);
                if (std.mem.eql(u8, &entry_prefix, id_prefix)) {
                    type_name = entry.key_ptr.*;
                    break;
                }
            }
            if (std.mem.eql(u8, type_name, "SObject")) {
                var ft_iter = self.field_types.iterator();
                while (ft_iter.next()) |entry| {
                    const entry_prefix = sobject_key_prefix(entry.key_ptr.*);
                    if (std.mem.eql(u8, &entry_prefix, id_prefix)) {
                        type_name = entry.key_ptr.*;
                        break;
                    }
                }
            }
        }
        return type_name;
    }

    fn eval_string_method_get_sobject_type(self: *Evaluator, s: []const u8) !Value {
        const type_name = self.resolve_sobject_type_from_id(s);
        if (is_template_s_object_type(type_name)) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "System.SObjectException" };
            try exc.fields.put(self.arena, "message", Value{ .string = try std.fmt.allocPrint(
                self.arena,
                "Cannot locate Apex Type for {s}",
                .{type_name},
            ) });
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        const sot = try self.arena.create(types.ObjectInstance);
        sot.* = .{ .class_name = "Schema.SObjectType" };
        try sot.fields.put(self.arena, "name", Value{ .string = type_name });
        return Value{ .object = sot };
    }

    fn eval_string_method_enum_values(self: *Evaluator, s: []const u8) !?Value {
        var class_iter = self.classes.iterator();
        while (class_iter.next()) |entry| {
            for (entry.value_ptr.*.members) |member| {
                switch (member) {
                    .enum_decl => |ed| {
                        if (!std.ascii.eqlIgnoreCase(ed.name, s)) continue;
                        const list = try self.arena.create(types.ListValue);
                        list.* = .{};
                        for (ed.values) |v| {
                            try list.items.append(self.arena, Value{ .string = v });
                        }
                        return Value{ .list = list };
                    },
                    else => {},
                }
            }
        }
        return null;
    }

    fn eval_string_method_misc(self: *Evaluator, s: []const u8, method: []const u8, args: []const Value) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "toInteger")) {
            return Value{ .integer = std.fmt.parseInt(i64, s, 10) catch 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "valueOf") and args.len == 0) {
            return Value{ .string = s };
        }
        if (std.ascii.eqlIgnoreCase(method, "getDescribe")) {
            const dfr = try self.arena.create(types.ObjectInstance);
            dfr.* = .{ .class_name = "Schema.DescribeFieldResult" };
            try dfr.fields.put(self.arena, "fieldName", Value{ .string = s });
            return Value{ .object = dfr };
        }
        if (std.ascii.eqlIgnoreCase(method, "name") or
            std.ascii.eqlIgnoreCase(method, "toString"))
        {
            return Value{ .string = s };
        }
        if (std.ascii.eqlIgnoreCase(method, "ordinal")) {
            return Value{ .integer = lookup_enum_ordinal(s) };
        }
        if (std.ascii.eqlIgnoreCase(method, "getOffset")) {
            return Value{ .integer = 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "getID") or std.ascii.eqlIgnoreCase(method, "getId")) {
            return Value{ .string = s };
        }
        if (std.ascii.eqlIgnoreCase(method, "getDisplayName")) {
            return Value{ .string = s };
        }
        if (std.ascii.eqlIgnoreCase(method, "isSameDay") and args.len > 0) {
            const other_str = builtins.extract_date_string(args[0]) orelse
                (if (args[0] == .string) args[0].string else "");
            const dt = parse_iso_date(s) orelse return Value{ .boolean = false };
            const odt = parse_iso_date(other_str) orelse return Value{ .boolean = false };
            return Value{ .boolean = dt.y == odt.y and dt.m == odt.m and dt.d == odt.d };
        }
        if (std.ascii.eqlIgnoreCase(method, "dateGmt") or
            std.ascii.eqlIgnoreCase(method, "dateGMT"))
        {
            const dt = parse_iso_date(s) orelse return Value{ .string = s };
            return Value{ .string = try std.fmt.allocPrint(
                self.arena,
                "{d:0>4}-{d:0>2}-{d:0>2}",
                .{ @as(u32, @intCast(dt.y)), dt.m, dt.d },
            ) };
        }
        return null;
    }

    fn eval_string_method_char_ops(self: *Evaluator, s: []const u8, method: []const u8, args: []const Value) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "countMatches") and
            args.len > 0 and args[0] == .string)
        {
            const sep = args[0].string;
            if (sep.len == 0) return Value{ .integer = 0 };
            var count: i64 = 0;
            var k: usize = 0;
            while (k + sep.len <= s.len) {
                if (std.mem.eql(u8, s[k .. k + sep.len], sep)) {
                    count += 1;
                    k += sep.len;
                } else {
                    k += 1;
                }
            }
            return Value{ .integer = count };
        }
        if (std.ascii.eqlIgnoreCase(method, "reverse")) {
            const reversed = try self.arena.alloc(u8, s.len);
            for (s, 0..) |ch, i| reversed[s.len - 1 - i] = ch;
            return Value{ .string = reversed };
        }
        if (std.ascii.eqlIgnoreCase(method, "charAt") and
            args.len > 0 and args[0] == .integer)
        {
            const idx: usize = @intCast(@max(args[0].integer, 0));
            if (idx < s.len) return Value{ .integer = @intCast(s[idx]) };
            return Value{ .integer = 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "compareTo") and
            args.len > 0 and args[0] == .string)
        {
            const other = args[0].string;
            const len = @min(s.len, other.len);
            for (0..len) |i| {
                if (s[i] < other[i]) return Value{ .integer = -1 };
                if (s[i] > other[i]) return Value{ .integer = 1 };
            }
            if (s.len < other.len) return Value{ .integer = -1 };
            if (s.len > other.len) return Value{ .integer = 1 };
            return Value{ .integer = 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "starts_with_ignore_case") and
            args.len > 0 and args[0] == .string)
        {
            return Value{ .boolean = std.ascii.startsWithIgnoreCase(s, args[0].string) };
        }
        if (std.ascii.eqlIgnoreCase(method, "endsWithIgnoreCase") and
            args.len > 0 and args[0] == .string)
        {
            return Value{ .boolean = std.ascii.endsWithIgnoreCase(s, args[0].string) };
        }
        if (std.ascii.eqlIgnoreCase(method, "remove") and
            args.len > 0 and args[0] == .string)
        {
            const result = try std.mem.replaceOwned(u8, self.arena, s, args[0].string, "");
            return Value{ .string = result };
        }
        return null;
    }

    fn eval_string_method_substring_family(s: []const u8, method: []const u8, args: []const Value) ?Value {
        if (args.len == 0 or args[0] != .string) return null;
        const sep = args[0].string;
        if (std.ascii.eqlIgnoreCase(method, "substringAfter")) {
            if (std.mem.indexOf(u8, s, sep)) |idx| {
                return Value{ .string = s[idx + sep.len ..] };
            }
            return Value{ .string = "" };
        }
        if (std.ascii.eqlIgnoreCase(method, "substringBefore")) {
            if (std.mem.indexOf(u8, s, sep)) |idx| {
                return Value{ .string = s[0..idx] };
            }
            return Value{ .string = s };
        }
        if (std.ascii.eqlIgnoreCase(method, "substringAfterLast")) {
            if (sep.len == 0) return Value{ .string = "" };
            var last_idx: ?usize = null;
            var k: usize = 0;
            while (k + sep.len <= s.len) : (k += 1) {
                if (std.mem.eql(u8, s[k .. k + sep.len], sep)) last_idx = k;
            }
            if (last_idx) |idx| return Value{ .string = s[idx + sep.len ..] };
            return Value{ .string = "" };
        }
        if (std.ascii.eqlIgnoreCase(method, "substringBeforeLast")) {
            if (sep.len == 0) return Value{ .string = s };
            var last_idx: ?usize = null;
            var k: usize = 0;
            while (k + sep.len <= s.len) : (k += 1) {
                if (std.mem.eql(u8, s[k .. k + sep.len], sep)) last_idx = k;
            }
            if (last_idx) |idx| return Value{ .string = s[0..idx] };
            return Value{ .string = s };
        }
        return null;
    }

    fn eval_string_method_unescape(self: *Evaluator, s: []const u8, method: []const u8) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "unescapeJava")) {
            var buf = std.ArrayListUnmanaged(u8).empty;
            var i: usize = 0;
            while (i < s.len) : (i += 1) {
                if (s[i] == '\\' and i + 1 < s.len) {
                    i += 1;
                    const escaped = switch (s[i]) {
                        'n' => '\n',
                        'r' => '\r',
                        't' => '\t',
                        '\\' => '\\',
                        '\'' => '\'',
                        '"' => '"',
                        else => s[i],
                    };
                    try buf.append(self.arena, escaped);
                    continue;
                }
                try buf.append(self.arena, s[i]);
            }
            return Value{ .string = try buf.toOwnedSlice(self.arena) };
        }
        if (std.ascii.eqlIgnoreCase(method, "unescapeHtml4")) {
            var result = try std.mem.replaceOwned(u8, self.arena, s, "&lt;", "<");
            result = try std.mem.replaceOwned(u8, self.arena, result, "&gt;", ">");
            result = try std.mem.replaceOwned(u8, self.arena, result, "&quot;", "\"");
            result = try std.mem.replaceOwned(u8, self.arena, result, "&#39;", "'");
            result = try std.mem.replaceOwned(u8, self.arena, result, "&apos;", "'");
            result = try std.mem.replaceOwned(u8, self.arena, result, "&amp;", "&");
            return Value{ .string = result };
        }
        if (std.ascii.eqlIgnoreCase(method, "escapeHtml4") or
            std.ascii.eqlIgnoreCase(method, "escapeJava") or
            std.ascii.eqlIgnoreCase(method, "escapeSingleQuotes"))
        {
            return Value{ .string = s };
        }
        return null;
    }

    fn eval_string_method_replace_equals(self: *Evaluator, s: []const u8, method: []const u8, args: []const Value) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "substring")) {
            return try eval_string_method_substring(s, args);
        }
        if (std.ascii.eqlIgnoreCase(method, "split") and args.len > 0 and args[0] == .string) {
            return try self.eval_string_method_split(s, args);
        }
        if (std.ascii.eqlIgnoreCase(method, "replace") and
            args.len >= 2 and args[0] == .string and args[1] == .string)
        {
            const result = try std.mem.replaceOwned(
                u8,
                self.arena,
                s,
                args[0].string,
                args[1].string,
            );
            return Value{ .string = result };
        }
        if (std.ascii.eqlIgnoreCase(method, "replace_all") and
            args.len >= 2 and args[0] == .string and args[1] == .string)
        {
            return try self.eval_string_method_replace_all(s, args);
        }
        if (std.ascii.eqlIgnoreCase(method, "equals") and
            args.len > 0 and args[0] == .string)
        {
            return Value{ .boolean = std.mem.eql(u8, s, args[0].string) };
        }
        if (std.ascii.eqlIgnoreCase(method, "equalsIgnoreCase") and
            args.len > 0 and args[0] == .string)
        {
            return Value{ .boolean = std.ascii.eqlIgnoreCase(s, args[0].string) };
        }
        return null;
    }

    fn eval_string_method_last_index_of(s: []const u8, method: []const u8, args: []const Value) ?Value {
        if (!std.ascii.eqlIgnoreCase(method, "lastIndexOf")) return null;
        if (args.len == 0 or args[0] != .string) return null;
        const target = args[0].string;
        if (target.len == 0 or s.len == 0) return Value{ .integer = -1 };
        var last: i64 = -1;
        var k: usize = 0;
        while (k + target.len <= s.len) : (k += 1) {
            if (std.mem.eql(u8, s[k .. k + target.len], target)) last = @intCast(k);
        }
        return Value{ .integer = last };
    }

    fn eval_string_method_date_ops(self: *Evaluator, s: []const u8, method: []const u8, args: []const Value) !?Value {
        if (std.ascii.eqlIgnoreCase(method, "format")) {
            return try self.eval_string_method_format(s, args);
        }
        if (try self.eval_string_method_date_accessor(s, method)) |v| return v;
        if (try self.eval_string_method_add_hms(s, method, args)) |v| return v;
        if (eval_string_method_date_component(s, method)) |v| return v;
        if (std.ascii.eqlIgnoreCase(method, "addYears") or
            std.ascii.eqlIgnoreCase(method, "addMonths") or
            std.ascii.eqlIgnoreCase(method, "addDays"))
        {
            return try self.date_time_add(s, method, args);
        }
        if (eval_string_method_date_diff(s, method, args)) |v| return v;
        if (std.ascii.eqlIgnoreCase(method, "formatGMT") or
            std.ascii.eqlIgnoreCase(method, "formatGmt"))
        {
            return try self.eval_string_method_format_gmt(s, args);
        }
        return null;
    }

    fn eval_string_method(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !Value {
        if (try self.eval_string_method_basic(s, method, args)) |v| return v;
        if (try self.eval_string_method_search(s, method, args)) |v| return v;
        if (try self.eval_string_method_replace_equals(s, method, args)) |v| return v;
        if (try self.eval_string_method_pad_abbrev(s, method, args)) |v| return v;
        if (eval_string_method_predicates(s, method)) |v| return v;
        if (try self.eval_string_method_char_class(s, method)) |v| return v;
        if (eval_string_method_last_index_of(s, method, args)) |v| return v;
        if (eval_string_method_remove(s, method, args)) |v| return v;
        if (try self.eval_string_method_unescape(s, method)) |v| return v;
        if (try self.eval_string_method_date_ops(s, method, args)) |v| return v;
        if (std.ascii.eqlIgnoreCase(method, "valueOf") and args.len > 0) {
            return self.eval_string_method_enum_value_of(s, args);
        }
        if (eval_string_method_substring_family(s, method, args)) |v| return v;
        if (try self.eval_string_method_char_ops(s, method, args)) |v| return v;
        if (std.ascii.eqlIgnoreCase(method, "getSobjectType") or
            std.ascii.eqlIgnoreCase(method, "getSObjectType"))
        {
            return self.eval_string_method_get_sobject_type(s);
        }
        if (std.ascii.eqlIgnoreCase(method, "values")) {
            if (try self.eval_string_method_enum_values(s)) |v| return v;
        }
        if (try self.eval_string_method_misc(s, method, args)) |v| return v;
        return Value.null_val;
    }

    // -----------------------------------------------------------------------
    // new 式
    // -----------------------------------------------------------------------

    fn eval_new_expr(self: *Evaluator, ne: *ast.NewExpr, current_env: *Env) !Value {
        // Strip "System." and "Schema." prefixes for type resolution
        const raw_type_name = ne.type_name.name;
        const is_platform_qualified = std.ascii.startsWithIgnoreCase(raw_type_name, "System.") or
            std.ascii.startsWithIgnoreCase(raw_type_name, "Schema.");
        const type_name = if (std.ascii.startsWithIgnoreCase(raw_type_name, "System."))
            raw_type_name[7..]
        else if (std.ascii.startsWithIgnoreCase(raw_type_name, "Schema."))
            raw_type_name[7..]
        else
            raw_type_name;

        // Type literal: List<T>.class, Map<K,V>.class, Type[].class → return Type object
        if ((std.mem.indexOf(u8, type_name, "<") != null or std.mem.endsWith(
            u8,
            type_name,
            "[]",
        )) and ne.args.len == 0) {
            const type_obj = try self.arena.create(types.ObjectInstance);
            type_obj.* = .{ .class_name = "Type" };
            try type_obj.fields.put(self.arena, "name", Value{ .string = type_name });
            return Value{ .object = type_obj };
        }

        // new List<T>() / new List<T>{...}
        if (std.ascii.eqlIgnoreCase(type_name, "List")) {
            const list = try self.arena.create(types.ListValue);
            list.* = .{};
            if (ne.type_name.params.len > 0) {
                const rendered = strip_type_namespace(self.render_type_ref(ne.type_name.params[0]));
                list.element_type = rendered;
                // Mark truly-generic explicit constructions. Real Apex returns
                // null from `getSObjectType()` on a list that the user built
                // with `new List<SObject>()` and populated by hand, even when
                // every element is the same concrete SObjectType. Lists that
                // inherit `element_type = "SObject"` later (via parameter
                // annotation, etc.) keep `explicitly_generic = false`.
                const rendered_base = type_base_name(rendered);
                if (std.ascii.eqlIgnoreCase(rendered_base, "SObject") or
                    std.ascii.eqlIgnoreCase(rendered_base, "Object"))
                {
                    list.explicitly_generic = true;
                }
            }
            // Single arg that is a Set → convert to list
            if (ne.args.len == 1 and !ne.is_brace_initializer) {
                var arg_copy = ne.args[0];
                const arg_val = try self.eval_expr(&arg_copy, current_env);
                if (arg_val == .set) {
                    for (arg_val.set.entries.values()) |item| {
                        try list.items.append(self.arena, item);
                    }
                    return Value{ .list = list };
                }
                if (arg_val == .list) {
                    // Copy list
                    for (arg_val.list.items.items) |item| {
                        try list.items.append(self.arena, item);
                    }
                    return Value{ .list = list };
                }
                // Single non-collection arg → add to list
                try list.items.append(self.arena, arg_val);
                return Value{ .list = list };
            }
            for (ne.args) |*arg| {
                try list.items.append(self.arena, try self.eval_expr(arg, current_env));
            }
            return Value{ .list = list };
        }

        // new Map<K,V>()
        if (std.ascii.eqlIgnoreCase(type_name, "Map")) {
            const map = try self.arena.create(types.MapValue);
            map.* = .{};
            for (ne.args) |*arg| {
                if (arg.* == .assignment) {
                    // Map literal: key => value
                    const asgn = arg.assignment;
                    const key_val = try self.eval_expr(asgn.target, current_env);
                    const val_val = try self.eval_expr(asgn.value, current_env);
                    const key_str = if (key_val == .null_val) "" else try utils.coerce_to_string(
                        key_val,
                        self.arena,
                    );
                    try map.entries.put(self.arena, key_str, val_val);
                    try map.key_values.put(self.arena, key_str, key_val);
                }
            }
            // If single non-assignment arg is a list, construct map from SObject list
            if (ne.args.len == 1 and ne.args[0] != .assignment) {
                var arg_copy = ne.args[0];
                const arg_val = try self.eval_expr(&arg_copy, current_env);
                if (arg_val == .list) {
                    for (arg_val.list.items.items) |item| {
                        if (item == .sobject and item.sobject.id != null) {
                            try map.entries.put(self.arena, item.sobject.id.?, item);
                            try map.key_values.put(
                                self.arena,
                                item.sobject.id.?,
                                Value{ .string = item.sobject.id.? },
                            );
                        }
                    }
                }
            }
            return Value{ .map = map };
        }

        // DataWeaveScriptResource.* → create DataWeave.Script stub
        if (std.ascii.startsWithIgnoreCase(type_name, "DataWeaveScriptResource")) {
            const instance = try self.arena.create(types.ObjectInstance);
            instance.* = .{ .class_name = "DataWeave.Script" };
            // Extract script name from the type (e.g., "DataWeaveScriptResource.helloWorld" →
            // "helloWorld")
            const dot_pos = std.mem.lastIndexOfScalar(u8, type_name, '.');
            const script_name = if (dot_pos) |dp| type_name[dp + 1 ..] else type_name;
            try instance.fields.put(self.arena, "scriptName", Value{ .string = script_name });
            return Value{ .object = instance };
        }

        // new Set<T>() or new Set<T>(collection)
        if (std.ascii.eqlIgnoreCase(type_name, "Set")) {
            const set = try self.arena.create(types.SetValue);
            set.* = .{};
            for (ne.args) |*arg| {
                const v = try self.eval_expr(arg, current_env);
                // If argument is a list or set, add each element individually
                if (v == .list) {
                    for (v.list.items.items) |item| {
                        const key = try self.set_entry_key(item);
                        try set.entries.put(self.arena, key, item);
                    }
                } else if (v == .set) {
                    for (v.set.entries.keys(), v.set.entries.values()) |k, item| {
                        try set.entries.put(self.arena, k, item);
                    }
                } else {
                    const key = try self.set_entry_key(v);
                    try set.entries.put(self.arena, key, v);
                }
            }
            return Value{ .set = set };
        }

        const builtin_exception_types = [_][]const u8{
            "Exception",
            "DMLException",
            "DmlException",
            "NullPointerException",
            "TypeException",
            "QueryException",
            "JSONException",
            "ListException",
            "MathException",
            "SecurityException",
            "NoAccessException",
            "InvalidParameterValueException",
            "CalloutException",
            "StringException",
            "NoSuchElementException",
            "NoDataFoundException",
            "SearchException",
            "SObjectException",
            "HandledException",
            "IllegalArgumentException",
            "LimitException",
            "AsyncException",
            "SerializationException",
            "FlowException",
            "FinalException",
            "UnsupportedOperationException",
            "EventBusException",
        };
        inline for (builtin_exception_types) |exc_type| {
            if (std.ascii.eqlIgnoreCase(type_name, exc_type)) {
                const instance = try self.arena.create(types.ObjectInstance);
                instance.* = .{ .class_name = exc_type };
                if (ne.args.len > 0) {
                    var arg_copy = ne.args[0];
                    try instance.fields.put(
                        self.arena,
                        "message",
                        try self.eval_expr(&arg_copy, current_env),
                    );
                }
                return Value{ .object = instance };
            }
        }

        // ApexPages.StandardController constructor
        if (std.ascii.eqlIgnoreCase(type_name, "ApexPages.StandardController") or
            std.ascii.eqlIgnoreCase(type_name, "StandardController"))
        {
            const instance = try self.arena.create(types.ObjectInstance);
            instance.* = .{ .class_name = "ApexPages.StandardController" };
            if (ne.args.len > 0) {
                var arg_copy = ne.args[0];
                const record = try self.eval_expr(&arg_copy, current_env);
                try instance.fields.put(self.arena, "record", record);
            }
            return Value{ .object = instance };
        }

        // ApexPages.StandardSetController constructor
        if (std.ascii.eqlIgnoreCase(type_name, "ApexPages.StandardSetController") or
            std.ascii.eqlIgnoreCase(type_name, "StandardSetController"))
        {
            const instance = try self.arena.create(types.ObjectInstance);
            instance.* = .{ .class_name = "ApexPages.StandardSetController" };
            if (ne.args.len > 0) {
                var arg_copy = ne.args[0];
                const records = try self.eval_expr(&arg_copy, current_env);
                try instance.fields.put(self.arena, "records", records);
            }
            try instance.fields.put(
                self.arena,
                "pageSize",
                Value{ .integer = 20 },
            ); // default page size
            return Value{ .object = instance };
        }

        // Known non-SObject types: create ObjectInstance instead
        const non_sobject_types = [_][]const u8{
            "RestRequest",            "RestResponse",        "HttpRequest",                      "HttpResponse",
            "Http",                   "PageReference",       "SelectOption",                     "Messaging.SingleEmailMessage",
            "Messaging.InboundEmail", "QueryException",      "DmlException",                     "AuraHandledException",
            "CalloutException",       "Database.DmlOptions", "DmlOptions",                       "ApexPages.Message",
            "VisualEditor.DataRow",   "DataRow",             "VisualEditor.DynamicPickListRows", "DynamicPickListRows",
        };
        for (non_sobject_types) |nst| {
            if (std.ascii.eqlIgnoreCase(type_name, nst)) {
                const instance = try self.arena.create(types.ObjectInstance);
                instance.* = .{ .class_name = type_name };

                // SelectOption constructor: (value, label) or (value, label, disabled)
                if (std.ascii.eqlIgnoreCase(type_name, "SelectOption")) {
                    if (ne.args.len >= 2) {
                        var arg0_copy = ne.args[0];
                        var arg1_copy = ne.args[1];
                        const val = try self.eval_expr(&arg0_copy, current_env);
                        const label = try self.eval_expr(&arg1_copy, current_env);
                        const val_str = try utils.coerce_to_string(val, self.arena);
                        const label_str = try utils.coerce_to_string(label, self.arena);
                        try instance.fields.put(self.arena, "value", Value{ .string = val_str });
                        try instance.fields.put(self.arena, "label", Value{ .string = label_str });
                        if (ne.args.len >= 3) {
                            var arg2_copy = ne.args[2];
                            const disabled = try self.eval_expr(&arg2_copy, current_env);
                            try instance.fields.put(self.arena, "disabled", disabled);
                        } else {
                            try instance.fields.put(
                                self.arena,
                                "disabled",
                                Value{ .boolean = false },
                            );
                        }
                    }
                    return Value{ .object = instance };
                }

                if (std.ascii.eqlIgnoreCase(type_name, "VisualEditor.DataRow") or
                    std.ascii.eqlIgnoreCase(type_name, "DataRow"))
                {
                    if (ne.args.len >= 2) {
                        var arg0_copy = ne.args[0];
                        var arg1_copy = ne.args[1];
                        const label = try self.eval_expr(&arg0_copy, current_env);
                        const value = try self.eval_expr(&arg1_copy, current_env);
                        try instance.fields.put(self.arena, "label", label);
                        try instance.fields.put(self.arena, "value", value);
                    }
                    return Value{ .object = instance };
                }

                if (std.ascii.eqlIgnoreCase(type_name, "VisualEditor.DynamicPickListRows") or
                    std.ascii.eqlIgnoreCase(type_name, "DynamicPickListRows"))
                {
                    const data_rows = try self.arena.create(types.ListValue);
                    data_rows.* = .{};
                    try instance.fields.put(self.arena, "dataRows", Value{ .list = data_rows });
                    return Value{ .object = instance };
                }

                if (std.ascii.eqlIgnoreCase(type_name, "ApexPages.Message")) {
                    const severity = if (ne.args.len >= 1) blk: {
                        var arg0_copy = ne.args[0];
                        const severity_val = try self.eval_expr(&arg0_copy, current_env);
                        break :blk try utils.coerce_to_string(severity_val, self.arena);
                    } else "ERROR";
                    const summary = if (ne.args.len >= 2) blk: {
                        var arg1_copy = ne.args[1];
                        const summary_val = try self.eval_expr(&arg1_copy, current_env);
                        break :blk try utils.coerce_to_string(summary_val, self.arena);
                    } else "";
                    const detail = if (ne.args.len >= 3) blk: {
                        var arg2_copy = ne.args[2];
                        const detail_val = try self.eval_expr(&arg2_copy, current_env);
                        break :blk try utils.coerce_to_string(detail_val, self.arena);
                    } else summary;
                    try instance.fields.put(self.arena, "severity", Value{ .string = severity });
                    try instance.fields.put(self.arena, "summary", Value{ .string = summary });
                    try instance.fields.put(self.arena, "detail", Value{ .string = detail });
                    try instance.fields.put(self.arena, "message", Value{ .string = summary });
                    return Value{ .object = instance };
                }

                if (std.ascii.eqlIgnoreCase(type_name, "PageReference")) {
                    if (ne.args.len > 0) {
                        var arg0_copy = ne.args[0];
                        const url_val = try self.eval_expr(&arg0_copy, current_env);
                        if (url_val == .string) {
                            try instance.fields.put(self.arena, "url", url_val);
                        } else {
                            try instance.fields.put(
                                self.arena,
                                "url",
                                Value{ .string = try utils.coerce_to_string(url_val, self.arena) },
                            );
                        }
                    } else {
                        try instance.fields.put(self.arena, "url", Value{ .string = "" });
                    }
                    const params = try self.arena.create(types.MapValue);
                    params.* = .{};
                    try instance.fields.put(self.arena, "parameters", Value{ .map = params });
                    return Value{ .object = instance };
                }

                // RestRequest: initialize params map
                if (std.ascii.eqlIgnoreCase(type_name, "RestRequest")) {
                    const params = try self.arena.create(types.MapValue);
                    params.* = .{};
                    try instance.fields.put(self.arena, "params", Value{ .map = params });
                    const headers = try self.arena.create(types.MapValue);
                    headers.* = .{};
                    try instance.fields.put(self.arena, "headers", Value{ .map = headers });
                    const blob = try self.arena.create(types.ObjectInstance);
                    blob.* = .{ .class_name = "Blob" };
                    try blob.fields.put(self.arena, "value", Value.null_val);
                    try instance.fields.put(self.arena, "requestBody", Value{ .object = blob });
                    return Value{ .object = instance };
                }
                // RestResponse: initialize responseBody as Blob
                if (std.ascii.eqlIgnoreCase(type_name, "RestResponse")) {
                    const blob = try self.arena.create(types.ObjectInstance);
                    blob.* = .{ .class_name = "Blob" };
                    try blob.fields.put(self.arena, "value", Value{ .string = "" });
                    try instance.fields.put(self.arena, "responseBody", Value{ .object = blob });
                    const headers = try self.arena.create(types.MapValue);
                    headers.* = .{};
                    try instance.fields.put(self.arena, "headers", Value{ .map = headers });
                    return Value{ .object = instance };
                }

                // If args contain a message (exception pattern)
                if (ne.args.len > 0) {
                    var arg_copy = ne.args[0];
                    const arg_val = try self.eval_expr(&arg_copy, current_env);
                    if (std.mem.endsWith(u8, type_name, "Exception")) {
                        // AuraHandledException always returns "Script-thrown exception" from
                        // getMessage()
                        if (std.ascii.eqlIgnoreCase(type_name, "AuraHandledException")) {
                            try instance.fields.put(
                                self.arena,
                                "message",
                                Value{ .string = "Script-thrown exception" },
                            );
                        } else {
                            try instance.fields.put(self.arena, "message", arg_val);
                        }
                    }
                }
                return Value{ .object = instance };
            }
        }

        // SObject with named params: new Account(Name = 'Test', ...)
        // Strip "Schema." prefix for SObject type names (e.g. Schema.User → User)
        const sob_type_name =
            if (std.ascii.startsWithIgnoreCase(type_name, "Schema.")) type_name[7..] else type_name;
        const obj = try self.arena.create(types.SObject);
        obj.* = .{ .type_name = sob_type_name };
        // Parse named params: args should be Assignment expressions
        for (ne.args) |*arg| {
            if (arg.* == .assignment) {
                const asgn = arg.assignment;
                if (asgn.target.* == .identifier) {
                    const field_name = asgn.target.identifier.name;
                    const field_val = try self.eval_expr(asgn.value, current_env);
                    try obj.fields.put(self.arena, field_name, field_val);
                    // Sync internal id field when Id is set via constructor
                    if (std.ascii.eqlIgnoreCase(field_name, "Id") and field_val == .string) {
                        obj.id = field_val.string;
                    }
                }
            }
        }

        // Check if it's a user-defined class or exception.
        // Resolve simple names against the current lexical scope first so
        // nested inner classes instantiate sibling inner classes from the
        // correct outer class instead of drifting to an unrelated duplicate.
        const simple_name = if (std.mem.lastIndexOfScalar(
            u8,
            type_name,
            '.',
        )) |di| type_name[di + 1 ..] else type_name;
        const fq_inner_name: ?[]const u8 = if (self.current_class) |cc|
            (if (std.mem.indexOfScalar(u8, type_name, '.') == null)
                (std.fmt.allocPrint(self.arena, "{s}.{s}", .{ cc, type_name }) catch null)
            else
                null)
        else
            null;
        const allow_simple_name_fallback = !is_platform_qualified and std.mem.indexOfScalar(
            u8,
            type_name,
            '.',
        ) == null;
        const resolved_class_name: ?[]const u8 = blk: {
            if (!is_platform_qualified) {
                if (!std.ascii.eqlIgnoreCase(simple_name, "Database")) {
                    if (self.resolve_visible_user_class_in_scope(
                        current_env,
                        type_name,
                    )) |visible_class| break :blk visible_class;
                }
                if (fq_inner_name) |fqn| {
                    if (self.find_class(fqn) != null) break :blk fqn;
                }
                if (self.find_class(type_name) != null) break :blk type_name;
            }
            if (allow_simple_name_fallback and self.find_class(simple_name) != null) {
                // Look up whether simple_name is an inner class of some outer — prefer FQ if unique
                if (self.find_outer_class_name(simple_name)) |outer| {
                    break :blk std.fmt.allocPrint(
                        self.arena,
                        "{s}.{s}",
                        .{ outer, simple_name },
                    ) catch simple_name;
                }
                break :blk simple_name;
            }
            break :blk null;
        };
        if (if (resolved_class_name) |rn| self.find_class(rn) else null) |class_decl| {
            const instance = try self.arena.create(types.ObjectInstance);
            instance.* = .{ .class_name = resolved_class_name.? };

            // Lazy static init for this class and parent hierarchy
            // (so static field initializers like `static final Integer X = 5;`
            // are evaluated before the constructor body references them)
            self.ensure_static_init(class_decl.name);
            if (class_decl.super_class) |sc| self.ensure_static_init(sc.name);

            // Check if it's an exception class (extends Exception)
            // If the class has its own constructor, fall through to run it
            // (user-defined exceptions like RestRouteError.RestException may set extra fields)
            {
                const is_exc = if (class_decl.super_class) |sc| std.mem.endsWith(u8, sc.name, "Exception") else std.mem.endsWith(u8, type_name, "Exception");
                if (is_exc) {
                    // Check if class has a user-defined constructor
                    var has_constructor = false;
                    for (class_decl.members) |member| {
                        switch (member) {
                            .constructor_decl => {
                                has_constructor = true;
                                break;
                            },
                            else => {},
                        }
                    }
                    if (!has_constructor) {
                        // No constructor: use simple message extraction
                        if (ne.args.len > 0) {
                            var arg_copy = ne.args[0];
                            const msg_val = try self.eval_expr(&arg_copy, current_env);
                            try instance.fields.put(self.arena, "message", msg_val);
                        }
                        return Value{ .object = instance };
                    }
                    // Has constructor: fall through to normal constructor logic below
                }
            }

            // Initialize ancestor fields top-down (grandparents before parent) so child
            // field declarations can shadow, and every inherited field with an
            // initializer actually runs.
            {
                var chain: std.ArrayListUnmanaged(*ast.ClassDecl) = .empty;
                defer chain.deinit(self.arena);

                var cursor: ?*ast.ClassDecl =
                    if (class_decl.super_class) |sc| self.find_class(sc.name) else null;
                while (cursor) |cd_cursor| {
                    try chain.append(self.arena, cd_cursor);
                    cursor = if (cd_cursor.super_class) |sc| self.find_class(sc.name) else null;
                }
                var i: usize = chain.items.len;
                while (i > 0) {
                    i -= 1;
                    self.init_instance_fields(chain.items[i], instance) catch {};
                }
            }

            // Initialize instance fields from class (non-static) — after ancestors
            self.init_instance_fields(class_decl, instance) catch {};

            // Evaluate constructor args. Capture enum-only type hints so
            // overload resolution can distinguish `(String, Enum, Boolean)`
            // from `(String, String, Enum)` when a typed variable or enum
            // literal appears in the middle position. We intentionally stay
            // narrower than method-call hinting (enum_access_type_name plus
            // declared enum-typed locals) because broader hinting regresses
            // overloads that rely on raw argument-shape scoring.
            var eval_args: std.ArrayListUnmanaged(Value) = .empty;
            var ctor_type_hints: std.ArrayListUnmanaged(?[]const u8) = .empty;
            var any_enum_hint = false;
            for (ne.args) |*arg| {
                const enum_hint = self.enum_access_type_name(arg) orelse blk: {
                    // Also surface declared enum-typed local variables like
                    // `Mode direction = Mode.A; new Ordering(name, direction, flag)`.
                    if (arg.* != .identifier) break :blk null;
                    if (self.resolve_assignment_target_type(arg, current_env)) |t| {
                        const base = type_base_name(strip_type_namespace(t));
                        if (is_system_enum_type_name(base)) break :blk base;
                        if (self.find_visible_enum_decl(base) != null) break :blk base;
                    }
                    break :blk null;
                };
                if (enum_hint != null) any_enum_hint = true;
                try ctor_type_hints.append(self.arena, enum_hint);
                try eval_args.append(self.arena, try self.eval_expr(arg, current_env));
            }
            const prev_ctor_hints = self.cast_type_hints;
            if (any_enum_hint) self.cast_type_hints = ctor_type_hints.items;
            defer if (any_enum_hint) {
                self.cast_type_hints = prev_ctor_hints;
            };

            // Execute parent constructor first (if has super_class and parent has constructor).
            // Skip the implicit parent call if the child's chosen constructor explicitly
            // invokes super(...) or this(...). Also skip if the parent only declares
            // non-zero-arg constructors (the child must then call super(...) explicitly,
            // which we evaluate inside its body instead).
            if (class_decl.super_class) |sc| {
                if (self.find_class(sc.name)) |parent_decl| {
                    const child_chosen = self.find_matching_constructor(
                        class_decl,
                        eval_args.items,
                    );
                    const child_explicit =
                        if (child_chosen) |cc| ctor_starts_with_super_or_this(cc) else false;
                    if (!child_explicit and class_has_no_arg_ctor(parent_decl)) {
                        try self.run_constructor(parent_decl, instance, &.{});
                    }
                }
            }

            // Execute own constructor
            try self.run_constructor(class_decl, instance, eval_args.items);

            return Value{ .object = instance };
        }

        // Any type ending with "Exception" that wasn't found as a user class
        // should still be an ObjectInstance (not SObject)
        if (std.mem.endsWith(u8, type_name, "Exception")) {
            const instance = try self.arena.create(types.ObjectInstance);
            instance.* = .{ .class_name = type_name };
            if (ne.args.len > 0) {
                var arg_copy = ne.args[0];
                const msg_val = try self.eval_expr(&arg_copy, current_env);
                try instance.fields.put(self.arena, "message", msg_val);
            }
            return Value{ .object = instance };
        }

        return Value{ .sobject = obj };
    }

    // -----------------------------------------------------------------------
    // フィールドアクセス
    // -----------------------------------------------------------------------

    /// Handle nested chains rooted at `ApexPages.Severity.X`, `Schema.SObjectType.X`,
    /// `Schema.X.SObjectType`, or `Schema.X.Y` (returning an SObjectField token).
    fn fa_try_apexpages_schema_nested(
        self: *Evaluator,
        fa: *ast.FieldAccess,
    ) anyerror!?Value {
        if (fa.object.* != .field_access) return null;
        const inner_fa = fa.object.field_access;
        if (inner_fa.object.* != .identifier) return null;

        if (std.ascii.eqlIgnoreCase(inner_fa.object.identifier.name, "ApexPages") and
            std.ascii.eqlIgnoreCase(inner_fa.field, "Severity"))
        {
            return Value{ .string = fa.field };
        }
        if (!std.ascii.eqlIgnoreCase(inner_fa.object.identifier.name, "Schema")) return null;

        if (std.ascii.eqlIgnoreCase(inner_fa.field, "sObjectType") or
            std.ascii.eqlIgnoreCase(inner_fa.field, "SObjectType"))
        {
            return try self.make_sobject_type_token(fa.field);
        }
        if (std.ascii.eqlIgnoreCase(fa.field, "SObjectType")) {
            return try self.make_sobject_type_token(inner_fa.field);
        }
        if (!std.ascii.eqlIgnoreCase(fa.field, "class")) {
            return try self.make_s_object_field_token(inner_fa.field, fa.field);
        }
        return null;
    }

    /// Handle identifiers of the form `Schema.X` whose `.Y` access resolves
    /// to an SObjectType/SObjectField token.
    fn fa_try_schema_prefix_identifier(
        self: *Evaluator,
        fa: *ast.FieldAccess,
    ) anyerror!?Value {
        if (fa.object.* != .identifier) return null;
        const ident = fa.object.identifier.name;
        if (!std.mem.startsWith(u8, ident, "Schema.")) return null;
        const schema_name = ident["Schema.".len..];
        if (std.ascii.eqlIgnoreCase(schema_name, "SObjectType")) {
            return try self.make_sobject_type_token(fa.field);
        }
        if (std.ascii.eqlIgnoreCase(fa.field, "SObjectType")) {
            return try self.make_sobject_type_token(schema_name);
        }
        if (!std.ascii.eqlIgnoreCase(fa.field, "class")) {
            return try self.make_s_object_field_token(schema_name, fa.field);
        }
        return null;
    }

    /// Global `SObjectType.X` shortcut → Schema.SObjectType { name: X }.
    fn fa_try_sobjecttype_shortcut(
        self: *Evaluator,
        fa: *ast.FieldAccess,
    ) anyerror!?Value {
        if (fa.object.* != .identifier) return null;
        if (!std.ascii.eqlIgnoreCase(fa.object.identifier.name, "SObjectType")) return null;
        return try self.make_sobject_type_token(fa.field);
    }

    /// `System.Search` → a Search proxy object.
    fn fa_try_system_search(self: *Evaluator, fa: *ast.FieldAccess) anyerror!?Value {
        if (fa.object.* != .identifier) return null;
        if (!std.ascii.eqlIgnoreCase(fa.object.identifier.name, "System")) return null;
        if (!std.ascii.eqlIgnoreCase(fa.field, "Search")) return null;
        const search = try self.arena.create(types.ObjectInstance);
        search.* = .{ .class_name = "Search" };
        return Value{ .object = search };
    }

    /// `System.Label.X` / `Label.X` → fallback label name string when metadata
    /// is unavailable.
    fn fa_try_label_identifier(self: *Evaluator, fa: *ast.FieldAccess) anyerror!?Value {
        if (fa.object.* == .field_access) {
            const inner = fa.object.field_access;
            const is_system_label = inner.object.* == .identifier and
                ((std.ascii.eqlIgnoreCase(inner.object.identifier.name, "System") and
                    std.ascii.eqlIgnoreCase(inner.field, "Label")) or
                    std.ascii.eqlIgnoreCase(inner.object.identifier.name, "Label"));
            if (is_system_label) {
                return Value{ .string = try self.arena.dupe(u8, fa.field) };
            }
        }
        if (fa.object.* == .identifier and
            std.ascii.eqlIgnoreCase(fa.object.identifier.name, "Label"))
        {
            return Value{ .string = try self.arena.dupe(u8, fa.field) };
        }
        return null;
    }

    fn make_sobject_type_token(self: *Evaluator, name: []const u8) anyerror!Value {
        const sot = try self.arena.create(types.ObjectInstance);
        sot.* = .{ .class_name = "Schema.SObjectType" };
        try sot.fields.put(self.arena, "name", Value{ .string = name });
        return Value{ .object = sot };
    }

    /// List field access: auto-unwrap to the first SObject element (single-
    /// record SOQL pattern), expose `.size`, and raise QueryException on empty
    /// SOQL results.
    fn fa_list_access(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        list: *types.ListValue,
    ) anyerror!Value {
        if (list.items.items.len == 0 and fa.object.* == .soql) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "QueryException" };
            try exc.fields.put(
                self.arena,
                "message",
                Value{ .string = "List has no rows for assignment to SObject" },
            );
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        if (list.items.items.len > 0) {
            const first = list.items.items[0];
            if (first == .sobject) {
                return self.get_s_object_field_value_case_insensitive(
                    first.sobject,
                    fa.field,
                ) orelse Value.null_val;
            }
        }
        if (std.ascii.eqlIgnoreCase(fa.field, "size")) {
            return Value{ .integer = @intCast(list.items.items.len) };
        }
        return Value.null_val;
    }

    /// SObject field access: case-insensitive lookup, with SObjectException
    /// when the row was produced by stripInaccessible.
    fn fa_sobject_access(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        sobj: *types.SObject,
    ) anyerror!Value {
        if (self.get_s_object_field_value_case_insensitive(sobj, fa.field)) |v| return v;
        if (sobj.is_stripped) {
            const exc = try self.arena.create(types.ObjectInstance);
            exc.* = .{ .class_name = "SObjectException" };
            try exc.fields.put(self.arena, "message", Value{ .string = "SObject row was retrieved via SOQL without querying the requested field: " });
            self.pending_exception = Value{ .object = exc };
            return error.ApexException;
        }
        return Value.null_val;
    }

    /// ObjectInstance field access. Checks property getters first, then
    /// built-in proxy types (Schema.SObjectType / FieldDescribeMap /
    /// DescribeSObjectResult), and finally a case-insensitive field lookup.
    fn fa_object_instance_access(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        inst: *types.ObjectInstance,
    ) anyerror!Value {
        if (try self.fa_try_property_getter(fa, inst)) |v| return v;
        if (try self.fa_try_schema_proxy_access(fa, inst)) |v| return v;

        // Case-insensitive field lookup (no custom getter found).
        for (inst.fields.keys(), inst.fields.values()) |k, v| {
            if (std.ascii.eqlIgnoreCase(k, fa.field)) return v;
        }
        return Value.null_val;
    }

    /// Property getter chain (walks up the class hierarchy). Returns null when
    /// no matching field_decl defines a getter.
    fn fa_try_property_getter(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        inst: *types.ObjectInstance,
    ) anyerror!?Value {
        const cd = self.find_class(inst.class_name) orelse return null;
        var cur_cd: ?*ast.ClassDecl = cd;
        while (cur_cd) |ccd| {
            for (ccd.members) |member| {
                switch (member) {
                    .field_decl => |fd| {
                        if (!std.ascii.eqlIgnoreCase(fd.name, fa.field)) continue;
                        const getter = fd.getter_body orelse continue;
                        return try self.invoke_property_getter_inline(fa, inst, cd, ccd, fd, getter);
                    },
                    else => {},
                }
            }
            cur_cd = if (ccd.super_class) |sc| self.find_class(sc.name) else null;
        }
        return null;
    }

    /// Execute a property getter body with `this` bound to the instance. When
    /// we are already inside this property's own getter (self-reference), fall
    /// back to reading the backing field directly.
    fn invoke_property_getter_inline(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        inst: *types.ObjectInstance,
        owner_cd: *ast.ClassDecl,
        declaring_cd: *ast.ClassDecl,
        fd: *ast.FieldDecl,
        getter: []ast.Stmt,
    ) anyerror!Value {
        if (self.evaluating_getter) |eg| {
            if (std.ascii.eqlIgnoreCase(eg, fd.name)) {
                if (fd.modifiers.is_static) {
                    return self.read_static_backing_value(declaring_cd.name, fd.name);
                }
                if (inst.fields.get(fa.field)) |fv| return fv;
                for (inst.fields.keys(), inst.fields.values()) |fk, fv| {
                    if (std.ascii.eqlIgnoreCase(fk, fa.field)) return fv;
                }
                return .null_val;
            }
        }
        const getter_env = self.global_env.child() catch return Value.null_val;
        getter_env.define("this", Value{ .object = inst }) catch {};
        // Load instance fields as local variables, but SKIP fields that have
        // their own getter (so this.field inside THIS getter still chains
        // through to the property getter).
        for (inst.fields.keys(), inst.fields.values()) |fk, fv| {
            const skip = !std.ascii.eqlIgnoreCase(fk, fd.name) and
                fa_field_has_getter(self, owner_cd, fk);
            if (!skip) {
                getter_env.set(fk, fv) catch {
                    getter_env.define(fk, fv) catch {};
                };
            }
        }
        const saved_class = self.current_class;
        const saved_getter = self.evaluating_getter;
        self.current_class = declaring_cd.name;
        self.evaluating_getter = fd.name;
        defer {
            self.current_class = saved_class;
            self.evaluating_getter = saved_getter;
        }

        const result = self.exec_block(getter, getter_env) catch |err| {
            if (err == error.StackOverflow) return Value.null_val;
            return err;
        };
        return switch (result) {
            .return_val => |v| v,
            else => self.return_value,
        };
    }

    /// Walk `cd` and its parents to check whether any field_decl with the
    /// given name declares a getter_body.
    fn fa_field_has_getter(self: *Evaluator, cd: *ast.ClassDecl, name: []const u8) bool {
        var check_cd: ?*ast.ClassDecl = cd;
        while (check_cd) |ccd2| {
            for (ccd2.members) |m2| {
                switch (m2) {
                    .field_decl => |fd2| {
                        if (std.ascii.eqlIgnoreCase(fd2.name, name) and
                            fd2.getter_body != null) return true;
                    },
                    else => {},
                }
            }
            check_cd = if (ccd2.super_class) |sc| self.find_class(sc.name) else null;
        }
        return false;
    }

    /// Schema.SObjectTypeNamespace / Schema.SObjectType / FieldDescribeMap /
    /// DescribeSObjectResult proxy field access. Returns null when the object
    /// is not one of the recognised proxy classes.
    fn fa_try_schema_proxy_access(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        inst: *types.ObjectInstance,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(inst.class_name, "Schema.SObjectTypeNamespace")) {
            return try self.make_sobject_type_token(fa.field);
        }
        if (std.ascii.eqlIgnoreCase(inst.class_name, "Schema.SObjectType") and
            std.ascii.eqlIgnoreCase(fa.field, "fieldSets"))
        {
            return try self.fa_build_field_set_collection(inst);
        }
        if (std.ascii.eqlIgnoreCase(inst.class_name, "Schema.SObjectType") and
            std.ascii.eqlIgnoreCase(fa.field, "fields"))
        {
            if (inst.fields.get("fields")) |existing| return existing;
            const object_name = fa_object_name_or_sobject(inst);
            var ctx = builtins.BuiltinContext{
                .arena = self.arena,
                .stdout = &self.stdout,
                .pending_exception = &self.pending_exception,
                .see_all_data = self.see_all_data,
                .eval = self,
            };
            const fv = try builtins.create_field_describe_map_value(&ctx, object_name);
            try inst.fields.put(self.arena, "fields", fv);
            return fv;
        }
        if (std.ascii.eqlIgnoreCase(inst.class_name, "FieldDescribeMap")) {
            if (std.ascii.eqlIgnoreCase(fa.field, "map")) {
                if (inst.fields.get("map")) |m| return m;
            }
            if (inst.fields.get("owner")) |owner_val| {
                if (owner_val == .string) {
                    return try self.make_s_object_field_token(owner_val.string, fa.field);
                }
            }
            return null;
        }
        if ((std.ascii.eqlIgnoreCase(inst.class_name, "DescribeSObjectResult") or
            std.ascii.eqlIgnoreCase(inst.class_name, "Schema.DescribeSObjectResult")) and
            std.ascii.eqlIgnoreCase(fa.field, "fieldSets"))
        {
            return try self.fa_build_field_set_collection(inst);
        }
        return null;
    }

    fn fa_build_field_set_collection(
        self: *Evaluator,
        inst: *types.ObjectInstance,
    ) anyerror!Value {
        if (inst.fields.get("fieldSets")) |field_sets| return field_sets;
        const object_name = fa_object_name_or_sobject(inst);
        const field_sets = try builtins.create_field_set_collection_value(
            self.arena,
            self,
            object_name,
        );
        try inst.fields.put(self.arena, "fieldSets", field_sets);
        return field_sets;
    }

    fn fa_object_name_or_sobject(inst: *types.ObjectInstance) []const u8 {
        if (inst.fields.get("name")) |name_val| {
            if (name_val == .string) return name_val.string;
        }
        return "SObject";
    }

    /// String field access: Schema enum/token handling, `.length`, and
    /// enum-name-to-value lookup. Returns null when no rule matches (caller
    /// continues with other dispatch branches).
    fn fa_string_access(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        s: []const u8,
    ) anyerror!?Value {
        if (fa.object.* == .field_access) {
            const inner_fa = fa.object.field_access;
            if (inner_fa.object.* == .identifier and
                std.ascii.eqlIgnoreCase(inner_fa.object.identifier.name, "Schema"))
            {
                if (is_known_schema_enum_type(inner_fa.field)) {
                    return Value{ .string = fa.field };
                }
                return try self.make_s_object_field_token(s, fa.field);
            }
        }
        if (fa.object.* == .identifier and
            std.mem.startsWith(u8, fa.object.identifier.name, "Schema."))
        {
            const schema_name = fa.object.identifier.name["Schema.".len..];
            if (is_known_schema_enum_type(schema_name)) {
                return Value{ .string = fa.field };
            }
            if (std.ascii.eqlIgnoreCase(schema_name, "SObjectType")) {
                return try self.make_sobject_type_token(fa.field);
            }
            return try self.make_s_object_field_token(schema_name, fa.field);
        }
        if (std.ascii.eqlIgnoreCase(fa.field, "length")) {
            return Value{ .integer = @intCast(s.len) };
        }
        // Enum value pattern: when obj is an enum name (from ClassName.EnumName),
        // field access returns the enum value string (e.g., HttpVerb.GET → "GET").
        var enum_iter = self.classes.iterator();
        while (enum_iter.next()) |entry| {
            for (entry.value_ptr.*.members) |member| {
                switch (member) {
                    .enum_decl => |ed| {
                        if (std.ascii.eqlIgnoreCase(ed.name, s)) {
                            return Value{ .string = fa.field };
                        }
                    },
                    else => {},
                }
            }
        }
        return null;
    }

    /// Resolve `staticBase.identifier.X` where `staticBase` is a static field
    /// of the current class (or its outer class). Returns null when no
    /// matching chain resolves.
    fn fa_try_null_with_static_base(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        obj: Value,
        current_env: *Env,
    ) anyerror!?Value {
        if (obj != .null_val) return null;
        if (fa.object.* != .identifier) return null;
        const base_name = fa.object.identifier.name;
        const cc = self.current_class orelse return null;
        if (self.resolve_static_field_value_on_class(cc, base_name)) |base| {
            if (base != .null_val) return try self.eval_field_access_on_resolved_value(
                base,
                fa.field,
                current_env,
            );
        }
        if (self.find_outer_class_name(cc)) |outer| {
            if (self.resolve_static_field_value_on_class(outer, base_name)) |base| {
                if (base != .null_val) return try self.eval_field_access_on_resolved_value(
                    base,
                    fa.field,
                    current_env,
                );
            }
        }
        return null;
    }

    /// Static field access of the form `ClassName.field`. Handles Schema
    /// prefixes, Date.today(), enum-like singletons (AccessLevel/AccessType),
    /// RestContext, SObjectType / .class, Trigger context, and user-defined
    /// class/enum lookups.
    fn fa_try_static_class_access(
        self: *Evaluator,
        fa: *ast.FieldAccess,
    ) anyerror!?Value {
        if (fa.object.* != .identifier) return null;
        const class_name = fa.object.identifier.name;
        self.ensure_static_init(class_name);

        if (try self.fa_try_schema_qualified_static(class_name, fa.field)) |v| return v;
        if (try self.fa_try_date_today_static(class_name, fa.field)) |v| return v;
        if (fa_try_access_level_enum_static(class_name, fa.field)) |v| return v;
        if (try self.fa_try_rest_context_static(class_name, fa.field)) |v| return v;
        if (try self.fa_try_sobject_type_literal(class_name, fa.field)) |v| return v;
        if (try self.fa_try_class_literal_from_identifier(class_name, fa.field)) |v| return v;
        if (self.is_s_object_type_name(class_name)) {
            return try self.make_s_object_field_token(class_name, fa.field);
        }
        if (std.ascii.eqlIgnoreCase(class_name, "Trigger")) {
            return try self.fa_trigger_context_field(fa.field);
        }
        if (try self.fa_try_global_enum_match(class_name, fa.field)) |v| return v;
        if (try self.fa_try_class_member_static(class_name, fa.field)) |v| return v;

        // General enum value pattern — any ClassName.CONSTANT_NAME
        const key = try std.fmt.allocPrint(self.arena, "{s}.{s}", .{ class_name, fa.field });
        if (self.global_env.get(key)) |v| return v;

        // If it looks like an enum constant (all upper case or known pattern), return as string.
        return Value{ .string = fa.field };
    }

    fn fa_try_schema_qualified_static(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) anyerror!?Value {
        if (!std.mem.startsWith(u8, class_name, "Schema.")) return null;
        const schema_name = class_name["Schema.".len..];
        if (is_known_schema_enum_type(schema_name)) {
            return Value{ .string = field_name };
        }
        if (std.ascii.eqlIgnoreCase(schema_name, "SObjectType")) {
            return try self.make_sobject_type_token(field_name);
        }
        if (std.ascii.eqlIgnoreCase(field_name, "SObjectType")) {
            return try self.make_sobject_type_token(schema_name);
        }
        if (!std.ascii.eqlIgnoreCase(field_name, "class")) {
            return try self.make_s_object_field_token(schema_name, field_name);
        }
        return null;
    }

    fn fa_try_date_today_static(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) anyerror!?Value {
        if (!std.ascii.eqlIgnoreCase(class_name, "Date")) return null;
        if (!std.ascii.eqlIgnoreCase(field_name, "today")) return null;
        return try builtins.make_date_value(
            self.arena,
            try builtins.current_date_string(self.arena),
        );
    }

    fn fa_try_access_level_enum_static(class_name: []const u8, field_name: []const u8) ?Value {
        if (std.ascii.eqlIgnoreCase(class_name, "AccessLevel") or
            std.ascii.eqlIgnoreCase(class_name, "AccessType") or
            std.ascii.eqlIgnoreCase(class_name, "ApexPages.Severity"))
        {
            return Value{ .string = field_name };
        }
        return null;
    }

    fn fa_try_rest_context_static(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) anyerror!?Value {
        if (!std.ascii.eqlIgnoreCase(class_name, "RestContext")) return null;
        if (std.ascii.eqlIgnoreCase(field_name, "request")) {
            const key = try std.fmt.allocPrint(self.arena, "RestContext.request", .{});
            if (self.global_env.get(key)) |existing| return existing;
            const req = try self.arena.create(types.ObjectInstance);
            req.* = .{ .class_name = "RestRequest" };
            try req.fields.put(
                self.arena,
                "requestURI",
                Value{ .string = "/services/apexrest/test" },
            );
            try req.fields.put(self.arena, "httpMethod", Value{ .string = "GET" });
            const blob = try self.arena.create(types.ObjectInstance);
            blob.* = .{ .class_name = "Blob" };
            try blob.fields.put(self.arena, "value", Value.null_val);
            try req.fields.put(self.arena, "requestBody", Value{ .object = blob });
            const params = try self.arena.create(types.MapValue);
            params.* = .{};
            try req.fields.put(self.arena, "params", Value{ .map = params });
            const headers = try self.arena.create(types.MapValue);
            headers.* = .{};
            try req.fields.put(self.arena, "headers", Value{ .map = headers });
            const value = Value{ .object = req };
            try self.global_env.define(key, value);
            return value;
        }
        if (std.ascii.eqlIgnoreCase(field_name, "response")) {
            const key = try std.fmt.allocPrint(self.arena, "RestContext.response", .{});
            if (self.global_env.get(key)) |existing| return existing;
            const resp = try self.arena.create(types.ObjectInstance);
            resp.* = .{ .class_name = "RestResponse" };
            const blob = try self.arena.create(types.ObjectInstance);
            blob.* = .{ .class_name = "Blob" };
            try blob.fields.put(self.arena, "value", Value{ .string = "" });
            try resp.fields.put(self.arena, "responseBody", Value{ .object = blob });
            const headers = try self.arena.create(types.MapValue);
            headers.* = .{};
            try resp.fields.put(self.arena, "headers", Value{ .map = headers });
            const value = Value{ .object = resp };
            try self.global_env.define(key, value);
            return value;
        }
        return null;
    }

    fn fa_try_sobject_type_literal(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) anyerror!?Value {
        if (!std.ascii.eqlIgnoreCase(field_name, "SObjectType")) return null;
        if (std.ascii.eqlIgnoreCase(class_name, "Schema")) {
            const ns = try self.arena.create(types.ObjectInstance);
            ns.* = .{ .class_name = "Schema.SObjectTypeNamespace" };
            return Value{ .object = ns };
        }
        return try self.make_sobject_type_token(class_name);
    }

    fn fa_try_class_literal_from_identifier(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) anyerror!?Value {
        if (!std.ascii.eqlIgnoreCase(field_name, "class")) return null;
        const type_obj = try self.arena.create(types.ObjectInstance);
        type_obj.* = .{ .class_name = "Type" };
        // For inner classes, return the FQ name (e.g., "OuterClass.InnerClass").
        // Prefer current_class as the outer qualifier when the inner class exists
        // there (avoids picking a same-named inner from a different outer class).
        const fq_name: []const u8 = if (self.current_class) |cc| blk: {
            if (std.mem.indexOfScalar(u8, class_name, '.') == null) {
                const fq = std.fmt.allocPrint(
                    self.arena,
                    "{s}.{s}",
                    .{ cc, class_name },
                ) catch class_name;
                if (self.find_class(fq) != null) break :blk fq;
            }
            break :blk self.resolve_full_class_name(class_name);
        } else self.resolve_full_class_name(class_name);
        try type_obj.fields.put(self.arena, "name", Value{ .string = fq_name });
        return Value{ .object = type_obj };
    }

    fn fa_trigger_context_field(self: *Evaluator, field_name: []const u8) anyerror!Value {
        if (self.trigger_context) |tc| {
            if (std.ascii.eqlIgnoreCase(field_name, "new"))
                return tc.new_list orelse Value.null_val;
            if (std.ascii.eqlIgnoreCase(field_name, "old"))
                return tc.old_list orelse Value.null_val;
            if (std.ascii.eqlIgnoreCase(field_name, "newMap"))
                return tc.new_map orelse Value.null_val;
            if (std.ascii.eqlIgnoreCase(field_name, "oldMap"))
                return tc.old_map orelse Value.null_val;
            if (std.ascii.eqlIgnoreCase(field_name, "isBefore"))
                return Value{ .boolean = tc.is_before };
            if (std.ascii.eqlIgnoreCase(field_name, "isAfter"))
                return Value{ .boolean = tc.is_after };
            if (std.ascii.eqlIgnoreCase(field_name, "isInsert"))
                return Value{ .boolean = tc.is_insert };
            if (std.ascii.eqlIgnoreCase(field_name, "isUpdate"))
                return Value{ .boolean = tc.is_update };
            if (std.ascii.eqlIgnoreCase(field_name, "isDelete"))
                return Value{ .boolean = tc.is_delete };
            if (std.ascii.eqlIgnoreCase(field_name, "isUndelete"))
                return Value{ .boolean = tc.is_undelete };
            if (std.ascii.eqlIgnoreCase(field_name, "isExecuting"))
                return Value{ .boolean = tc.is_executing };
            if (std.ascii.eqlIgnoreCase(field_name, "size"))
                return Value{ .integer = tc.size };
            if (std.ascii.eqlIgnoreCase(field_name, "operationType")) {
                return if (tc.operation_type) |ot| Value{ .string = ot } else Value.null_val;
            }
            return Value.null_val;
        }
        // No active trigger: defer to globally-set values / defaults.
        if (std.ascii.eqlIgnoreCase(field_name, "new") or
            std.ascii.eqlIgnoreCase(field_name, "old") or
            std.ascii.eqlIgnoreCase(field_name, "newMap") or
            std.ascii.eqlIgnoreCase(field_name, "oldMap"))
        {
            const key = try std.fmt.allocPrint(self.arena, "Trigger.{s}", .{field_name});
            if (self.global_env.get(key)) |v| return v;
            return Value.null_val;
        }
        if (std.ascii.eqlIgnoreCase(field_name, "isBefore") or
            std.ascii.eqlIgnoreCase(field_name, "isAfter") or
            std.ascii.eqlIgnoreCase(field_name, "isInsert") or
            std.ascii.eqlIgnoreCase(field_name, "isUpdate") or
            std.ascii.eqlIgnoreCase(field_name, "isDelete") or
            std.ascii.eqlIgnoreCase(field_name, "isUndelete") or
            std.ascii.eqlIgnoreCase(field_name, "isExecuting"))
        {
            return Value{ .boolean = false };
        }
        if (std.ascii.eqlIgnoreCase(field_name, "size")) return Value{ .integer = 0 };
        return Value.null_val;
    }

    /// Enum class match scan: if any loaded class declares an enum whose name
    /// matches `class_name`, the access returns the enum value string.
    fn fa_try_global_enum_match(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) anyerror!?Value {
        var class_iter = self.classes.iterator();
        while (class_iter.next()) |entry| {
            for (entry.value_ptr.*.members) |member| {
                switch (member) {
                    .enum_decl => |ed| {
                        if (std.ascii.eqlIgnoreCase(ed.name, class_name)) {
                            return Value{ .string = field_name };
                        }
                    },
                    else => {},
                }
            }
        }
        return null;
    }

    /// Static members lookup on a specific class: enum/static field/inner
    /// class/inner interface.
    fn fa_try_class_member_static(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) anyerror!?Value {
        const cd = self.find_class(class_name) orelse return null;
        for (cd.members) |member| {
            switch (member) {
                .enum_decl => |ed| {
                    if (std.ascii.eqlIgnoreCase(ed.name, field_name)) {
                        // Return the enum name as a string; ClassName.EnumName.VALUE
                        // patterns are resolved by a subsequent field_access matching
                        // the enum name through fa_try_global_enum_match.
                        return Value{ .string = field_name };
                    }
                },
                .field_decl => |fd| {
                    if (!std.ascii.eqlIgnoreCase(fd.name, field_name)) continue;
                    if (!fd.modifiers.is_static) continue;
                    return try self.fa_read_static_field(class_name, fd, field_name);
                },
                .class_decl => |inner_cd| {
                    if (std.ascii.eqlIgnoreCase(inner_cd.name, field_name)) {
                        return Value{ .string = try std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ class_name, inner_cd.name },
                        ) };
                    }
                },
                .interface_decl => |inner_iface| {
                    if (std.ascii.eqlIgnoreCase(inner_iface.name, field_name)) {
                        return Value{ .string = try std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ class_name, inner_iface.name },
                        ) };
                    }
                },
                else => {},
            }
        }
        return null;
    }

    /// Read a static field value: run the getter body if present (and not
    /// already inside it), otherwise fall back to the global static store.
    fn fa_read_static_field(
        self: *Evaluator,
        class_name: []const u8,
        fd: *ast.FieldDecl,
        field_name: []const u8,
    ) anyerror!Value {
        if (fd.getter_body) |getter_body| {
            const already_in = if (self.evaluating_getter) |eg|
                std.ascii.eqlIgnoreCase(eg, field_name)
            else
                false;
            if (!already_in) {
                const getter_env = self.global_env.child() catch return Value.null_val;
                const saved_class = self.current_class;
                const saved_getter = self.evaluating_getter;
                self.current_class = class_name;
                self.evaluating_getter = field_name;
                defer {
                    self.current_class = saved_class;
                    self.evaluating_getter = saved_getter;
                }

                const result = self.exec_block(getter_body, getter_env) catch
                    return Value.null_val;
                return switch (result) {
                    .return_val => |v| v,
                    else => self.return_value,
                };
            }
        }
        const skey = std.fmt.allocPrint(
            self.arena,
            "{s}.{s}",
            .{ class_name, field_name },
        ) catch return Value.null_val;
        return self.global_env.get(skey) orelse Value.null_val;
    }

    /// Nested static access chain: `Outer.Inner.X` where the object operand
    /// is itself a `field_access`. Handles inner enums/classes/interfaces,
    /// common System.* pseudo-enums, and Schema.* variants.
    fn fa_try_nested_static_access(
        self: *Evaluator,
        fa: *ast.FieldAccess,
    ) anyerror!?Value {
        if (fa.object.* != .field_access) return null;
        const inner_fa = fa.object.field_access;
        if (inner_fa.object.* != .identifier) return null;
        const outer_name = inner_fa.object.identifier.name;
        const inner_name = inner_fa.field;

        if (try self.fa_nested_in_user_class(fa, outer_name, inner_name)) |v| return v;
        if (try self.fa_nested_in_system_or_schema(fa, outer_name, inner_name)) |v| return v;
        return null;
    }

    /// Handle the `Outer.Inner.X` chain where `Outer` resolves to a user class.
    fn fa_nested_in_user_class(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        outer_name: []const u8,
        inner_name: []const u8,
    ) anyerror!?Value {
        const cd = self.find_class(outer_name) orelse return null;
        for (cd.members) |member| {
            switch (member) {
                .enum_decl => |ed| {
                    if (std.ascii.eqlIgnoreCase(ed.name, inner_name)) {
                        return Value{ .string = fa.field };
                    }
                },
                .class_decl => |inner_cd| {
                    if (!std.ascii.eqlIgnoreCase(inner_cd.name, inner_name)) continue;
                    if (std.ascii.eqlIgnoreCase(fa.field, "class")) {
                        return try self.fa_make_type_object_fq(outer_name, inner_cd.name);
                    }
                    const fq_inner_name = try std.fmt.allocPrint(
                        self.arena,
                        "{s}.{s}",
                        .{ outer_name, inner_cd.name },
                    );
                    const static_key = try std.fmt.allocPrint(
                        self.arena,
                        "{s}.{s}",
                        .{ fq_inner_name, fa.field },
                    );
                    if (self.global_env.get(static_key)) |v| return v;
                    return Value{ .string = fa.field };
                },
                .interface_decl => |inner_iface| {
                    if (std.ascii.eqlIgnoreCase(inner_iface.name, inner_name) and
                        std.ascii.eqlIgnoreCase(fa.field, "class"))
                    {
                        return try self.fa_make_type_object_fq(outer_name, inner_iface.name);
                    }
                },
                else => {},
            }
        }
        return null;
    }

    /// Handle `System.<Enum>.X` and `Schema.<X>.Y` shortcuts.
    fn fa_nested_in_system_or_schema(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        outer_name: []const u8,
        inner_name: []const u8,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(outer_name, "System") and
            (std.ascii.eqlIgnoreCase(inner_name, "AccessType") or
                std.ascii.eqlIgnoreCase(inner_name, "AccessLevel") or
                std.ascii.eqlIgnoreCase(inner_name, "Quiddity") or
                std.ascii.eqlIgnoreCase(inner_name, "TriggerOperation") or
                std.ascii.eqlIgnoreCase(inner_name, "LoggingLevel") or
                std.ascii.eqlIgnoreCase(inner_name, "StatusCode")))
        {
            return Value{ .string = fa.field };
        }
        if (std.ascii.eqlIgnoreCase(fa.field, "class") and
            std.ascii.eqlIgnoreCase(outer_name, "System"))
        {
            return try self.fa_make_type_object_fq("System", inner_name);
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "Schema") and
            std.ascii.eqlIgnoreCase(inner_name, "SObjectType"))
        {
            return try self.make_sobject_type_token(fa.field);
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "Schema") and
            is_known_schema_enum_type(inner_name))
        {
            return Value{ .string = fa.field };
        }
        if (std.ascii.eqlIgnoreCase(outer_name, "Schema")) {
            return try self.make_s_object_field_token(inner_name, fa.field);
        }
        return null;
    }

    fn fa_make_type_object_fq(
        self: *Evaluator,
        outer: []const u8,
        inner: []const u8,
    ) anyerror!Value {
        const type_obj = try self.arena.create(types.ObjectInstance);
        type_obj.* = .{ .class_name = "Type" };
        const fq_name = try std.fmt.allocPrint(self.arena, "{s}.{s}", .{ outer, inner });
        try type_obj.fields.put(self.arena, "name", Value{ .string = fq_name });
        return Value{ .object = type_obj };
    }

    /// `.class` literal variants: multi-level dotted chain (A.B.C.class),
    /// single-identifier (ClassName.class), and string-named outer
    /// (OuterClass.InnerClass.class produced via a string value).
    fn fa_try_class_literal(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        obj: Value,
    ) anyerror!?Value {
        if (std.ascii.eqlIgnoreCase(fa.field, "class") and fa.object.* == .field_access) {
            if (self.collect_dotted_identifier_chain(fa.object)) |chain| {
                const display_name: []const u8 = blk: {
                    if (std.ascii.startsWithIgnoreCase(chain, "Flow.Interview.")) {
                        const leaf = chain["Flow.Interview.".len..];
                        if (leaf.len > 0 and std.mem.indexOfScalar(u8, leaf, '.') == null) {
                            if (self.find_class(leaf) == null) break :blk "Flow.Interview";
                        }
                    }
                    break :blk chain;
                };
                const type_obj = try self.arena.create(types.ObjectInstance);
                type_obj.* = .{ .class_name = "Type" };
                try type_obj.fields.put(self.arena, "name", Value{ .string = display_name });
                return Value{ .object = type_obj };
            }
        }
        if (fa.object.* == .identifier and std.ascii.eqlIgnoreCase(fa.field, "class")) {
            return try self.fa_class_literal_from_simple(fa.object.identifier.name);
        }
        if (obj == .string and std.ascii.eqlIgnoreCase(fa.field, "class")) {
            return try self.fa_class_literal_from_simple(obj.string);
        }
        return null;
    }

    fn fa_class_literal_from_simple(
        self: *Evaluator,
        simple_name: []const u8,
    ) anyerror!Value {
        const type_name: []const u8 = if (self.current_class) |cc| blk: {
            const fq = std.fmt.allocPrint(
                self.arena,
                "{s}.{s}",
                .{ cc, simple_name },
            ) catch simple_name;
            break :blk if (self.find_class(fq) != null)
                fq
            else
                self.resolve_full_class_name(simple_name);
        } else self.resolve_full_class_name(simple_name);
        const type_obj = try self.arena.create(types.ObjectInstance);
        type_obj.* = .{ .class_name = "Type" };
        try type_obj.fields.put(self.arena, "name", Value{ .string = type_name });
        return Value{ .object = type_obj };
    }

    fn eval_field_access(
        self: *Evaluator,
        fa: *ast.FieldAccess,
        obj: Value,
        current_env: *Env,
    ) !Value {
        if (try self.fa_try_apexpages_schema_nested(fa)) |v| return v;
        if (try self.fa_try_schema_prefix_identifier(fa)) |v| return v;
        if (try self.fa_try_sobjecttype_shortcut(fa)) |v| return v;
        if (try self.fa_try_system_search(fa)) |v| return v;
        if (try self.fa_try_label_identifier(fa)) |v| return v;
        if (obj == .list) return try self.fa_list_access(fa, obj.list);
        if (obj == .sobject) return try self.fa_sobject_access(fa, obj.sobject);
        if (obj == .object) return try self.fa_object_instance_access(fa, obj.object);
        if (obj == .string) {
            if (try self.fa_string_access(fa, obj.string)) |v| return v;
        }
        if (try self.fa_try_null_with_static_base(fa, obj, current_env)) |v| return v;
        if (try self.fa_try_static_class_access(fa)) |v| return v;
        if (try self.fa_try_nested_static_access(fa)) |v| return v;
        if (try self.fa_try_class_literal(fa, obj)) |v| return v;
        return Value.null_val;
    }

    fn eval_field_access_on_resolved_value(
        self: *Evaluator,
        obj: Value,
        field_name: []const u8,
        current_env: *Env,
    ) !Value {
        const placeholder_expr = try self.arena.create(ast.Expr);
        placeholder_expr.* = .null_literal;
        const synthetic_fa = try self.arena.create(ast.FieldAccess);
        synthetic_fa.* = .{ .object = placeholder_expr, .field = field_name, .null_safe = false };
        return self.eval_field_access(synthetic_fa, obj, current_env);
    }

    /// expr が `Identifier.Field.Field...` の形で全てドット連結のパスになっている場合、
    /// そのパスを `A.B.C` の形式で返す。非ドット式が混ざっていれば null を返す。
    fn collect_dotted_identifier_chain(self: *Evaluator, expr: *const ast.Expr) ?[]const u8 {
        var parts: std.ArrayListUnmanaged([]const u8) = .empty;
        defer parts.deinit(self.arena);

        var cur: *const ast.Expr = expr;
        while (true) {
            switch (cur.*) {
                .identifier => |id| {
                    parts.append(self.arena, id.name) catch return null;
                    break;
                },
                .field_access => |fa| {
                    parts.append(self.arena, fa.field) catch return null;
                    cur = fa.object;
                },
                else => return null,
            }
        }
        // Reverse: parts holds leaf-to-root, we want root-to-leaf.
        std.mem.reverse([]const u8, parts.items);
        // Compute total length
        var total: usize = 0;
        for (parts.items, 0..) |p, i| {
            if (i > 0) total += 1; // dot
            total += p.len;
        }
        const buf = self.arena.alloc(u8, total) catch return null;
        var idx: usize = 0;
        for (parts.items, 0..) |p, i| {
            if (i > 0) {
                buf[idx] = '.';
                idx += 1;
            }
            std.mem.copyForwards(u8, buf[idx..], p);
            idx += p.len;
        }
        return buf;
    }

    // -----------------------------------------------------------------------
    // Datetime ヘルパー
    // -----------------------------------------------------------------------

    /// 文字列が Date 形式 (YYYY-MM-DD, 10文字ちょうど) かどうかを判定する。
    fn is_date_only_format_string(s: []const u8) bool {
        if (s.len != 10) return false;
        if (s[4] != '-' or s[7] != '-') return false;
        _ = std.fmt.parseInt(i32, s[0..4], 10) catch return false;
        _ = std.fmt.parseInt(u8, s[5..7], 10) catch return false;
        _ = std.fmt.parseInt(u8, s[8..10], 10) catch return false;
        return true;
    }

    /// 文字列が DateTime 形式 (YYYY-MM-DDThh:mm:ss...) かどうかを判定する。
    fn is_date_time_format_string(s: []const u8) bool {
        if (s.len < 19) return false;
        if (s[4] != '-' or s[7] != '-' or s[10] != 'T') return false;
        _ = std.fmt.parseInt(i32, s[0..4], 10) catch return false;
        _ = std.fmt.parseInt(u8, s[5..7], 10) catch return false;
        _ = std.fmt.parseInt(u8, s[8..10], 10) catch return false;
        _ = std.fmt.parseInt(u8, s[11..13], 10) catch return false;
        _ = std.fmt.parseInt(u8, s[14..16], 10) catch return false;
        _ = std.fmt.parseInt(u8, s[17..19], 10) catch return false;
        return true;
    }

    fn is_salesforce_id_string(value: []const u8) bool {
        if (value.len != 15 and value.len != 18) return false;
        for (value) |ch| {
            if (!std.ascii.isAlphanumeric(ch)) return false;
        }
        return true;
    }

    /// instanceof チェック: Value がプリミティブ型名にマッチするか。
    fn instanceof_matches_primitive(val: Value, tn: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(tn, "Object")) return val != .null_val and val != .void_val;
        if (val == .integer) {
            return std.ascii.eqlIgnoreCase(tn, "Integer") or
                std.ascii.eqlIgnoreCase(tn, "Long") or
                std.ascii.eqlIgnoreCase(tn, "Decimal") or
                std.ascii.eqlIgnoreCase(tn, "Double") or
                std.ascii.eqlIgnoreCase(tn, "Number");
        }
        if (val == .long) {
            return std.ascii.eqlIgnoreCase(tn, "Long") or
                std.ascii.eqlIgnoreCase(tn, "Decimal") or
                std.ascii.eqlIgnoreCase(tn, "Double") or
                std.ascii.eqlIgnoreCase(tn, "Number");
        }
        if (val == .double) {
            return std.ascii.eqlIgnoreCase(tn, "Decimal") or
                std.ascii.eqlIgnoreCase(tn, "Double") or
                std.ascii.eqlIgnoreCase(tn, "Number");
        }
        if (val == .boolean) return std.ascii.eqlIgnoreCase(tn, "Boolean");
        if (val == .string) {
            return std.ascii.eqlIgnoreCase(tn, "String") or
                (std.ascii.eqlIgnoreCase(
                    tn,
                    "Id",
                ) and Evaluator.is_salesforce_id_string(val.string));
        }
        if (val == .sobject) {
            return std.ascii.eqlIgnoreCase(tn, "SObject") or
                std.ascii.eqlIgnoreCase(tn, "Sobject") or
                std.ascii.eqlIgnoreCase(tn, "sObject") or
                std.ascii.eqlIgnoreCase(tn, val.sobject.type_name);
        }
        if (val == .object) {
            const cn = val.object.class_name;
            if (cn.len > 0 and cn.len < 256) {
                if (std.ascii.eqlIgnoreCase(cn, "Date")) return std.ascii.eqlIgnoreCase(tn, "Date") or std.ascii.eqlIgnoreCase(tn, "DateTime") or std.ascii.eqlIgnoreCase(tn, "Datetime");
                if (std.ascii.eqlIgnoreCase(cn, "Datetime")) return std.ascii.eqlIgnoreCase(tn, "DateTime") or std.ascii.eqlIgnoreCase(tn, "Datetime");
                if (std.ascii.eqlIgnoreCase(cn, "Time")) return std.ascii.eqlIgnoreCase(tn, "Time");
                if (std.ascii.eqlIgnoreCase(cn, "Schema.SObjectField") or
                    std.ascii.eqlIgnoreCase(cn, "SObjectField"))
                {
                    return std.ascii.eqlIgnoreCase(
                        tn,
                        "Schema.SObjectField",
                    ) or std.ascii.eqlIgnoreCase(tn, "SObjectField");
                }
                if (std.ascii.eqlIgnoreCase(cn, "Schema.SObjectType")) {
                    return std.ascii.eqlIgnoreCase(
                        tn,
                        "Schema.SObjectType",
                    ) or std.ascii.eqlIgnoreCase(tn, "SObjectType");
                }
                if (std.ascii.eqlIgnoreCase(cn, "Schema.FieldSet")) {
                    return std.ascii.eqlIgnoreCase(
                        tn,
                        "Schema.FieldSet",
                    ) or std.ascii.eqlIgnoreCase(tn, "FieldSet");
                }
            }
        }
        return false;
    }

    /// child_class が parent_type のサブクラスかどうかを継承チェーンで確認する。
    fn is_subclass_of(self: *Evaluator, child_class: []const u8, parent_type: []const u8) bool {
        // Direct match
        if (std.ascii.eqlIgnoreCase(child_class, parent_type)) return true;
        // Check simple name match (inner class: "OuterClass.InnerClass" → "InnerClass")
        if (std.mem.lastIndexOfScalar(u8, child_class, '.')) |di| {
            if (std.ascii.eqlIgnoreCase(child_class[di + 1 ..], parent_type)) return true;
        }
        // Walk the inheritance chain
        var cd = self.find_class(child_class);
        var depth: u8 = 0;
        while (cd) |c| : (depth += 1) {
            if (depth > 20) break; // Safety limit
            if (c.super_class) |sc| {
                if (std.ascii.eqlIgnoreCase(sc.name, parent_type)) return true;
                if (std.mem.lastIndexOfScalar(u8, sc.name, '.')) |di| {
                    if (std.ascii.eqlIgnoreCase(sc.name[di + 1 ..], parent_type)) return true;
                }
                // Also check interfaces
                for (c.interfaces) |iface| {
                    if (std.ascii.eqlIgnoreCase(iface.name, parent_type)) return true;
                }
                cd = self.find_class(sc.name);
            } else {
                // Check interfaces at this level
                for (c.interfaces) |iface| {
                    if (std.ascii.eqlIgnoreCase(iface.name, parent_type)) return true;
                }
                break;
            }
        }
        // All *Exception classes are subclasses of Exception / System.Exception
        if ((std.ascii.eqlIgnoreCase(parent_type, "Exception") or std.ascii.eqlIgnoreCase(
            parent_type,
            "System.Exception",
        )) and
            std.mem.endsWith(u8, child_class, "Exception"))
        {
            return true;
        }
        return false;
    }

    /// System enum の文字列値から ordinal 値を返す。
    /// System.LoggingLevel, System.StatusCode, DisplayType など既知のenumに対応。
    fn lookup_enum_ordinal(s: []const u8) i64 {
        // System.LoggingLevel: Salesforce declaration order (most verbose first)
        // INTERNAL=0, FINEST=1, FINER=2, FINE=3, DEBUG=4, INFO=5, WARN=6, ERROR=7, NONE=8
        const logging_levels = [_][]const u8{ "INTERNAL", "FINEST", "FINER", "FINE", "DEBUG", "INFO", "WARN", "ERROR", "NONE" };
        for (logging_levels, 0..) |name, i| {
            if (std.ascii.eqlIgnoreCase(s, name)) return @intCast(i);
        }
        // System.TriggerOperation: BEFORE_INSERT=0, BEFORE_UPDATE=1, BEFORE_DELETE=2,
        // AFTER_INSERT=3, AFTER_UPDATE=4, AFTER_DELETE=5, AFTER_UNDELETE=6
        const trigger_ops = [_][]const u8{ "BEFORE_INSERT", "BEFORE_UPDATE", "BEFORE_DELETE", "AFTER_INSERT", "AFTER_UPDATE", "AFTER_DELETE", "AFTER_UNDELETE" };
        for (trigger_ops, 0..) |name, i| {
            if (std.ascii.eqlIgnoreCase(s, name)) return @intCast(i);
        }
        return 0;
    }

    /// ISO 日付文字列 (YYYY-MM-DD or YYYY-MM-DDTHH:MM:SSZ) をパースする。
    fn parse_iso_date(
        s: []const u8,
    ) ?struct { y: i32, m: u8, d: u8, h: u8, mi: u8, sec: u8, has_time: bool } {
        if (s.len < 10 or s[4] != '-' or s[7] != '-') return null;
        const y = std.fmt.parseInt(i32, s[0..4], 10) catch return null;
        const m = std.fmt.parseInt(u8, s[5..7], 10) catch return null;
        const day = std.fmt.parseInt(u8, s[8..10], 10) catch return null;
        if (s.len >= 19 and s[10] == 'T') {
            const h = std.fmt.parseInt(u8, s[11..13], 10) catch 0;
            const mi = std.fmt.parseInt(u8, s[14..16], 10) catch 0;
            const sec = std.fmt.parseInt(u8, s[17..19], 10) catch 0;
            return .{ .y = y, .m = m, .d = day, .h = h, .mi = mi, .sec = sec, .has_time = true };
        }
        return .{ .y = y, .m = m, .d = day, .h = 0, .mi = 0, .sec = 0, .has_time = false };
    }

    /// 月と日から年内通算日を返す (1-indexed)
    fn day_of_year(m: u8, d: u8) u16 {
        const cumulative = [_]u16{ 0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334 };
        return cumulative[m - 1] + d;
    }

    /// 年月日から 1970-01-01 を原点とする連続日数を返す。負の年でも動作する。
    fn iso_date_to_epoch_days(year: i32, month: u8, day: u8) i64 {
        const y = @as(i64, year);
        const doy = @as(i64, day_of_year(month, day));
        const is_leap: i64 =
            if (@mod(y, 4) == 0 and (@mod(y, 100) != 0 or @mod(y, 400) == 0)) @as(i64, 1) else 0;
        const leap_adj: i64 = if (month > 2) is_leap else 0;
        return (y - 1970) * 365 + @divFloor(y - 1969, 4) - @divFloor(
            y - 1901,
            100,
        ) + @divFloor(y - 1601, 400) + doy - 1 + leap_adj;
    }

    /// ISO 8601 day-of-week: Monday=1 ... Sunday=7.
    fn iso_day_of_week(year: i32, month: u8, day: u8) u8 {
        // 1970-01-01 was a Thursday (ISO dow=4).
        const epoch_days = iso_date_to_epoch_days(year, month, day);
        const r = @mod(epoch_days + 3, 7); // Mon=0..Sun=6
        return @as(u8, @intCast(r + 1));
    }

    const IsoWeek = struct { year: i32, week: u8 };

    /// ISO 8601 week-of-year / week-year. Week 1 contains the first Thursday.
    fn iso_week_of_year(year: i32, month: u8, day: u8) IsoWeek {
        // Day-of-year (1-based).
        const is_leap = (@mod(year, 4) == 0 and (@mod(year, 100) != 0 or @mod(year, 400) == 0));
        var doy: i32 = @as(i32, day_of_year(month, day));
        if (is_leap and month > 2) doy += 1;
        const dow: i32 = @as(i32, iso_day_of_week(year, month, day));
        const woy_num = @divFloor((doy - dow + 10), 7);
        if (woy_num < 1) {
            // Week belongs to the previous year's last ISO week (52 or 53).
            return iso_week_of_year(year - 1, 12, 31);
        }
        const is_leap_this = if ((@mod(year, 4) == 0 and (@mod(
            year,
            100,
        ) != 0 or @mod(year, 400) == 0))) true else false;
        _ = is_leap_this;
        // How many ISO weeks does this year have? Either 52 or 53.
        const jan1_dow: i32 = @as(i32, iso_day_of_week(year, 1, 1));
        const dec31_dow: i32 = @as(i32, iso_day_of_week(year, 12, 31));
        const weeks_in_year: i32 = if (jan1_dow == 4 or dec31_dow == 4) 53 else 52;
        if (woy_num > weeks_in_year) {
            return IsoWeek{ .year = year + 1, .week = 1 };
        }
        return IsoWeek{ .year = year, .week = @as(u8, @intCast(woy_num)) };
    }

    /// Datetime パターンフォーマット (Java SimpleDateFormat 互換サブセット)
    fn format_date_time_pattern(self: *Evaluator, s: []const u8, pattern: []const u8) !Value {
        const dt = parse_iso_date(s) orelse return Value{ .string = s };
        const month_names = [_][]const u8{ "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December" };
        const month_abbr = [_][]const u8{ "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };
        const month_name = if (dt.m >= 1 and dt.m <= 12) month_names[dt.m - 1] else "January";
        const month_short = if (dt.m >= 1 and dt.m <= 12) month_abbr[dt.m - 1] else "Jan";

        var result: std.ArrayListUnmanaged(u8) = .empty;
        var i: usize = 0;
        while (i < pattern.len) {
            const c = pattern[i];
            // Count consecutive same characters
            var count: usize = 1;
            while (i + count < pattern.len and pattern[i + count] == c) : (count += 1) {}

            switch (c) {
                'y' => {
                    if (count <= 2) {
                        const short_y: u32 = @intCast(@mod(dt.y, 100));
                        const ys = try std.fmt.allocPrint(self.arena, "{d:0>2}", .{short_y});
                        try result.appendSlice(self.arena, ys);
                    } else {
                        const ys = try std.fmt.allocPrint(
                            self.arena,
                            "{d:0>4}",
                            .{@as(u32, @intCast(dt.y))},
                        );
                        try result.appendSlice(self.arena, ys);
                    }
                },
                'M' => {
                    if (count >= 4) {
                        try result.appendSlice(self.arena, month_name);
                    } else if (count == 3) {
                        try result.appendSlice(self.arena, month_short);
                    } else if (count == 2) {
                        const ms = try std.fmt.allocPrint(self.arena, "{d:0>2}", .{dt.m});
                        try result.appendSlice(self.arena, ms);
                    } else {
                        const ms = try std.fmt.allocPrint(self.arena, "{d}", .{dt.m});
                        try result.appendSlice(self.arena, ms);
                    }
                },
                'd' => {
                    if (count >= 2) {
                        const ds = try std.fmt.allocPrint(self.arena, "{d:0>2}", .{dt.d});
                        try result.appendSlice(self.arena, ds);
                    } else {
                        const ds = try std.fmt.allocPrint(self.arena, "{d}", .{dt.d});
                        try result.appendSlice(self.arena, ds);
                    }
                },
                'H' => {
                    if (count >= 2) {
                        const hs = try std.fmt.allocPrint(self.arena, "{d:0>2}", .{dt.h});
                        try result.appendSlice(self.arena, hs);
                    } else {
                        const hs = try std.fmt.allocPrint(self.arena, "{d}", .{dt.h});
                        try result.appendSlice(self.arena, hs);
                    }
                },
                'h' => {
                    const h12: u8 = if (dt.h == 0) 12 else if (dt.h > 12) dt.h - 12 else dt.h;
                    if (count >= 2) {
                        const hs = try std.fmt.allocPrint(self.arena, "{d:0>2}", .{h12});
                        try result.appendSlice(self.arena, hs);
                    } else {
                        const hs = try std.fmt.allocPrint(self.arena, "{d}", .{h12});
                        try result.appendSlice(self.arena, hs);
                    }
                },
                'm' => {
                    if (count >= 2) {
                        const ms = try std.fmt.allocPrint(self.arena, "{d:0>2}", .{dt.mi});
                        try result.appendSlice(self.arena, ms);
                    } else {
                        const ms = try std.fmt.allocPrint(self.arena, "{d}", .{dt.mi});
                        try result.appendSlice(self.arena, ms);
                    }
                },
                's' => {
                    if (count >= 2) {
                        const ss = try std.fmt.allocPrint(self.arena, "{d:0>2}", .{dt.sec});
                        try result.appendSlice(self.arena, ss);
                    } else {
                        const ss = try std.fmt.allocPrint(self.arena, "{d}", .{dt.sec});
                        try result.appendSlice(self.arena, ss);
                    }
                },
                'a' => {
                    try result.appendSlice(self.arena, if (dt.h < 12) "AM" else "PM");
                },
                'w', 'Y' => {
                    // ISO week (week-of-week-based-year) and week-year pair.
                    // Week 1 is the week containing the first Thursday.
                    const iso = iso_week_of_year(dt.y, dt.m, dt.d);
                    if (c == 'w') {
                        const ws = try std.fmt.allocPrint(self.arena, "{d}", .{iso.week});
                        try result.appendSlice(self.arena, ws);
                    } else {
                        const ys = try std.fmt.allocPrint(
                            self.arena,
                            "{d:0>4}",
                            .{@as(u32, @intCast(iso.year))},
                        );
                        try result.appendSlice(self.arena, ys);
                    }
                },
                'u' => {
                    // ISO day of week: Monday=1..Sunday=7.
                    const dow = iso_day_of_week(dt.y, dt.m, dt.d);
                    const ds = try std.fmt.allocPrint(self.arena, "{d}", .{dow});
                    try result.appendSlice(self.arena, ds);
                },
                'D' => {
                    // Day of year (1-based).
                    const is_leap =
                        (@mod(dt.y, 4) == 0 and (@mod(dt.y, 100) != 0 or @mod(dt.y, 400) == 0));
                    var doy: u16 = day_of_year(dt.m, dt.d);
                    if (is_leap and dt.m > 2) doy += 1;
                    const ds = try std.fmt.allocPrint(self.arena, "{d}", .{doy});
                    try result.appendSlice(self.arena, ds);
                },
                '\'' => {
                    // Quoted literal text
                    i += 1; // skip opening quote
                    while (i < pattern.len and pattern[i] != '\'') : (i += 1) {
                        try result.append(self.arena, pattern[i]);
                    }
                    if (i < pattern.len) i += 1; // skip closing quote
                    continue;
                },
                else => {
                    for (0..count) |_| try result.append(self.arena, c);
                },
            }
            i += count;
        }
        return Value{ .string = result.items };
    }

    /// addYears / addMonths / addDays — ISO 日付文字列に対する日付演算
    fn date_time_add(
        self: *Evaluator,
        s: []const u8,
        method: []const u8,
        args: []const Value,
    ) !Value {
        const dt = parse_iso_date(s) orelse return Value{ .string = s };
        const delta: i32 = if (args.len > 0) switch (args[0]) {
            .integer => |i| @intCast(i),
            .double => |d| @intFromFloat(d),
            else => 0,
        } else 0;

        var y = dt.y;
        var m: i32 = dt.m;
        var d: i32 = dt.d;

        if (std.ascii.eqlIgnoreCase(method, "addYears")) {
            y += delta;
        } else if (std.ascii.eqlIgnoreCase(method, "addMonths")) {
            m += delta;
            while (m < 1) {
                m += 12;
                y -= 1;
            }
            while (m > 12) {
                m -= 12;
                y += 1;
            }
        } else if (std.ascii.eqlIgnoreCase(method, "addDays")) {
            d += delta;
            // 簡易実装: 各月の日数でオーバーフロー/アンダーフローを処理
            const days_in_month = [_]u8{ 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
            while (d > days_in_month[@intCast(m - 1)]) {
                d -= days_in_month[@intCast(m - 1)];
                m += 1;
                if (m > 12) {
                    m = 1;
                    y += 1;
                }
            }
            while (d < 1) {
                m -= 1;
                if (m < 1) {
                    m = 12;
                    y -= 1;
                }
                d += days_in_month[@intCast(m - 1)];
            }
        }

        if (dt.has_time) {
            return Value{ .string = try std.fmt.allocPrint(self.arena, "{d:0>4}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}Z", .{
                @as(u32, @intCast(y)),
                @as(u32, @intCast(m)),
                @as(u32, @intCast(d)),
                dt.h,
                dt.mi,
                dt.sec,
            }) };
        }
        return Value{ .string = try std.fmt.allocPrint(self.arena, "{d:0>4}-{d:0>2}-{d:0>2}", .{
            @as(u32, @intCast(y)),
            @as(u32, @intCast(m)),
            @as(u32, @intCast(d)),
        }) };
    }

    // -----------------------------------------------------------------------
    // テストフレームワーク
    // -----------------------------------------------------------------------

    fn handle_assert(self: *Evaluator, method: []const u8, args: []const Value) !Value {
        if (std.ascii.eqlIgnoreCase(method, "areEqual") or
            std.ascii.eqlIgnoreCase(method, "assertEquals"))
        {
            if (args.len >= 2) {
                if (!self.values_equal(args[0], args[1])) {
                    const expected_str = try utils.coerce_to_string(args[0], self.arena);
                    const actual_str = try utils.coerce_to_string(args[1], self.arena);
                    self.assertion_failure = if (args.len >= 3 and args[2] == .string)
                        try std.fmt.allocPrint(
                            self.arena,
                            "{s} | Expected: {s}, Actual: {s}",
                            .{ args[2].string, expected_str, actual_str },
                        )
                    else
                        try std.fmt.allocPrint(
                            self.arena,
                            "Expected: {s}, Actual: {s}",
                            .{ expected_str, actual_str },
                        );
                }
            }
        } else if (std.ascii.eqlIgnoreCase(method, "areNotEqual") or
            std.ascii.eqlIgnoreCase(method, "assertNotEquals"))
        {
            if (args.len >= 2) {
                if (self.values_equal(args[0], args[1])) {
                    const val_str = try utils.coerce_to_string(args[0], self.arena);
                    self.assertion_failure = if (args.len >= 3 and args[2] == .string)
                        try std.fmt.allocPrint(
                            self.arena,
                            "{s} | Both values: {s}",
                            .{ args[2].string, val_str },
                        )
                    else
                        try std.fmt.allocPrint(
                            self.arena,
                            "Values should not be equal: {s}",
                            .{val_str},
                        );
                }
            }
        } else if (std.ascii.eqlIgnoreCase(method, "isTrue") or
            std.ascii.eqlIgnoreCase(method, "assertTrue"))
        {
            if (args.len >= 1) {
                const val = utils.coerce_to_bool(args[0]) catch false;
                if (!val) {
                    const actual_str = try utils.coerce_to_string(args[0], self.arena);
                    self.assertion_failure = if (args.len >= 2 and args[1] == .string)
                        try std.fmt.allocPrint(
                            self.arena,
                            "{s} | Expected: true, Actual: {s}",
                            .{ args[1].string, actual_str },
                        )
                    else
                        try std.fmt.allocPrint(
                            self.arena,
                            "Expected: true, Actual: {s}",
                            .{actual_str},
                        );
                }
            }
        } else if (std.ascii.eqlIgnoreCase(method, "isFalse") or
            std.ascii.eqlIgnoreCase(method, "assertFalse"))
        {
            if (args.len >= 1) {
                const val = utils.coerce_to_bool(args[0]) catch false;
                if (val) {
                    const actual_str = try utils.coerce_to_string(args[0], self.arena);
                    self.assertion_failure = if (args.len >= 2 and args[1] == .string)
                        try std.fmt.allocPrint(
                            self.arena,
                            "{s} | Expected: false, Actual: {s}",
                            .{ args[1].string, actual_str },
                        )
                    else
                        try std.fmt.allocPrint(
                            self.arena,
                            "Expected: false, Actual: {s}",
                            .{actual_str},
                        );
                }
            }
        } else if (std.ascii.eqlIgnoreCase(method, "isNotNull") or
            std.ascii.eqlIgnoreCase(method, "assertNotNull"))
        {
            if (args.len >= 1) {
                if (args[0] == .null_val) {
                    self.assertion_failure = if (args.len >= 2 and args[1] == .string)
                        try std.fmt.allocPrint(
                            self.arena,
                            "{s} | Expected: non-null, Actual: null",
                            .{args[1].string},
                        )
                    else
                        "Expected: non-null, Actual: null";
                }
            }
        } else if (std.ascii.eqlIgnoreCase(method, "is_null")) {
            if (args.len >= 1) {
                if (args[0] != .null_val) {
                    const actual_str = try utils.coerce_to_string(args[0], self.arena);
                    self.assertion_failure = if (args.len >= 2 and args[1] == .string)
                        try std.fmt.allocPrint(
                            self.arena,
                            "{s} | Expected: null, Actual: {s}",
                            .{ args[1].string, actual_str },
                        )
                    else
                        try std.fmt.allocPrint(
                            self.arena,
                            "Expected: null, Actual: {s}",
                            .{actual_str},
                        );
                }
            }
        } else if (std.ascii.eqlIgnoreCase(method, "isInstanceOfType")) {
            // simplified: always pass
        } else if (std.ascii.eqlIgnoreCase(method, "fail")) {
            self.assertion_failure = if (args.len >= 1 and args[0] == .string) args[0].string else "Assert.fail called";
        }
        return .void_val;
    }

    fn handle_test(self: *Evaluator, method: []const u8, args: []const Value) !Value {
        // Test.startTest() — reset governor limits (Salesforce resets at startTest)
        if (std.ascii.eqlIgnoreCase(method, "startTest")) {
            self.limits_dml = 0;
            self.limits_dml_rows = 0;
            self.limits_soql = 0;
            self.limits_publish_immediate = 0;
            self.limits_queueable = 0;
            self.limits_callouts = 0;
            self.limits_email_invocations = 0;
            self.reserved_single_email_capacity = 0;
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "stopTest")) {
            // Execute any Schedulable instances queued via System.schedule between
            // startTest/stopTest.
            while (self.pending_schedulables.items.len > 0) {
                const sched = self.pending_schedulables.orderedRemove(0);
                if (sched == .object) {
                    if (self.find_class(sched.object.class_name)) |class_decl| {
                        const ctx_obj = try self.arena.create(types.ObjectInstance);
                        ctx_obj.* = .{ .class_name = "System.SchedulableContext" };
                        try ctx_obj.fields.put(
                            self.arena,
                            "triggerId",
                            Value{ .string = "08e000000000001" },
                        );
                        _ = self.call_instance_method(
                            class_decl,
                            sched.object,
                            "execute",
                            &.{Value{ .object = ctx_obj }},
                        ) catch {};
                    }
                }
            }
            return .void_val;
        }
        // Test.setFixedSearchResults(List<Id>)
        if (std.ascii.eqlIgnoreCase(method, "setFixedSearchResults") and args.len >= 1) {
            self.fixed_search_results = args[0];
            return .void_val;
        }
        // Test.setMock(Type, mockInstance)
        if (std.ascii.eqlIgnoreCase(method, "setMock") and args.len >= 2) {
            self.callout_mock = args[1];
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "isRunningTest")) {
            return Value{ .boolean = true };
        }
        if (std.ascii.eqlIgnoreCase(method, "testInstall") and
            args.len >= 1 and
            args[0] == .object)
        {
            if (self.find_class(args[0].object.class_name)) |install_handler_class| {
                const install_context = try self.arena.create(types.ObjectInstance);
                install_context.* = .{ .class_name = "System.InstallContext" };
                if (args.len >= 2)
                    try install_context.fields.put(self.arena, "previousVersion", args[1]);
                if (args.len >= 3) try install_context.fields.put(self.arena, "upgrade", args[2]);
                if (args.len >= 3 and args[2] == .boolean) {
                    try install_context.fields.put(
                        self.arena,
                        "firstInstall",
                        Value{ .boolean = !args[2].boolean },
                    );
                }
                _ = try self.call_instance_method(
                    install_handler_class,
                    args[0].object,
                    "onInstall",
                    &.{Value{ .object = install_context }},
                );
            }
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "setCreatedDate")) {
            var bctx = builtins.BuiltinContext{ .arena = self.arena, .stdout = &self.stdout, .pending_exception = &self.pending_exception, .see_all_data = self.see_all_data, .eval = self };
            _ = try builtins.dispatch_static(&bctx, "Test", method, args);
            return .void_val;
        }
        // Test.getEventBus() → return an EventBus stub with deliver() method
        if (std.ascii.eqlIgnoreCase(method, "getEventBus")) {
            const eb = try self.arena.create(types.ObjectInstance);
            eb.* = .{ .class_name = "EventBus" };
            return Value{ .object = eb };
        }
        // Test.createStub(Type, StubProvider) → create a stub proxy
        if (std.ascii.eqlIgnoreCase(method, "createStub") and args.len >= 2) {
            const type_val = args[0]; // Type object
            const provider = args[1]; // StubProvider instance
            const type_name: []const u8 = if (type_val == .object)
                (if (type_val.object.fields.get("name")) |n| (if (n == .string) n.string else "Object") else "Object")
            else
                "Object";
            // Create a stub instance that records the provider for method dispatch
            const stub = try self.arena.create(types.ObjectInstance);
            stub.* = .{ .class_name = type_name };
            try stub.fields.put(self.arena, "__stubProvider__", provider);
            try stub.fields.put(self.arena, "__stubDisplayClassName__", Value{ .string = try std.fmt.allocPrint(self.arena, "{s}__sfdc_ApexStub", .{type_name}) });
            // Initialize instance fields from the class if it exists
            if (self.find_class(type_name)) |class_decl| {
                self.init_instance_fields(class_decl, stub) catch {};
                if (class_decl.super_class) |sc| {
                    if (self.find_class(sc.name)) |parent| {
                        self.init_instance_fields(parent, stub) catch {};
                    }
                }
            }
            return Value{ .object = stub };
        }
        return .void_val;
    }

    fn handle_trigger_handler(self: *Evaluator, method: []const u8, args: []const Value) !Value {
        if (std.ascii.eqlIgnoreCase(method, "bypass") and args.len > 0 and args[0] == .string) {
            try self.bypasses.put(self.arena, args[0].string, {});
        }
        return .void_val;
    }

    fn get_dml_options_all_or_none(_: *Evaluator, value: Value) ?bool {
        const fields = switch (value) {
            .object => value.object.fields,
            .sobject => value.sobject.fields,
            else => return null,
        };
        if (fields.get("OptAllOrNone")) |opt| {
            if (opt == .boolean) return opt.boolean;
        }
        for (fields.keys(), fields.values()) |k, v| {
            if (std.ascii.eqlIgnoreCase(k, "OptAllOrNone") and v == .boolean) return v.boolean;
        }
        return null;
    }

    fn sobject_id_for_result(_: *Evaluator, obj: *types.SObject) ?[]const u8 {
        if (obj.id) |id| return id;
        if (utils.sobject_get(&obj.fields, "Id")) |id_val| {
            if (id_val == .string) return id_val.string;
        }
        return null;
    }

    fn create_dml_result_value(
        self: *Evaluator,
        result_class: []const u8,
        success: bool,
        id: ?[]const u8,
        is_created: ?bool,
    ) !Value {
        const sr = try self.arena.create(types.ObjectInstance);
        sr.* = .{ .class_name = result_class };
        try sr.fields.put(self.arena, "isSuccess", Value{ .boolean = success });
        try sr.fields.put(self.arena, "success", Value{ .boolean = success });
        if (id) |record_id| {
            try sr.fields.put(self.arena, "id", Value{ .string = record_id });
            try sr.fields.put(self.arena, "Id", Value{ .string = record_id });
        }
        if (is_created) |created| {
            try sr.fields.put(self.arena, "isCreated", Value{ .boolean = created });
            try sr.fields.put(self.arena, "created", Value{ .boolean = created });
        }
        return Value{ .object = sr };
    }

    fn create_empty_result_list_value(self: *Evaluator) !Value {
        const empty = try self.arena.create(types.ListValue);
        empty.* = .{};
        return Value{ .list = empty };
    }

    fn build_failed_dml_result(
        self: *Evaluator,
        result_class: []const u8,
        target: Value,
        is_upsert: bool,
    ) !Value {
        const result_id =
            if (target == .sobject) self.sobject_id_for_result(target.sobject) else null;
        const result = try self.create_dml_result_value(
            result_class,
            false,
            result_id,
            if (is_upsert) false else null,
        );
        if (self.pending_exception) |pe| {
            const errors_list = try self.arena.create(types.ListValue);
            errors_list.* = .{};
            const err_obj = try self.arena.create(types.ObjectInstance);
            err_obj.* = .{ .class_name = "Database.Error" };
            var message_val: Value = Value{ .string = "" };
            var fields_val: Value = Value{ .list = blk: {
                const empty = try self.arena.create(types.ListValue);
                empty.* = .{};
                break :blk empty;
            } };
            if (pe == .object) {
                if (pe.object.fields.get("message")) |m| message_val = m;
                if (pe.object.fields.get("field")) |f| {
                    if (f == .string) {
                        const fl = try self.arena.create(types.ListValue);
                        fl.* = .{};
                        try fl.items.append(self.arena, f);
                        fields_val = Value{ .list = fl };
                    }
                }
            } else if (pe == .string) {
                message_val = pe;
            }
            try err_obj.fields.put(self.arena, "message", message_val);
            try err_obj.fields.put(
                self.arena,
                "statusCode",
                Value{ .string = "FIELD_CUSTOM_VALIDATION_EXCEPTION" },
            );
            try err_obj.fields.put(self.arena, "fields", fields_val);
            try errors_list.items.append(self.arena, Value{ .object = err_obj });
            if (result == .object) {
                try result.object.fields.put(self.arena, "errors", Value{ .list = errors_list });
            }
        }
        return result;
    }

    fn execute_partial_database_method(
        self: *Evaluator,
        op: ast.DmlOp,
        result_class: []const u8,
        target: Value,
        external_id_field: ?[]const u8,
    ) !Value {
        const appendFailure = struct {
            fn build(
                self_eval: *Evaluator,
                cls: []const u8,
                item: Value,
                op_kind: ast.DmlOp,
            ) !Value {
                const result_id =
                    if (item == .sobject) self_eval.sobject_id_for_result(item.sobject) else null;
                const result = try self_eval.create_dml_result_value(
                    cls,
                    false,
                    result_id,
                    if (op_kind == .upsert) false else null,
                );
                // Capture pending exception as Database.Error on the failed result
                if (self_eval.pending_exception) |pe| {
                    const errors_list = try self_eval.arena.create(types.ListValue);
                    errors_list.* = .{};
                    const err_obj = try self_eval.arena.create(types.ObjectInstance);
                    err_obj.* = .{ .class_name = "Database.Error" };
                    var message_val: Value = Value{ .string = "" };
                    var fields_val: Value = Value{ .list = blk: {
                        const empty = try self_eval.arena.create(types.ListValue);
                        empty.* = .{};
                        break :blk empty;
                    } };
                    if (pe == .object) {
                        if (pe.object.fields.get("message")) |m| message_val = m;
                        if (pe.object.fields.get("field")) |f| {
                            if (f == .string) {
                                const fl = try self_eval.arena.create(types.ListValue);
                                fl.* = .{};
                                try fl.items.append(self_eval.arena, f);
                                fields_val = Value{ .list = fl };
                            }
                        }
                    } else if (pe == .string) {
                        message_val = pe;
                    }
                    try err_obj.fields.put(self_eval.arena, "message", message_val);
                    try err_obj.fields.put(
                        self_eval.arena,
                        "statusCode",
                        Value{ .string = "FIELD_CUSTOM_VALIDATION_EXCEPTION" },
                    );
                    try err_obj.fields.put(self_eval.arena, "fields", fields_val);
                    try errors_list.items.append(self_eval.arena, Value{ .object = err_obj });
                    if (result == .object) {
                        try result.object.fields.put(
                            self_eval.arena,
                            "errors",
                            Value{ .list = errors_list },
                        );
                    }
                }
                return result;
            }
        };

        switch (target) {
            .null_val, .void_val => return self.create_empty_result_list_value(),
            .sobject => {
                self.limits_dml += 1;
                self.limits_dml_rows += 1;
                return switch (op) {
                    .insert => blk: {
                        try self.execute_dml_with_external_id_internal(
                            .insert,
                            target,
                            null,
                            false,
                            null,
                        );
                        break :blk try self.create_dml_result_value(
                            result_class,
                            true,
                            self.sobject_id_for_result(target.sobject),
                            null,
                        );
                    },
                    .update => blk: {
                        try self.execute_dml_with_external_id_internal(
                            .update,
                            target,
                            null,
                            false,
                            null,
                        );
                        break :blk try self.create_dml_result_value(
                            result_class,
                            true,
                            self.sobject_id_for_result(target.sobject),
                            null,
                        );
                    },
                    .upsert => blk: {
                        const was_created = self.will_upsert_create_record(
                            target.sobject,
                            external_id_field,
                        );
                        try self.execute_dml_with_external_id_internal(
                            .upsert,
                            target,
                            external_id_field,
                            false,
                            null,
                        );
                        break :blk try self.create_dml_result_value(
                            result_class,
                            true,
                            self.sobject_id_for_result(target.sobject),
                            was_created,
                        );
                    },
                    .delete => blk: {
                        try self.execute_dml_with_external_id_internal(
                            .delete,
                            target,
                            null,
                            false,
                            null,
                        );
                        break :blk try self.create_dml_result_value(
                            result_class,
                            true,
                            self.sobject_id_for_result(target.sobject),
                            null,
                        );
                    },
                    .undelete => blk: {
                        try self.execute_dml_with_external_id_internal(
                            .undelete,
                            target,
                            null,
                            false,
                            null,
                        );
                        break :blk try self.create_dml_result_value(
                            result_class,
                            true,
                            self.sobject_id_for_result(target.sobject),
                            null,
                        );
                    },
                    else => Value.null_val,
                };
            },
            .list => |records| {
                const items = records.items.items;
                if (items.len == 0) return self.create_empty_result_list_value();

                self.limits_dml += 1;
                self.limits_dml_rows += @intCast(items.len);

                const list = try self.arena.create(types.ListValue);
                list.* = .{};
                for (items) |item| {
                    if (item != .sobject) {
                        try list.items.append(
                            self.arena,
                            try appendFailure.build(self, result_class, item, op),
                        );
                        continue;
                    }
                    const was_created = op == .upsert and self.will_upsert_create_record(
                        item.sobject,
                        external_id_field,
                    );
                    const result = switch (op) {
                        .insert => blk: {
                            self.execute_dml_with_external_id_internal(
                                .insert,
                                item,
                                null,
                                false,
                                null,
                            ) catch {
                                const failed = try appendFailure.build(
                                    self,
                                    result_class,
                                    item,
                                    op,
                                );
                                self.pending_exception = null;
                                break :blk failed;
                            };
                            break :blk try self.create_dml_result_value(
                                result_class,
                                true,
                                self.sobject_id_for_result(item.sobject),
                                null,
                            );
                        },
                        .update => blk: {
                            self.execute_dml_with_external_id_internal(
                                .update,
                                item,
                                null,
                                false,
                                null,
                            ) catch {
                                const failed = try appendFailure.build(
                                    self,
                                    result_class,
                                    item,
                                    op,
                                );
                                self.pending_exception = null;
                                break :blk failed;
                            };
                            break :blk try self.create_dml_result_value(
                                result_class,
                                true,
                                self.sobject_id_for_result(item.sobject),
                                null,
                            );
                        },
                        .upsert => blk: {
                            self.execute_dml_with_external_id_internal(
                                .upsert,
                                item,
                                external_id_field,
                                false,
                                null,
                            ) catch {
                                const failed = try appendFailure.build(
                                    self,
                                    result_class,
                                    item,
                                    op,
                                );
                                self.pending_exception = null;
                                break :blk failed;
                            };
                            break :blk try self.create_dml_result_value(
                                result_class,
                                true,
                                self.sobject_id_for_result(item.sobject),
                                was_created,
                            );
                        },
                        .delete => blk: {
                            self.execute_dml_with_external_id_internal(
                                .delete,
                                item,
                                null,
                                false,
                                null,
                            ) catch {
                                const failed = try appendFailure.build(
                                    self,
                                    result_class,
                                    item,
                                    op,
                                );
                                self.pending_exception = null;
                                break :blk failed;
                            };
                            break :blk try self.create_dml_result_value(
                                result_class,
                                true,
                                self.sobject_id_for_result(item.sobject),
                                null,
                            );
                        },
                        .undelete => blk: {
                            self.execute_dml_with_external_id_internal(
                                .undelete,
                                item,
                                null,
                                false,
                                null,
                            ) catch {
                                const failed = try appendFailure.build(
                                    self,
                                    result_class,
                                    item,
                                    op,
                                );
                                self.pending_exception = null;
                                break :blk failed;
                            };
                            break :blk try self.create_dml_result_value(
                                result_class,
                                true,
                                self.sobject_id_for_result(item.sobject),
                                null,
                            );
                        },
                        else => Value.null_val,
                    };
                    try list.items.append(self.arena, result);
                }
                return Value{ .list = list };
            },
            .set => |records| {
                const items = records.entries.values();
                if (items.len == 0) return self.create_empty_result_list_value();

                self.limits_dml += 1;
                self.limits_dml_rows += @intCast(items.len);

                const list = try self.arena.create(types.ListValue);
                list.* = .{};
                for (items) |item| {
                    if (item != .sobject) {
                        try list.items.append(
                            self.arena,
                            try appendFailure.build(self, result_class, item, op),
                        );
                        continue;
                    }
                    const was_created = op == .upsert and self.will_upsert_create_record(
                        item.sobject,
                        external_id_field,
                    );
                    const result = switch (op) {
                        .insert => blk: {
                            self.execute_dml_with_external_id_internal(
                                .insert,
                                item,
                                null,
                                false,
                                null,
                            ) catch {
                                const failed = try appendFailure.build(
                                    self,
                                    result_class,
                                    item,
                                    op,
                                );
                                self.pending_exception = null;
                                break :blk failed;
                            };
                            break :blk try self.create_dml_result_value(
                                result_class,
                                true,
                                self.sobject_id_for_result(item.sobject),
                                null,
                            );
                        },
                        .update => blk: {
                            self.execute_dml_with_external_id_internal(
                                .update,
                                item,
                                null,
                                false,
                                null,
                            ) catch {
                                const failed = try appendFailure.build(
                                    self,
                                    result_class,
                                    item,
                                    op,
                                );
                                self.pending_exception = null;
                                break :blk failed;
                            };
                            break :blk try self.create_dml_result_value(
                                result_class,
                                true,
                                self.sobject_id_for_result(item.sobject),
                                null,
                            );
                        },
                        .upsert => blk: {
                            self.execute_dml_with_external_id_internal(
                                .upsert,
                                item,
                                external_id_field,
                                false,
                                null,
                            ) catch {
                                const failed = try appendFailure.build(
                                    self,
                                    result_class,
                                    item,
                                    op,
                                );
                                self.pending_exception = null;
                                break :blk failed;
                            };
                            break :blk try self.create_dml_result_value(
                                result_class,
                                true,
                                self.sobject_id_for_result(item.sobject),
                                was_created,
                            );
                        },
                        .delete => blk: {
                            self.execute_dml_with_external_id_internal(
                                .delete,
                                item,
                                null,
                                false,
                                null,
                            ) catch {
                                const failed = try appendFailure.build(
                                    self,
                                    result_class,
                                    item,
                                    op,
                                );
                                self.pending_exception = null;
                                break :blk failed;
                            };
                            break :blk try self.create_dml_result_value(
                                result_class,
                                true,
                                self.sobject_id_for_result(item.sobject),
                                null,
                            );
                        },
                        .undelete => blk: {
                            self.execute_dml_with_external_id_internal(
                                .undelete,
                                item,
                                null,
                                false,
                                null,
                            ) catch {
                                const failed = try appendFailure.build(
                                    self,
                                    result_class,
                                    item,
                                    op,
                                );
                                self.pending_exception = null;
                                break :blk failed;
                            };
                            break :blk try self.create_dml_result_value(
                                result_class,
                                true,
                                self.sobject_id_for_result(item.sobject),
                                null,
                            );
                        },
                        else => Value.null_val,
                    };
                    try list.items.append(self.arena, result);
                }
                return Value{ .list = list };
            },
            else => {
                const list = try self.arena.create(types.ListValue);
                list.* = .{};
                try list.items.append(
                    self.arena,
                    try appendFailure.build(self, result_class, target, op),
                );
                return Value{ .list = list };
            },
        }
    }

    fn handle_database_method(
        self: *Evaluator,
        method: []const u8,
        args: []const Value,
        env: *Env,
    ) anyerror!Value {
        if (std.ascii.eqlIgnoreCase(method, "insert") or
            std.ascii.eqlIgnoreCase(method, "update") or
            std.ascii.eqlIgnoreCase(method, "upsert") or
            std.ascii.eqlIgnoreCase(method, "delete") or
            std.ascii.eqlIgnoreCase(method, "undelete"))
        {
            const result_class = if (std.ascii.eqlIgnoreCase(method, "upsert"))
                "Database.UpsertResult"
            else if (std.ascii.eqlIgnoreCase(method, "undelete"))
                "Database.UndeleteResult"
            else if (std.ascii.eqlIgnoreCase(method, "delete"))
                "Database.DeleteResult"
            else
                "Database.SaveResult";

            const is_upsert = std.ascii.eqlIgnoreCase(method, "upsert");
            const external_id_field = if (is_upsert and args.len >= 2 and args[1] != .boolean) extract_s_object_field_name(args[1]) else null;
            // Check allOrNothing flag (second arg, defaults to true).
            // Upsert with external id field uses the third arg for allOrNothing.
            const all_or_nothing = blk: {
                if (is_upsert and args.len >= 3 and args[2] == .boolean) break :blk args[2].boolean;
                if (is_upsert and args.len >= 3) {
                    if (self.get_dml_options_all_or_none(args[2])) |opt| break :blk opt;
                }
                if (args.len >= 2 and args[1] == .boolean) break :blk args[1].boolean;
                if (args.len >= 2) {
                    if (self.get_dml_options_all_or_none(args[1])) |opt| break :blk opt;
                }
                break :blk true;
            };

            // Check if second arg is AccessLevel.USER_MODE for min-access user context (without
            // permsets)
            const has_permset_db =
                if (self.store.get("PermissionSetAssignment")) |psa| psa.items.len > 0 else false;
            if (self.is_min_access_user and !has_permset_db and args.len >= 2) {
                const is_user_mode = if (args[1] == .string)
                    std.ascii.eqlIgnoreCase(args[1].string, "USER_MODE")
                else if (args[1] == .object) blk: {
                    if (args[1].object.fields.get("name")) |n| {
                        if (n == .string) break :blk std.ascii.eqlIgnoreCase(n.string, "USER_MODE");
                    }
                    break :blk false;
                } else false;
                if (is_user_mode) {
                    const from_type = if (args[0] == .sobject) args[0].sobject.type_name else if (args[0] == .list and args[0].list.items.items.len > 0 and args[0].list.items.items[0] == .sobject)
                        args[0].list.items.items[0].sobject.type_name
                    else
                        "SObject";
                    const msg = try std.fmt.allocPrint(
                        self.arena,
                        "Access to entity '{s}' denied",
                        .{from_type},
                    );
                    const exc = try self.arena.create(types.ObjectInstance);
                    exc.* = .{ .class_name = "System.SecurityException" };
                    try exc.fields.put(self.arena, "message", Value{ .string = msg });
                    self.pending_exception = Value{ .object = exc };
                    return error.ApexException;
                }
            }

            // For upsert, record which items will insert vs update before DML runs.
            var upsert_creates: std.ArrayListUnmanaged(bool) = .empty;
            if (is_upsert and args.len > 0) {
                if (args[0] == .sobject) {
                    try upsert_creates.append(
                        self.arena,
                        self.will_upsert_create_record(args[0].sobject, external_id_field),
                    );
                } else if (args[0] == .list) {
                    for (args[0].list.items.items) |item| {
                        try upsert_creates.append(self.arena, if (item == .sobject) self.will_upsert_create_record(item.sobject, external_id_field) else true);
                    }
                }
            }

            // First arg is the records to DML
            if (args.len > 0) {
                const op: ast.DmlOp = if (std.ascii.eqlIgnoreCase(method, "insert"))
                    .insert
                else if (std.ascii.eqlIgnoreCase(method, "update"))
                    .update
                else if (std.ascii.eqlIgnoreCase(method, "upsert"))
                    .upsert
                else if (std.ascii.eqlIgnoreCase(method, "undelete"))
                    .undelete
                else
                    .delete;

                if (all_or_nothing) {
                    // allOrNothing mode: propagate exceptions
                    if (is_upsert) {
                        try self.execute_dml_with_external_id(op, args[0], external_id_field);
                    } else {
                        try self.execute_dml(op, args[0]);
                    }
                } else {
                    // Best-effort mode: allow per-record failures instead of failing the whole DML
                    // statement.
                    return self.execute_partial_database_method(
                        op,
                        result_class,
                        args[0],
                        external_id_field,
                    ) catch |err| {
                        if (err == error.ApexException and args[0] == .sobject) {
                            const failed = try self.build_failed_dml_result(
                                result_class,
                                args[0],
                                is_upsert,
                            );
                            self.pending_exception = null;
                            return failed;
                        }
                        self.pending_exception = null;
                        return err;
                    };
                }
            }
            // Create SaveResult(s) for success case
            if (args.len > 0 and args[0] == .sobject) {
                // Single record: return single result (not a list)
                const was_created =
                    is_upsert and (upsert_creates.items.len > 0 and upsert_creates.items[0]);
                const sr = try self.arena.create(types.ObjectInstance);
                sr.* = .{ .class_name = result_class };
                try sr.fields.put(self.arena, "isSuccess", Value{ .boolean = true });
                try sr.fields.put(self.arena, "success", Value{ .boolean = true });
                try sr.fields.put(
                    self.arena,
                    "Id",
                    Value{ .string = args[0].sobject.id orelse "001000000000001" },
                );
                if (is_upsert) {
                    try sr.fields.put(self.arena, "isCreated", Value{ .boolean = was_created });
                    try sr.fields.put(self.arena, "created", Value{ .boolean = was_created });
                }
                return Value{ .object = sr };
            }
            // Return SaveResult list
            const list = try self.arena.create(types.ListValue);
            list.* = .{};
            if (args.len > 0 and args[0] == .list) {
                for (args[0].list.items.items, 0..) |item, idx| {
                    const was_created = is_upsert and (if (idx < upsert_creates.items.len) upsert_creates.items[idx] else true);
                    const sr = try self.arena.create(types.ObjectInstance);
                    sr.* = .{ .class_name = result_class };
                    try sr.fields.put(self.arena, "isSuccess", Value{ .boolean = true });
                    try sr.fields.put(self.arena, "success", Value{ .boolean = true });
                    try sr.fields.put(self.arena, "Id", Value{ .string = if (item == .sobject) (item.sobject.id orelse "001000000000001") else "001000000000001" });
                    if (is_upsert) {
                        try sr.fields.put(self.arena, "isCreated", Value{ .boolean = was_created });
                        try sr.fields.put(self.arena, "created", Value{ .boolean = was_created });
                    }
                    try list.items.append(self.arena, Value{ .object = sr });
                }
            } else {
                const sr = try self.arena.create(types.ObjectInstance);
                sr.* = .{ .class_name = result_class };
                try sr.fields.put(self.arena, "isSuccess", Value{ .boolean = true });
                try sr.fields.put(self.arena, "success", Value{ .boolean = true });
                try sr.fields.put(self.arena, "Id", Value{ .string = "001000000000001" });
                try list.items.append(self.arena, Value{ .object = sr });
            }
            return Value{ .list = list };
        }
        if (std.ascii.eqlIgnoreCase(method, "query")) {
            // Execute the SOQL string against the store
            if (args.len > 0 and args[0] == .string) {
                return self.execute_soql(args[0].string, env);
            }
            const list = try self.arena.create(types.ListValue);
            list.* = .{};
            return Value{ .list = list };
        }
        if (std.ascii.eqlIgnoreCase(method, "queryWithBinds")) {
            // debug removed
            // Database.queryWithBinds(queryString, bindMap, accessLevel)
            if (args.len >= 2 and args[0] == .string) {
                // Resolve bind variables from the map
                var soql_str = args[0].string;
                if (args[1] == .map) {
                    // Replace :bindVar with actual values from the map
                    var result_buf: std.ArrayListUnmanaged(u8) = .empty;
                    var pos: usize = 0;
                    while (pos < soql_str.len) {
                        if (soql_str[pos] == ':') {
                            // Extract bind variable name
                            var end = pos + 1;
                            while (end < soql_str.len and (std.ascii.isAlphanumeric(soql_str[end]) or soql_str[end] == '_')) end += 1;
                            const bind_name = soql_str[pos + 1 .. end];
                            if (args[1].map.entries.get(bind_name)) |bind_val| {
                                const s = try utils.coerce_to_string(bind_val, self.arena);
                                try result_buf.append(self.arena, '\'');
                                try result_buf.appendSlice(self.arena, s);
                                try result_buf.append(self.arena, '\'');
                            } else {
                                try result_buf.appendSlice(self.arena, soql_str[pos..end]);
                            }
                            pos = end;
                        } else {
                            try result_buf.append(self.arena, soql_str[pos]);
                            pos += 1;
                        }
                    }
                    soql_str = try result_buf.toOwnedSlice(self.arena);
                }
                return self.execute_soql(soql_str, env);
            }
            return try self.make_empty_list();
        }
        if (std.ascii.eqlIgnoreCase(method, "countQuery") or
            std.ascii.eqlIgnoreCase(method, "countQueryWithBinds"))
        {
            // countQuery can take a SOQL string
            if (args.len > 0 and args[0] == .string) {
                const soql = args[0].string;
                // Execute as a count query
                if (std.ascii.indexOfIgnoreCase(soql, "count()")) |_| {
                    return self.execute_soql(soql, env);
                }
                // Wrap as COUNT query
                const count_result = try self.execute_soql(soql, env);
                if (count_result == .list)
                    return Value{ .integer = @intCast(count_result.list.items.items.len) };
                return count_result;
            }
            return Value{ .integer = 0 };
        }
        if (std.ascii.eqlIgnoreCase(method, "getQueryLocator")) {
            const ql = try self.arena.create(types.ObjectInstance);
            ql.* = .{ .class_name = "Database.QueryLocator" };
            if (args.len > 0 and args[0] == .string) {
                try ql.fields.put(self.arena, "query", args[0]);
            } else if (args.len > 0 and args[0] == .list) {
                try ql.fields.put(self.arena, "records", args[0]);
            }
            return Value{ .object = ql };
        }
        if (std.ascii.eqlIgnoreCase(method, "emptyRecycleBin")) {
            // Database.emptyRecycleBin permanently deletes records from the recycle bin.
            // Count it as a DML operation.
            self.limits_dml += 1;
            if (args.len > 0 and args[0] == .list) {
                self.limits_dml_rows += @intCast(args[0].list.items.items.len);
            } else if (args.len > 0) {
                self.limits_dml_rows += 1;
            }
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "setSavepoint")) {
            // Setting a savepoint counts as a DML statement in Apex's governor
            // limits, matching real platform semantics.
            self.limits_dml += 1;
            const sp = try self.arena.create(types.ObjectInstance);
            sp.* = .{ .class_name = "Database.SavePoint" };
            return Value{ .object = sp };
        }
        if (std.ascii.eqlIgnoreCase(method, "rollback")) {
            // Database.rollback(savepoint) also counts as a DML statement.
            self.limits_dml += 1;
            return .void_val;
        }
        if (std.ascii.eqlIgnoreCase(method, "executeBatch")) {
            // Batch runs in separate transaction — save/restore limits
            const sb_dml = self.limits_dml;
            const sb_dml_rows = self.limits_dml_rows;
            const sb_soql = self.limits_soql;
            const sb_pub = self.limits_publish_immediate;
            const sb_call = self.limits_callouts;
            defer {
                self.limits_dml = sb_dml;
                self.limits_dml_rows = sb_dml_rows;
                self.limits_soql = sb_soql;
                self.limits_publish_immediate = sb_pub;
                self.limits_callouts = sb_call;
            }

            if (args.len > 0 and args[0] == .object) {
                if (self.batch_job_runner_active or self.batch_lifecycle_depth > 0) {
                    const job_id = try self.create_async_apex_job(
                        "BatchApex",
                        args[0].object.class_name,
                        "execute",
                    );
                    try args[0].object.fields.put(
                        self.arena,
                        "__batchJobId",
                        Value{ .string = job_id },
                    );
                    if (self.active_batch_context) |batch_context| {
                        try batch_context.fields.put(
                            self.arena,
                            "ChildJobId",
                            Value{ .string = job_id },
                        );
                    }
                    if (self.batch_job_runner_active) {
                        try self.pending_batch_jobs.append(self.arena, args[0]);
                    }
                    return Value{ .string = job_id };
                }

                const job_id = try self.create_async_apex_job(
                    "BatchApex",
                    args[0].object.class_name,
                    "execute",
                );
                try args[0].object.fields.put(
                    self.arena,
                    "__batchJobId",
                    Value{ .string = job_id },
                );
                self.batch_job_runner_active = true;
                self.pending_batch_jobs = .empty;
                defer {
                    self.pending_batch_jobs = .empty;
                    self.batch_job_runner_active = false;
                }

                try self.pending_batch_jobs.append(self.arena, args[0]);

                var job_index: usize = 0;
                while (job_index < self.pending_batch_jobs.items.len) : (job_index += 1) {
                    const batch_value = self.pending_batch_jobs.items[job_index];
                    if (batch_value != .object) continue;
                    try self.execute_pending_batch_job(batch_value.object);
                }
                return Value{ .string = job_id };
            }
            return Value{ .string = try self.alloc_id() }; // Fake job ID
        }
        if (std.ascii.eqlIgnoreCase(method, "merge")) {
            // Database.merge(primary, secondaries, allOrNothing)
            // Delete secondary records and cascade-delete referencing DuplicateRecordItems.
            // Return MergeResult[].
            if (args.len >= 2) {
                var secondary_ids: std.ArrayListUnmanaged([]const u8) = .empty;
                // Collect secondary record ids
                if (args[1] == .sobject and args[1].sobject.id != null) {
                    try secondary_ids.append(self.arena, args[1].sobject.id.?);
                } else if (args[1] == .list) {
                    for (args[1].list.items.items) |item| {
                        if (item == .sobject and item.sobject.id != null) {
                            try secondary_ids.append(self.arena, item.sobject.id.?);
                        }
                    }
                }
                // Delete secondary records from store
                for (secondary_ids.items) |sec_id| {
                    var store_iter = self.store.iterator();
                    while (store_iter.next()) |entry| {
                        var i: usize = 0;
                        while (i < entry.value_ptr.items.len) {
                            if (entry.value_ptr.items[i] == .sobject and entry.value_ptr.items[i].sobject.id != null and
                                std.mem.eql(u8, entry.value_ptr.items[i].sobject.id.?, sec_id))
                            {
                                _ = entry.value_ptr.orderedRemove(i);
                            } else {
                                i += 1;
                            }
                        }
                    }
                }
                // Cascade-delete DuplicateRecordItems that reference deleted secondary records
                if (self.store.getPtr("DuplicateRecordItem")) |dri_records| {
                    var i: usize = 0;
                    while (i < dri_records.items.len) {
                        const item = dri_records.items[i];
                        if (item == .sobject) {
                            const rec_id_val = utils.sobject_get(&item.sobject.fields, "RecordId");
                            if (rec_id_val != null and rec_id_val.? == .string) {
                                var is_deleted = false;
                                for (secondary_ids.items) |sec_id| {
                                    if (std.mem.eql(u8, rec_id_val.?.string, sec_id)) {
                                        is_deleted = true;
                                        break;
                                    }
                                }
                                if (is_deleted) {
                                    // Update RecordCount on parent DRS before removing
                                    self.update_duplicate_record_set_count(
                                        item.sobject,
                                        -1,
                                    ) catch {};
                                    _ = dri_records.orderedRemove(i);
                                    continue;
                                }
                            }
                        }
                        i += 1;
                    }
                }
            }
            // Auto-delete orphaned DuplicateRecordSets after merge
            try self.cleanup_orphaned_duplicate_record_sets();
            // Return MergeResult list
            const mr_list = try self.arena.create(types.ListValue);
            mr_list.* = .{};
            const mr = try self.arena.create(types.ObjectInstance);
            mr.* = .{ .class_name = "Database.MergeResult" };
            try mr.fields.put(self.arena, "isSuccess", Value{ .boolean = true });
            try mr.fields.put(self.arena, "success", Value{ .boolean = true });
            try mr_list.items.append(self.arena, Value{ .object = mr });
            return Value{ .list = mr_list };
        }
        return .void_val;
    }

    fn handle_system_method(
        self: *Evaluator,
        inner: []const u8,
        method: []const u8,
        args: []const Value,
        current_env: *Env,
    ) !Value {
        // System.enqueue_job → execute the Queueable's execute method synchronously
        // Queueable runs in a separate transaction in Salesforce, so save/restore limits
        if (std.ascii.eqlIgnoreCase(inner, "enqueue_job") and args.len > 0 and args[0] == .object) {
            return self.enqueue_job(args[0].object);
        }
        if (std.ascii.eqlIgnoreCase(inner, "enqueue_job")) return .void_val;
        if (std.ascii.eqlIgnoreCase(inner, "attachFinalizer")) {
            if (self.active_queueable_job_id != null and args.len > 0 and args[0] == .object) {
                self.attached_finalizer = args[0].object;
            }
            return .void_val;
        }
        // System.runAs → now handled by run_as_stmt in the AST; this is a fallback no-op
        if (std.ascii.eqlIgnoreCase(inner, "runAs")) {
            return .void_val;
        }
        // System.schedule → store cron expression and return unique job ID
        if (std.ascii.eqlIgnoreCase(inner, "schedule")) {
            const job_id = try std.fmt.allocPrint(self.arena, "08e{d:0>15}", .{self.next_id});
            self.next_id += 1;
            // args: (jobName, cronExpression, schedulableInstance)
            if (args.len >= 2 and args[1] == .string) {
                try self.scheduled_jobs.put(self.arena, job_id, args[1].string);
            }
            if (args.len >= 3 and args[2] == .object) {
                try self.pending_schedulables.append(self.arena, args[2]);
            }
            return Value{ .string = job_id };
        }
        // System.abortJob → no-op
        if (std.ascii.eqlIgnoreCase(inner, "abortJob")) return .void_val;
        // System.debug
        if (std.ascii.eqlIgnoreCase(inner, "debug") and args.len > 0) {
            const msg = try utils.coerce_to_string(args[0], self.arena);
            try self.stdout.appendSlice(self.arena, msg);
            try self.stdout.append(self.arena, '\n');
            return .void_val;
        }
        // System.Request.getCurrent() → return a Request object
        if (std.ascii.eqlIgnoreCase(inner, "Request")) {
            var bctx = builtins.BuiltinContext{ .arena = self.arena, .stdout = &self.stdout, .pending_exception = &self.pending_exception, .see_all_data = self.see_all_data, .eval = self };
            if (try builtins.dispatch_static(
                &bctx,
                "Request",
                method,
                args,
            )) |result| return result;
            const obj = try self.arena.create(types.ObjectInstance);
            obj.* = .{ .class_name = "Request" };
            return Value{ .object = obj };
        }
        // System.AccessType/AccessLevel
        if (std.ascii.eqlIgnoreCase(inner, "AccessType") or
            std.ascii.eqlIgnoreCase(inner, "AccessLevel"))
        {
            return Value{ .string = method };
        }
        // System.LoggingLevel / System.TriggerOperation
        if (std.ascii.eqlIgnoreCase(inner, "LoggingLevel") or
            std.ascii.eqlIgnoreCase(inner, "TriggerOperation"))
        {
            // valueOf(name) → return the enum value string, throw NoSuchElementException for
            // invalid values
            if (std.ascii.eqlIgnoreCase(method, "valueOf") and
                args.len > 0 and
                args[0] == .string)
            {
                const valid_values: []const []const u8 =
                    if (std.ascii.eqlIgnoreCase(inner, "LoggingLevel"))
                        &.{ "INTERNAL", "FINEST", "FINER", "FINE", "DEBUG", "INFO", "WARN", "ERROR", "NONE" }
                    else
                        &.{ "BEFORE_INSERT", "BEFORE_UPDATE", "BEFORE_DELETE", "AFTER_INSERT", "AFTER_UPDATE", "AFTER_DELETE", "AFTER_UNDELETE" };
                for (valid_values) |v| {
                    if (std.ascii.eqlIgnoreCase(args[0].string, v)) return Value{ .string = v };
                }
                const exc = try self.arena.create(types.ObjectInstance);
                exc.* = .{ .class_name = "System.NoSuchElementException" };
                try exc.fields.put(self.arena, "message", Value{ .string = try std.fmt.allocPrint(self.arena, "No enum constant System.{s}.{s}", .{ inner, args[0].string }) });
                self.pending_exception = Value{ .object = exc };
                return error.ApexException;
            }
            // values() → return list of all values
            if (std.ascii.eqlIgnoreCase(method, "values")) {
                const list = try self.arena.create(types.ListValue);
                list.* = .{};
                if (std.ascii.eqlIgnoreCase(inner, "LoggingLevel")) {
                    const names = [_][]const u8{ "INTERNAL", "FINEST", "FINER", "FINE", "DEBUG", "INFO", "WARN", "ERROR", "NONE" };
                    for (names) |name| try list.items.append(self.arena, Value{ .string = name });
                } else {
                    const names = [_][]const u8{ "BEFORE_INSERT", "BEFORE_UPDATE", "BEFORE_DELETE", "AFTER_INSERT", "AFTER_UPDATE", "AFTER_DELETE", "AFTER_UNDELETE" };
                    for (names) |name| try list.items.append(self.arena, Value{ .string = name });
                }
                return Value{ .list = list };
            }
            // ENUM_VALUE → return the value name
            return Value{ .string = method };
        }
        // System.SObjectAccessDecision
        if (std.ascii.eqlIgnoreCase(inner, "SObjectAccessDecision")) {
            return .void_val;
        }
        // System.Limits → all methods return 0
        if (std.ascii.eqlIgnoreCase(inner, "Limits")) {
            var bctx = builtins.BuiltinContext{ .arena = self.arena, .stdout = &self.stdout, .pending_exception = &self.pending_exception, .see_all_data = self.see_all_data, .eval = self };
            if (try builtins.dispatch_static(&bctx, "Limits", method, args)) |result| return result;
            return Value{ .integer = 0 };
        }
        // System.JSON.serialize / System.JSON.deserialize / System.JSON.deserializeUntyped
        if (std.ascii.eqlIgnoreCase(inner, "JSON")) {
            if (std.ascii.eqlIgnoreCase(method, "serialize") or
                std.ascii.eqlIgnoreCase(method, "serializePretty"))
            {
                if (args.len > 0) {
                    if (args[0] == .object and
                        (std.ascii.eqlIgnoreCase(
                            args[0].object.class_name,
                            "Schema.SObjectField",
                        ) or
                            std.ascii.eqlIgnoreCase(args[0].object.class_name, "SObjectField")))
                    {
                        const exc = try self.arena.create(types.ObjectInstance);
                        exc.* = .{ .class_name = "System.JSONException" };
                        try exc.fields.put(
                            self.arena,
                            "message",
                            Value{ .string = "Apex Type unsupported in JSON: Schema.SObjectField" },
                        );
                        self.pending_exception = Value{ .object = exc };
                        return error.ApexException;
                    }
                    return Value{ .string = try utils.to_json(args[0], self.arena) };
                }
                return Value{ .string = "{}" };
            }
            if (std.ascii.eqlIgnoreCase(method, "deserialize") or
                std.ascii.eqlIgnoreCase(method, "deserializeUntyped"))
            {
                if (args.len >= 1 and args[0] == .null_val) {
                    const exc = try self.arena.create(types.ObjectInstance);
                    exc.* = .{ .class_name = "System.JSONException" };
                    try exc.fields.put(
                        self.arena,
                        "message",
                        Value{ .string = "Argument cannot be null." },
                    );
                    self.pending_exception = Value{ .object = exc };
                    return error.ApexException;
                }
                if (args.len >= 1 and args[0] == .string) {
                    const json_str = args[0].string;
                    const trimmed_json = std.mem.trim(u8, json_str, " \t\r\n");
                    // Check balanced braces/brackets for truncated JSON detection
                    if (!utils.is_json_balanced(trimmed_json)) {
                        const exc = try self.arena.create(types.ObjectInstance);
                        exc.* = .{ .class_name = "System.JSONException" };
                        try exc.fields.put(
                            self.arena,
                            "message",
                            Value{ .string = "Unexpected end-of-input" },
                        );
                        self.pending_exception = Value{ .object = exc };
                        return error.ApexException;
                    }
                    // Delegate to builtins for actual parsing
                    var bctx = builtins.BuiltinContext{ .arena = self.arena, .stdout = &self.stdout, .pending_exception = &self.pending_exception, .see_all_data = self.see_all_data, .eval = self };
                    if (try builtins.dispatch_static(
                        &bctx,
                        "JSON",
                        method,
                        args,
                    )) |result| return result;
                    const type_name: []const u8 = if (args.len >= 2 and args[1] == .object) blk: {
                        if (std.ascii.eqlIgnoreCase(args[1].object.class_name, "Type")) {
                            if (args[1].object.fields.get("name")) |n| {
                                if (n == .string) break :blk n.string;
                            }
                        }
                        break :blk args[1].object.class_name;
                    } else "Object";
                    if (self.parse_json_value(json_str, type_name)) |pv| return pv;
                }
                return Value.null_val;
            }
            // JSON.createParser → JSONParser instance with the JSON body stored
            if (std.ascii.eqlIgnoreCase(method, "createParser")) {
                if (args.len >= 1 and args[0] == .string) {
                    const parser_obj = try self.arena.create(types.ObjectInstance);
                    parser_obj.* = .{ .class_name = "JSONParser" };
                    try parser_obj.fields.put(self.arena, "__json_body__", args[0]);
                    return Value{ .object = parser_obj };
                }
                return Value.null_val;
            }
            // Other JSON methods: delegate to builtins
            var bctx2 = builtins.BuiltinContext{ .arena = self.arena, .stdout = &self.stdout, .pending_exception = &self.pending_exception, .see_all_data = self.see_all_data, .eval = self };
            if (try builtins.dispatch_static(&bctx2, "JSON", method, args)) |result| return result;
        }
        // System.Test.startTest / System.Test.stopTest / setMock / etc.
        if (std.ascii.eqlIgnoreCase(inner, "Test")) {
            return self.handle_test(method, args);
        }
        // System.Database.insert / update / delete / upsert / undelete
        if (std.ascii.eqlIgnoreCase(inner, "Database")) {
            return self.handle_database_method(method, args, current_env);
        }
        // System.EventBus.publish → delegate to call_method so it goes through the EventBus.publish
        // handler
        if (std.ascii.eqlIgnoreCase(inner, "EventBus") and
            std.ascii.eqlIgnoreCase(method, "publish"))
        {
            return self.call_method("EventBus", "publish", args) catch .void_val;
        }
        // Generic fallback: delegate System.X.method to builtins.dispatch_static(X, method, args)
        // This covers System.UserInfo, System.Type, System.Assert, System.URL, etc.
        {
            var bctx = builtins.BuiltinContext{ .arena = self.arena, .stdout = &self.stdout, .pending_exception = &self.pending_exception, .see_all_data = self.see_all_data, .eval = self };
            if (try builtins.dispatch_static(&bctx, inner, method, args)) |result| return result;
        }
        return .void_val;
    }

    // -----------------------------------------------------------------------
    // ヘルパー
    // -----------------------------------------------------------------------

    fn handle_test_factory(
        self: *Evaluator,
        class_name: []const u8,
        method_name: []const u8,
        args: []const Value,
    ) !?Value {
        // TestFactory.createSObject(sObj) / createSObject(sObj, doInsert) / createSObject(sObj,
        // className)
        if (std.ascii.eqlIgnoreCase(class_name, "TestFactory")) {
            if (std.ascii.eqlIgnoreCase(method_name, "createSObject")) {
                if (args.len >= 1 and args[0] == .sobject) {
                    // Apply default fields if not set
                    if (utils.sobject_get(&args[0].sobject.fields, "Name") == null) {
                        try args[0].sobject.fields.put(
                            self.arena,
                            "Name",
                            Value{ .string = "Test Record" },
                        );
                    }
                    if (std.ascii.eqlIgnoreCase(args[0].sobject.type_name, "Contact") and
                        utils.sobject_get(&args[0].sobject.fields, "LastName") == null)
                    {
                        try args[0].sobject.fields.put(
                            self.arena,
                            "LastName",
                            Value{ .string = "Test Record" },
                        );
                    }
                    // If second arg is boolean and true, insert
                    if (args.len >= 2 and args[1] == .boolean and args[1].boolean) {
                        try self.insert_record(args[0].sobject);
                    }
                    // If second arg is string, it's a defaults class name — just insert
                    if (args.len >= 2 and args[1] == .string) {
                        try self.insert_record(args[0].sobject);
                    }
                    return args[0];
                }
                return Value.null_val;
            }
            if (std.ascii.eqlIgnoreCase(method_name, "createSObjectList")) {
                // createSObjectList(sObj, count, doInsert)
                var template: ?*types.SObject = null;
                var count: i64 = 5;
                var do_insert = false;

                if (args.len >= 1 and args[0] == .sobject) template = args[0].sobject;
                if (args.len >= 2 and args[1] == .integer) count = args[1].integer;
                if (args.len >= 3 and args[2] == .boolean) do_insert = args[2].boolean;

                const list = try self.arena.create(types.ListValue);
                list.* = .{};
                var i: i64 = 0;
                while (i < count) : (i += 1) {
                    const obj = try self.arena.create(types.SObject);
                    obj.* = .{ .type_name = if (template) |t| t.type_name else "Account" };
                    // Copy template fields
                    if (template) |t| {
                        for (t.fields.keys(), t.fields.values()) |k, v| {
                            try obj.fields.put(self.arena, k, v);
                        }
                    }
                    // Set Name with index
                    const name = try std.fmt.allocPrint(self.arena, "Test Record {d}", .{i});
                    try obj.fields.put(self.arena, "Name", Value{ .string = name });
                    // Set required fields for specific object types
                    if (std.ascii.eqlIgnoreCase(obj.type_name, "Contact") and
                        utils.sobject_get(&obj.fields, "LastName") == null)
                    {
                        try obj.fields.put(self.arena, "LastName", Value{ .string = name });
                    }
                    if (std.ascii.eqlIgnoreCase(obj.type_name, "Opportunity") and
                        utils.sobject_get(&obj.fields, "StageName") == null)
                    {
                        try obj.fields.put(
                            self.arena,
                            "StageName",
                            Value{ .string = "Prospecting" },
                        );
                    }

                    try list.items.append(self.arena, Value{ .sobject = obj });
                }
                // Insert all records with trigger support
                if (do_insert) {
                    self.execute_dml(.insert, Value{ .list = list }) catch |err| {
                        if (err == error.ApexException) return err;
                    };
                }
                return Value{ .list = list };
            }
            if (std.ascii.eqlIgnoreCase(method_name, "assignPermSetToUser")) {
                // Delegate to user-defined TestFactory if available
                var assign_iter = self.classes.iterator();
                while (assign_iter.next()) |entry| {
                    if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, "TestFactory")) {
                        if (self.find_best_method_in_class(
                            entry.value_ptr.*,
                            method_name,
                            args,
                        ) != null) {
                            return null; // Fall through to user-defined class
                        }
                    }
                }
                return .void_val;
            }
            if (std.ascii.eqlIgnoreCase(method_name, "createTestUser") or
                std.ascii.eqlIgnoreCase(method_name, "createMinAccessUser") or
                std.ascii.eqlIgnoreCase(method_name, "createMarketingUser"))
            {
                // If user-defined TestFactory class has this method, delegate to it
                var class_iter = self.classes.iterator();
                while (class_iter.next()) |entry| {
                    if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, "TestFactory")) {
                        if (self.find_best_method_in_class(
                            entry.value_ptr.*,
                            method_name,
                            args,
                        ) != null) {
                            return null; // Let the caller fall through to user-defined class
                        }
                    }
                }
                // Fallback: create a minimal user stub
                const user = try self.arena.create(types.SObject);
                user.* = .{ .type_name = "User" };
                try user.fields.put(self.arena, "Name", Value{ .string = "Test User" });
                const user_id = try self.alloc_id();
                try user.fields.put(self.arena, "Id", Value{ .string = user_id });
                user.id = user_id;
                // Set profile info based on method name
                const profile = try self.arena.create(types.SObject);
                profile.* = .{ .type_name = "Profile" };
                if (std.ascii.eqlIgnoreCase(method_name, "createMinAccessUser")) {
                    try profile.fields.put(
                        self.arena,
                        "Name",
                        Value{ .string = "Minimum Access - Salesforce" },
                    );
                } else if (std.ascii.eqlIgnoreCase(method_name, "createMarketingUser")) {
                    try profile.fields.put(self.arena, "Name", Value{ .string = "Marketing User" });
                } else {
                    try profile.fields.put(self.arena, "Name", Value{ .string = "Standard User" });
                }
                try user.fields.put(self.arena, "Profile", Value{ .sobject = profile });
                // Insert if first arg is true (or for createMinAccessUser/createMarketingUser)
                if (args.len >= 1 and args[0] == .boolean and args[0].boolean) {
                    try self.insert_record(user);
                }
                return Value{ .sobject = user };
            }
            return null;
        }

        // TestDataHelpers
        if (std.ascii.eqlIgnoreCase(class_name, "TestDataHelpers")) {
            // If user-defined TestDataHelpers class has this method, delegate to it
            var tdh_iter = self.classes.iterator();
            while (tdh_iter.next()) |entry| {
                if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, "TestDataHelpers")) {
                    if (self.find_best_method_in_class(
                        entry.value_ptr.*,
                        method_name,
                        args,
                    ) != null) {
                        return null; // Fall through to user-defined class
                    }
                }
            }
            if (std.ascii.eqlIgnoreCase(method_name, "createAccount")) {
                const acct = try self.arena.create(types.SObject);
                acct.* = .{ .type_name = "Account" };
                try acct.fields.put(self.arena, "Name", Value{ .string = "Awesome Test Account" });
                // Check if shipping country arg provided
                if (args.len >= 2 and args[1] == .string and args[1].string.len > 0) {
                    try acct.fields.put(self.arena, "ShippingCountry", args[1]);
                }
                try self.insert_record(acct);
                return Value{ .sobject = acct };
            }
            if (std.ascii.eqlIgnoreCase(method_name, "genXnumberOfAccounts")) {
                const count = if (args.len >= 1 and args[0] == .integer) args[0].integer else 5;
                const list = try self.arena.create(types.ListValue);
                list.* = .{};
                var i: i64 = 0;
                while (i < count) : (i += 1) {
                    const acct = try self.arena.create(types.SObject);
                    acct.* = .{ .type_name = "Account" };
                    const name = try std.fmt.allocPrint(
                        self.arena,
                        "Awesome Test Account {d}",
                        .{i},
                    );
                    try acct.fields.put(self.arena, "Name", Value{ .string = name });
                    try list.items.append(self.arena, Value{ .sobject = acct });
                }
                return Value{ .list = list };
            }
            if (std.ascii.eqlIgnoreCase(method_name, "genAccountWithOptions")) {
                const acct = try self.arena.create(types.SObject);
                acct.* = .{ .type_name = "Account" };
                try acct.fields.put(self.arena, "Name", Value{ .string = "Awesome Test Account" });
                try acct.fields.put(
                    self.arena,
                    "ShippingStreet",
                    Value{ .string = "123 Sessame St." },
                );
                try acct.fields.put(self.arena, "ShippingCity", Value{ .string = "Wehawkin" });
                // First arg is setCountry (not doInsert)
                if (args.len >= 1 and args[0] == .boolean and args[0].boolean) {
                    if (args.len >= 2 and args[1] == .string) {
                        try acct.fields.put(self.arena, "ShippingCountry", args[1]);
                    }
                }
                return Value{ .sobject = acct };
            }
            if (std.ascii.eqlIgnoreCase(method_name, "genContactForAccount")) {
                const contact = try self.arena.create(types.SObject);
                contact.* = .{ .type_name = "Contact" };
                try contact.fields.put(self.arena, "LastName", Value{ .string = "Test Contact" });
                try contact.fields.put(self.arena, "Name", Value{ .string = "Test Contact" });
                if (args.len >= 1) {
                    try contact.fields.put(self.arena, "AccountId", args[0]);
                    try contact.fields.put(self.arena, "accountId", args[0]);
                }
                return Value{ .sobject = contact };
            }
            return null;
        }

        // TestHelper
        if (std.ascii.eqlIgnoreCase(class_name, "TestHelper")) {
            // If user-defined TestHelper class has this method, delegate to it
            var th_iter = self.classes.iterator();
            while (th_iter.next()) |entry| {
                if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, "TestHelper")) {
                    if (self.find_best_method_in_class(
                        entry.value_ptr.*,
                        method_name,
                        args,
                    ) != null) {
                        return null; // Fall through to user-defined class
                    }
                }
            }
            if (std.ascii.eqlIgnoreCase(method_name, "getUnknownObjectType")) {
                // Return the class name of the object
                if (args.len > 0) {
                    return switch (args[0]) {
                        .object => |o| Value{ .string = o.class_name },
                        .sobject => |s| Value{ .string = s.type_name },
                        .string => Value{ .string = "String" },
                        .integer => Value{ .string = "Integer" },
                        .long => Value{ .string = "Long" },
                        .double => Value{ .string = "Double" },
                        .boolean => Value{ .string = "Boolean" },
                        .list => Value{ .string = "List" },
                        .map => Value{ .string = "Map" },
                        .set => Value{ .string = "Set" },
                        .null_val => Value{ .string = "null" },
                        .void_val => Value{ .string = "void" },
                    };
                }
                return Value{ .string = "null" };
            }
            return null;
        }

        return null;
    }

    /// Create a new instance of the named class and call a method on it.
    pub fn call_instance_method_by_name(
        self: *Evaluator,
        class_name: []const u8,
        method_name: []const u8,
        args: []const Value,
    ) anyerror!Value {
        const class_decl = self.find_class(class_name) orelse return Value.null_val;
        const instance = try self.arena.create(types.ObjectInstance);
        instance.* = .{ .class_name = class_name };
        // Run constructor if exists
        for (class_decl.members) |member| {
            switch (member) {
                .constructor_decl => |cd| {
                    if (cd.params.len == 0) {
                        const ctor_env = try self.global_env.child();
                        try ctor_env.define("this", Value{ .object = instance });
                        _ = self.exec_block(cd.body, ctor_env) catch {};
                        break;
                    }
                },
                else => {},
            }
        }
        return self.call_instance_method(class_decl, instance, method_name, args);
    }

    pub fn call_instance_method_public(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        instance: *types.ObjectInstance,
        method_name: []const u8,
        args: []const Value,
    ) anyerror!Value {
        return self.call_instance_method(class_decl, instance, method_name, args);
    }

    pub fn resolve_full_class_name_public(self: *Evaluator, name: []const u8) []const u8 {
        return self.resolve_full_class_name(name);
    }

    pub fn handle_database_method_public(
        self: *Evaluator,
        method: []const u8,
        args: []const Value,
        env: *Env,
    ) anyerror!Value {
        return self.handle_database_method(method, args, env);
    }

    pub fn value_to_string_public(self: *Evaluator, value: Value) anyerror![]const u8 {
        return self.value_to_string(value);
    }

    pub fn value_hash_code_public(self: *Evaluator, value: Value) anyerror!i64 {
        return self.value_hash_code(value);
    }

    pub fn values_equal_public(self: *Evaluator, left: Value, right: Value) bool {
        return self.values_equal(left, right);
    }

    const ResolvedInstanceMethod = struct {
        owner: *ast.ClassDecl,
        method: *ast.MethodDecl,
    };

    fn value_to_string(self: *Evaluator, value: Value) anyerror![]const u8 {
        if (value == .null_val) return "null";

        if (value == .object) {
            if (value.object.fields.get("__stubProvider__") != null) {
                if (value.object.fields.get("__stubDisplayClassName__")) |display_name| {
                    if (display_name == .string) {
                        return try std.fmt.allocPrint(
                            self.arena,
                            "{s}:[instance]",
                            .{display_name.string},
                        );
                    }
                }
                return utils.coerce_to_string(value, self.arena);
            }
        }

        switch (value) {
            .object, .list, .map, .set, .sobject => {
                const result = self.eval_instance_method(
                    value,
                    "toString",
                    &.{},
                    self.global_env,
                ) catch return utils.coerce_to_string(value, self.arena);
                if (result == .string) return result.string;
            },
            else => {},
        }

        return utils.coerce_to_string(value, self.arena);
    }

    fn string_hash_code(_: *Evaluator, value: []const u8) i64 {
        var result: i32 = 0;
        for (value) |ch| {
            result = result *% 31 +% @as(i32, ch);
        }
        return @as(i64, result);
    }

    fn strict_values_equal(self: *Evaluator, left: Value, right: Value) bool {
        _ = self;
        if (left == .object and right == .object) return left.object == right.object;
        if (left == .sobject and right == .sobject) return left.sobject == right.sobject;
        if (left == .list and right == .list) return left.list == right.list;
        if (left == .map and right == .map) return left.map == right.map;
        if (left == .set and right == .set) return left.set == right.set;
        return utils.value_eql(left, right);
    }

    fn values_equal(self: *Evaluator, left: Value, right: Value) bool {
        if (left == .list and right == .list) return self.lists_equal(left.list, right.list);
        if (left == .map and right == .map) return self.maps_equal(left.map, right.map);
        if (left == .set and right == .set) return self.sets_equal(left.set, right.set);
        if (left == .object and right == .object) {
            if (utils.value_eql(left, right)) return true;
            if (builtin_value_classes_equal(left.object, right.object)) |result| return result;
            if (self.try_user_equals(left.object, right)) |result| return result;
            if (self.try_user_equals(right.object, left)) |result| return result;
        }
        return utils.value_eql(left, right);
    }

    fn lists_equal(self: *Evaluator, a: *types.ListValue, b: *types.ListValue) bool {
        if (a == b) return true;
        if (a.items.items.len != b.items.items.len) return false;
        for (a.items.items, b.items.items) |x, y| {
            if (!self.values_equal(x, y)) return false;
        }
        return true;
    }

    fn maps_equal(self: *Evaluator, a: *types.MapValue, b: *types.MapValue) bool {
        if (a == b) return true;
        if (a.entries.count() != b.entries.count()) return false;
        for (a.entries.keys(), a.entries.values()) |key, left_value| {
            const right_value = b.entries.get(key) orelse return false;
            if (!self.values_equal(left_value, right_value)) return false;
        }
        return true;
    }

    fn sets_equal(self: *Evaluator, a: *types.SetValue, b: *types.SetValue) bool {
        if (a == b) return true;
        if (a.entries.count() != b.entries.count()) return false;
        outer: for (a.entries.values()) |left_item| {
            for (b.entries.values()) |right_item| {
                if (self.values_equal(left_item, right_item)) continue :outer;
            }
            return false;
        }
        return true;
    }

    /// Built-in value classes (Date / Datetime / Time / Blob) compare by the
    /// stored "value" field rather than ObjectInstance identity. Returns null
    /// when the pair isn't a matched built-in-value class — the caller should
    /// continue with user-defined equals() resolution.
    fn builtin_value_classes_equal(
        left: *types.ObjectInstance,
        right: *types.ObjectInstance,
    ) ?bool {
        if (!std.ascii.eqlIgnoreCase(left.class_name, right.class_name)) return null;
        const cn = left.class_name;
        const is_builtin = std.ascii.eqlIgnoreCase(cn, "Date") or
            std.ascii.eqlIgnoreCase(cn, "Datetime") or
            std.ascii.eqlIgnoreCase(cn, "Time") or
            std.ascii.eqlIgnoreCase(cn, "Blob");
        if (!is_builtin) return null;
        const lv = left.fields.get("value") orelse Value.null_val;
        const rv = right.fields.get("value") orelse Value.null_val;
        if (lv == .string and rv == .string) return std.mem.eql(u8, lv.string, rv.string);
        return null;
    }

    /// Try dispatching a user-defined equals(...) on `subject.class_name`.
    /// Returns null when the class doesn't declare one; otherwise the boolean
    /// outcome of the call (false when the call throws).
    fn try_user_equals(
        self: *Evaluator,
        subject: *types.ObjectInstance,
        other: Value,
    ) ?bool {
        const subject_class = self.find_class(subject.class_name) orelse return null;
        const has_typed = self.find_method_in_hierarchy_typed(
            null,
            subject_class,
            "equals",
            &.{other},
        ) != null;
        const has_arity = self.find_method_in_hierarchy(null, subject_class, "equals", 1) != null;
        if (!has_typed and !has_arity) return null;
        const result = self.call_instance_method(
            subject_class,
            subject,
            "equals",
            &.{other},
        ) catch return false;
        return result == .boolean and result.boolean;
    }

    fn value_hash_code(self: *Evaluator, value: Value) anyerror!i64 {
        return switch (value) {
            .null_val => 0,
            .boolean => |b| if (b) 1231 else 1237,
            .integer => |i| i,
            .long => |i| i,
            .double => |d| @intFromFloat(d),
            .string => |s| self.string_hash_code(s),
            .sobject => |sob| blk: {
                if (sob.id) |id| break :blk self.string_hash_code(id);
                const json = try utils.to_json(value, self.arena);
                break :blk self.string_hash_code(json);
            },
            .list => |list| try self.list_hash_code(list),
            .map => |map| try self.map_hash_code(map),
            .set => |set| try self.set_hash_code(set),
            .object => |obj| try self.object_hash_code(obj),
            .void_val => 0,
        };
    }

    fn list_hash_code(self: *Evaluator, list: *types.ListValue) anyerror!i64 {
        var result: i64 = 1;
        for (list.items.items) |item| {
            result = result *% 31 +% try self.value_hash_code(item);
        }
        return result;
    }

    fn map_hash_code(self: *Evaluator, map: *types.MapValue) anyerror!i64 {
        var result: i64 = 1;
        for (map.entries.keys(), map.entries.values()) |key, entry_value| {
            result = result *% 31 +% self.string_hash_code(key);
            result = result *% 31 +% try self.value_hash_code(entry_value);
        }
        return result;
    }

    fn set_hash_code(self: *Evaluator, set: *types.SetValue) anyerror!i64 {
        var result: i64 = 1;
        for (set.entries.values()) |item| {
            result = result *% 31 +% try self.value_hash_code(item);
        }
        return result;
    }

    fn object_hash_code(self: *Evaluator, obj: *types.ObjectInstance) anyerror!i64 {
        if (try self.builtin_identity_hash_code(obj)) |v| return v;
        if (try self.try_user_hash_code(obj)) |v| return v;
        if (obj.fields.get("__hashCode__")) |existing| {
            if (existing == .integer) return existing.integer;
        }
        const generated = @as(i64, @intCast(@intFromPtr(obj) & 0x7fffffff));
        try obj.fields.put(self.arena, "__hashCode__", Value{ .integer = generated });
        return generated;
    }

    /// Hash codes for built-in Type/Schema.SObjectType/SObjectField tokens
    /// (which compare by their `name`/`fieldName`), plus Date/Datetime/Blob
    /// (which hash their stored `value` string). Returns null when `obj` is
    /// a plain user ObjectInstance.
    fn builtin_identity_hash_code(self: *Evaluator, obj: *types.ObjectInstance) anyerror!?i64 {
        if (std.ascii.eqlIgnoreCase(obj.class_name, "Type") or
            std.ascii.eqlIgnoreCase(obj.class_name, "Schema.SObjectType") or
            std.ascii.eqlIgnoreCase(obj.class_name, "Schema.SObjectField") or
            std.ascii.eqlIgnoreCase(obj.class_name, "SObjectField"))
        {
            const name_value = obj.fields.get("name") orelse
                obj.fields.get("fieldName") orelse Value.null_val;
            if (name_value == .string) return self.string_hash_code(name_value.string);
        }
        if (std.ascii.eqlIgnoreCase(obj.class_name, "Date") or
            std.ascii.eqlIgnoreCase(obj.class_name, "Datetime") or
            std.ascii.eqlIgnoreCase(obj.class_name, "Blob"))
        {
            if (obj.fields.get("value")) |raw_value| {
                if (raw_value == .string) return self.string_hash_code(raw_value.string);
            }
        }
        return null;
    }

    fn try_user_hash_code(self: *Evaluator, obj: *types.ObjectInstance) anyerror!?i64 {
        const class_decl = self.find_class(obj.class_name) orelse return null;
        const has_typed = self.find_method_in_hierarchy_typed(
            null,
            class_decl,
            "hashCode",
            &.{},
        ) != null;
        const has_arity = self.find_method_in_hierarchy(null, class_decl, "hashCode", 0) != null;
        if (!has_typed and !has_arity) return null;
        const result = self.call_instance_method(
            class_decl,
            obj,
            "hashCode",
            &.{},
        ) catch Value{ .integer = 0 };
        return switch (result) {
            .integer => |i| i,
            .double => |d| @as(i64, @intFromFloat(d)),
            else => null,
        };
    }

    fn call_instance_method(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        instance: *types.ObjectInstance,
        method_name: []const u8,
        args: []const Value,
    ) anyerror!Value {
        const actual_class = self.find_class(instance.class_name);
        return self.call_instance_method_resolved(
            class_decl,
            actual_class,
            instance,
            method_name,
            args,
        );
    }

    fn call_super_instance_method(
        self: *Evaluator,
        super_decl: *ast.ClassDecl,
        instance: *types.ObjectInstance,
        method_name: []const u8,
        args: []const Value,
    ) anyerror!Value {
        return self.call_instance_method_resolved(super_decl, null, instance, method_name, args);
    }

    fn call_instance_method_resolved(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        actual_class: ?*ast.ClassDecl,
        instance: *types.ObjectInstance,
        method_name: []const u8,
        args: []const Value,
    ) anyerror!Value {
        self.call_depth +|= 1;
        defer self.call_depth -|= 1;

        if (self.call_depth > self.max_call_depth) {
            return .null_val;
        }
        // Push call frame for stack trace generation (use current_call_line set by caller)
        const frame_line = self.current_call_line;
        self.current_call_line = 0;
        // Lazy static init for the instance's class and its parent hierarchy
        self.ensure_static_init(instance.class_name);
        self.ensure_static_init(class_decl.name);
        if (class_decl.super_class) |sc| self.ensure_static_init(sc.name);
        // For virtual dispatch: find method in instance's actual class first (child override),
        // then in the provided class_decl, then in parent classes.
        // `actual_class = null` is used for super.method() dispatch.
        const resolved = self.find_resolved_method_in_hierarchy_typed(
            actual_class,
            class_decl,
            method_name,
            args,
        ) orelse
            self.find_resolved_method_in_hierarchy(actual_class, class_decl, method_name, args.len);

        if (resolved) |rm| {
            const owner_decl = rm.owner;
            const method = rm.method;
            const frame_class_name: []const u8 = blk: {
                if (std.mem.lastIndexOfScalar(u8, instance.class_name, '.')) |di| {
                    if (std.ascii.eqlIgnoreCase(instance.class_name[di + 1 ..], owner_decl.name)) {
                        break :blk instance.class_name;
                    }
                }
                break :blk owner_decl.name;
            };
            try self.call_stack.append(
                self.arena,
                .{ .class_name = frame_class_name, .method_name = method_name, .line = frame_line },
            );
            defer _ = self.call_stack.pop();

            const method_env = try self.global_env.child();
            try method_env.define("this", Value{ .object = instance });
            // Define instance fields as local variables FIRST
            for (instance.fields.keys(), instance.fields.values()) |k, v| {
                method_env.set(k, v) catch {
                    try method_env.define(k, v);
                };
            }
            // Then define method parameters (so they shadow instance fields with same name).
            // Always use define_typed — instance-field pre-loads above set the value but no
            // declared type, so a later identifier lookup that reads `get_declared_type` to
            // distinguish "real param binding" from "stale ctor pre-load" would otherwise
            // misclassify the parameter and fall back to instance.fields (bug:
            // nothingToProcessShouldExitEarly).
            for (method.params, 0..) |param, i| {
                const val = if (i < args.len) try self.prepare_method_arg_value(args[i]) else Value.null_val;
                const declared_type = self.render_type_ref(param.type_ref);
                try method_env.define_typed(
                    param.name,
                    self.annotate_declared_collection_type(val, declared_type),
                    declared_type,
                );
            }
            const saved_class = self.current_class;
            self.current_class = owner_decl.name;
            defer self.current_class = saved_class;

            const batch_lifecycle = self.is_batch_lifecycle_method(owner_decl.name, method_name) or
                self.is_batch_lifecycle_method(instance.class_name, method_name);
            if (batch_lifecycle) self.batch_lifecycle_depth += 1;
            defer {
                if (batch_lifecycle) self.batch_lifecycle_depth -= 1;
            }

            const result = try self.exec_block(method.body, method_env);
            // Sync back fields modified via `this.field = value`
            const this_val = method_env.get("this");
            if (this_val != null and this_val.? == .object) {
                const updated = this_val.?.object;
                if (updated == instance) {
                    // Same pointer, fields already updated in place
                } else {
                    // Copy fields back
                    for (updated.fields.keys(), updated.fields.values()) |k, v| {
                        instance.fields.put(self.arena, k, v) catch {};
                    }
                }
            }
            // Sync instance field values back to the method env so that bare
            // identifier access sees updates made by the method body via this.field = ...
            // Skip fields whose name matches a parameter to avoid overwriting parameters.
            for (instance.fields.keys(), instance.fields.values()) |fk, fv| {
                var is_param = false;
                for (method.params) |p| {
                    if (std.ascii.eqlIgnoreCase(p.name, fk)) {
                        is_param = true;
                        break;
                    }
                }
                if (!is_param) {
                    method_env.set(fk, fv) catch {};
                }
            }
            const final_result = switch (result) {
                .return_val => |v| v,
                else => blk: {
                    // Fluent pattern: if method return type matches the class (or parent),
                    // return `this` instead of void. This enables method chaining.
                    if (method.return_type.name.len > 0 and
                        !std.ascii.eqlIgnoreCase(method.return_type.name, "void"))
                    {
                        if (std.ascii.eqlIgnoreCase(method.return_type.name, owner_decl.name) or
                            std.ascii.eqlIgnoreCase(method.return_type.name, instance.class_name))
                        {
                            break :blk Value{ .object = instance };
                        }
                        // Check if return type matches a parent class
                        if (owner_decl.super_class) |sc| {
                            if (std.ascii.eqlIgnoreCase(method.return_type.name, sc.name)) {
                                break :blk Value{ .object = instance };
                            }
                        }
                    }
                    break :blk self.return_value;
                },
            };
            return final_result;
        }
        // Try static method as fallback
        return self.call_method(class_decl.name, method_name, args);
    }

    fn find_resolved_method_in_hierarchy_typed(
        self: *Evaluator,
        actual_class: ?*ast.ClassDecl,
        class_decl: *ast.ClassDecl,
        method_name: []const u8,
        args: []const Value,
    ) ?ResolvedInstanceMethod {
        const arg_type_hints = self.cast_type_hints;
        var best: ?ResolvedInstanceMethod = null;
        var best_score: i32 = -1;

        const considerOwner = struct {
            fn run(
                eval: *Evaluator,
                owner: *ast.ClassDecl,
                method_name_inner: []const u8,
                args_inner: []const Value,
                hints: ?[]const ?[]const u8,
                best_inner: *?ResolvedInstanceMethod,
                best_score_inner: *i32,
            ) void {
                for (owner.members) |member| {
                    switch (member) {
                        .method_decl => |md| {
                            if (!std.ascii.eqlIgnoreCase(md.name, method_name_inner) or
                                md.params.len != args_inner.len)
                            {
                                continue;
                            }
                            if (eval.single_method_candidate_score(md, args_inner, hints)) |score| {
                                if (best_inner.* == null or score > best_score_inner.*) {
                                    best_inner.* = .{ .owner = owner, .method = md };
                                    best_score_inner.* = score;
                                }
                            }
                        },
                        else => {},
                    }
                }
            }
        }.run;

        // Walk the runtime-type chain first so intermediate overrides are seen.
        if (actual_class) |ac| {
            var cur: ?*ast.ClassDecl = ac;
            while (cur) |cd| {
                considerOwner(self, cd, method_name, args, arg_type_hints, &best, &best_score);
                cur = if (cd.super_class) |sc| self.find_class(sc.name) else null;
            }
        }

        considerOwner(self, class_decl, method_name, args, arg_type_hints, &best, &best_score);

        var current: ?*ast.ClassDecl = class_decl;
        while (current) |cd| {
            if (cd.super_class) |sc| {
                const parent = self.find_class(sc.name) orelse break;
                considerOwner(self, parent, method_name, args, arg_type_hints, &best, &best_score);
                current = parent;
            } else break;
        }

        return best;
    }

    fn find_resolved_method_in_hierarchy(
        self: *Evaluator,
        actual_class: ?*ast.ClassDecl,
        class_decl: *ast.ClassDecl,
        method_name: []const u8,
        arg_count: usize,
    ) ?ResolvedInstanceMethod {
        // Walk the runtime-type chain first so intermediate overrides are seen.
        if (actual_class) |ac| {
            var cur: ?*ast.ClassDecl = ac;
            while (cur) |cd| {
                if (self.find_method_in_class(
                    cd,
                    method_name,
                    arg_count,
                )) |md| return .{ .owner = cd, .method = md };
                cur = if (cd.super_class) |sc| self.find_class(sc.name) else null;
            }
        }
        if (self.find_method_in_class(
            class_decl,
            method_name,
            arg_count,
        )) |md| return .{ .owner = class_decl, .method = md };
        var current: ?*ast.ClassDecl = class_decl;
        while (current) |cd| {
            if (cd.super_class) |sc| {
                const parent = self.find_class(sc.name);
                if (parent) |p| {
                    if (self.find_method_in_class(
                        p,
                        method_name,
                        arg_count,
                    )) |md| return .{ .owner = p, .method = md };
                    current = p;
                } else break;
            } else break;
        }
        return null;
    }

    /// Type-aware version of find_method_in_hierarchy. Walks the runtime (child)
    /// type chain first so intermediate overrides aren't skipped.
    fn find_method_in_hierarchy_typed(
        self: *Evaluator,
        actual_class: ?*ast.ClassDecl,
        class_decl: *ast.ClassDecl,
        method_name: []const u8,
        args: []const Value,
    ) ?*ast.MethodDecl {
        if (actual_class) |ac| {
            var cur: ?*ast.ClassDecl = ac;
            while (cur) |cd| {
                if (self.find_best_method_in_class(cd, method_name, args)) |md| return md;
                cur = if (cd.super_class) |sc| self.find_class(sc.name) else null;
            }
        }
        if (self.find_best_method_in_class(class_decl, method_name, args)) |md| return md;
        var current: ?*ast.ClassDecl = class_decl;
        while (current) |cd| {
            if (cd.super_class) |sc| {
                const parent = self.find_class(sc.name);
                if (parent) |p| {
                    if (self.find_best_method_in_class(p, method_name, args)) |md| return md;
                    current = p;
                } else break;
            } else break;
        }
        return null;
    }

    /// Find a method in the class hierarchy. Searches:
    /// 1. The actual (child) class for overrides
    /// 2. The provided class_decl
    /// 3. Parent classes via super_class chain
    fn find_method_in_hierarchy(
        self: *Evaluator,
        actual_class: ?*ast.ClassDecl,
        class_decl: *ast.ClassDecl,
        method_name: []const u8,
        arg_count: usize,
    ) ?*ast.MethodDecl {
        // Virtual dispatch: walk the full runtime-type chain first (child overrides
        // may live at any intermediate ancestor, not just at the most-derived class).
        if (actual_class) |ac| {
            var cur: ?*ast.ClassDecl = ac;
            while (cur) |cd| {
                if (self.find_method_in_class(cd, method_name, arg_count)) |md| return md;
                cur = if (cd.super_class) |sc| self.find_class(sc.name) else null;
            }
        }
        // Fallback: search from the statically-known declaring class upward
        // (used for super.method() dispatch or when the actual class isn't loaded).
        if (self.find_method_in_class(class_decl, method_name, arg_count)) |md| return md;
        var current: ?*ast.ClassDecl = class_decl;
        while (current) |cd| {
            if (cd.super_class) |sc| {
                const parent = self.find_class(sc.name);
                if (parent) |p| {
                    if (self.find_method_in_class(p, method_name, arg_count)) |md| return md;
                    current = p;
                } else break;
            } else break;
        }
        return null;
    }

    fn find_method_in_class(
        _: *Evaluator,
        class_decl: *ast.ClassDecl,
        method_name: []const u8,
        arg_count: usize,
    ) ?*ast.MethodDecl {
        var best_match: ?*ast.MethodDecl = null;
        for (class_decl.members) |member| {
            switch (member) {
                .method_decl => |md| {
                    if (std.ascii.eqlIgnoreCase(md.name, method_name)) {
                        if (md.params.len == arg_count) return md;
                        if (best_match == null) best_match = md;
                    }
                },
                else => {},
            }
        }
        return best_match;
    }

    /// Type-aware method resolution filtered by static/instance.
    fn find_best_method_in_class_filtered(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        method_name: []const u8,
        args: []const Value,
        static_only: bool,
    ) ?*ast.MethodDecl {
        var candidates: [64]*ast.MethodDecl = undefined;
        var best_any: ?*ast.MethodDecl = null;
        const count = collect_method_candidates_filtered(
            class_decl,
            method_name,
            args.len,
            static_only,
            &candidates,
            &best_any,
        );
        if (count == 0) return best_any;
        if (count == 1) return candidates[0];
        return self.pick_best_candidate(candidates[0..count], args, false);
    }

    /// Type-aware method resolution for overloaded methods.
    /// When multiple methods match by name and arg count, picks the one
    /// whose parameter types best match the actual argument types.
    fn find_best_method_in_class(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        method_name: []const u8,
        args: []const Value,
    ) ?*ast.MethodDecl {
        var candidates: [64]*ast.MethodDecl = undefined;
        var best_any: ?*ast.MethodDecl = null;
        const count = collect_method_candidates_filtered(
            class_decl,
            method_name,
            args.len,
            null,
            &candidates,
            &best_any,
        );
        if (count == 0) return best_any;
        if (count == 1) return candidates[0];
        return self.pick_best_candidate(candidates[0..count], args, true);
    }

    /// Scan `class_decl.members` for methods matching name and arg count.
    /// Fills `candidates` with up-to-buffer-length matches and tracks the
    /// first same-named method as `best_any` (a fallback when no arity match
    /// is found). `static_only`: null = no filter, true = static only,
    /// false = instance only.
    fn collect_method_candidates_filtered(
        class_decl: *ast.ClassDecl,
        method_name: []const u8,
        arg_count: usize,
        static_only: ?bool,
        candidates: []*ast.MethodDecl,
        best_any: *?*ast.MethodDecl,
    ) usize {
        var count: usize = 0;
        for (class_decl.members) |member| {
            switch (member) {
                .method_decl => |md| {
                    if (!std.ascii.eqlIgnoreCase(md.name, method_name)) continue;
                    if (static_only) |want_static| {
                        if (md.modifiers.is_static != want_static) continue;
                    }
                    if (md.params.len == arg_count) {
                        if (count < candidates.len) {
                            candidates[count] = md;
                            count += 1;
                        }
                    }
                    if (best_any.* == null) best_any.* = md;
                },
                else => {},
            }
        }
        return count;
    }

    /// Score every candidate and return the highest. `apply_collection_penalty`
    /// switches between the two call sites' slightly different treatments of
    /// the SObject↔List and List↔non-List mismatches.
    fn pick_best_candidate(
        self: *Evaluator,
        candidates: []const *ast.MethodDecl,
        args: []const Value,
        apply_collection_penalty: bool,
    ) *ast.MethodDecl {
        const arg_type_hints = self.cast_type_hints;
        var best: ?*ast.MethodDecl = null;
        var best_score: i32 = -1;
        for (candidates) |md| {
            const score = self.score_candidate_method(
                md,
                args,
                arg_type_hints,
                apply_collection_penalty,
            );
            if (best == null or score > best_score) {
                best_score = score;
                best = md;
            }
        }
        return best orelse candidates[0];
    }

    fn score_candidate_method(
        self: *Evaluator,
        md: *ast.MethodDecl,
        args: []const Value,
        arg_type_hints: ?[]const ?[]const u8,
        apply_collection_penalty: bool,
    ) i32 {
        var score: i32 = 0;
        for (md.params, 0..) |param, i| {
            if (i >= args.len) break;
            const pt = param.type_ref.name;
            const arg = args[i];
            const arg_hint = if (arg_type_hints != null and i < arg_type_hints.?.len)
                arg_type_hints.?[i]
            else
                null;
            if (arg_hint) |hint| {
                const hint_score = self.overload_score_for_type_hint(
                    hint,
                    self.render_type_ref(param.type_ref),
                );
                if (hint_score > 0) {
                    score += hint_score;
                    if (arg == .null_val) continue;
                }
            }
            if (apply_collection_penalty) {
                if (arg == .sobject and std.ascii.eqlIgnoreCase(pt, "List")) {
                    score -= 1;
                    continue;
                }
                if (arg == .list and !std.ascii.eqlIgnoreCase(pt, "List")) {
                    score -= 1;
                    continue;
                }
            }
            score += self.score_candidate_arg(arg, param, pt, arg_hint);
        }
        return score;
    }

    fn score_candidate_arg(
        self: *Evaluator,
        arg: Value,
        param: ast.Param,
        pt: []const u8,
        arg_hint: ?[]const u8,
    ) i32 {
        var arg_score = overload_score_for_arg(arg, pt);
        if (arg_score == 0 and arg == .object and
            self.is_subclass_of(arg.object.class_name, pt))
        {
            arg_score = 2;
        }
        if (arg == .list and std.ascii.eqlIgnoreCase(pt, "List") and
            param.type_ref.params.len > 0)
        {
            arg_score = self.score_list_argument_for_param(arg.list, arg_hint, param.type_ref);
        }
        return arg_score;
    }

    fn find_compatible_method_in_class(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        method_name: []const u8,
        args: []const Value,
    ) ?*ast.MethodDecl {
        var candidates: [64]*ast.MethodDecl = undefined;
        var count: usize = 0;
        for (class_decl.members) |member| {
            switch (member) {
                .method_decl => |md| {
                    if (std.ascii.eqlIgnoreCase(md.name, method_name) and
                        md.params.len == args.len)
                    {
                        if (count < candidates.len) {
                            candidates[count] = md;
                            count += 1;
                        }
                    }
                },
                else => {},
            }
        }

        if (count == 0) return null;

        const arg_type_hints = self.cast_type_hints;
        var best: ?*ast.MethodDecl = null;
        var best_score: i32 = -1;
        for (candidates[0..count]) |md| {
            if (self.single_method_candidate_score(md, args, arg_type_hints)) |score| {
                if (best == null or score > best_score) {
                    best = md;
                    best_score = score;
                }
            }
        }
        return best;
    }

    fn single_method_candidate_score(
        self: *Evaluator,
        md: *ast.MethodDecl,
        args: []const Value,
        arg_type_hints: ?[]const ?[]const u8,
    ) ?i32 {
        var score: i32 = 0;
        for (md.params, 0..) |param, i| {
            if (i >= args.len) break;
            const arg = args[i];
            const rendered_param_type = self.render_type_ref(param.type_ref);
            const param_base = type_base_name(rendered_param_type);
            const arg_hint = if (arg_type_hints != null and i < arg_type_hints.?.len)
                arg_type_hints.?[i]
            else
                null;

            var enum_bridge = false;
            if (arg_hint) |hint| {
                const hint_score = self.overload_score_for_type_hint(hint, rendered_param_type);
                if (hint_score > 0) {
                    score += hint_score;
                    if (arg == .null_val) continue;
                    if (self.arg_bridges_to_enum_param(arg, rendered_param_type)) {
                        enum_bridge = true;
                    }
                }
            }
            if (arg == .null_val) continue;

            const arg_score = self.score_overload_arg(arg, param, param_base, arg_hint) orelse {
                return null;
            };
            if (arg_score <= 0) {
                // Without an enum bridge we reject; with one the hint already
                // credited the match and we skip the argument score.
                if (enum_bridge) continue;
                return null;
            }
            score += arg_score;
        }
        return score;
    }

    /// Enum values are stored as plain strings internally; when a declared
    /// type hint matches an enum-typed parameter, accept the arg even though
    /// `overload_score_for_arg` would score a plain string as 0 against the
    /// enum param.
    fn arg_bridges_to_enum_param(
        self: *Evaluator,
        arg: Value,
        rendered_param_type: []const u8,
    ) bool {
        if (arg != .string) return false;
        if (is_system_enum_type_name(rendered_param_type)) return true;
        const simple_name = if (std.mem.lastIndexOfScalar(u8, rendered_param_type, '.')) |di|
            rendered_param_type[di + 1 ..]
        else
            rendered_param_type;
        return self.find_visible_enum_decl(simple_name) != null;
    }

    /// Score a single argument against a parameter. Returns null when the
    /// match is structurally impossible (e.g. `SObject` passed to `List<...>`).
    /// A score of 0 indicates no positive match; the caller may still accept
    /// the argument via an enum bridge.
    fn score_overload_arg(
        self: *Evaluator,
        arg: Value,
        param: ast.Param,
        param_base: []const u8,
        arg_hint: ?[]const u8,
    ) ?i32 {
        if (arg == .sobject and std.ascii.eqlIgnoreCase(param_base, "List")) return null;
        if (arg == .list) {
            if (std.ascii.eqlIgnoreCase(param_base, "List") or
                std.ascii.eqlIgnoreCase(param_base, "Iterable"))
            {
                return self.score_list_argument_for_param(arg.list, arg_hint, param.type_ref);
            }
            if (std.ascii.eqlIgnoreCase(param_base, "Object")) return 1;
            return null;
        }
        var arg_score = overload_score_for_arg(arg, param.type_ref.name);
        if (arg_score == 0 and
            arg == .string and std.ascii.eqlIgnoreCase(param_base, "Blob")) arg_score = 1;
        if (arg_score == 0 and arg == .object and
            self.is_subclass_of(arg.object.class_name, param.type_ref.name))
        {
            arg_score = 2;
        }
        return arg_score;
    }

    /// If `expr` syntactically accesses an enum value (e.g. `SortOrder.ASCENDING`,
    /// `fflib_QueryFactory.SortOrder.ASCENDING`), return the enum type name for use
    /// as an overload-resolution type hint. Returns null otherwise.
    fn enum_access_type_name(self: *Evaluator, expr: *const ast.Expr) ?[]const u8 {
        if (expr.* != .field_access) return null;
        const fa = expr.field_access;
        // Direct identifier owner: SortOrder.ASCENDING (bare enum) — also handles
        // dotted identifiers the parser collapsed into a single name.
        if (fa.object.* == .identifier) {
            const owner_name = fa.object.identifier.name;
            if (self.find_visible_enum_decl(owner_name)) |ed| {
                for (ed.values) |v| {
                    if (std.ascii.eqlIgnoreCase(v, fa.field)) return ed.name;
                }
            }
            // Qualified identifier "Outer.Enum" that the parser did not split up.
            if (std.mem.lastIndexOfScalar(u8, owner_name, '.')) |di| {
                const outer_name = owner_name[0..di];
                const enum_name = owner_name[di + 1 ..];
                if (self.find_class(outer_name)) |cd| {
                    if (find_enum_in_class_members(cd, enum_name)) |ed| {
                        for (ed.values) |v| {
                            if (std.ascii.eqlIgnoreCase(v, fa.field)) return ed.name;
                        }
                    }
                }
            }
        }
        // Nested owner: ClassName.EnumName.VALUE
        if (fa.object.* == .field_access) {
            const inner = fa.object.field_access;
            if (inner.object.* == .identifier) {
                const outer_name = inner.object.identifier.name;
                const enum_name = inner.field;
                if (self.find_class(outer_name)) |cd| {
                    if (find_enum_in_class_members(cd, enum_name)) |ed| {
                        for (ed.values) |v| {
                            if (std.ascii.eqlIgnoreCase(v, fa.field)) return ed.name;
                        }
                    }
                }
            }
        }
        return null;
    }

    fn find_enum_in_class_members(cd: *ast.ClassDecl, enum_name: []const u8) ?*ast.EnumDecl {
        for (cd.members) |member| {
            switch (member) {
                .enum_decl => |ed| {
                    if (std.ascii.eqlIgnoreCase(ed.name, enum_name)) return ed;
                },
                else => {},
            }
        }
        return null;
    }

    /// True when `arg_str` looks like a value of the enum type named by `param_type`.
    /// Handles both bare enum names ("SortOrder") and qualified forms
    /// ("fflib_QueryFactory.SortOrder").
    fn string_matches_enum_param_type(
        self: *Evaluator,
        arg_str: []const u8,
        param_type: []const u8,
    ) bool {
        if (arg_str.len == 0) return false;
        const simple = if (std.mem.lastIndexOfScalar(
            u8,
            param_type,
            '.',
        )) |di| param_type[di + 1 ..] else param_type;
        if (simple.len == 0) return false;
        // System built-in enums (TriggerOperation, LoggingLevel, AccessType, etc.)
        if (is_system_enum_value(simple, arg_str)) return true;
        if (self.find_visible_enum_decl(simple)) |ed| {
            for (ed.values) |v| {
                if (std.ascii.eqlIgnoreCase(v, arg_str)) return true;
            }
        }
        // Also scan all classes for an enum member with this simple name.
        var iter = self.classes.iterator();
        while (iter.next()) |entry| {
            for (entry.value_ptr.*.members) |member| {
                switch (member) {
                    .enum_decl => |ed| {
                        if (std.ascii.eqlIgnoreCase(ed.name, simple)) {
                            for (ed.values) |v| {
                                if (std.ascii.eqlIgnoreCase(v, arg_str)) return true;
                            }
                        }
                    },
                    else => {},
                }
            }
        }
        return false;
    }

    fn overload_score_for_type_hint(
        self: *Evaluator,
        raw_hint: []const u8,
        raw_param_type: []const u8,
    ) i32 {
        if (std.ascii.eqlIgnoreCase(raw_hint, raw_param_type)) return 6;
        const hint = strip_type_namespace(raw_hint);
        const pt = strip_type_namespace(raw_param_type);
        const hint_base = type_base_name(hint);
        const pt_base = type_base_name(pt);
        const hint_has_generics = std.mem.indexOfScalar(u8, hint, '<') != null;
        const pt_has_generics = std.mem.indexOfScalar(u8, pt, '<') != null;
        if (std.ascii.eqlIgnoreCase(hint, pt)) return 3;
        if (hint_has_generics and pt_has_generics and std.ascii.eqlIgnoreCase(hint_base, pt_base)) {
            if (self.score_generic_container_match(hint, pt, hint_base)) |s| return s;
        }
        if (!(hint_has_generics and pt_has_generics) and
            std.ascii.eqlIgnoreCase(hint_base, pt_base)) return 3;
        if (!(hint_has_generics and pt_has_generics)) {
            if (score_dotted_tail_match(hint_base, pt_base)) |s| return s;
        }
        if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
        if (is_collection_type_name(hint_base)) {
            return score_collection_vs_iterable(hint, pt, hint_base, pt_base, hint_has_generics, pt_has_generics);
        }
        if (self.is_s_object_type_name(hint_base) and
            (std.ascii.eqlIgnoreCase(pt_base, "SObject") or
                std.ascii.eqlIgnoreCase(pt_base, "sObject") or
                std.ascii.eqlIgnoreCase(pt_base, "Sobject")))
        {
            return 3;
        }
        if (self.find_class(hint_base) != null and self.is_subclass_of(hint_base, pt_base))
            return 2;
        return 0;
    }

    /// When hint and param both have the same generic container base (both
    /// `Map<..>` or both `List<..>`/`Set<..>`), compare element types and
    /// accept SObject-typed params for any SObject element. Returns the score
    /// or null when element types disagree.
    fn score_generic_container_match(
        self: *Evaluator,
        hint: []const u8,
        pt: []const u8,
        hint_base: []const u8,
    ) ?i32 {
        if (std.ascii.eqlIgnoreCase(hint_base, "Map")) {
            return self.score_generic_map_match(hint, pt);
        }
        const hint_elem_type = extract_collection_element_type_name(hint) orelse return null;
        const param_elem_type = extract_collection_element_type_name(pt) orelse return null;
        const hint_elem = strip_type_namespace(hint_elem_type);
        const param_elem = strip_type_namespace(param_elem_type);
        if (names_match_by_simple_name(hint_elem, param_elem)) return 3;
        if (std.ascii.eqlIgnoreCase(type_base_name(param_elem), "SObject") and
            self.is_s_object_type_name(type_base_name(hint_elem))) return 3;
        return null;
    }

    fn score_generic_map_match(self: *Evaluator, hint: []const u8, pt: []const u8) ?i32 {
        const hint_args = extract_map_type_args(hint) orelse return null;
        const param_args = extract_map_type_args(pt) orelse return null;
        if (!names_match_by_simple_name(
            strip_type_namespace(hint_args.key),
            strip_type_namespace(param_args.key),
        )) return null;
        const hint_value = strip_type_namespace(hint_args.value);
        const param_value = strip_type_namespace(param_args.value);
        if (names_match_by_simple_name(hint_value, param_value)) return 3;
        if (std.ascii.eqlIgnoreCase(type_base_name(param_value), "SObject") and
            self.is_s_object_type_name(type_base_name(hint_value))) return 3;
        return null;
    }

    /// Match a dotted hint name against its simple tail (and vice versa) so
    /// that `ModeTarget2.Mode` scores against a bare `Mode` parameter. Common
    /// when user code references an inner enum from outside its declaring
    /// class.
    fn score_dotted_tail_match(hint_base: []const u8, pt_base: []const u8) ?i32 {
        if (std.mem.lastIndexOfScalar(u8, hint_base, '.')) |di| {
            if (std.ascii.eqlIgnoreCase(hint_base[di + 1 ..], pt_base)) return 3;
        }
        if (std.mem.lastIndexOfScalar(u8, pt_base, '.')) |di| {
            if (std.ascii.eqlIgnoreCase(pt_base[di + 1 ..], hint_base)) return 3;
        }
        return null;
    }

    fn score_collection_vs_iterable(
        hint: []const u8,
        pt: []const u8,
        hint_base: []const u8,
        pt_base: []const u8,
        hint_has_generics: bool,
        pt_has_generics: bool,
    ) i32 {
        if (!std.ascii.eqlIgnoreCase(pt_base, "Iterable")) return 0;
        if (hint_has_generics and pt_has_generics) {
            const hint_elem_type = extract_collection_element_type_name(hint);
            const param_elem_type = extract_collection_element_type_name(pt);
            if (hint_elem_type != null and param_elem_type != null and names_match_by_simple_name(
                strip_type_namespace(hint_elem_type.?),
                strip_type_namespace(param_elem_type.?),
            )) {
                return if (std.ascii.eqlIgnoreCase(hint_base, "Set")) 4 else 3;
            }
        }
        if (std.ascii.eqlIgnoreCase(hint_base, "Set")) return 2;
        if (std.ascii.eqlIgnoreCase(hint_base, "List")) return 1;
        return 0;
    }

    fn init_instance_fields(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        instance: *types.ObjectInstance,
    ) !void {
        // Set current_class so that unqualified static field references (e.g. BASE_URL)
        // resolve to ClassName.BASE_URL in the global environment.
        const saved_class = self.current_class;
        self.current_class = class_decl.name;
        defer self.current_class = saved_class;

        const init_env = try self.global_env.child();
        try init_env.define("this", Value{ .object = instance });

        for (class_decl.members) |member| {
            switch (member) {
                .field_decl => |fd| {
                    if (!fd.modifiers.is_static) {
                        const val = if (fd.initializer) |init_expr|
                            self.eval_expr(init_expr, init_env) catch Value.null_val
                        else
                            default_value(fd.type_ref);
                        try instance.fields.put(self.arena, fd.name, val);
                        init_env.set(fd.name, val) catch {
                            try init_env.define(fd.name, val);
                        };
                    }
                },
                else => {},
            }
        }
    }

    fn class_has_no_arg_ctor(class_decl: *ast.ClassDecl) bool {
        var has_any_ctor = false;
        for (class_decl.members) |member| {
            switch (member) {
                .constructor_decl => |cd| {
                    has_any_ctor = true;
                    if (cd.params.len == 0) return true;
                },
                else => {},
            }
        }
        // No explicit constructors ⇒ synthetic no-arg default exists.
        return !has_any_ctor;
    }

    fn ctor_starts_with_super_or_this(cd: *ast.ConstructorDecl) bool {
        if (cd.body.len == 0) return false;
        const first = cd.body[0];
        if (first != .expr_stmt) return false;
        const e = first.expr_stmt;
        if (e.* != .call) return false;
        const callee = e.call.callee;
        return std.mem.eql(u8, callee, "super") or std.mem.eql(u8, callee, "this");
    }

    fn find_matching_constructor(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        args: []const Value,
    ) ?*ast.ConstructorDecl {
        var candidates: [8]*ast.ConstructorDecl = undefined;
        var count: usize = 0;
        for (class_decl.members) |member| {
            switch (member) {
                .constructor_decl => |cd| {
                    if (cd.params.len == args.len and count < candidates.len) {
                        candidates[count] = cd;
                        count += 1;
                    }
                },
                else => {},
            }
        }
        if (count == 0) return null;
        if (count == 1) return candidates[0];
        var best: ?*ast.ConstructorDecl = null;
        var best_score: i32 = -1;
        for (candidates[0..count]) |cd| {
            var score: i32 = 0;
            for (cd.params, 0..) |param, i| {
                if (i >= args.len) break;
                const pt = param.type_ref.name;
                const arg = args[i];
                if (arg == .string and
                    (std.ascii.eqlIgnoreCase(pt, "String") or std.ascii.eqlIgnoreCase(pt, "Id")))
                {
                    score += 2;
                } else if (arg == .integer and (std.ascii.eqlIgnoreCase(
                    pt,
                    "Integer",
                ) or std.ascii.eqlIgnoreCase(pt, "int"))) {
                    score += 2;
                } else if (arg == .boolean and std.ascii.eqlIgnoreCase(pt, "Boolean")) {
                    score += 2;
                } else if (arg == .object) {
                    if (std.ascii.eqlIgnoreCase(arg.object.class_name, pt)) {
                        score += 3;
                    } else if (self.is_subclass_of(arg.object.class_name, pt)) {
                        score += 2;
                    }
                } else if (arg == .list and std.ascii.eqlIgnoreCase(pt, "List")) {
                    score += 2;
                }
            }
            if (best == null or score > best_score) {
                best = cd;
                best_score = score;
            }
        }
        return best;
    }

    fn run_constructor(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        instance: *types.ObjectInstance,
        args: []const Value,
    ) anyerror!void {
        // Collect candidates with matching param count
        var candidates: [8]*ast.ConstructorDecl = undefined;
        var count: usize = 0;
        var best_any: ?*ast.ConstructorDecl = null;
        for (class_decl.members) |member| {
            switch (member) {
                .constructor_decl => |cd| {
                    if (cd.params.len == args.len) {
                        if (count < candidates.len) {
                            candidates[count] = cd;
                            count += 1;
                        }
                    }
                    if (best_any == null and (cd.params.len == args.len or args.len == 0))
                        best_any = cd;
                },
                else => {},
            }
        }
        // Pick best candidate using type scoring
        const arg_type_hints = self.cast_type_hints;
        const chosen: ?*ast.ConstructorDecl =
            if (count == 0) best_any else if (count == 1) candidates[0] else blk: {
                var best: ?*ast.ConstructorDecl = null;
                var best_score: i32 = -1;
                for (candidates[0..count]) |cd| {
                    var score: i32 = 0;
                    for (cd.params, 0..) |param, i| {
                        if (i >= args.len) break;
                        const pt = param.type_ref.name;
                        const arg = args[i];
                        const arg_hint = if (arg_type_hints != null and i < arg_type_hints.?.len) arg_type_hints.?[i] else null;
                        if (arg_hint) |hint| {
                            const hint_score = self.overload_score_for_type_hint(
                                hint,
                                self.render_type_ref(param.type_ref),
                            );
                            if (hint_score > 0) score += hint_score;
                        }
                        if (arg == .string and (std.ascii.eqlIgnoreCase(
                            pt,
                            "String",
                        ) or std.ascii.eqlIgnoreCase(pt, "Id"))) {
                            score += 2;
                        } else if (arg == .integer and (std.ascii.eqlIgnoreCase(
                            pt,
                            "Integer",
                        ) or std.ascii.eqlIgnoreCase(pt, "int"))) {
                            score += 2;
                        } else if (arg == .long and std.ascii.eqlIgnoreCase(pt, "Long")) {
                            score += 2;
                        } else if (arg == .boolean and std.ascii.eqlIgnoreCase(pt, "Boolean")) {
                            score += 2;
                        } else if (arg == .object and std.mem.endsWith(u8, pt, "Exception")) {
                            score += 2;
                        } else if (arg == .object) {
                            // Check if the object's class_name matches the param type
                            if (std.ascii.eqlIgnoreCase(arg.object.class_name, pt)) {
                                score += 3;
                            } else if (self.is_subclass_of(arg.object.class_name, pt)) {
                                score += 2;
                            } else {
                                score += 0;
                            }
                        } else if (arg == .list and std.ascii.eqlIgnoreCase(pt, "List")) {
                            score += 2;
                        } else if (arg == .sobject) {
                            const arg_type = arg.sobject.type_name;
                            if (std.ascii.eqlIgnoreCase(arg_type, pt)) {
                                score += 4;
                            } else if (std.mem.lastIndexOfScalar(u8, pt, '.')) |di| {
                                if (std.ascii.eqlIgnoreCase(arg_type, pt[di + 1 ..])) {
                                    score += 4;
                                } else if (std.ascii.eqlIgnoreCase(pt, "SObject") or
                                    std.ascii.eqlIgnoreCase(pt, "sObject") or
                                    std.ascii.eqlIgnoreCase(pt, "Sobject"))
                                {
                                    score += 2;
                                }
                            } else if (std.ascii.eqlIgnoreCase(pt, "SObject") or
                                std.ascii.eqlIgnoreCase(pt, "sObject") or
                                std.ascii.eqlIgnoreCase(pt, "Sobject"))
                            {
                                score += 2;
                            } else {
                                score += 0;
                            }
                        } else if (arg == .null_val) {
                            // Null prefers primitive types (String/Id/Integer/etc) over Exception,
                            // since `null` is most commonly assigned to strings/IDs in Apex code.
                            if (std.ascii.eqlIgnoreCase(pt, "String") or
                                std.ascii.eqlIgnoreCase(pt, "Id"))
                            {
                                score += 2;
                            } else if (std.mem.endsWith(u8, pt, "Exception")) {
                                score += 0;
                            } else {
                                score += 1;
                            }
                        }
                    }
                    if (best == null or score > best_score) {
                        best = cd;
                        best_score = score;
                    }
                }
                break :blk best;
            };
        if (chosen) |cd| {
            const ctor_env = try self.global_env.child();
            try ctor_env.define("this", Value{ .object = instance });
            for (instance.fields.keys(), instance.fields.values()) |k, v| {
                ctor_env.set(k, v) catch {
                    try ctor_env.define(k, v);
                };
            }
            for (cd.params, 0..) |param, pi| {
                const pval = if (pi < args.len) args[pi] else Value.null_val;
                const declared_type = self.render_type_ref(param.type_ref);
                try ctor_env.define_typed(
                    param.name,
                    self.annotate_declared_collection_type(pval, declared_type),
                    declared_type,
                );
            }
            // Push call frame for constructor (use current_call_line from new-expression site)
            const ctor_line = if (self.current_call_line > 0) self.current_call_line else if (cd.loc.line > 0) cd.loc.line else 1;
            self.current_call_line = 0;
            // Prefer the FQ class name for stack traces: if the instance's class_name
            // is an FQ form ("Outer.Inner") and its suffix matches class_decl.name, use it.
            const frame_class_name: []const u8 = blk: {
                if (std.mem.lastIndexOfScalar(u8, instance.class_name, '.')) |di| {
                    if (std.ascii.eqlIgnoreCase(instance.class_name[di + 1 ..], class_decl.name)) {
                        break :blk instance.class_name;
                    }
                }
                break :blk class_decl.name;
            };
            try self.call_stack.append(
                self.arena,
                .{ .class_name = frame_class_name, .method_name = "<init>", .line = ctor_line },
            );
            defer _ = self.call_stack.pop();
            // Track which class's constructor is running (for correct super() dispatch)
            const saved_ctor_class = self.current_constructor_class;
            self.current_constructor_class = class_decl.name;
            defer self.current_constructor_class = saved_ctor_class;
            // Set current_class so unqualified method/field references resolve to this class
            const saved_class = self.current_class;
            self.current_class = class_decl.name;
            defer self.current_class = saved_class;

            _ = try self.exec_block(cd.body, ctor_env);
        }
    }

    fn is_instance_field(_: *Evaluator, class_decl: *ast.ClassDecl, name: []const u8) bool {
        for (class_decl.members) |member| {
            switch (member) {
                .field_decl => |fd| {
                    if (!fd.modifiers.is_static and std.ascii.eqlIgnoreCase(fd.name, name))
                        return true;
                },
                else => {},
            }
        }
        return false;
    }

    const FieldLookup = struct {
        owner_name: []const u8,
        field_decl: *ast.FieldDecl,
    };

    fn find_field_decl_with_owner(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) ?FieldLookup {
        var current = self.find_class(class_name);
        while (current) |cd| {
            for (cd.members) |member| {
                switch (member) {
                    .field_decl => |fd| {
                        if (std.ascii.eqlIgnoreCase(fd.name, field_name)) {
                            return .{ .owner_name = cd.name, .field_decl = fd };
                        }
                    },
                    else => {},
                }
            }
            current = if (cd.super_class) |sc| self.find_class(sc.name) else null;
        }
        return null;
    }

    fn read_static_backing_value(
        self: *Evaluator,
        owner_name: []const u8,
        field_name: []const u8,
    ) Value {
        self.ensure_static_init(owner_name);
        const key = std.fmt.allocPrint(
            self.arena,
            "{s}.{s}",
            .{ owner_name, field_name },
        ) catch return .null_val;
        if (self.global_env.get(key)) |v| return v;
        if (self.find_outer_class_name(owner_name)) |outer| {
            const outer_key = std.fmt.allocPrint(
                self.arena,
                "{s}.{s}",
                .{ outer, field_name },
            ) catch return .null_val;
            if (self.global_env.get(outer_key)) |v| return v;
        }
        return .null_val;
    }

    fn is_parent_instance_field(
        self: *Evaluator,
        class_decl: *ast.ClassDecl,
        name: []const u8,
    ) bool {
        if (class_decl.super_class) |sc| {
            if (self.find_class(sc.name)) |parent| {
                if (self.is_instance_field(parent, name)) return true;
                return self.is_parent_instance_field(parent, name);
            }
        }
        return false;
    }

    pub fn find_class_public(self: *Evaluator, name: []const u8) ?*ast.ClassDecl {
        return self.find_class(name);
    }

    pub fn instantiate_class_public(self: *Evaluator, class_name: []const u8) !Value {
        return self.instantiate_class(class_name);
    }

    /// True for a bare SObject simple name (e.g. "Account", "MyObject__c").
    /// Public wrapper around the internal `is_s_object_type_name` used by builtin dispatch.
    pub fn is_s_object_type_name_public(self: *Evaluator, name: []const u8) bool {
        return self.is_s_object_type_name(name);
    }

    /// Returns true when `name` matches an interface declaration loaded from the source
    /// set, including inner interfaces declared as `Outer.Inner`. Used by the cast path
    /// to decide whether to throw TypeException for a failed interface cast.
    fn is_known_interface_name(self: *Evaluator, name: []const u8) bool {
        if (name.len == 0) return false;
        // Top-level interface?
        var iter = self.classes.iterator();
        while (iter.next()) |entry| {
            const cd = entry.value_ptr.*;
            for (cd.members) |member| {
                switch (member) {
                    .interface_decl => |iface| {
                        // Match either "Outer.Inner" or just "Inner"
                        if (std.ascii.eqlIgnoreCase(iface.name, name)) return true;
                        if (std.mem.lastIndexOfScalar(u8, name, '.')) |di| {
                            if (std.ascii.eqlIgnoreCase(name[0..di], entry.key_ptr.*) and
                                std.ascii.eqlIgnoreCase(name[di + 1 ..], iface.name))
                            {
                                return true;
                            }
                        }
                    },
                    else => {},
                }
            }
        }
        return false;
    }

    fn find_class(self: *Evaluator, name: []const u8) ?*ast.ClassDecl {
        var iter = self.classes.iterator();
        while (iter.next()) |entry| {
            if (std.ascii.eqlIgnoreCase(entry.key_ptr.*, name)) return entry.value_ptr.*;
        }
        return null;
    }

    /// Find the outer (enclosing) class name for a given inner class.
    /// Returns null if the class is not an inner class.
    /// Accepts either simple inner class name ("Inner") or FQ form ("Outer.Inner");
    /// when FQ is passed and the prefix matches an outer class, returns it directly.
    fn find_outer_class_name(self: *Evaluator, inner_class_name: []const u8) ?[]const u8 {
        // Fast path: FQ form "Outer.Inner" → return prefix if it's a registered top-level class
        if (std.mem.lastIndexOfScalar(u8, inner_class_name, '.')) |di| {
            const outer = inner_class_name[0..di];
            if (self.find_class(outer)) |_| return outer;
        }
        const simple = if (std.mem.lastIndexOfScalar(u8, inner_class_name, '.')) |di|
            inner_class_name[di + 1 ..]
        else
            inner_class_name;
        var iter = self.classes.iterator();
        while (iter.next()) |entry| {
            // Skip fully-qualified names (e.g. "Outer.Inner") — only check top-level class entries
            if (std.mem.indexOfScalar(u8, entry.key_ptr.*, '.') != null) continue;
            for (entry.value_ptr.*.members) |member| {
                switch (member) {
                    .class_decl => |inner_cd| {
                        if (std.ascii.eqlIgnoreCase(inner_cd.name, simple))
                            return entry.key_ptr.*;
                    },
                    else => {},
                }
            }
        }
        return null;
    }

    fn register_class_recursive(
        self: *Evaluator,
        ca: std.mem.Allocator,
        cd: *ast.ClassDecl,
        fq_name: ?[]const u8,
    ) !void {
        try self.classes.put(ca, cd.name, cd);
        if (fq_name) |fq| {
            try self.classes.put(ca, fq, cd);
        }
        for (cd.members) |member| {
            switch (member) {
                .field_decl => |fd| {
                    if (fd.modifiers.is_static) {
                        const key = std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ cd.name, fd.name },
                        ) catch continue;
                        self.global_env.define(key, default_value(fd.type_ref)) catch {};
                    }
                },
                .class_decl => |inner_cd| {
                    const parent_name = fq_name orelse cd.name;
                    const inner_fq = std.fmt.allocPrint(
                        ca,
                        "{s}.{s}",
                        .{ parent_name, inner_cd.name },
                    ) catch continue;
                    try self.register_class_recursive(ca, inner_cd, inner_fq);
                },
                .enum_decl => |ed| {
                    for (ed.values) |v| {
                        const ekey = std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}",
                            .{ ed.name, v },
                        ) catch continue;
                        self.global_env.define(ekey, Value{ .string = v }) catch {};
                        const enum_owner = fq_name orelse cd.name;
                        const fq_key = std.fmt.allocPrint(
                            self.arena,
                            "{s}.{s}.{s}",
                            .{ enum_owner, ed.name, v },
                        ) catch continue;
                        self.global_env.define(fq_key, Value{ .string = v }) catch {};
                    }
                },
                else => {},
            }
        }
    }

    fn create_async_apex_job(
        self: *Evaluator,
        apex_job_type: []const u8,
        class_name: []const u8,
        method_name: ?[]const u8,
    ) ![]const u8 {
        const job_id = try std.fmt.allocPrint(self.arena, "707{d:0>15}", .{self.next_id});
        self.next_id += 1;

        const top_level_class = self.find_outer_class_name(class_name) orelse class_name;
        const apex_class_name = if (std.mem.lastIndexOfScalar(
            u8,
            top_level_class,
            '.',
        )) |di| top_level_class[di + 1 ..] else top_level_class;
        const apex_class = try self.arena.create(types.SObject);
        apex_class.* = .{ .type_name = "ApexClass" };
        try apex_class.fields.put(
            self.arena,
            "Id",
            Value{ .string = try std.fmt.allocPrint(self.arena, "01p{d:0>15}", .{self.next_id}) },
        );
        try apex_class.fields.put(self.arena, "Name", Value{ .string = apex_class_name });
        try apex_class.fields.put(self.arena, "NamespacePrefix", Value.null_val);

        const async_job = try self.arena.create(types.SObject);
        async_job.* = .{ .type_name = "AsyncApexJob", .id = job_id };
        try async_job.fields.put(self.arena, "Id", Value{ .string = job_id });
        try async_job.fields.put(self.arena, "Status", Value{ .string = "Completed" });
        try async_job.fields.put(self.arena, "JobType", Value{ .string = apex_job_type });
        try async_job.fields.put(
            self.arena,
            "MethodName",
            if (method_name) |name| Value{ .string = name } else Value.null_val,
        );
        try async_job.fields.put(self.arena, "JobItemsProcessed", Value{ .integer = 0 });
        try async_job.fields.put(self.arena, "NumberOfErrors", Value{ .integer = 0 });
        try async_job.fields.put(self.arena, "ApexClass", Value{ .sobject = apex_class });
        if (utils.sobject_get(&apex_class.fields, "Id")) |apex_class_id| {
            try async_job.fields.put(self.arena, "ApexClassId", apex_class_id);
        }
        try async_job.fields.put(
            self.arena,
            "CreatedById",
            Value{ .string = self.current_user_id },
        );
        const created_by = try self.create_current_user_record();
        if (created_by == .sobject) {
            try async_job.fields.put(self.arena, "CreatedBy", created_by);
        }
        const now_str = builtins.current_date_time_string(self.arena) catch "2026-01-01T00:00:00Z";
        try async_job.fields.put(self.arena, "CreatedDate", Value{ .string = now_str });

        const gop = try self.store.getOrPut(self.arena, "AsyncApexJob");
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        try gop.value_ptr.append(self.arena, Value{ .sobject = async_job });
        try self.id_type_map.put(self.arena, job_id, "AsyncApexJob");
        return job_id;
    }

    fn update_async_apex_job(
        self: *Evaluator,
        job_id: []const u8,
        status: []const u8,
        number_of_errors: i64,
    ) void {
        const jobs = self.store.getPtr("AsyncApexJob") orelse return;
        for (jobs.items) |item| {
            if (item != .sobject or item.sobject.id == null) continue;
            if (!std.ascii.eqlIgnoreCase(item.sobject.id.?, job_id)) continue;
            item.sobject.fields.put(self.arena, "Status", Value{ .string = status }) catch {};
            item.sobject.fields.put(
                self.arena,
                "NumberOfErrors",
                Value{ .integer = number_of_errors },
            ) catch {};
            break;
        }
    }

    fn build_batchable_context(
        self: *Evaluator,
        job_id: []const u8,
        child_job_id: ?[]const u8,
    ) !Value {
        const ctx = try self.arena.create(types.ObjectInstance);
        ctx.* = .{ .class_name = "Database.BatchableContext" };
        try ctx.fields.put(self.arena, "JobId", Value{ .string = job_id });
        try ctx.fields.put(
            self.arena,
            "ChildJobId",
            if (child_job_id) |child| Value{ .string = child } else Value.null_val,
        );
        return Value{ .object = ctx };
    }

    fn build_queueable_context(self: *Evaluator, job_id: []const u8) !Value {
        const ctx = try self.arena.create(types.ObjectInstance);
        ctx.* = .{ .class_name = "System.QueueableContext" };
        try ctx.fields.put(self.arena, "JobId", Value{ .string = job_id });
        return Value{ .object = ctx };
    }

    fn build_finalizer_context(
        self: *Evaluator,
        job_id: []const u8,
        exception_value: ?Value,
    ) !Value {
        const ctx = try self.arena.create(types.ObjectInstance);
        ctx.* = .{ .class_name = "System.FinalizerContext" };
        try ctx.fields.put(self.arena, "AsyncApexJobId", Value{ .string = job_id });
        try ctx.fields.put(self.arena, "Exception", exception_value orelse Value.null_val);
        try ctx.fields.put(
            self.arena,
            "Result",
            Value{ .string = if (exception_value == null) "SUCCESS" else "UNHANDLED_EXCEPTION" },
        );
        try ctx.fields.put(self.arena, "RequestId", Value{ .string = "4eR000000000001" });
        return Value{ .object = ctx };
    }

    fn publish_batch_apex_error_event(
        self: *Evaluator,
        batch_obj: *types.ObjectInstance,
        job_id: []const u8,
        phase: []const u8,
        exception_value: Value,
    ) !void {
        if (!self.class_raises_platform_events(batch_obj.class_name)) return;

        const evt = try self.arena.create(types.SObject);
        evt.* = .{ .type_name = "BatchApexErrorEvent" };
        try evt.fields.put(self.arena, "AsyncApexJobId", Value{ .string = job_id });
        try evt.fields.put(self.arena, "Phase", Value{ .string = phase });

        const parts = try self.extract_batch_exception_parts(exception_value);
        try evt.fields.put(self.arena, "ExceptionType", Value{ .string = parts.exception_type });
        try evt.fields.put(self.arena, "Message", parts.message);
        try evt.fields.put(self.arena, "StackTrace", Value{ .string = parts.stack_trace });
        _ = self.call_method("EventBus", "publish", &.{Value{ .sobject = evt }}) catch {};
    }

    fn class_raises_platform_events(self: *Evaluator, class_name: []const u8) bool {
        return self.class_implements_interface(class_name, "Database.RaisesPlatformEvents") or
            self.class_implements_interface(class_name, "RaisesPlatformEvents");
    }

    const BatchExceptionParts = struct {
        message: Value,
        exception_type: []const u8,
        stack_trace: []const u8,
    };

    fn extract_batch_exception_parts(
        self: *Evaluator,
        exception_value: Value,
    ) !BatchExceptionParts {
        var result = BatchExceptionParts{
            .message = Value.null_val,
            .exception_type = "System.Exception",
            .stack_trace = "stacktrace",
        };
        switch (exception_value) {
            .object => |obj| {
                result.message = obj.fields.get("message") orelse Value.null_val;
                result.exception_type = try self.namespace_builtin_exception(obj.class_name);
                if (obj.fields.get("stackTraceString")) |stack_val| {
                    if (stack_val == .string and stack_val.string.len > 0) {
                        result.stack_trace = stack_val.string;
                    }
                }
            },
            .string => |s| result.message = Value{ .string = s },
            else => result.message = Value{ .string = try utils.coerce_to_string(
                exception_value,
                self.arena,
            ) },
        }
        return result;
    }

    /// When `class_name` is a bare built-in exception name, prepend the
    /// `System.` namespace to match what Apex emits on BatchApexErrorEvent.
    fn namespace_builtin_exception(
        self: *Evaluator,
        class_name: []const u8,
    ) ![]const u8 {
        if (std.mem.indexOfScalar(u8, class_name, '.') != null) return class_name;
        const builtin_exception_types = [_][]const u8{
            "Exception",              "DMLException",
            "DmlException",           "NullPointerException",
            "TypeException",          "QueryException",
            "JSONException",          "ListException",
            "MathException",          "SecurityException",
            "NoAccessException",      "InvalidParameterValueException",
            "CalloutException",       "StringException",
            "NoSuchElementException", "NoDataFoundException",
            "SearchException",        "SObjectException",
            "HandledException",       "IllegalArgumentException",
            "LimitException",         "AsyncException",
            "SerializationException", "FlowException",
            "FinalException",         "UnsupportedOperationException",
            "EventBusException",
        };
        inline for (builtin_exception_types) |builtin_exception_type| {
            if (std.ascii.eqlIgnoreCase(class_name, builtin_exception_type)) {
                return try std.fmt.allocPrint(
                    self.arena,
                    "System.{s}",
                    .{builtin_exception_type},
                );
            }
        }
        return class_name;
    }

    fn invoke_attached_finalizer(
        self: *Evaluator,
        job_id: []const u8,
        exception_value: ?Value,
    ) !void {
        const finalizer_obj = self.attached_finalizer orelse return;
        const finalizer_class = self.find_class(finalizer_obj.class_name) orelse return;
        const finalizer_context = try self.build_finalizer_context(job_id, exception_value);
        const saved_pending_exception = self.pending_exception;
        self.pending_exception = null;
        _ = self.call_instance_method(
            finalizer_class,
            finalizer_obj,
            "execute",
            &.{finalizer_context},
        ) catch |err| {
            if (exception_value != null) {
                self.pending_exception = exception_value;
                return;
            }
            if (self.pending_exception == null) self.pending_exception = saved_pending_exception;
            return err;
        };
        self.pending_exception = saved_pending_exception;
    }

    fn execute_pending_batch_job(self: *Evaluator, batch_obj: *types.ObjectInstance) !void {
        const batch_class = self.find_class(batch_obj.class_name) orelse return;
        const batch_job_id = if (batch_obj.fields.get("__batchJobId")) |job_id_val|
            switch (job_id_val) {
                .string => job_id_val.string,
                else => try self.create_async_apex_job(
                    "BatchApex",
                    batch_obj.class_name,
                    "execute",
                ),
            }
        else
            try self.create_async_apex_job("BatchApex", batch_obj.class_name, "execute");

        const batch_context_value = try self.build_batchable_context(batch_job_id, null);
        const batch_context = batch_context_value.object;
        const saved_batch_context = self.active_batch_context;
        const saved_batch_job_id = self.active_batch_job_id;
        self.active_batch_context = batch_context;
        self.active_batch_job_id = batch_job_id;
        defer {
            self.active_batch_context = saved_batch_context;
            self.active_batch_job_id = saved_batch_job_id;
        }

        const start_scope = self.call_instance_method(
            batch_class,
            batch_obj,
            "start",
            &.{batch_context_value},
        ) catch |err| {
            self.update_async_apex_job(batch_job_id, "Failed", 1);
            if (self.pending_exception) |exception_value| {
                try self.publish_batch_apex_error_event(
                    batch_obj,
                    batch_job_id,
                    "START",
                    exception_value,
                );
            }
            return err;
        };

        var all_records: std.ArrayListUnmanaged(Value) = .empty;
        if (start_scope == .object) {
            if (start_scope.object.fields.get("query")) |query_val| {
                if (query_val == .string) {
                    const batch_env = try self.global_env.child();
                    const query_result = self.execute_soql(
                        query_val.string,
                        batch_env,
                    ) catch Value.null_val;
                    if (query_result == .list) {
                        for (query_result.list.items.items) |item| {
                            try all_records.append(self.arena, item);
                        }
                    }
                }
            } else if (start_scope.object.fields.get("records")) |records_val| {
                if (records_val == .list) {
                    for (records_val.list.items.items) |item| {
                        try all_records.append(self.arena, item);
                    }
                }
            } else {
                var store_iter = self.store.iterator();
                while (store_iter.next()) |entry| {
                    for (entry.value_ptr.items) |item| {
                        try all_records.append(self.arena, item);
                    }
                }
            }
        } else {
            var store_iter = self.store.iterator();
            while (store_iter.next()) |entry| {
                for (entry.value_ptr.items) |item| {
                    try all_records.append(self.arena, item);
                }
            }
        }

        const record_list = try self.arena.create(types.ListValue);
        record_list.* = .{ .items = all_records };
        _ = self.call_instance_method(
            batch_class,
            batch_obj,
            "execute",
            &.{ batch_context_value, Value{ .list = record_list } },
        ) catch |err| {
            self.update_async_apex_job(batch_job_id, "Failed", 1);
            if (self.pending_exception) |exception_value| {
                try self.publish_batch_apex_error_event(
                    batch_obj,
                    batch_job_id,
                    "EXECUTE",
                    exception_value,
                );
            }
            return err;
        };
        _ = self.call_instance_method(
            batch_class,
            batch_obj,
            "finish",
            &.{batch_context_value},
        ) catch |err| {
            self.update_async_apex_job(batch_job_id, "Failed", 1);
            if (self.pending_exception) |exception_value| {
                try self.publish_batch_apex_error_event(
                    batch_obj,
                    batch_job_id,
                    "FINISH",
                    exception_value,
                );
            }
            return err;
        };

        self.update_async_apex_job(batch_job_id, "Completed", 0);
    }

    fn enqueue_job(self: *Evaluator, job_obj: *types.ObjectInstance) !Value {
        self.limits_queueable += 1;
        const saved_dml = self.limits_dml;
        const saved_dml_rows = self.limits_dml_rows;
        const saved_soql = self.limits_soql;
        const saved_pub = self.limits_publish_immediate;
        const saved_callouts = self.limits_callouts;
        const saved_attached_finalizer = self.attached_finalizer;
        const saved_active_queueable_job_id = self.active_queueable_job_id;

        const job_id = try self.create_async_apex_job("Queueable", job_obj.class_name, null);
        self.attached_finalizer = null;
        self.active_queueable_job_id = job_id;

        defer {
            self.attached_finalizer = saved_attached_finalizer;
            self.active_queueable_job_id = saved_active_queueable_job_id;
            self.limits_dml = saved_dml;
            self.limits_dml_rows = saved_dml_rows;
            self.limits_soql = saved_soql;
            self.limits_publish_immediate = saved_pub;
            self.limits_callouts = saved_callouts;
        }

        if (self.find_class(job_obj.class_name)) |job_class| {
            const queueable_context = try self.build_queueable_context(job_id);
            const execute_args = [_]Value{queueable_context};
            const execute_result = if (self.find_best_method_in_class_filtered(
                job_class,
                "execute",
                &execute_args,
                true,
            ) != null)
                self.call_method(job_obj.class_name, "execute", &execute_args)
            else
                self.call_instance_method(job_class, job_obj, "execute", &execute_args);
            _ = execute_result catch |err| {
                if (err == error.ApexException) {
                    const thrown_exception = self.pending_exception;
                    self.update_async_apex_job(job_id, "Failed", 1);
                    try self.invoke_attached_finalizer(job_id, thrown_exception);
                    self.pending_exception = thrown_exception;
                }
                return err;
            };
        }

        self.update_async_apex_job(job_id, "Completed", 0);

        try self.invoke_attached_finalizer(job_id, null);
        return Value{ .string = job_id };
    }

    /// Resolve a static field or static property getter from a specific class.
    /// Tries getter first (for lazy-init patterns), then plain global_env lookup.
    fn resolve_static_field_value_on_class(
        self: *Evaluator,
        class_name: []const u8,
        field_name: []const u8,
    ) ?Value {
        self.ensure_static_init(class_name);
        const cd = self.find_class(class_name) orelse return null;
        // Try static property getter first
        const already_in_getter =
            if (self.evaluating_getter) |eg| std.ascii.eqlIgnoreCase(eg, field_name) else false;
        if (!already_in_getter) {
            for (cd.members) |member| {
                switch (member) {
                    .field_decl => |fd| {
                        if (fd.modifiers.is_static and
                            std.ascii.eqlIgnoreCase(fd.name, field_name) and
                            fd.getter_body != null)
                        {
                            const getter_env = self.global_env.child() catch return null;
                            const saved_class = self.current_class;
                            const saved_getter = self.evaluating_getter;
                            self.current_class = class_name;
                            self.evaluating_getter = field_name;
                            defer {
                                self.current_class = saved_class;
                                self.evaluating_getter = saved_getter;
                            }

                            const result = self.exec_block(
                                fd.getter_body.?,
                                getter_env,
                            ) catch return null;

                            return switch (result) {
                                .return_val => |v| v,
                                else => self.return_value,
                            };
                        }
                    },
                    else => {},
                }
            }
        }
        // Plain static field lookup
        const key = std.fmt.allocPrint(
            self.arena,
            "{s}.{s}",
            .{ class_name, field_name },
        ) catch return null;
        return self.global_env.get(key);
    }

    /// Resolve a static field or static property getter from the outer class of an inner class.
    /// Tries getter first (for lazy-init patterns), then plain global_env lookup.
    fn resolve_outer_static_field(
        self: *Evaluator,
        inner_class_name: []const u8,
        field_name: []const u8,
    ) ?Value {
        const outer_name = self.find_outer_class_name(inner_class_name) orelse return null;
        return self.resolve_static_field_value_on_class(outer_name, field_name);
    }

    /// Resolve a bare method call from an inner class to the nearest enclosing
    /// outer class that defines a compatible static method with the same name.
    fn resolve_outer_static_method_owner(
        self: *Evaluator,
        inner_class_name: []const u8,
        method_name: []const u8,
        args: []const Value,
    ) ?[]const u8 {
        var current_name = inner_class_name;
        while (self.find_outer_class_name(current_name)) |outer_name| {
            if (std.ascii.eqlIgnoreCase(outer_name, current_name)) break;
            if (self.find_class(outer_name)) |outer_decl| {
                if (self.find_best_method_in_class_filtered(
                    outer_decl,
                    method_name,
                    args,
                    true,
                ) != null) {
                    return outer_name;
                }
            }
            current_name = outer_name;
        }
        return null;
    }

    // -----------------------------------------------------------------------
    // JSON パーサー
    // -----------------------------------------------------------------------

    /// Compare two Values by a field name for ORDER BY.
    /// Returns: -1 if a < b, 0 if equal, 1 if a > b
    fn compare_by_field(self: *Evaluator, a: Value, b: Value, field: []const u8) i32 {
        const av = if (a == .sobject) self.get_s_object_field_value_case_insensitive(
            a.sobject,
            field,
        ) orelse Value.null_val else Value.null_val;
        const bv = if (b == .sobject) self.get_s_object_field_value_case_insensitive(
            b.sobject,
            field,
        ) orelse Value.null_val else Value.null_val;
        // null sorts last
        if (av == .null_val and bv == .null_val) return 0;
        if (av == .null_val) return 1;
        if (bv == .null_val) return -1;
        if (builtins.extract_date_string(av)) |a_date| {
            if (builtins.extract_date_string(bv)) |b_date| {
                return compare_case_insensitive_strings(a_date, b_date);
            }
        }
        // String comparison (case-insensitive)
        if (av == .string and bv == .string) {
            return compare_case_insensitive_strings(av.string, bv.string);
        }
        // Integer/Long comparison
        if ((av == .integer or av == .long) and (bv == .integer or bv == .long)) {
            const ai = if (av == .integer) av.integer else av.long;
            const bi = if (bv == .integer) bv.integer else bv.long;
            if (ai < bi) return -1;
            if (ai > bi) return 1;
            return 0;
        }
        // Double comparison
        if (av == .double and bv == .double) {
            if (av.double < bv.double) return -1;
            if (av.double > bv.double) return 1;
            return 0;
        }
        return 0;
    }

    /// Compare two Values for natural ordering.
    /// null < non-null; strings case-insensitive; integers/doubles numeric order
    fn compare_values(_: *Evaluator, a: Value, b: Value) i32 {
        // null handling
        if (a == .null_val and b == .null_val) return 0;
        if (a == .null_val) return -1;
        if (b == .null_val) return 1;
        if (builtins.extract_date_string(a)) |a_date| {
            if (builtins.extract_date_string(b)) |b_date| {
                return compare_case_insensitive_strings(a_date, b_date);
            }
        }
        // String comparison
        if (a == .string and b == .string) {
            return compare_case_insensitive_strings(a.string, b.string);
        }
        // Integer/Long comparison
        if ((a == .integer or a == .long) and (b == .integer or b == .long)) {
            const ai = if (a == .integer) a.integer else a.long;
            const bi = if (b == .integer) b.integer else b.long;
            if (ai < bi) return -1;
            if (ai > bi) return 1;
            return 0;
        }
        // Double comparison
        if (a == .double and b == .double) {
            if (a.double < b.double) return -1;
            if (a.double > b.double) return 1;
            return 0;
        }
        // Boolean
        if (a == .boolean and b == .boolean) {
            if (!a.boolean and b.boolean) return -1;
            if (a.boolean and !b.boolean) return 1;
            return 0;
        }
        const a_rank: i32 = switch (a) {
            .string => 0,
            .integer, .long, .double => 1,
            .boolean => 2,
            else => 3,
        };
        const b_rank: i32 = switch (b) {
            .string => 0,
            .integer, .long, .double => 1,
            .boolean => 2,
            else => 3,
        };
        if (a_rank < b_rank) return -1;
        if (a_rank > b_rank) return 1;
        return 0;
    }

    fn compare_case_insensitive_strings(left: []const u8, right: []const u8) i32 {
        const len = @min(left.len, right.len);
        for (0..len) |i| {
            const lhs = std.ascii.toLower(left[i]);
            const rhs = std.ascii.toLower(right[i]);
            const lhs_rank: u8 = if (std.ascii.isAlphabetic(lhs))
                0
            else if (std.ascii.isDigit(lhs))
                1
            else
                2;
            const rhs_rank: u8 = if (std.ascii.isAlphabetic(rhs))
                0
            else if (std.ascii.isDigit(rhs))
                1
            else
                2;
            if (lhs_rank < rhs_rank) return -1;
            if (lhs_rank > rhs_rank) return 1;
            if (lhs < rhs) return -1;
            if (lhs > rhs) return 1;
        }
        if (left.len < right.len) return -1;
        if (left.len > right.len) return 1;
        return 0;
    }

    fn class_implements_interface(
        self: *Evaluator,
        class_name: []const u8,
        interface_name: []const u8,
    ) bool {
        const cd = self.find_class(class_name) orelse return false;
        for (cd.interfaces) |iface| {
            if (std.ascii.eqlIgnoreCase(iface.name, interface_name)) return true;
            if (std.mem.lastIndexOfScalar(u8, iface.name, '.')) |dot_pos| {
                if (std.ascii.eqlIgnoreCase(iface.name[dot_pos + 1 ..], interface_name))
                    return true;
            }
        }
        // Check parent class
        if (cd.super_class) |sc| {
            return self.class_implements_interface(sc.name, interface_name);
        }
        return false;
    }

    fn has_comparable_interface(self: *Evaluator, class_name: []const u8) bool {
        return self.class_implements_interface(class_name, "Comparable");
    }

    fn is_batch_lifecycle_method(
        self: *Evaluator,
        class_name: []const u8,
        method_name: []const u8,
    ) bool {
        if (!(std.ascii.eqlIgnoreCase(method_name, "start") or
            std.ascii.eqlIgnoreCase(method_name, "execute") or
            std.ascii.eqlIgnoreCase(method_name, "finish")))
        {
            return false;
        }
        return self.class_implements_interface(class_name, "Database.Batchable") or
            self.class_implements_interface(class_name, "Batchable");
    }

    fn call_compare_to(self: *Evaluator, a: *types.ObjectInstance, b_val: Value) !i32 {
        if (self.find_class(a.class_name)) |cd| {
            const result = try self.call_instance_method(cd, a, "compareTo", &.{b_val});
            if (result == .integer) return @intCast(if (result.integer > 0) @as(i32, 1) else if (result.integer < 0) @as(i32, -1) else @as(i32, 0));
        }
        return 0;
    }

    /// Find the element type of an array field by scanning the source code.
    /// Looks for patterns like "TypeName[] fieldName" or "List<TypeName> fieldName".
    fn find_field_array_type(
        _: *Evaluator,
        source: []const u8,
        field_name: []const u8,
    ) ?[]const u8 {
        // Search for "fieldName" in source and look backwards for the type
        var pos: usize = 0;
        while (pos < source.len) {
            // Find field_name in source (case-insensitive)
            const found = std.ascii.indexOfIgnoreCasePos(source, pos, field_name) orelse break;
            // Ensure it's a whole-word match (not part of a larger identifier)
            const is_word_start = found == 0 or (!std.ascii.isAlphanumeric(source[found - 1]) and source[found - 1] != '_');
            const after_end = found + field_name.len;
            const is_word_end = after_end >= source.len or (!std.ascii.isAlphanumeric(source[after_end]) and source[after_end] != '_');
            if (!is_word_start or !is_word_end) {
                pos = found + 1;
                continue;
            }
            // Check that it's preceded by "[] " or "> " (array type indicators)
            if (found >= 3) {
                const before = source[0..found];
                const trimmed_before = std.mem.trimEnd(u8, before, " \t");
                // Check for "[]" suffix → "TypeName[]"
                if (std.mem.endsWith(u8, trimmed_before, "[]")) {
                    // Find the start of the type name
                    const type_end = trimmed_before.len - 2;
                    var type_start = type_end;
                    while (type_start > 0 and (std.ascii.isAlphanumeric(trimmed_before[type_start - 1]) or trimmed_before[type_start - 1] == '_')) {
                        type_start -= 1;
                    }
                    if (type_start < type_end) {
                        return trimmed_before[type_start..type_end];
                    }
                }
                // Check for ">" suffix → "List<TypeName>"
                if (std.mem.endsWith(u8, trimmed_before, ">")) {
                    // Find the opening "<"
                    if (std.mem.lastIndexOfScalar(u8, trimmed_before, '<')) |lt| {
                        const inner = std.mem.trim(
                            u8,
                            trimmed_before[lt + 1 .. trimmed_before.len - 1],
                            " \t",
                        );
                        if (inner.len > 0) {
                            return inner;
                        }
                    }
                }
            }
            pos = found + field_name.len;
        }
        return null;
    }

    /// Parse a JSON string into a Value.
    fn parse_json_value(self: *Evaluator, json_str: []const u8, type_hint: []const u8) ?Value {
        const trimmed = std.mem.trim(u8, json_str, " \t\r\n");
        if (trimmed.len == 0) return null;

        if (trimmed[0] == '[') {
            // JSON array → List
            const list = self.arena.create(types.ListValue) catch return null;
            list.* = .{};
            // Extract element type from "List<Contact>", "Contact[]", etc.
            const elem_type = if (std.mem.indexOf(u8, type_hint, "<")) |lt|
                if (std.mem.indexOf(u8, type_hint[lt + 1 ..], ">")) |gt|
                    type_hint[lt + 1 .. lt + 1 + gt]
                else
                    "Object"
            else if (std.mem.endsWith(u8, type_hint, "[]"))
                type_hint[0 .. type_hint.len - 2]
            else
                "Object";
            // Parse array elements
            var depth: i32 = 0;
            var start: usize = 1; // skip opening '['
            var i: usize = 1;
            while (i < trimmed.len) : (i += 1) {
                if (trimmed[i] == '"') {
                    i += 1;
                    while (i < trimmed.len and trimmed[i] != '"') : (i += 1) {
                        if (trimmed[i] == '\\') i += 1;
                    }
                } else if (trimmed[i] == '{' or trimmed[i] == '[') {
                    depth += 1;
                } else if (trimmed[i] == '}' or trimmed[i] == ']') {
                    if (depth == 0) {
                        // End of array
                        const elem_str = std.mem.trim(u8, trimmed[start..i], " \t\r\n,");
                        if (elem_str.len > 0) {
                            if (self.parse_json_value(elem_str, elem_type)) |v| {
                                list.items.append(self.arena, v) catch {};
                            }
                        }
                        break;
                    }
                    depth -= 1;
                } else if (trimmed[i] == ',' and depth == 0) {
                    const elem_str = std.mem.trim(u8, trimmed[start..i], " \t\r\n");
                    if (elem_str.len > 0) {
                        if (self.parse_json_value(elem_str, elem_type)) |v| {
                            list.items.append(self.arena, v) catch {};
                        }
                    }
                    start = i + 1;
                }
            }
            return Value{ .list = list };
        }

        if (trimmed[0] == '{') {
            // Framework classes like Invocable.Action.Result are neither SObjects nor
            // user-defined Apex classes — but tests do `(Invocable.Action.Result)
            // JSON.deserialize(...)`
            // and then call getOutputParameters()/isSuccess() on the result. Produce an
            // ObjectInstance so our class-specific dispatch can handle the getters.
            const is_framework_obj = std.mem.startsWith(u8, type_hint, "Invocable.") or
                std.mem.startsWith(u8, type_hint, "Flow.") or
                std.mem.startsWith(u8, type_hint, "Messaging.") or
                std.mem.startsWith(u8, type_hint, "Auth.") or
                std.mem.startsWith(u8, type_hint, "Reports.");
            if (is_framework_obj) {
                const obj = self.arena.create(types.ObjectInstance) catch return null;
                obj.* = .{ .class_name = type_hint };
                // Parse key/value pairs into fields generically
                var jd: i32 = 0;
                var js: usize = 1;
                var ji: usize = 1;
                while (ji < trimmed.len) : (ji += 1) {
                    if (trimmed[ji] == '"' and jd == 0) {
                        const key_start = ji + 1;
                        ji += 1;
                        while (ji < trimmed.len and trimmed[ji] != '"') : (ji += 1) {}
                        const key_name = trimmed[key_start..ji];
                        ji += 1;
                        while (ji < trimmed.len and trimmed[ji] != ':') : (ji += 1) {}
                        ji += 1;
                        while (ji < trimmed.len and
                            (trimmed[ji] == ' ' or trimmed[ji] == '\t')) : (ji += 1)
                        {}
                        js = ji;
                        var val_depth: i32 = 0;
                        while (ji < trimmed.len) : (ji += 1) {
                            if (trimmed[ji] == '"') {
                                ji += 1;
                                while (ji < trimmed.len and trimmed[ji] != '"') : (ji += 1) {
                                    if (trimmed[ji] == '\\') ji += 1;
                                }
                            } else if (trimmed[ji] == '{' or trimmed[ji] == '[') {
                                val_depth += 1;
                            } else if (trimmed[ji] == '}' or trimmed[ji] == ']') {
                                if (val_depth == 0) break;
                                val_depth -= 1;
                            } else if (trimmed[ji] == ',' and val_depth == 0) break;
                        }
                        const val_str = std.mem.trim(u8, trimmed[js..ji], " \t\r\n");
                        if (val_str.len > 0) {
                            if (self.parse_json_value(val_str, "Object")) |v| {
                                obj.fields.put(self.arena, key_name, v) catch {};
                            }
                        }
                    } else if (trimmed[ji] == '{' or trimmed[ji] == '[') {
                        jd += 1;
                    } else if (trimmed[ji] == '}' or trimmed[ji] == ']') {
                        if (jd == 0) break;
                        jd -= 1;
                    }
                }
                return Value{ .object = obj };
            }
            // Check if type_hint is a user-defined class → ObjectInstance
            const is_user_class = self.find_class(type_hint) != null;
            if (is_user_class) {
                const obj = self.arena.create(types.ObjectInstance) catch return null;
                obj.* = .{ .class_name = type_hint };
                if (self.find_class(type_hint)) |class_decl| {
                    if (class_decl.super_class) |sc| {
                        if (self.find_class(sc.name)) |parent_decl| {
                            self.init_instance_fields(parent_decl, obj) catch {};
                        }
                    }
                    self.init_instance_fields(class_decl, obj) catch {};
                }
                // Parse key-value pairs into fields
                var jd: i32 = 0;
                var js: usize = 1;
                var ji: usize = 1;
                while (ji < trimmed.len) : (ji += 1) {
                    if (trimmed[ji] == '"' and jd == 0) {
                        const key_start = ji + 1;
                        ji += 1;
                        while (ji < trimmed.len and trimmed[ji] != '"') : (ji += 1) {}
                        const key_name = trimmed[key_start..ji];
                        ji += 1;
                        while (ji < trimmed.len and trimmed[ji] != ':') : (ji += 1) {}
                        ji += 1;
                        while (ji < trimmed.len and
                            (trimmed[ji] == ' ' or trimmed[ji] == '\t')) : (ji += 1)
                        {}
                        js = ji;
                        var val_depth: i32 = 0;
                        while (ji < trimmed.len) : (ji += 1) {
                            if (trimmed[ji] == '"') {
                                ji += 1;
                                while (ji < trimmed.len and trimmed[ji] != '"') : (ji += 1) {
                                    if (trimmed[ji] == '\\') ji += 1;
                                }
                            } else if (trimmed[ji] == '{' or trimmed[ji] == '[') {
                                val_depth += 1;
                            } else if (trimmed[ji] == '}' or trimmed[ji] == ']') {
                                if (val_depth == 0) break;
                                val_depth -= 1;
                            } else if (trimmed[ji] == ',' and val_depth == 0) break;
                        }
                        const val_str = std.mem.trim(u8, trimmed[js..ji], " \t\r\n");
                        if (val_str.len > 0) {
                            // Resolve field type from class declaration for type-aware parsing.
                            // For List fields (T[]), find the element type from the source code.
                            const field_type_hint: []const u8 = blk: {
                                if (self.find_class(type_hint)) |cd| {
                                    for (cd.members) |member| {
                                        switch (member) {
                                            .field_decl => |fd| {
                                                if (std.ascii.eqlIgnoreCase(fd.name, key_name)) {
                                                    if (std.ascii.eqlIgnoreCase(
                                                        fd.type_ref.name,
                                                        "List",
                                                    )) {
                                                        // Find the element type from source code
                                                        for (
                                                            self.class_sources.keys(),
                                                            self.class_sources.values(),
                                                        ) |k, src| {
                                                            if (std.ascii.eqlIgnoreCase(
                                                                k,
                                                                type_hint,
                                                            )) {
                                                                if (self.find_field_array_type(
                                                                    src,
                                                                    key_name,
                                                                )) |elem| {
                                                                    // elem is a slice into src
                                                                    // which is stable
                                                                    // (arena-allocated class
                                                                    // source)
                                                                    if (elem.len > 0 and
                                                                        elem.len < 200)
                                                                    {
                                                                        break :blk std.fmt.allocPrint(self.arena, "{s}[]", .{elem}) catch "Object";
                                                                    }
                                                                }
                                                            }
                                                        }
                                                    }
                                                    break :blk fd.type_ref.name;
                                                }
                                            },
                                            else => {},
                                        }
                                    }
                                }
                                break :blk "Object";
                            };
                            if (self.parse_json_value(val_str, field_type_hint)) |v| {
                                obj.fields.put(self.arena, key_name, v) catch {};
                            }
                        }
                    } else if (trimmed[ji] == '{' or trimmed[ji] == '[') {
                        jd += 1;
                    } else if (trimmed[ji] == '}' or trimmed[ji] == ']') {
                        if (jd == 0) break;
                        jd -= 1;
                    }
                }
                return Value{ .object = obj };
            }
            // JSON object → SObject (for unknown/SObject types)
            const sob = self.arena.create(types.SObject) catch return null;
            var resolved_type = type_hint;
            sob.* = .{ .type_name = resolved_type };
            // Parse key-value pairs
            var depth: i32 = 0;
            var i: usize = 1;
            while (i < trimmed.len) {
                // Skip whitespace
                while (i < trimmed.len and (trimmed[i] == ' ' or trimmed[i] == '\t' or trimmed[i] == '\n' or trimmed[i] == '\r' or trimmed[i] == ',')) : (i += 1) {}
                if (i >= trimmed.len or trimmed[i] == '}') break;
                // Expect key in quotes
                if (trimmed[i] != '"') {
                    i += 1;
                    continue;
                }
                const key_start = i + 1;
                i += 1;
                while (i < trimmed.len and trimmed[i] != '"') : (i += 1) {
                    if (trimmed[i] == '\\') i += 1;
                }
                if (i >= trimmed.len) break;
                const key = trimmed[key_start..i];
                i += 1; // skip closing quote
                // Skip whitespace after key
                while (i < trimmed.len and (trimmed[i] == ' ' or trimmed[i] == '\t' or trimmed[i] == '\n' or trimmed[i] == '\r')) : (i += 1) {}
                // Expect colon - if not found, JSON is malformed
                if (i >= trimmed.len or trimmed[i] != ':') return null;
                i += 1; // skip colon
                while (i < trimmed.len and (trimmed[i] == ' ' or trimmed[i] == '\t' or trimmed[i] == '\n' or trimmed[i] == '\r')) : (i += 1) {}
                if (i >= trimmed.len) break;
                // Parse value
                const val_start = i;
                if (trimmed[i] == '"') {
                    // String value
                    i += 1;
                    while (i < trimmed.len and trimmed[i] != '"') : (i += 1) {
                        if (trimmed[i] == '\\') i += 1;
                    }
                    if (i < trimmed.len) {
                        const val_str = trimmed[val_start + 1 .. i];
                        i += 1;
                        // Special handling for "attributes" object
                        if (std.mem.eql(u8, key, "attributes")) {
                            // Value was a nested object but we parsed the first " - skip rest
                            // Re-parse from val_start
                            if (trimmed[val_start] == '{') {
                                // already handled below
                            } else {
                                // "attributes" was not an object; skip
                            }
                        } else if (std.ascii.eqlIgnoreCase(key, "Id")) {
                            sob.id = val_str;
                            sob.fields.put(self.arena, "Id", Value{ .string = val_str }) catch {};
                        } else {
                            const normalized = self.normalize_parsed_json_s_object_field(
                                sob,
                                key,
                                Value{ .string = val_str },
                            );
                            sob.fields.put(self.arena, key, normalized) catch {};
                        }
                    }
                } else if (trimmed[i] == '{') {
                    // Nested object
                    depth = 1;
                    i += 1;
                    while (i < trimmed.len and depth > 0) : (i += 1) {
                        if (trimmed[i] == '{') depth += 1;
                        if (trimmed[i] == '}') depth -= 1;
                        if (trimmed[i] == '"') {
                            i += 1;
                            while (i < trimmed.len and trimmed[i] != '"') : (i += 1) {
                                if (trimmed[i] == '\\') i += 1;
                            }
                        }
                    }
                    const nested = trimmed[val_start..i];
                    if (std.mem.eql(u8, key, "attributes")) {
                        // Extract type from attributes (handles both "type":"X" and "type": "X")
                        const type_key_patterns =
                            [_][]const u8{ "\"type\":\"", "\"type\": \"", "\"type\" : \"" };
                        for (type_key_patterns) |pattern| {
                            if (std.mem.indexOf(u8, nested, pattern)) |type_pos| {
                                const ts = type_pos + pattern.len;
                                if (std.mem.indexOfPos(u8, nested, ts, "\"")) |te| {
                                    resolved_type = nested[ts..te];
                                    sob.type_name = resolved_type;
                                }
                                break;
                            }
                        }
                    } else {
                        if (self.parse_json_value(nested, "Object")) |nv| {
                            const stored_value = self.relationship_records_value(nv) orelse self.normalize_parsed_json_s_object_field(sob, key, nv);
                            sob.fields.put(self.arena, key, stored_value) catch {};
                        }
                    }
                } else if (trimmed[i] == '[') {
                    // Array value
                    depth = 1;
                    i += 1;
                    while (i < trimmed.len and depth > 0) : (i += 1) {
                        if (trimmed[i] == '[') depth += 1;
                        if (trimmed[i] == ']') depth -= 1;
                        if (trimmed[i] == '"') {
                            i += 1;
                            while (i < trimmed.len and trimmed[i] != '"') : (i += 1) {
                                if (trimmed[i] == '\\') i += 1;
                            }
                        }
                    }
                    const arr = trimmed[val_start..i];
                    if (self.parse_json_value(arr, "List")) |av| {
                        sob.fields.put(self.arena, key, av) catch {};
                    }
                } else if (std.mem.startsWith(u8, trimmed[i..], "null")) {
                    sob.fields.put(self.arena, key, Value.null_val) catch {};
                    i += 4;
                } else if (std.mem.startsWith(u8, trimmed[i..], "true")) {
                    const normalized = self.normalize_parsed_json_s_object_field(
                        sob,
                        key,
                        Value{ .boolean = true },
                    );
                    sob.fields.put(self.arena, key, normalized) catch {};
                    i += 4;
                } else if (std.mem.startsWith(u8, trimmed[i..], "false")) {
                    const normalized = self.normalize_parsed_json_s_object_field(
                        sob,
                        key,
                        Value{ .boolean = false },
                    );
                    sob.fields.put(self.arena, key, normalized) catch {};
                    i += 5;
                } else {
                    // Number
                    var num_end = i;
                    while (num_end < trimmed.len and
                        trimmed[num_end] != ',' and trimmed[num_end] != '}' and
                        trimmed[num_end] != ' ') : (num_end += 1)
                    {}
                    const num_str = trimmed[i..num_end];
                    if (std.fmt.parseInt(i64, num_str, 10)) |n| {
                        const normalized = self.normalize_parsed_json_s_object_field(
                            sob,
                            key,
                            Value{ .integer = n },
                        );
                        sob.fields.put(self.arena, key, normalized) catch {};
                    } else |_| {
                        if (std.fmt.parseFloat(f64, num_str)) |f| {
                            const normalized = self.normalize_parsed_json_s_object_field(
                                sob,
                                key,
                                Value{ .double = f },
                            );
                            sob.fields.put(self.arena, key, normalized) catch {};
                        } else |_| {
                            const normalized = self.normalize_parsed_json_s_object_field(
                                sob,
                                key,
                                Value{ .string = num_str },
                            );
                            sob.fields.put(self.arena, key, normalized) catch {};
                        }
                    }
                    i = num_end;
                }
            }
            return Value{ .sobject = sob };
        }

        // Scalar values
        if (trimmed[0] == '"') {
            if (std.mem.lastIndexOfScalar(u8, trimmed, '"')) |end| {
                if (end > 0) {
                    const str_val = trimmed[1..end];
                    // When type_hint is Date or Datetime, wrap the string as a Date/DateTime object
                    if (std.ascii.eqlIgnoreCase(type_hint, "Date")) {
                        return builtins.make_date_value(
                            self.arena,
                            str_val,
                        ) catch Value{ .string = str_val };
                    }
                    if (std.ascii.eqlIgnoreCase(type_hint, "DateTime") or
                        std.ascii.eqlIgnoreCase(type_hint, "Datetime"))
                    {
                        return builtins.make_datetime_value(
                            self.arena,
                            str_val,
                        ) catch Value{ .string = str_val };
                    }
                    return Value{ .string = str_val };
                }
            }
            return Value{ .string = "" };
        }
        if (std.mem.eql(u8, trimmed, "null")) return Value.null_val;
        if (std.mem.eql(u8, trimmed, "true")) return Value{ .boolean = true };
        if (std.mem.eql(u8, trimmed, "false")) return Value{ .boolean = false };
        if (std.fmt.parseInt(i64, trimmed, 10) catch null) |n| return Value{ .integer = n };
        if (std.fmt.parseFloat(f64, trimmed) catch null) |f| return Value{ .double = f };
        return null;
    }

    /// Determine whether a type name represents a Salesforce SObject type.
    fn is_s_object_type_name(self: *Evaluator, name: []const u8) bool {
        // Custom suffixes: __c, __e, __mdt, __b
        if (std.mem.endsWith(u8, name, "__c") or std.mem.endsWith(u8, name, "__e") or
            std.mem.endsWith(u8, name, "__mdt") or std.mem.endsWith(u8, name, "__b"))
            return true;
        // Present in the data store
        if (self.store.get(name) != null) return true;
        // Known standard SObject types
        const known = [_][]const u8{
            "Account",                 "Contact",                "Opportunity",         "Case",                   "Lead",                 "Task",                 "Event",
            "Campaign",                "User",                   "ContentVersion",      "ContentDocument",        "ContentDocumentLink",  "ContentDistribution",  "PermissionSet",
            "PermissionSetAssignment", "ObjectPermissions",      "Profile",             "Organization",           "ApexClass",            "StaticResource",       "FieldPermissions",
            "PermissionSetGroup",      "PlatformCachePartition", "CronTrigger",         "AsyncApexJob",           "EntityDefinition",     "FieldDefinition",      "AggregateResult",
            "RecordType",              "DuplicateRule",          "DuplicateRecordSet",  "DuplicateRecordItem",    "UserRecordAccess",     "AuthSession",          "LoginHistory",
            "TaskStatus",              "BusinessHours",          "FeedItem",            "CollaborationGroup",     "UserRole",             "GroupMember",          "Group",
            "Attachment",              "Note",                   "EmailMessage",        "CaseComment",            "Solution",             "Contract",             "Product2",
            "Pricebook2",              "PricebookEntry",         "OpportunityLineItem", "Quote",                  "QuoteLineItem",        "PermissionSetLicense", "EmailTemplate",
            "Folder",                  "Document",               "CampaignMember",      "CampaignMemberStatus",   "EmailMessageRelation", "OrgWideEmailAddress",  "PermissionSetLicenseAssign",
            "ServiceResource",         "AssignedResource",       "ServiceTerritory",    "ServiceTerritoryMember", "ApexTrigger",          "CustomPermission",     "FlowDefinitionView",
            "FlowVersionView",         "ApexEmailNotification",  "Network",             "Topic",                  "OmniProcess",          "SObject",              "BatchApexErrorEvent",
            "AsyncOperationEvent",     "AsyncOperationStatus",   "EventBusSubscriber",  "LeadStatus",             "UserPreference",       "UserLogin",            "LoginIp",
            // Standard object-Share sharing tables.
            "AccountShare",            "OpportunityShare",       "CaseShare",           "LeadShare",              "ContactShare",         "CampaignShare",        "ContractShare",
            "ProductShare",            "AssetShare",             "OrderShare",          "QuoteShare",
        };
        for (known) |kt| {
            if (std.ascii.eqlIgnoreCase(name, kt)) return true;
        }
        return false;
    }

    fn is_known_schema_enum_type(name: []const u8) bool {
        return std.ascii.eqlIgnoreCase(name, "DisplayType") or
            std.ascii.eqlIgnoreCase(name, "SoapType");
    }

    /// Instantiate a class by name (for Type.forName().newInstance())
    fn instantiate_class(self: *Evaluator, class_name: []const u8) !Value {
        // Lazy static init: ensure the class's static fields/blocks are initialized
        self.ensure_static_init(class_name);
        if (self.find_class(class_name)) |class_decl| {
            // Also ensure parent class hierarchy is initialized
            if (class_decl.super_class) |sc| self.ensure_static_init(sc.name);
            const instance = try self.arena.create(types.ObjectInstance);
            // Preserve the requested class name so qualified inner classes
            // continue to dispatch against the intended outer class.
            instance.* = .{ .class_name = class_name };
            // Initialize instance fields
            self.init_instance_fields(class_decl, instance) catch {};
            // Initialize parent class fields
            if (class_decl.super_class) |sc| {
                if (self.find_class(sc.name)) |parent_decl| {
                    self.init_instance_fields(parent_decl, instance) catch {};
                }
            }
            // Execute parent constructor
            if (class_decl.super_class) |sc| {
                if (self.find_class(sc.name)) |parent_decl| {
                    try self.run_constructor(parent_decl, instance, &.{});
                }
            }
            // Execute own constructor
            try self.run_constructor(class_decl, instance, &.{});
            return Value{ .object = instance };
        }
        // SObject type name → return .sobject instead of .object
        if (self.is_s_object_type_name(class_name)) {
            const sob = try self.arena.create(types.SObject);
            sob.* = .{ .type_name = class_name };
            return Value{ .sobject = sob };
        }
        // Fallback: create a bare ObjectInstance
        const instance = try self.arena.create(types.ObjectInstance);
        instance.* = .{ .class_name = class_name };
        return Value{ .object = instance };
    }
};

// ---------------------------------------------------------------------------
// 静的ヘルパー
// ---------------------------------------------------------------------------

/// Apex-compatible `String.split(regex)` implementation backed by the interpret regex engine.
/// `split_limit` mirrors the `split(regex, limit)` overload: when set and > 1, only that many
/// segments are produced (the final one absorbs any unsplit tail); limit == 1 is a no-op.
/// Callers remain responsible for the "empty regex splits every character" case — this helper
/// only handles non-empty patterns.
fn split_by_regex(
    arena: std.mem.Allocator,
    pattern: []const u8,
    s: []const u8,
    split_limit: ?usize,
) ![][]const u8 {
    var parts = std.ArrayListUnmanaged([]const u8).empty;
    const matches = try regex.find_all(arena, pattern, s);
    if (split_limit) |lim| {
        if (lim <= 1) {
            try parts.append(arena, s);
            return parts.items;
        }
    }
    var start: usize = 0;
    var splits_done: usize = 0;
    for (matches) |m| {
        const span = m.groups[0] orelse continue;
        if (split_limit) |lim| {
            if (splits_done + 1 >= lim) break;
        }
        // Zero-width match on the current cursor — skip to avoid infinite splitting.
        if (span.start == start and span.end == start) continue;
        try parts.append(arena, s[start..span.start]);
        start = span.end;
        splits_done += 1;
    }
    try parts.append(arena, s[start..]);
    return parts.items;
}

/// True when (enum_simple_name, value) matches a well-known built-in System enum.
/// Used for overload resolution since enum values are represented as plain strings.
fn is_system_enum_value(enum_simple: []const u8, value: []const u8) bool {
    if (enum_simple.len == 0 or value.len == 0) return false;
    const trigger_ops = [_][]const u8{ "BEFORE_INSERT", "BEFORE_UPDATE", "BEFORE_DELETE", "AFTER_INSERT", "AFTER_UPDATE", "AFTER_DELETE", "AFTER_UNDELETE" };
    const logging_levels = [_][]const u8{ "INTERNAL", "FINEST", "FINER", "FINE", "DEBUG", "INFO", "WARN", "ERROR", "NONE" };
    const access_types = [_][]const u8{ "CREATABLE", "READABLE", "UPDATABLE", "UPSERTABLE" };
    const access_levels = [_][]const u8{ "USER_MODE", "SYSTEM_MODE" };
    const quiddity_vals = [_][]const u8{ "ANONYMOUS", "AURA", "BATCH_APEX", "BATCH_CHUNK_PARALLEL", "BATCH_CHUNK_SERIAL", "BULK_API", "FUTURE", "INVOCABLE_ACTION", "IOT", "LIGHTNING_OUT", "QUEUEABLE", "QUICK_ACTION", "REMOTE_ACTION", "REST", "RUNTEST_ASYNC", "RUNTEST_DEPLOY", "RUNTEST_SYNC", "SCHEDULED", "SOAP", "SYNCHRONOUS", "VF", "WAVE" };
    const system_mode = [_][]const u8{ "SANDBOX", "PROD", "DEVELOPER", "TRIAL", "SCRATCH_ORG" };
    if (std.ascii.eqlIgnoreCase(enum_simple, "TriggerOperation")) {
        for (trigger_ops) |n| if (std.ascii.eqlIgnoreCase(n, value)) return true;
        return false;
    }
    if (std.ascii.eqlIgnoreCase(enum_simple, "LoggingLevel")) {
        for (logging_levels) |n| if (std.ascii.eqlIgnoreCase(n, value)) return true;
        return false;
    }
    if (std.ascii.eqlIgnoreCase(enum_simple, "AccessType")) {
        for (access_types) |n| if (std.ascii.eqlIgnoreCase(n, value)) return true;
        return false;
    }
    if (std.ascii.eqlIgnoreCase(enum_simple, "AccessLevel")) {
        for (access_levels) |n| if (std.ascii.eqlIgnoreCase(n, value)) return true;
        return false;
    }
    if (std.ascii.eqlIgnoreCase(enum_simple, "Quiddity")) {
        for (quiddity_vals) |n| if (std.ascii.eqlIgnoreCase(n, value)) return true;
        return false;
    }
    if (std.ascii.eqlIgnoreCase(enum_simple, "OrganizationType") or
        std.ascii.eqlIgnoreCase(enum_simple, "InstanceType"))
    {
        for (system_mode) |n| if (std.ascii.eqlIgnoreCase(n, value)) return true;
        return false;
    }
    return false;
}

/// True if `pt` looks like a known built-in System enum type name (simple or qualified).
fn is_system_enum_type_name(pt: []const u8) bool {
    const simple = if (std.mem.lastIndexOfScalar(u8, pt, '.')) |di| pt[di + 1 ..] else pt;
    if (simple.len == 0) return false;
    const names = [_][]const u8{ "TriggerOperation", "LoggingLevel", "AccessType", "AccessLevel", "Quiddity", "DisplayType", "SoapType" };
    for (names) |n| {
        if (std.ascii.eqlIgnoreCase(n, simple)) return true;
    }
    return false;
}

/// メソッドオーバーロード解決用: 引数の Value とパラメータ型名のスコア計算。
fn overload_score_for_arg(arg: Value, pt: []const u8) i32 {
    if (arg == .string) {
        if (std.ascii.eqlIgnoreCase(pt, "String")) return 2;
        if (std.ascii.eqlIgnoreCase(pt, "Id"))
            return if (Evaluator.is_salesforce_id_string(arg.string)) 3 else 2;
        if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
        // Date/DateTime-like strings should match Date/DateTime params
        if (std.ascii.eqlIgnoreCase(pt, "Date") and
            Evaluator.is_date_only_format_string(arg.string))
        {
            return 2;
        }
        if ((std.ascii.eqlIgnoreCase(pt, "DateTime") or std.ascii.eqlIgnoreCase(pt, "Datetime")) and
            Evaluator.is_date_time_format_string(arg.string))
        {
            return 2;
        }
        return 0;
    }
    if (arg == .integer) {
        if (std.ascii.eqlIgnoreCase(pt, "Integer") or std.ascii.eqlIgnoreCase(pt, "int")) return 2;
        if (std.ascii.eqlIgnoreCase(pt, "Long") or
            std.ascii.eqlIgnoreCase(pt, "Decimal") or
            std.ascii.eqlIgnoreCase(pt, "Double"))
        {
            return 1;
        }
        if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
        return 0;
    }
    if (arg == .long) {
        if (std.ascii.eqlIgnoreCase(pt, "Long")) return 2;
        if (std.ascii.eqlIgnoreCase(pt, "Decimal") or std.ascii.eqlIgnoreCase(pt, "Double"))
            return 1;
        if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
        return 0;
    }
    if (arg == .double) {
        if (std.ascii.eqlIgnoreCase(pt, "Decimal") or std.ascii.eqlIgnoreCase(pt, "Double"))
            return 2;
        if (std.ascii.eqlIgnoreCase(pt, "Integer") or
            std.ascii.eqlIgnoreCase(pt, "int") or
            std.ascii.eqlIgnoreCase(pt, "Long"))
        {
            return 1;
        }
        if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
        return 0;
    }
    if (arg == .boolean) {
        if (std.ascii.eqlIgnoreCase(pt, "Boolean")) return 2;
        if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
        return 0;
    }
    if (arg == .list) {
        if (std.ascii.eqlIgnoreCase(pt, "List")) return 2;
        // Check List element type against generic parameter: List<Database.SaveResult> etc.
        if (std.mem.startsWith(u8, pt, "List<") or std.mem.startsWith(u8, pt, "list<")) {
            // Extract element type from param: "List<Database.SaveResult>" → "Database.SaveResult"
            if (std.mem.indexOf(u8, pt, "<")) |lt| {
                if (std.mem.lastIndexOf(u8, pt, ">")) |gt| {
                    const elem_type = pt[lt + 1 .. gt];
                    // Check first element of the list
                    // SObject is a generic parent type — any SObject matches List<SObject>
                    if (std.ascii.eqlIgnoreCase(elem_type, "SObject") or
                        std.ascii.eqlIgnoreCase(elem_type, "sObject") or
                        std.ascii.eqlIgnoreCase(elem_type, "Sobject"))
                    {
                        if (arg.list.items.items.len > 0) {
                            if (arg.list.items.items[0] == .sobject) return 3;
                        }
                        return 2; // Empty list matches List<SObject>
                    }
                    if (arg.list.items.items.len > 0) {
                        const first = arg.list.items.items[0];
                        if (first == .sobject) {
                            if (std.ascii.eqlIgnoreCase(first.sobject.type_name, elem_type))
                                return 3;
                            // Simple name match
                            if (std.mem.lastIndexOfScalar(u8, elem_type, '.')) |di| {
                                if (std.ascii.eqlIgnoreCase(
                                    first.sobject.type_name,
                                    elem_type[di + 1 ..],
                                )) return 3;
                            }
                        }
                        if (first == .object) {
                            if (std.ascii.eqlIgnoreCase(first.object.class_name, elem_type))
                                return 3;
                        }
                    }
                    return 1; // It's a List but element type doesn't match
                }
            }
        }
        return 0;
    }
    if (arg == .map) {
        if (std.ascii.eqlIgnoreCase(pt, "Map")) return 2;
        if (std.ascii.startsWithIgnoreCase(pt, "Map<")) return 2;
        if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
        return 0;
    }
    if (arg == .set) {
        if (std.ascii.eqlIgnoreCase(pt, "Set")) return 2;
        if (std.ascii.startsWithIgnoreCase(pt, "Set<")) return 2;
        if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
        if (std.ascii.startsWithIgnoreCase(pt, "Iterable") or std.mem.endsWith(u8, pt, "Iterable"))
            return 1;
        return 0;
    }
    if (arg == .sobject) {
        const tn = arg.sobject.type_name;
        // Exact type match (e.g., Database.SaveResult matches param Database.SaveResult)
        if (std.ascii.eqlIgnoreCase(tn, pt)) return 3;
        // Simple name match (e.g., "SaveResult" matches param "Database.SaveResult")
        if (std.mem.lastIndexOfScalar(u8, pt, '.')) |di| {
            if (std.ascii.eqlIgnoreCase(tn, pt[di + 1 ..])) return 3;
        }
        if (std.mem.lastIndexOfScalar(u8, tn, '.')) |di| {
            if (std.ascii.eqlIgnoreCase(tn[di + 1 ..], pt)) return 3;
        }
        // Generic SObject match
        if (std.ascii.eqlIgnoreCase(pt, "SObject") or
            std.ascii.eqlIgnoreCase(pt, "Sobject") or
            std.ascii.eqlIgnoreCase(pt, "sObject"))
        {
            return 2;
        }
        return 0;
    }
    if (arg == .object) {
        const cn = arg.object.class_name;
        // Exact class name match (case-insensitive)
        if (std.ascii.eqlIgnoreCase(cn, pt)) return 3;
        // Match when the class_name is dotted ("Outer.Inner") and pt uses the simple form.
        if (std.mem.lastIndexOfScalar(u8, cn, '.')) |di| {
            if (std.ascii.eqlIgnoreCase(cn[di + 1 ..], pt)) return 3;
        }
        // Match when the param type is dotted ("System.Type") and the class_name uses
        // the simple form ("Type") — happens whenever the interpreter stores built-in
        // objects with their Apex simple names while user code spells the qualified form.
        if (std.mem.lastIndexOfScalar(u8, pt, '.')) |di| {
            if (std.ascii.eqlIgnoreCase(pt[di + 1 ..], cn)) return 3;
        }
        // Date/DateTime objects should score well for their specific types
        if (std.ascii.eqlIgnoreCase(cn, "Date")) {
            if (std.ascii.eqlIgnoreCase(pt, "Date")) return 2;
            if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
            return 0;
        }
        if (std.ascii.eqlIgnoreCase(cn, "Datetime")) {
            if (std.ascii.eqlIgnoreCase(pt, "DateTime") or std.ascii.eqlIgnoreCase(pt, "Datetime"))
                return 2;
            if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
            return 0;
        }
        if (std.ascii.eqlIgnoreCase(pt, "Object")) return 1;
        return 0;
    }
    return 0;
}

fn eval_binary(
    eval: *Evaluator,
    left: Value,
    op: ast.BinaryOp,
    right: Value,
    arena: std.mem.Allocator,
) !Value {
    const TemporalComparable = struct {
        fn normalize(raw: []const u8) []const u8 {
            if (raw.len > 10 and std.mem.indexOf(u8, raw, "T") != null) {
                if (std.mem.endsWith(u8, raw, ".000+0000")) return raw[0 .. raw.len - 9];
                if (std.mem.endsWith(u8, raw, ".000Z")) return raw[0 .. raw.len - 4];
                if (std.mem.endsWith(u8, raw, "Z")) return raw[0 .. raw.len - 1];
            }
            return raw;
        }

        fn from_value(value: Value) ?[]const u8 {
            return switch (value) {
                .object => |obj| blk: {
                    if (!std.ascii.eqlIgnoreCase(obj.class_name, "Date") and
                        !std.ascii.eqlIgnoreCase(obj.class_name, "Datetime"))
                    {
                        break :blk null;
                    }
                    const raw = obj.fields.get("value") orelse break :blk null;
                    if (raw != .string) break :blk null;
                    break :blk normalize(raw.string);
                },
                .string => |raw| blk: {
                    const normalized = normalize(raw);
                    const is_date_like =
                        normalized.len >= 10 and normalized[4] == '-' and normalized[7] == '-';
                    if (!is_date_like) break :blk null;
                    break :blk normalized;
                },
                else => null,
            };
        }
    };

    switch (op) {
        .eq => return .{ .boolean = eval.values_equal(left, right) },
        .neq => return .{ .boolean = !eval.values_equal(left, right) },
        .strict_eq => return .{ .boolean = eval.strict_values_equal(left, right) },
        .strict_neq => return .{ .boolean = !eval.strict_values_equal(left, right) },
        .and_op => return .{ .boolean = (utils.coerce_to_bool(left) catch false) and (utils.coerce_to_bool(right) catch false) },
        .or_op => return .{ .boolean = (utils.coerce_to_bool(left) catch false) or (utils.coerce_to_bool(right) catch false) },
        .bit_and, .bit_or, .bit_xor => {
            // Apex accepts `&`/`|`/`^` on both Boolean and integer operands. Preserve
            // the operand type: two Booleans produce a Boolean, mixed integer/long
            // values produce the wider integer type. Anything else collapses to null.
            if (left == .boolean and right == .boolean) {
                const lb = left.boolean;
                const rb = right.boolean;
                const b = switch (op) {
                    .bit_and => lb and rb,
                    .bit_or => lb or rb,
                    .bit_xor => lb != rb,
                    else => unreachable,
                };
                return Value{ .boolean = b };
            }
            const li: i64 = switch (left) {
                .integer => |v| v,
                .long => |v| v,
                .boolean => |b| if (b) 1 else 0,
                .null_val => 0,
                else => return Value.null_val,
            };
            const ri: i64 = switch (right) {
                .integer => |v| v,
                .long => |v| v,
                .boolean => |b| if (b) 1 else 0,
                .null_val => 0,
                else => return Value.null_val,
            };
            const use_long = left == .long or right == .long;
            const v: i64 = switch (op) {
                .bit_and => li & ri,
                .bit_or => li | ri,
                .bit_xor => li ^ ri,
                else => unreachable,
            };
            return if (use_long) Value{ .long = v } else Value{ .integer = v };
        },
        else => {},
    }

    if ((left == .integer or left == .long) and (right == .integer or right == .long)) {
        const li = if (left == .integer) left.integer else left.long;
        const ri = if (right == .integer) right.integer else right.long;
        const use_long = left == .long or right == .long;
        return if (use_long) .{ .long = switch (op) {
            .add => li + ri,
            .sub => li - ri,
            .mul => li * ri,
            .div => if (ri != 0) @divTrunc(li, ri) else 0,
            .mod => if (ri != 0) @mod(li, ri) else 0,
            .lt => return .{ .boolean = li < ri },
            .gt => return .{ .boolean = li > ri },
            .lte => return .{ .boolean = li <= ri },
            .gte => return .{ .boolean = li >= ri },
            else => 0,
        } } else .{ .integer = switch (op) {
            .add => li + ri,
            .sub => li - ri,
            .mul => li * ri,
            .div => if (ri != 0) @divTrunc(li, ri) else 0,
            .mod => if (ri != 0) @mod(li, ri) else 0,
            .lt => return .{ .boolean = li < ri },
            .gt => return .{ .boolean = li > ri },
            .lte => return .{ .boolean = li <= ri },
            .gte => return .{ .boolean = li >= ri },
            else => 0,
        } };
    }

    if ((left == .double or left == .integer or left == .long) and
        (right == .double or right == .integer or right == .long))
    {
        const l = if (left == .double) left.double else if (left == .integer) @as(
            f64,
            @floatFromInt(left.integer),
        ) else @as(f64, @floatFromInt(left.long));
        const r = if (right == .double) right.double else if (right == .integer) @as(
            f64,
            @floatFromInt(right.integer),
        ) else @as(f64, @floatFromInt(right.long));
        return switch (op) {
            .add => .{ .double = l + r },
            .sub => .{ .double = l - r },
            .mul => .{ .double = l * r },
            .div => .{ .double = if (r != 0) l / r else 0 },
            .lt => .{ .boolean = l < r },
            .gt => .{ .boolean = l > r },
            .lte => .{ .boolean = l <= r },
            .gte => .{ .boolean = l >= r },
            else => .null_val,
        };
    }

    // String concatenation
    if (op == .add and (left == .string or right == .string)) {
        const ls = try eval.value_to_string(left);
        const rs = try eval.value_to_string(right);
        const result = try std.fmt.allocPrint(arena, "{s}{s}", .{ ls, rs });
        return .{ .string = result };
    }

    if (TemporalComparable.from_value(left)) |lv| {
        if (TemporalComparable.from_value(right)) |rv| {
            const cmp = std.mem.order(u8, lv, rv);
            return switch (op) {
                .lt => .{ .boolean = cmp == .lt },
                .gt => .{ .boolean = cmp == .gt },
                .lte => .{ .boolean = cmp != .gt },
                .gte => .{ .boolean = cmp != .lt },
                else => .null_val,
            };
        }
    }

    // Date/DateTime comparison (objects with "value" field containing ISO strings)
    if (left == .object and right == .object) {
        const left_cn = left.object.class_name;
        const right_cn = right.object.class_name;
        if ((std.ascii.eqlIgnoreCase(left_cn, "Date") or std.ascii.eqlIgnoreCase(
            left_cn,
            "Datetime",
        )) and
            (std.ascii.eqlIgnoreCase(right_cn, "Date") or std.ascii.eqlIgnoreCase(
                right_cn,
                "Datetime",
            )))
        {
            const lv = if (left.object.fields.get("value")) |v| (if (v == .string) v.string else "") else "";
            const rv = if (right.object.fields.get("value")) |v| (if (v == .string) v.string else "") else "";
            const cmp = std.mem.order(u8, lv, rv);
            return switch (op) {
                .lt => .{ .boolean = cmp == .lt },
                .gt => .{ .boolean = cmp == .gt },
                .lte => .{ .boolean = cmp != .gt },
                .gte => .{ .boolean = cmp != .lt },
                else => .null_val,
            };
        }
    }
    // String comparison for < > <= >=
    if (left == .string and right == .string) {
        const cmp = std.mem.order(u8, left.string, right.string);
        return switch (op) {
            .lt => .{ .boolean = cmp == .lt },
            .gt => .{ .boolean = cmp == .gt },
            .lte => .{ .boolean = cmp != .gt },
            .gte => .{ .boolean = cmp != .lt },
            else => .null_val,
        };
    }

    return .null_val;
}

fn eval_unary(op: ast.UnaryOp, operand: Value) !Value {
    switch (op) {
        .negate => {
            if (operand == .integer) return .{ .integer = -operand.integer };
            if (operand == .long) return .{ .long = -operand.long };
            if (operand == .double) return .{ .double = -operand.double };
            return .null_val;
        },
        .not => return .{ .boolean = !(utils.coerce_to_bool(operand) catch false) },
    }
}

fn eval_compound_assign(
    current: Value,
    op: ast.AssignOp,
    value: Value,
    arena: std.mem.Allocator,
) Value {
    const Numeric = struct {
        fn as_f64(v: Value) ?f64 {
            return switch (v) {
                .integer => |i| @floatFromInt(i),
                .long => |i| @floatFromInt(i),
                .double => |d| d,
                else => null,
            };
        }

        fn is_integral(f: f64) bool {
            return @floor(f) == f;
        }

        fn from_arithmetic(current_value: Value, incoming_value: Value, result: f64) Value {
            if (current_value == .double or incoming_value == .double) {
                if (is_integral(result)) {
                    if (current_value == .integer or incoming_value == .integer)
                        return .{ .integer = @intFromFloat(result) };
                    if (current_value == .long or incoming_value == .long)
                        return .{ .long = @intFromFloat(result) };
                }
                return .{ .double = result };
            }
            if (current_value == .long or incoming_value == .long)
                return .{ .long = @intFromFloat(result) };
            return .{ .integer = @intFromFloat(result) };
        }

        fn from_division(current_value: Value, incoming_value: Value, result: f64) Value {
            if (current_value == .double or incoming_value == .double) {
                if (is_integral(result)) return .{ .integer = @intFromFloat(result) };
                return .{ .double = result };
            }
            if (current_value == .long or incoming_value == .long) {
                if (is_integral(result)) return .{ .long = @intFromFloat(result) };
                return .{ .double = result };
            }
            if (is_integral(result)) return .{ .integer = @intFromFloat(result) };
            return .{ .double = result };
        }
    };

    switch (op) {
        .plus_assign => {
            if (current == .integer and value == .integer)
                return .{ .integer = current.integer + value.integer };
            if (current == .long and value == .long) return .{ .long = current.long + value.long };
            if (current == .double and value == .double)
                return .{ .double = current.double + value.double };
            if (Numeric.as_f64(current)) |lhs| {
                if (Numeric.as_f64(value)) |rhs| {
                    return Numeric.from_arithmetic(current, value, lhs + rhs);
                }
            }
            // String concatenation for +=
            if (current == .string or value == .string) {
                const ls = utils.coerce_to_string(current, arena) catch return current;
                const rs = utils.coerce_to_string(value, arena) catch return current;
                const result = std.fmt.allocPrint(
                    arena,
                    "{s}{s}",
                    .{ ls, rs },
                ) catch return current;
                return .{ .string = result };
            }
        },
        .minus_assign => {
            if (current == .integer and value == .integer)
                return .{ .integer = current.integer - value.integer };
            if (current == .long and value == .long) return .{ .long = current.long - value.long };
            if (Numeric.as_f64(current)) |lhs| {
                if (Numeric.as_f64(value)) |rhs| {
                    return Numeric.from_arithmetic(current, value, lhs - rhs);
                }
            }
        },
        .star_assign => {
            if (current == .integer and value == .integer)
                return .{ .integer = current.integer * value.integer };
            if (current == .long and value == .long) return .{ .long = current.long * value.long };
            if (Numeric.as_f64(current)) |lhs| {
                if (Numeric.as_f64(value)) |rhs| {
                    return Numeric.from_arithmetic(current, value, lhs * rhs);
                }
            }
        },
        .slash_assign => {
            if (current == .integer and value == .integer and value.integer != 0)
                return .{ .integer = @divTrunc(current.integer, value.integer) };
            if (current == .long and value == .long and value.long != 0)
                return .{ .long = @divTrunc(current.long, value.long) };
            if (Numeric.as_f64(current)) |lhs| {
                if (Numeric.as_f64(value)) |rhs| {
                    if (rhs != 0) return Numeric.from_division(current, value, lhs / rhs);
                }
            }
        },
        .assign => return value,
        .null_coalesce_assign => return if (current == .null_val) value else current,
    }
    return value;
}

fn default_value(type_ref: types.TypeRef) Value {
    // Apex treats all types (including Integer, Double, Decimal, Boolean) as
    // reference types whose uninitialized value is null.
    _ = type_ref;
    return .null_val;
}

fn extract_from_type(soql: []const u8) ?[]const u8 {
    // Find "FROM <type>" case-insensitive, skipping sub-queries in parens
    const lower = soql;
    var i: usize = 0;
    var depth: u32 = 0;
    while (i + 5 < lower.len) : (i += 1) {
        if (lower[i] == '(') {
            depth += 1;
            continue;
        }
        if (lower[i] == ')') {
            if (depth > 0) depth -= 1;
            continue;
        }
        if (depth > 0) continue; // Skip content inside parentheses
        if (std.ascii.eqlIgnoreCase(lower[i .. i + 4], "from") and
            is_soql_whitespace(lower[i + 4]))
        {
            var start = i + 5;
            while (start < lower.len and is_soql_whitespace(lower[start])) start += 1;
            var end = start;
            while (end < lower.len and
                !is_soql_whitespace(lower[end]) and
                lower[end] != ']' and lower[end] != ')') end += 1;
            if (end > start) return lower[start..end];
        }
    }
    return null;
}

/// Check if a character is whitespace (space, tab, newline, carriage return)
fn is_soql_whitespace(c: u8) bool {
    return c == ' ' or c == '\t' or c == '\n' or c == '\r';
}

fn extract_where_clause(soql: []const u8) ?[]const u8 {
    // Find WHERE ... (ends before ORDER BY, GROUP BY, LIMIT, OFFSET, WITH, FOR)
    // Skip content inside parentheses (sub-queries)
    var i: usize = 0;
    var paren_depth: u32 = 0;
    while (i + 5 < soql.len) : (i += 1) {
        if (soql[i] == '(') {
            paren_depth += 1;
            continue;
        }
        if (soql[i] == ')') {
            if (paren_depth > 0) paren_depth -= 1;
            continue;
        }
        if (paren_depth > 0) continue;
        if (std.ascii.eqlIgnoreCase(soql[i .. i + 5], "where") and
            (i == 0 or is_soql_whitespace(soql[i - 1])) and
            is_soql_whitespace(soql[i + 5]))
        {
            const start = i + 6;
            // Find end of WHERE clause
            var end = soql.len;
            var j: usize = start;
            while (j + 3 < soql.len) : (j += 1) {
                // Check for terminating keywords
                const remaining = soql[j..];
                if (remaining.len >= 5 and std.ascii.eqlIgnoreCase(remaining[0..5], "ORDER") and
                    (j == 0 or is_soql_whitespace(soql[j - 1])))
                {
                    end = j;
                    break;
                }
                if (remaining.len >= 5 and std.ascii.eqlIgnoreCase(remaining[0..5], "GROUP") and
                    (j == 0 or is_soql_whitespace(soql[j - 1])))
                {
                    end = j;
                    break;
                }
                if (remaining.len >= 5 and std.ascii.eqlIgnoreCase(remaining[0..5], "LIMIT") and
                    (j == 0 or is_soql_whitespace(soql[j - 1])))
                {
                    end = j;
                    break;
                }
                if (remaining.len >= 6 and std.ascii.eqlIgnoreCase(remaining[0..6], "OFFSET") and
                    (j == 0 or is_soql_whitespace(soql[j - 1])))
                {
                    end = j;
                    break;
                }
                if (remaining.len >= 4 and std.ascii.eqlIgnoreCase(remaining[0..4], "WITH") and
                    (j == 0 or is_soql_whitespace(soql[j - 1])))
                {
                    end = j;
                    break;
                }
                if (remaining.len >= 3 and std.ascii.eqlIgnoreCase(remaining[0..3], "FOR") and
                    (j == 0 or is_soql_whitespace(soql[j - 1])))
                {
                    end = j;
                    break;
                }
            }
            if (start < end) return soql[start..end];
        }
    }
    return null;
}

fn find_logical_op(clause: []const u8, keyword: []const u8) ?usize {
    // Find AND/OR at top level (not inside parens)
    var depth: u32 = 0;
    var i: usize = 0;
    while (i < clause.len) : (i += 1) {
        if (clause[i] == '(') {
            depth += 1;
            continue;
        }
        if (clause[i] == ')') {
            if (depth > 0) depth -= 1;
            continue;
        }
        if (clause[i] == '\'') {
            // Skip string literal
            i += 1;
            while (i < clause.len and clause[i] != '\'') : (i += 1) {}
            continue;
        }
        if (depth == 0 and i + keyword.len <= clause.len) {
            if (std.ascii.eqlIgnoreCase(clause[i .. i + keyword.len], keyword)) {
                // Check word boundaries
                const before_ok = (i == 0 or clause[i - 1] == ' ' or clause[i - 1] == '\n' or clause[i - 1] == ')');
                const after_ok = (i + keyword.len >= clause.len or clause[i + keyword.len] == ' ' or clause[i + keyword.len] == '\n' or clause[i + keyword.len] == '(');
                if (before_ok and after_ok) return i;
            }
        }
    }
    return null;
}

fn extract_offset(soql: []const u8) ?usize {
    var i: usize = 0;
    while (i + 7 < soql.len) : (i += 1) {
        if (std.ascii.eqlIgnoreCase(soql[i .. i + 6], "offset") and
            (soql[i + 6] == ' ' or soql[i + 6] == '\n'))
        {
            var start = i + 7;
            while (start < soql.len and soql[start] == ' ') start += 1;
            var end = start;
            while (end < soql.len and std.ascii.isDigit(soql[end])) end += 1;
            if (end > start) return std.fmt.parseUnsigned(usize, soql[start..end], 10) catch null;
        }
    }
    return null;
}

fn extract_offset_bind_var(soql: []const u8) ?[]const u8 {
    var i: usize = 0;
    while (i + 7 < soql.len) : (i += 1) {
        if (std.ascii.eqlIgnoreCase(soql[i .. i + 6], "offset") and
            (soql[i + 6] == ' ' or soql[i + 6] == '\n'))
        {
            var start = i + 7;
            while (start < soql.len and soql[start] == ' ') start += 1;
            if (start < soql.len and soql[start] == ':') {
                var end = start + 1;
                while (end < soql.len and
                    (std.ascii.isAlphanumeric(soql[end]) or soql[end] == '_')) end += 1;
                if (end > start + 1) return soql[start + 1 .. end];
            }
        }
    }
    return null;
}

const OrderByInfo = struct {
    field: []const u8,
    desc: bool,
};

fn extract_order_by_field(soql: []const u8) ?OrderByInfo {
    var i: usize = 0;
    while (i + 9 < soql.len) : (i += 1) {
        if (std.ascii.eqlIgnoreCase(soql[i .. i + 8], "ORDER BY") and
            (soql[i + 8] == ' ' or soql[i + 8] == '\n' or soql[i + 8] == '\t'))
        {
            var start = i + 9;
            while (start < soql.len and (soql[start] == ' ' or soql[start] == '\t' or soql[start] == '\n' or soql[start] == '\r')) start += 1;
            var end = start;
            while (end < soql.len and
                soql[end] != ' ' and soql[end] != '\n' and
                soql[end] != '\t' and soql[end] != ',' and
                soql[end] != ')') end += 1;
            if (end > start) {
                const field = soql[start..end];
                // Check for DESC/ASC after the field
                var pos = end;
                while (pos < soql.len and (soql[pos] == ' ' or soql[pos] == '\t' or soql[pos] == '\n' or soql[pos] == '\r')) pos += 1;
                var descending = false;
                if (pos + 4 <= soql.len and std.ascii.eqlIgnoreCase(soql[pos .. pos + 4], "DESC")) {
                    descending = true;
                }
                return OrderByInfo{ .field = field, .desc = descending };
            }
        }
    }
    return null;
}

fn extract_limit_bind_var(soql: []const u8) ?[]const u8 {
    var i: usize = 0;
    while (i + 6 < soql.len) : (i += 1) {
        if (std.ascii.eqlIgnoreCase(soql[i .. i + 5], "limit") and
            (soql[i + 5] == ' ' or soql[i + 5] == '\n'))
        {
            var start = i + 6;
            while (start < soql.len and soql[start] == ' ') start += 1;
            if (start < soql.len and soql[start] == ':') {
                var end = start + 1;
                while (end < soql.len and
                    (std.ascii.isAlphanumeric(soql[end]) or soql[end] == '_')) end += 1;
                return soql[start + 1 .. end];
            }
        }
    }
    return null;
}

fn extract_limit(soql: []const u8) ?usize {
    var i: usize = 0;
    while (i + 6 < soql.len) : (i += 1) {
        if (std.ascii.eqlIgnoreCase(soql[i .. i + 5], "limit") and
            (soql[i + 5] == ' ' or soql[i + 5] == '\n'))
        {
            var start = i + 6;
            while (start < soql.len and soql[start] == ' ') start += 1;
            var end = start;
            while (end < soql.len and std.ascii.isDigit(soql[end])) end += 1;
            if (end > start) return std.fmt.parseUnsigned(usize, soql[start..end], 10) catch null;
        }
    }
    return null;
}

// ---------------------------------------------------------------------------
// SOQL sub-query and parent field helpers
// ---------------------------------------------------------------------------

const SubQueryInfo = struct {
    relationship: []const u8,
    query: []const u8,
};

fn extract_sub_query(soql: []const u8) ?SubQueryInfo {
    // Find pattern: (SELECT ... FROM RelationshipName)
    var i: usize = 0;
    while (i < soql.len) : (i += 1) {
        if (soql[i] == '(' and i + 8 < soql.len) {
            var depth: u32 = 1;
            var close_idx = i + 1;
            while (close_idx < soql.len) : (close_idx += 1) {
                if (soql[close_idx] == '(') depth += 1;
                if (soql[close_idx] == ')') {
                    depth -= 1;
                    if (depth == 0) break;
                }
            }
            if (close_idx >= soql.len or depth != 0) continue;
            const inner_query = std.mem.trim(u8, soql[i + 1 .. close_idx], " \t\n\r");
            if (inner_query.len > 6 and std.ascii.eqlIgnoreCase(inner_query[0..6], "SELECT")) {
                if (std.ascii.indexOfIgnoreCase(inner_query, "FROM")) |from_pos| {
                    var start = from_pos + 4;
                    while (start < inner_query.len and (inner_query[start] == ' ' or inner_query[start] == '\t' or inner_query[start] == '\n')) start += 1;
                    var end = start;
                    while (end < inner_query.len and
                        inner_query[end] != ' ' and inner_query[end] != ')' and
                        inner_query[end] != '\n' and inner_query[end] != '\t') end += 1;
                    if (end > start) {
                        const raw_rel = inner_query[start..end];
                        // Strip parent prefix: "Account.Contacts" → "Contacts"
                        const rel = if (std.mem.lastIndexOfScalar(
                            u8,
                            raw_rel,
                            '.',
                        )) |dot_pos| raw_rel[dot_pos + 1 ..] else raw_rel;
                        return SubQueryInfo{ .relationship = rel, .query = inner_query };
                    }
                }
            }
        }
    }
    return null;
}

fn extract_parent_fields(soql: []const u8) ?[]const u8 {
    // Extract SELECT clause
    const select_start =
        if (std.ascii.indexOfIgnoreCase(soql, "SELECT")) |si| si + 6 else return null;
    // Find outer FROM (not inside parens)
    var from_end: usize = soql.len;
    var depth: u32 = 0;
    var idx: usize = select_start;
    while (idx + 4 < soql.len) : (idx += 1) {
        if (soql[idx] == '(') depth += 1;
        if (soql[idx] == ')') {
            if (depth > 0) depth -= 1;
        }
        if (depth == 0 and std.ascii.eqlIgnoreCase(soql[idx .. idx + 4], "FROM") and
            (idx == 0 or soql[idx - 1] == ' ' or soql[idx - 1] == '\n' or soql[idx - 1] == '\t'))
        {
            from_end = idx;
            break;
        }
    }
    return soql[select_start..from_end];
}

// ---------------------------------------------------------------------------
// テスト
// ---------------------------------------------------------------------------

const lexer_mod = @import("lexer.zig");
const parser_mod = @import("parser.zig");

const EvalTestResult = struct {
    value: Value,
    stdout: []const u8,
    arena: std.heap.ArenaAllocator,

    fn deinit(self: *EvalTestResult) void {
        self.arena.deinit();
    }
};

fn eval_source(
    source: []const u8,
    class_name: []const u8,
    method_name: []const u8,
) !EvalTestResult {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    errdefer arena.deinit();

    const tokens = try lexer_mod.tokenize(source, arena.allocator());
    const decls = try parser_mod.parse(tokens, arena.allocator());
    var eval = try Evaluator.init(arena.allocator(), std.testing.io);
    try eval.load_decls(decls);
    const result = try eval.call_method(class_name, method_name, &.{});

    return .{ .value = result, .stdout = eval.stdout.items, .arena = arena };
}

test "evaluate 1 + 2" {
    const tokens = try lexer_mod.tokenize("1 + 2", std.testing.allocator);
    defer std.testing.allocator.free(tokens);

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();

    const expr = try parser_mod.parse_expr(tokens, arena.allocator());
    var eval = try Evaluator.init(arena.allocator(), std.testing.io);
    const result = try eval.eval_expr(expr, eval.global_env);
    try std.testing.expectEqual(@as(i64, 3), result.integer);
}

test "evaluate string equality case-insensitive" {
    const tokens = try lexer_mod.tokenize("'Hello' == 'hello'", std.testing.allocator);
    defer std.testing.allocator.free(tokens);

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();

    const expr = try parser_mod.parse_expr(tokens, arena.allocator());
    var eval = try Evaluator.init(arena.allocator(), std.testing.io);
    const result = try eval.eval_expr(expr, eval.global_env);
    try std.testing.expect(result.boolean);
}

test "evaluate null == null" {
    const tokens = try lexer_mod.tokenize("null == null", std.testing.allocator);
    defer std.testing.allocator.free(tokens);

    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();

    const expr = try parser_mod.parse_expr(tokens, arena.allocator());
    var eval = try Evaluator.init(arena.allocator(), std.testing.io);
    const result = try eval.eval_expr(expr, eval.global_env);
    try std.testing.expect(result.boolean);
}

test "evaluate class method returning string" {
    const source =
        \\public class Hello {
        \\    public static String greet() {
        \\        return 'world';
        \\    }
        \\}
    ;
    var r = try eval_source(source, "Hello", "greet");
    defer r.deinit();

    try std.testing.expectEqualStrings("world", r.value.string);
}

