test "static property returning sobject resolves getter value" {
    const source =
        \\public class Outer {
        \\    private static Account CACHED {
        \\        get {
        \\            if (CACHED == null) {
        \\                insert new Account(Name = 'Acme');
        \\                CACHED = [SELECT Id, Name FROM Account LIMIT 1];
        \\            }
        \\            return CACHED;
        \\        }
        \\        set;
        \\    }
        \\    public static String run() {
        \\        return CACHED.Name;
        \\    }
        \\}
    ;
    var r = try eval_source(source, "Outer", "run");
    defer r.deinit();

    try std.testing.expectEqualStrings("Acme", r.value.string);
}

test "instance method reads static property getter without losing backing value" {
    const source =
        \\public class Outer {
        \\    private static String CACHED_VALUE {
        \\        get {
        \\            if (CACHED_VALUE == null) {
        \\                CACHED_VALUE = 'lazy-init';
        \\            }
        \\            return CACHED_VALUE;
        \\        }
        \\        set;
        \\    }
        \\    public String getValue() {
        \\        return CACHED_VALUE;
        \\    }
        \\    public static String run() {
        \\        return new Outer().getValue();
        \\    }
        \\}
    ;
    var r = try eval_source(source, "Outer", "run");
    defer r.deinit();

    try std.testing.expectEqualStrings("lazy-init", r.value.string);
}

test "mock singleton override feeds static lazy getter" {
    const source =
        \\public virtual class Selector {
        \\    private static Selector instance = new Selector();
        \\    public static Selector getInstance() {
        \\        return instance;
        \\    }
        \\    public static void setMock(Selector mockSelector) {
        \\        instance = mockSelector;
        \\    }
        \\    public virtual String getValue() {
        \\        return null;
        \\    }
        \\}
        \\public class MockSelector extends Selector {
        \\    private String cachedValue;
        \\    public void setValue(String cachedValue) {
        \\        this.cachedValue = cachedValue;
        \\    }
        \\    public override String getValue() {
        \\        return this.cachedValue;
        \\    }
        \\}
        \\public class Holder {
        \\    private static String CACHED_VALUE {
        \\        get {
        \\            if (CACHED_VALUE == null) {
        \\                CACHED_VALUE = Selector.getInstance().getValue();
        \\            }
        \\            return CACHED_VALUE;
        \\        }
        \\        set;
        \\    }
        \\    public static String run() {
        \\        return CACHED_VALUE;
        \\    }
        \\}
        \\public class Runner {
        \\    public static String run() {
        \\        MockSelector mockSelector = new MockSelector();
        \\        mockSelector.setValue('mocked');
        \\        Selector.setMock(mockSelector);
        \\        return Holder.run();
        \\    }
        \\}
    ;
    var r = try eval_source(source, "Runner", "run");
    defer r.deinit();

    try std.testing.expectEqualStrings("mocked", r.value.string);
}

test "mock singleton override feeds static lazy sobject getter" {
    const source =
        \\public virtual class Selector {
        \\    private static Selector instance = new Selector();
        \\    public static Selector getInstance() {
        \\        return instance;
        \\    }
        \\    public static void setMock(Selector mockSelector) {
        \\        instance = mockSelector;
        \\    }
        \\    public virtual Account getAccount() {
        \\        return null;
        \\    }
        \\}
        \\public class MockSelector extends Selector {
        \\    private Account cachedAccount;
        \\    public void setAccount(Account cachedAccount) {
        \\        this.cachedAccount = cachedAccount;
        \\    }
        \\    public override Account getAccount() {
        \\        return this.cachedAccount;
        \\    }
        \\}
        \\public class Holder {
        \\    private static Account CACHED_ACCOUNT {
        \\        get {
        \\            if (CACHED_ACCOUNT == null) {
        \\                CACHED_ACCOUNT = Selector.getInstance().getAccount();
        \\            }
        \\            return CACHED_ACCOUNT;
        \\        }
        \\        set;
        \\    }
        \\    public static String run() {
        \\        return CACHED_ACCOUNT?.Id;
        \\    }
        \\}
        \\public class Runner {
        \\    public static String run() {
        \\        MockSelector mockSelector = new MockSelector();
        \\        mockSelector.setAccount(new Account(Id = '001000000000001', Name = 'Acme'));
        \\        Selector.setMock(mockSelector);
        \\        return Holder.run();
        \\    }
        \\}
    ;
    var r = try eval_source(source, "Runner", "run");
    defer r.deinit();

    try std.testing.expectEqualStrings("001000000000001", r.value.string);
}

test "mock singleton override feeds nested inner-class getter" {
    const source =
        \\public class LoggerSObjectProxy {
        \\    public class AuthSession {
        \\        public LoginHistory LoginHistory;
        \\    }
        \\    public class LoginHistory {
        \\        public String Application;
        \\    }
        \\}
        \\public virtual class Selector {
        \\    private static Selector instance = new Selector();
        \\    public static Selector getInstance() {
        \\        return instance;
        \\    }
        \\    public static void setMock(Selector mockSelector) {
        \\        instance = mockSelector;
        \\    }
        \\    public virtual LoggerSObjectProxy.AuthSession getCachedAuthSessionProxy() {
        \\        return null;
        \\    }
        \\}
        \\public class MockSelector extends Selector {
        \\    private LoggerSObjectProxy.AuthSession mockAuthSessionProxy;
        \\    public void setCachedAuthSessionProxy(LoggerSObjectProxy.AuthSession mockAuthSessionProxy) {
        \\        this.mockAuthSessionProxy = mockAuthSessionProxy;
        \\    }
        \\    public override LoggerSObjectProxy.AuthSession getCachedAuthSessionProxy() {
        \\        if (this.mockAuthSessionProxy != null) {
        \\            return mockAuthSessionProxy;
        \\        }
        \\        return super.getCachedAuthSessionProxy();
        \\    }
        \\}
        \\public class Builder {
        \\    private static LoggerSObjectProxy.AuthSession CACHED_AUTH_SESSION_PROXY {
        \\        get {
        \\            if (CACHED_AUTH_SESSION_PROXY == null) {
        \\                CACHED_AUTH_SESSION_PROXY = Selector.getInstance().getCachedAuthSessionProxy();
        \\            }
        \\            return CACHED_AUTH_SESSION_PROXY;
        \\        }
        \\        set;
        \\    }
        \\    public static String run() {
        \\        return CACHED_AUTH_SESSION_PROXY.LoginHistory?.Application;
        \\    }
        \\}
        \\public class Runner {
        \\    public static String run() {
        \\        LoggerSObjectProxy.LoginHistory mockLoginHistoryProxy = new LoggerSObjectProxy.LoginHistory();
        \\        mockLoginHistoryProxy.Application = 'Application';
        \\        LoggerSObjectProxy.AuthSession mockAuthSessionProxy = new LoggerSObjectProxy.AuthSession();
        \\        mockAuthSessionProxy.LoginHistory = mockLoginHistoryProxy;
        \\        MockSelector mockSelector = new MockSelector();
        \\        mockSelector.setCachedAuthSessionProxy(mockAuthSessionProxy);
        \\        Selector.setMock(mockSelector);
        \\        return Builder.run();
        \\    }
        \\}
    ;
    var r = try eval_source(source, "Runner", "run");
    defer r.deinit();

    try std.testing.expectEqualStrings("Application", r.value.string);
}

test "typed null identifier prefers sobject overload over id overload" {
    const source =
        \\public class OverloadProbe {
        \\    public static String pick(Id value) {
        \\        return 'id';
        \\    }
        \\    public static String pick(SObject value) {
        \\        return 'sobject';
        \\    }
        \\    public static String run() {
        \\        User nullUser;
        \\        return pick(nullUser);
        \\    }
        \\}
    ;
    var r = try eval_source(source, "OverloadProbe", "run");
    defer r.deinit();

    try std.testing.expectEqualStrings("sobject", r.value.string);
}

test "typed null identifier prefers iterable overload over object overload" {
    const source =
        \\public class IterableProbe {
        \\    public static String pick(Object value) {
        \\        return 'object';
        \\    }
        \\    public static String pick(System.Iterable<Id> value) {
        \\        return 'iterable';
        \\    }
        \\    public static String run() {
        \\        System.Iterable<Id> ids = null;
        \\        return pick(ids);
        \\    }
        \\}
    ;
    var r = try eval_source(source, "IterableProbe", "run");
    defer r.deinit();

    try std.testing.expectEqualStrings("iterable", r.value.string);
}

test "null-returning helper method preserves declared return type for overload hints" {
    const source =
        \\public class MatchLikeHelper {
        \\    public static String anyString() {
        \\        return (String) null;
        \\    }
        \\}
        \\public class MatchLikeProbe {
        \\    public static String pick(String value) {
        \\        return 'string';
        \\    }
        \\    public static String pick(Object value) {
        \\        return 'object';
        \\    }
        \\    public static String run() {
        \\        return pick(MatchLikeHelper.anyString());
        \\    }
        \\}
    ;
    var r = try eval_source(source, "MatchLikeProbe", "run");
    defer r.deinit();

    try std.testing.expectEqualStrings("string", r.value.string);
}

test "createStub forwards declared param types for typed null helper arguments" {
    const source =
        \\public class StubMatcherHelper {
        \\    public static String anyString() {
        \\        return (String) null;
        \\    }
        \\}
        \\public class StubTarget {
        \\    public void take(String value) {
        \\    }
        \\    public void take(Object value) {
        \\    }
        \\}
        \\public class StubRecorder implements StubProvider {
        \\    public static String seenType;
        \\    public Object handleMethodCall(Object stubbedObject, String stubbedMethodName, Type returnType,
        \\        List<Type> listOfParamTypes, List<String> listOfParamNames, List<Object> listOfArgs) {
        \\        seenType = listOfParamTypes.get(0).getName();
        \\        return null;
        \\    }
        \\}
        \\public class StubProbe {
        \\    public static String run() {
        \\        StubTarget stubbed = (StubTarget) Test.createStub(StubTarget.class, new StubRecorder());
        \\        stubbed.take(StubMatcherHelper.anyString());
        \\        return StubRecorder.seenType;
        \\    }
        \\}
    ;
    var r = try eval_source(source, "StubProbe", "run");
    defer r.deinit();

    try std.testing.expectEqualStrings("String", r.value.string);
}

test "String.valueOf on Test.createStub proxy does not invoke stubbed Object methods" {
    const source =
        \\public class StubStringTarget {
        \\    public void ping() {
        \\    }
        \\}
        \\public class StubStringRecorder implements StubProvider {
        \\    public static Integer callCount = 0;
        \\    public Object handleMethodCall(Object stubbedObject, String stubbedMethodName, Type returnType,
        \\        List<Type> listOfParamTypes, List<String> listOfParamNames, List<Object> listOfArgs) {
        \\        callCount++;
        \\        return null;
        \\    }
        \\}
        \\public class StubStringProbe {
        \\    public static String run() {
        \\        StubStringTarget stubbed = (StubStringTarget) Test.createStub(StubStringTarget.class, new StubStringRecorder());
        \\        String rendered = String.valueOf(stubbed);
        \\        System.assert(rendered != null);
        \\        System.assertEquals(0, StubStringRecorder.callCount);
        \\        return rendered;
        \\    }
        \\}
    ;
    var r = try eval_source(source, "StubStringProbe", "run");
    defer r.deinit();

    try std.testing.expectEqualStrings(
        "StubStringTarget__sfdc_ApexStub:[instance]",
        r.value.string,
    );
}

test "List.add with explicit index inserts the provided value" {
    const source =
        \\public class IndexedListInsertProbe {
        \\    public static String run() {
        \\        List<Object> values = new List<Object>();
        \\        values.add('tail');
        \\        values.add(0, 'head');
        \\        return String.valueOf(values.get(0)) + '|' + String.valueOf(values.get(1)) + '|' + values.size();
        \\    }
        \\}
    ;
    var r = try eval_source(source, "IndexedListInsertProbe", "run");
    defer r.deinit();

    try std.testing.expectEqualStrings("head|tail|2", r.value.string);
}

test "instanceof supports Apex collection and schema token semantics" {
    const source =
        \\public class InstanceofProbe {
        \\    public static String run() {
        \\        List<String> names = new List<String>{ 'bob' };
        \\        return String.valueOf(Date.today() instanceof Datetime)
        \\            + '|'
        \\            + String.valueOf(new Account() instanceof SObject)
        \\            + '|'
        \\            + String.valueOf(names instanceof List<Object>)
        \\            + '|'
        \\            + String.valueOf(Account.Id instanceof SObjectField)
        \\            + '|'
        \\            + String.valueOf(Account.SObjectType instanceof SObjectType);
        \\    }
        \\}
    ;
    var r = try eval_source(source, "InstanceofProbe", "run");
    defer r.deinit();

    try std.testing.expectEqualStrings("true|true|true|true|true", r.value.string);
}
